          VoiceName = "voice/$Locale$/story/1001/100191/1914EEEC"
        },
        [10019103] = {
          Content = "▇▇▇渴望▇▇……这一切……",
          ContentKR = "이 모든 걸... ▇▇▇▇▇ 갈망한다면...",
          DialogueId = 10019103,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
