        [10030416] = {
          Camera = "17.873657,-44.469727,169.63678,-0.00131,-21.59972,96.626923,35.000008,39.151329,false,DoNotOverride,22,16:9 Digital Film",
          Content = "那晚泪湖边上的事，我听说了，我知道你多半不想见她。",
          ContentKR = "그날 밤 눈물의 호수에서 일어난 일에 대해 들었어. 네가 그녀와 만나기 싫은 것도 알아.",
          DialogueId = 10030416,
