        [10030616] = {
          Camera = "1297.798462,-671.682617,65.072266,0.000065,-0.601719,155.368057,35.000008,116.489357,false,Manual,3.0,16:9 Digital Film",
          Content = "喏，来了来了。麻烦一蹬腿不动弹了——麻烦死喽。",
