        [10030617] = {
          Camera = "230.647583,-1.03125,119.628906,0.000082,4.597776,170.360352,35.0,130.051529,false,DoNotOverride,3.0,16:9 Digital Film",
          Content = "……黎瑟·费西尔？",
          ContentKR = "...리듬 페실?",
          DialogueId = 10030617,
          GUID = "191C501A",
          NextDialogue = 10030618,
          SpeakNpcId = 100001,
          TalkActionId = {
