          },
          GUID = "191C5E36",
          NextDialogue = 10030704,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5E36"
        },
        [10030704] = {
          Camera = "-373.256409,-7.81543,220.638672,0.000206,-19.196136,3.056015,25.0,219.87709,false,Manual,3.0,16:9 Digital Film",
          Content = "我直接说正题吧。我是为了调查冰湖城外城近几日的恶性事件“卡戎狩猎”而来。",
          ContentKR = "바로 본론으로 들어가겠습니다. 최근 아이스레이크 시티 외성에서 발생한 '카론 사냥' 사건에 대해 조사하기 위해 찾아왔습니다.",
          DialogueId = 10030704,
          FacialId = {
            [1] = "100304:Unhappy01"
          },
          FinalCamera = "-330.987732,-5.65625,205.90625,0.000206,-19.196136,2.856016,25.0,219.87709,false,Manual,3.0,16:9 Digital Film",
          GUID = "191C5E60",
          LookAt = {
