          NextDialogue = 10030705,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "200002:Explain02_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100307/191C5E60"
        },
        [10030705] = {
          Camera = "-196.299988,-7.27832,128.933594,0.000239,-0.99649,-6.538433,35.000019,254.835373,false,Manual,6.0,16:9 Digital Film",
          Content = "这是第一次询问，我需要按照惯例确认一下你的身份。可以给我看一下<H>通行证</>吗？",
          ContentKR = "이번이 첫 번째 심문이기 때문에 관례에 따라 당신의 신원을 확인해야 합니다. <H>통행증</>을 보여주시겠습니까?",
          DialogueId = 10030705,
          GUID = "191C602F",
          NextDialogue = 10030706,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C602F"
        },
        [10030706] = {
          Camera = "-16.850769,-112.700195,139.550781,0.000263,-2.797638,120.662224,35.000019,146.760483,false,Manual,6.0,16:9 Digital Film",
          Content = "…………！",
          ContentKR = "......!",
          DialogueId = 10030706,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "191C6030",
          NextDialogue = 10030707,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C6030"
        },
        [10030707] = {
          Content = "我急着出门，通行证还在家里，我先回去拿。",
          ContentKR = "급하게 나오느라 통행증을 집에 두고 왔어요. 지금 가서 가져올게요.",
          DialogueId = 10030707,
          GUID = "191C6031",
