          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Shock_End",
            [2] = "100304:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C6031"
        },
        [10030708] = {
          Camera = "20.996643,167.708008,186.025391,0.000272,-16.19771,-130.733917,35.000015,206.537537,false,Manual,3.0,16:9 Digital Film",
          Content = "记错了吧？你通行证我前几天落在我家了，我正准备还给你——喏，长官，在这儿。",
          ContentKR = "잘못 기억한거 아냐? 너 며칠 전에 우리 집에 통행증을 두고 갔잖아. 마침 돌려주려 했는데, 자, 리듬 장교님, 여기있습니다.",
          DialogueId = 10030708,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "191C6032",
          LookAt = {
            [1] = "200021:n(100001)",
