        [10030710] = {
          Camera = "-80.779236,-40.317383,131.921875,0.000273,3.401782,-7.736254,35.000023,126.193214,false,Manual,6.0,16:9 Digital Film",
          Content = "呃，你不是狩月人吗？",
          ContentKR = "음, 당신은 월석 사냥꾼이 아니었던가요?",
          DialogueId = 10030710,
          FacialId = {
            [1] = "100304:Unacceptable01"
          },
