        [10030722] = {
          Camera = "36.484009,179.044922,176.644531,0.000295,-14.206376,-130.375656,35.000023,223.128433,false,Manual,6.0,16:9 Digital Film",
          Content = "好吧，那你八成还是在为那晚的事生黎瑟·费西尔的气喽。",
          ContentKR = "아닌가, 그럼 그날 밤 일 때문에 아직도 리듬 페실한테 화난거지?",
