            [2] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5F5C"
        },
        [10030723] = {
          Camera = "36.484009,179.044922,176.644531,0.000295,-14.206376,-130.375656,35.000023,223.128433,false,Manual,6.0,16:9 Digital Film",
          Content = "不过，要是能跟费西尔混熟，倒不是件坏事。军团的情报网四通八达，你<H>找人</>那事，兴许会有眉目。",
          ContentKR = "근데 말이지, 리듬 페실이랑 친해질 수 있으면 나쁘지 않을걸? 군단 정보망이 얼마나 넓은데, 네가 <H>사람 찾는</> 일도 어쩌면 실마리가 생길지도 몰라.",
          DialogueId = 10030723,
          GUID = "191C5FB0",
          NextDialogue = 10030724,
          Scripts = "CameraMoveTo{_delay{3},TargetPosition{\"-22.493896,92.760742,157.833984,0.000282,-9.206241,-123.576553,35.000019,109.330856,false,Manual,3.0,16:9 Digital Film\"},duration{0}}",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100307/191C5FB0"
        },
        [10030724] = {
          Camera = "7.651123,-118.004883,114.373047,0.000265,8.99109,120.035538,35.000019,156.230972,false,Manual,6.0,16:9 Digital Film",
          Content = "而且，你难道就不想亲手抓住那个不讲武德，背后偷袭的凶手吗？",
          ContentKR = "게다가, 그 뒤에서 널 습격한 나쁜 놈을 네 손으로 직접 잡고 싶지 않아?",
          DialogueId = 10030724,
          GUID = "191C5FB1",
          NextDialogue = 10030725,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100307/191C5FB1"
        },
        [10030725] = {
          Content = "至于我嘛，也想快点把“卡戎狩猎”这事解决了。现在整座外城都人心惶惶的，生怕下个就是自己。我家那破门也实在是加不了更多锁了。",
          ContentKR = "그리고, 나도 '카론 사냥' 사건을 얼른 해결하고 싶어. 지금 외성 사람들 모두가 다음에 습격당할 사람이 자신일까 봐 불안에 떨고 있잖아. 이제 우리 집 문에도 더 이상 자물쇠를 달 수 없고 말이야.",
          DialogueId = 10030725,
          GUID = "191C5F86",
          NextDialogue = 10030726,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5F86"
        },
        [10030726] = {
          Camera = "13.800354,86.224609,170.464844,0.000277,-12.408418,-140.354614,35.000015,93.577675,false,Manual,3.0,16:9 Digital Film",
          Content = "军团……贝蕾的消息……",
          ContentKR = "군단... 베레의 소식...",
          DialogueId = 10030726,
          FacialId = {
