        [10030901] = {
          Content = "队长你真了不起，军团的人都敢讹。",
          ContentKR = "대장 진짜 대단한데, 군단 사람한테도 조건을 걸고 말이야.",
          DialogueId = 10030901,
          GUID = "191C7EB2",
          NextDialogue = 10030902,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100309/191C7EB2"
        },
        [10030902] = {
          Content = "刚才不是你们说她很好说话吗？",
          ContentKR = "방금 저 녀석이 나긋나긋하다고 한 건 너희잖아?",
          DialogueId = 10030902,
          GUID = "191C7EDC",
          NextDialogue = 10030903,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100309/191C7EDC"
        },
        [10030903] = {
          Content = "那也没想到你会直接谈条件，你又不知道她脑袋里在想什么，万一……",
          ContentKR = "그래도 바로 조건을 걸 줄은 몰랐지. 저 녀석이 머릿속으로 무슨 생각을 하는지는 아무도 모르잖아, 만약에...",
          DialogueId = 10030903,
          GUID = "191C7F06",
          NextDialogue = 10030904,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100309/191C7F06"
        },
        [10030904] = {
          Content = "我在想如何快速还原凶手特征。",
          ContentKR = "어떻게 범인 특징을 빠르게 잡아낼지 생각중입니다.",
          DialogueId = 10030904,
          GUID = "191C7F30",
          NextDialogue = 10030905,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100309/191C7F30"
        },
        [10030905] = {
          Content = "嘘——她听到了，耳朵好尖。",
          ContentKR = "쉿... 들었어 들었어, 귀가 엄청 밝네.",
          DialogueId = 10030905,
          GUID = "191C7F5A",
          NextDialogue = 10030906,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100309/191C7F5A"
        },
        [10030906] = {
          Content = "过奖。时刻保持耳聪目明才能更好地执行任务。",
          ContentKR = "과찬입니다. 귀와 눈이 밝아야 퀘스트를 더 완벽하게 수행할 수 있습니다.",
          DialogueId = 10030906,
          GUID = "191C7F84",
          NextDialogue = 10030907,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100309/191C7F84"
        },
        [10030907] = {
