        },
        [10031110] = {
          Camera = "5.640625,-44.589111,120.307129,0.000218,2.797017,-73.17907,35.000015,324.824371,false,DoNotOverride,22,16:9 Digital Film",
          Content = "我记得，在这条街，我被什么东西尾随……那时，我听到的，除了它的脚步声外，还有……歌声。",
          ContentKR = "그래요, 맞아요... 목소리가 무슨 쇠 긁는 소리처럼 쉬긴 했어도 분명히 노랫소리였어요. <H>그 괴물은 노래하고 있었어요</>.",
          DialogueId = 10031110,
          GUID = "191CA0FC",
          NextDialogue = 10031111,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100311/191CA0FC"
        },
        [10031111] = {
          Camera = "105.765625,-455.361328,108.25,0.000137,4.600098,105.407356,35.000008,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "歌声？这个还没有人说过——太好了，是全新的线索！我就知道你那一下不会白挨。",
          ContentKR = "노랫소리요? 이건 아무도 몰랐던 새로운 단서군요! 괜히 당한게 아닐 줄 알았습니다.",
          DialogueId = 10031111,
          FacialId = {
            [1] = "100304:Happy01"
          },
          GUID = "191CA126",
          NextDialogue = 10031112,
          Scripts = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Confident_Start\"},Duration{2}}",
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA126"
        },
        [10031112] = {
          Camera = "124.522461,-52.962646,126.131836,0.000177,4.398307,-110.971375,35.0,941.904541,false,DoNotOverride,1.903106,16:9 Digital Film",
          Content = "喂，我说长官，人家经历挺痛苦的，这么激动不太好吧？",
          ContentKR = "저기요, 장교님. 아무리 그래도 누구한테는 끔찍한 경험인데, 그렇게 좋아하면 안 되는 거 아니에요?",
          DialogueId = 10031112,
          GUID = "191CA150",
          LookAt = {
            [1] = "100304:n(200021)",
            [2] = "100001:n(100304)"
          },
          NextDialogue = 10031113,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"200021:n(100304)\"}},PlayAnimation{ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{2}}}",
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "100304:Confident_End",
            [2] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA150"
        },
        [10031113] = {
          Camera = "90.230469,-472.615723,119.978027,0.000191,-0.400393,102.219055,40.0,941.904541,false,DoNotOverride,1.2,16:9 Digital Film",
          Content = "……抱歉。刚刚我只是想，案子有了突破口，兴许就可以早点结束这场“狩猎”，还大家一个安宁了。我没有拿你的痛苦回忆取乐的意思，万分抱歉。",
          ContentKR = "...죄송합니다. 사건의 새로운 돌파구를 찾아 이 '사냥'을 더 일찍 끝내고 모두에게 평화를 돌려줄 수 있을지도 모른다는 생각에 그만... 고통스러운 기억을 놀리려는 의도는 아니었습니다. 정말 죄송합니다.",
          DialogueId = 10031113,
