            [2] = "100304:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA17A"
        },
        [10031114] = {
          Content = "我没有介意。",
          ContentKR = "전 괜찮아요.",
          DialogueId = 10031114,
          GUID = "191CA1A4",
          ImprPlusId = 1007,
