        [10031116] = {
          Content = "我要精神损失费。",
          ContentKR = "정신적 손해배상을 받아야겠어요.",
          DialogueId = 10031116,
          GUID = "191CA1F8",
          ImprPlusId = 1010,
          NextDialogue = 10031117
        },
        [10031117] = {
          Camera = "58.354492,-249.67041,147.177734,0.000189,-3.600589,110.819168,40.0,941.904541,false,DoNotOverride,1.2,16:9 Digital Film",
          Content = "你需要多少？如果在我可以承受的范围内……",
          ContentKR = "얼마를 원하십니까? 제가 감당할 수 있을 정도라면...",
          DialogueId = 10031117,
          GUID = "191CA222",
          LookAt = {
