          VoiceName = "voice/$Locale$/story/1003/100311/191CA222"
        },
        [10031118] = {
          Camera = "124.522461,-52.962646,126.131836,0.000177,4.398307,-110.971375,35.0,941.904541,false,DoNotOverride,1.903106,16:9 Digital Film",
          Content = "这玩笑都当真？长官小姐，您是个没怎么和外城人打过交道的“桂冠卡戎”吧？",
          ContentKR = "농담을 못 하겠네. 이봐요 리듬 씨, 외성 사람들과 별로 접촉해 본 적이 없는 '계관카론'이신 것 같은데요?",
          DialogueId = 10031118,
          GUID = "191CA24C",
          NextDialogue = 10031119,
          RelatedWikiId = {
            [1] = 407003
          },
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA24C"
        },
        [10031119] = {
          Content = "要是把军团这身行头脱下来，便装去贫民窟转一圈，我看恐怕不等太阳下山，您就得赔得连鞋子都不剩了。",
          ContentKR = "그 군복을 벗으시고 편한 차림으로 빈민가에 가서 한 바퀴 돌고 오시면 해 지기 전에 신발까지 싹 다 뜯겨서 오실걸요.",
          DialogueId = 10031119,
          GUID = "191CA276",
          NextDialogue = 10031120,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "100304:Explain02_End",
            [2] = "200021:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA276"
        },
        [10031120] = {
          Camera = "149.513672,-169.366943,198.691895,0.000219,-21.601578,154.789032,35.0,324.824371,false,DoNotOverride,22,16:9 Digital Film",
          Content = "“桂冠卡戎”……很惭愧，现在的我还没有获得这份殊荣的资格。",
          ContentKR = "'계관카론'이라니요... 부끄럽습니다, 지금의 저에게 그런 영광은 가당치도 않습니다.",
          DialogueId = 10031120,
          FacialId = {
            [1] = "100304:Sad02"
          },
          GUID = "191CA2A0",
          NextDialogue = 10031121,
          Scripts = "PlayAnimation{_delay{5},ActorId{100304},AnimationId{\"DisagreeHead\"},Duration{2}}",
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA2A0"
        },
        [10031121] = {
          Camera = "114.541016,142.993408,51.0,0.000056,8.797734,-105.975571,35.0,941.904541,false,DoNotOverride,1.903106,16:9 Digital Film",
          Content = "相反，我自己就是雾区出身。我过过那种日子，知道外城卡戎人的生计有多难。所以，能帮上忙的我会尽量帮。",
          ContentKR = "오히려 그 반대로 저도 안개 구역 출신입니다. 저에게도 그런 시절이 있었기 때문에 외성에서 사는 카론의 생활이 얼마나 어려운지 압니다. 그래서 도울 수 있는 일은 최선을 다해 돕고 있고요.",
          DialogueId = 10031121,
          FacialId = {
            [1] = "100304:Sad02"
          },
          GUID = "191CA2CA",
          NextDialogue = 10031122,
          RelatedWikiId = {
            [1] = 408003
          },
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA2CA"
        },
        [10031122] = {
          Content = "更何况刚刚是我说错话在先，所以……",
          ContentKR = "그리고 제가 먼저 말실수한 건 맞잖아요, 그래서...",
          DialogueId = 10031122,
          GUID = "191CA2F4",
