        [10031601] = {
          Content = "这是……蓝色的雪？",
          ContentKR = "이건... 눈이 파란색이네요?",
          DetectiveQuestionId = 1004,
          DialogueId = 10031601,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_MoonWaterOnSnow.T_Guide_Chapter_MoonWaterOnSnow'}",
          GUID = "191CF18A",
          NextDialogue = 10031602,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100316/191CF18A"
        },
        [10031602] = {
          Content = "我看过了，这是几滴<H>月髓液</>，它滴在雪里会像花一样晕开。",
          ContentKR = "네, 저도 봤습니다, <H>액체 폭시코르</>입니다. 눈에 떨어지면 꽃처럼 피어나가죠.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031602,
          GUID = "191CF1B4",
          NextDialogue = 10031603,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100316/191CF1B4"
        },
        [10031603] = {
          Content = "很漂亮，不是吗？每次看到这种蓝色的“小花”，就感觉一天的疲惫都消失了。",
          ContentKR = "정말 예쁘지 않습니까? 매번 이렇게 파란 '꽃'을 보게 되면 하루의 피로가 전부 씻겨나가는 것 같습니다.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031603,
          GUID = "191CF1DE",
          NextDialogue = 10031604,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100316/191CF1DE"
        },
        [10031604] = {
          Content = "看这颜色，纯度还蛮高的啊。有月髓液泄漏了？",
          ContentKR = "색깔을 보니 순도가 꽤 높은 것 같네요. 액체 폭시코르 누출인 걸까요?",
          DetectiveQuestionId = 1004,
          DialogueId = 10031604,
          GUID = "191CF208",
          NextDialogue = 10031605,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100316/191CF208"
        },
        [10031605] = {
          Content = "嗯……的确有可能。不过保险起见，关于月髓液这件事，我需要跟{nickname}确认一下。",
          ContentKR = "음... 그럴 수도 있겠네요. 하지만 액체 폭시코르에 관한 일은 {nickname} 씨와 확인해 볼 것이 있어요.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031605,
          GUID = "191CF232",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100316/191CF232"
        },
