          DialogueId = 10031910,
          FinalCamera = "-585.371094,624.871887,401.661133,0.00005,-19.122007,-48.639709,30.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          GUID = "191D243C",
          LookAt = {
