          Content = "是奥特赛德啊。",
          ContentKR = "어, 아웃사이더로구나.",
          DialogueId = 10032101,
          FinalCamera = "-21.816895,363.6521,145.550781,0.000173,-3.800747,-115.966316,35.000008,100000.0,false,Manual,22.0,16:9 Digital Film",
