        [10032107] = {
          Camera = "-293.615234,-376.854492,46.109375,0.000463,6.997617,64.301308,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "对演员来说，完成演出就是在诠释生命，这比生命本身更加璀璨耀眼。不让他们演出，才是要了他们的命。",
          ContentKR = "배우에게 있어선 공연을 완성하는 게 삶의 의미지, 그건 생명 그 자체보다도 눈부시다고. 오히려 공연을 멈추게 하는 게 그들의 생명을 빼앗는 거야.",
          DialogueId = 10032107,
          FinalCamera = "-299.095703,-374.287598,46.109375,0.000462,6.997617,63.701469,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "191D448E",
