        },
        [10032108] = {
          Camera = "-601.805847,769.078125,-62.539062,-3.000002,9.000303,-56.889706,35.000008,945.516907,false,DoNotOverride,1.608127,16:9 Digital Film",
          Content = "所有人准备，今天第三场排练五分钟后开始。",
          ContentKR = "다들 준비해. 5분 뒤 오늘의 세 번째 리허설을 시작한다.",
          DialogueId = 10032108,
          FinalCamera = "-601.805847,769.078125,-32.179688,-3.000001,7.000288,-56.890057,35.000008,945.516907,false,DoNotOverride,1.608127,16:9 Digital Film",
          GUID = "191D44B8",
          LookAt = {
            [1] = "100313:n(100313)"
          },
          Scripts = "PlayAnimation{_delay{4},ActorId{100313},AnimationId{\"Confident_Start\"},Duration{2}}",
          SpeakNpcId = 100313,
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100313:p(180)"
          },
          VoiceName = "voice/$Locale$/story/1003/100321/191D44B8"
        },
        [10032109] = {
          Content = "……呜，真是一点都不肯配合呢。",
          ContentKR = "...힝, 정말 하나도 협조하지 않잖아.",
          DialogueId = 10032109,
          GUID = "191D44E2",
          NextDialogue = 10032110,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100321/191D44E2"
        },
        [10032110] = {
          Content = "分头问问看吧，至少她老人家没阻止我们。",
          ContentKR = "흩어져서 물어보자, 적어도 막진 않았잖아.",
          DialogueId = 10032110,
          GUID = "191D450C",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100321/191D450C"
        },
        [10032111] = {
          Content = "跟你们说过多少次，灯用完记得关！再忘了关灯或者没把道具放回仓库，我就把这些道具通通塞到你们的嘴里！",
          ContentKR = "몇 번을 말하는 거야. 불은 다 쓰면 끄라니까! 또 한 번 불 끄는 걸 잊거나 쓰고 난 소품을 창고에 다시 넣지 않으면, 이 소품들을 전부 다 입에 쑤셔 넣을 줄 알아!",
          DialogueId = 10032111,
          Duration = 17,
          GUID = "191D4536",
          SpeakNpcId = 100329,
          VoiceName = "voice/$Locale$/story/1003/100321/191D4536"
        },
        [10032112] = {
          Content = "诶，钉子呢，怎么偏偏在加固舞台架子的时候找不到了。",
          ContentKR = "어? 못 어디 갔지? 하필 무대 골조 보강하려니까 안 보이네.",
          DialogueId = 10032112,
          Duration = 9,
          GUID = "191D450D",
          VoiceName = "voice/$Locale$/story/1003/100321/191D450D"
        },
        [10032113] = {
          Content = "丹尼斯呢？还有几天就正式上台了，就差他没试妆拍定妆照了。",
          ContentKR = "데니스는 어디 간 거야? 며칠 뒤면 공연인데, 분장 테스트랑 컨셉 사진이 데니스만 아직이야.",
          DialogueId = 10032113,
          Duration = 10,
          GUID = "191D450E",
          VoiceName = "voice/$Locale$/story/1003/100321/191D450E"
        },
        [10032114] = {
          Content = "“秉烛起舞，放声歌唱在这个雪夜。”",
          ContentKR = "\"촛불 들고 춤추며, 이 눈 내리는 밤에 소리 높여 노래하리.\"",
          DialogueId = 10032114,
          Duration = 6,
          GUID = "191D450F",
          SpeakNpcId = 100370,
          VoiceName = "voice/$Locale$/story/1003/100321/191D450F"
        },
        [10032115] = {
          Content = "第三幕的灯光设计得改一下。我们要模拟的是蜡烛被逐个点亮的光线变化，明白吗？逐、个、点、亮！",
          ContentKR = "3막 조명 디자인에 수정이 필요해. 우리가 표현하려는 건 촛불이 하나씩 켜지는 조명 변화라고. 알겠어? 하, 나, 씩, 켜, 지, 는, 거!",
          DialogueId = 10032115,
          Duration = 15,
          GUID = "191D4510",
          VoiceName = "voice/$Locale$/story/1003/100321/191D4510"
        },
        [10032116] = {
          Content = "你又抢拍子了，打算几天后就用这种状态上台吗？重来。",
          ContentKR = "또 박자 놓쳤잖아. 며칠 뒤에 그 꼴로 무대 설래? 다시!",
          DialogueId = 10032116,
          Duration = 9,
          GUID = "191D4511",
          VoiceName = "voice/$Locale$/story/1003/100321/191D4511"
        },
        [10032117] = {
          Content = "抱歉……",
          ContentKR = "미안...",
          DialogueId = 10032117,
          Duration = 2,
          GUID = "191D4512",
          VoiceName = "voice/$Locale$/story/1003/100321/191D4512"
        },
        [10032118] = {
          Content = "贝尔，这些东西等会排练要用，帮忙搬一下。",
          ContentKR = "벨, 이따 리허설 때 이 물건들 잠깐 써야 하니까, 옮기는 것 좀 도와줘.",
          DialogueId = 10032118,
          Duration = 7,
          GUID = "191D4513",
          VoiceName = "voice/$Locale$/story/1003/100321/191D4513"
        },
        [10032119] = {
          Content = "来了来了。",
          ContentKR = "알겠어, 지금 가.",
          DialogueId = 10032119,
          Duration = 2,
          GUID = "191D4514",
          VoiceName = "voice/$Locale$/story/1003/100321/191D4514"
        },
        [10032201] = {
