        [10032204] = {
          Camera = "-38.398422,-255.859344,70.714844,0.000165,6.599745,108.419289,40.0,340.239532,false,Manual,3.429005,16:9 Digital Film",
          Content = "针脚不对，花纹不对，盖雷亚剧院才不会用这种劣质货。谁派你来的？你是不是哪里的小报记者，想造谣我们布景低劣？",
          ContentKR = "바느질도, 패턴도 잘못됐어, 갈레아 극장은 이런 쓰레기 같은 물건 안 써. 누가 보냈지? 너 어디 기자야? 우리 극장 소품이 형편없다는 헛소문 퍼뜨리러 온 건가?",
          DialogueId = 10032204,
          FinalCamera = "-38.398422,-255.859344,70.714844,0.000166,7.799755,108.219391,40.0,340.239532,false,Manual,3.429005,16:9 Digital Film",
          GUID = "191D5478",
          NextDialogue = 10032205,
          SpeakNpcId = 100329,
          TalkActionId = {
            [1] = "100329:Disagree",
            [2] = "100001:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100322/191D5478"
        },
        [10032205] = {
          Camera = "-103.923096,98.783195,108.738281,0.000139,7.197059,-62.586468,35.000011,284.991394,false,DoNotOverride,3.584893,16:9 Digital Film",
          Content = "啊不是不是，别激动，这是我们在“卡戎狩猎”案发现场捡到的，就问问而已。",
          ContentKR = "아, 아닙니다. 침착하세요. 이건 저희가 '카론 사냥' 사건의 현장에서 주운 겁니다. 그냥 한번 여쭤보려고요.",
          DialogueId = 10032205,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "-96.228012,102.699203,108.738281,0.000139,7.197059,-64.586884,35.000011,284.991394,false,DoNotOverride,3.584893,16:9 Digital Film",
          GUID = "191D54A2",
          NextDialogue = 10032206,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100322/191D54A2"
        },
        [10032206] = {
          Camera = "134.718857,678.446716,706.917969,-0.001009,-39.19453,-108.145706,40.0,340.239532,false,DoNotOverride,3.429005,16:9 Digital Film",
          Content = "……你这小报记者，是想抹黑剧院，说我们和杀人案有关？！",
          ContentKR = "...어디서 굴러온 기자 놈이길래 극장에 누명을 씌우는 거야! 우리 극장이 살인 사건과 연관이 있다고?!",
          DialogueId = 10032206,
          FacialId = {
            [1] = "200021:Confident01"
          },
          FinalCamera = "161.966888,668.893982,706.917969,-0.001007,-39.194515,-110.545403,40.0,340.239532,false,DoNotOverride,3.429005,16:9 Digital Film",
          GUID = "191D54CC",
          NextOptions = {
