          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-36.183578,-243.968689,115.859375,0.000218,2.599987,118.410843,35.000008,100000.0,false,Manual,22.0,16:9 Digital Film\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-36.183578,-243.968689,121.722656,0.000225,1.199948,118.210846,35.000008,100000.0,false,Manual,22.0,16:9 Digital Film\"},duration{5}}}",
          SpeakNpcId = 100329,
          TalkActionId = {
            [1] = "100329:Angry01_Start",
            [2] = "200021:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100322/191D54CC"
        },
        [10032207] = {
          Content = "都说了我们不是小报记者了！",
          ContentKR = "기자 아니라고 말했잖아요!",
          DialogueId = 10032207,
          GUID = "191D54F6",
          ImprPlusId = 1007,
          NextDialogue = 10032209
        },
        [10032208] = {
          Content = "再污蔑我，就把这块在垃圾桶里抹了一圈的布条塞到你嘴里。",
          ContentKR = "자꾸 그러면 이 쓰레기통을 한 바퀴 닦은 천 쪼가리를 당신 입에 쑤셔 넣을 거예요.",
          DialogueId = 10032208,
          GUID = "191D5520",
          ImprPlusId = 1010,
          NextDialogue = 10032209
        },
        [10032209] = {
          Camera = "-91.937477,-19.004244,138.511719,0.000139,-2.397847,-94.204163,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "我们是来协助卫戍部队调查“卡戎狩猎”事件的，我们在案发现场捡到了这块疑似出自剧院的绒布，请你配合调查。",
          ContentKR = "저흰 방위대를 도와 '카론 사냥' 사건을 조사하러 왔어요. 사건 현장에서 극장에서 나온 것으로 추정되는 벨벳 천 조각을 주웠습니다. 조사에 협조해 주시길 바랍니다.",
          DialogueId = 10032209,
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "-85.894508,-19.564302,138.511719,0.000138,-2.597869,-96.603889,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
