            [2] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100322/191D5521"
        },
        [10032210] = {
          Camera = "-82.898415,-30.874966,169.933594,0.000135,-14.003205,122.032799,45.000011,284.991394,false,DoNotOverride,3.584893,16:9 Digital Film",
          Content = "好吧，看来是我太敏感了，不好意思啊。",
          ContentKR = "방위대... 뭐, 내가 너무 예민했나 봐. 미안하구만.",
          DialogueId = 10032210,
          FacialId = {
