        [10032211] = {
          Camera = "195.853271,-530.033142,237.539062,7.201614,-13.600497,120.839867,45.0,284.991394,false,DoNotOverride,3.584893,16:9 Digital Film",
          Content = "自从两年前那件破事开始，就总有该死的小报记者给剧团造谣，说剧团都是骗子，还害得团长她老人家大病一场。",
          ContentKR = "2년 전 그 사건 뒤로 자꾸 빌어먹을 삼류 기자들이 우리 극단엔 사기꾼들뿐이라고 오명을 씌우고 다녀서 말이지. 단장님은 그것 때문에 앓아눕기까지 하셨다고.",
          DialogueId = 10032211,
          FacialId = {
            [1] = "100329:CM_Sad01"
          },
          FinalCamera = "208.112061,-522.162048,239.332031,7.201801,-13.600518,122.240273,45.0,284.991394,false,DoNotOverride,3.584893,16:9 Digital Film",
          GUID = "191D5574",
          NextDialogue = 10032212,
          SpeakNpcId = 100329,
          TalkActionId = {
            [1] = "100329:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100322/191D5574"
        },
        [10032212] = {
          Camera = "-110.570213,148.667206,110.816406,0.000218,-0.000676,-90.985168,35.000011,315.079285,false,Manual,3.120782,16:9 Digital Film",
          Content = "反正这布肯定不是我们剧院的，道具清单都在那边放着，信不过你们就自己去看，我该继续干活了！",
          ContentKR = "아무튼 이 천 쪼가리는 우리 극장 게 아니야. 소품 목록은 저기 있으니까 못 믿겠으면 확인해 보든가. 난 일하러 가야 돼!",
          DialogueId = 10032212,
          FacialId = {
            [1] = "100329:CM_Angry01"
          },
          FinalCamera = "-107.103416,148.607758,112.542969,0.000218,0.199332,-92.38517,35.000011,315.079285,false,Manual,3.120782,16:9 Digital Film",
          GUID = "191D559E",
          NextDialogue = 10032213,
          Scripts = "PlayAnimation{_delay{2},ActorId{100329},AnimationId{\"Disagree\"},Duration{2}}",
          SpeakNpcId = 100329,
          TalkActionId = {
            [1] = "100329:Sigh_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100322/191D559E"
        },
        [10032213] = {
          Camera = "-1017.098938,642.821167,548.960938,0.000052,-21.599352,-39.762207,55.000011,1185.884644,false,Manual,1.2,16:9 Digital Film",
          Content = "喂，你们几个臭小子，假发摘了就给我放回头模上，别跑，我今天非得把这些假发缝你们头皮上不可！",
          ContentKR = "이 자식들아, 가발을 벗었으면 마네킹에 다시 씌워놔야지. 거기 안 서? 오늘 이 가발들 내가 너희 두피에 꿰매준다!",
          DialogueId = 10032213,
          FinalCamera = "-1008.682922,652.714722,548.960938,0.000058,-21.199362,-42.361965,55.000011,1185.884644,false,Manual,1.2,16:9 Digital Film",
          GUID = "191D55C8",
          LookAt = {
            [1] = "100329:n(100329)"
          },
          Scripts = "MoveTo{_delay{3},ActorId{100329},TargetPoint{\"cp2fixsimple13Point01\"},MoveSpeed{80},Visibility{\"Show\"}}",
          SpeakNpcId = 100329,
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100329:p(90)"
          },
          VoiceName = "voice/$Locale$/story/1003/100322/191D55C8"
        },
        [10032214] = {
          ContentKR = "10월 08일, 의상, 침낭 준비 완료. 확인자: 몬델리 (참고: 식량 비축이 부족하여, <H>남은 한 달간의 집중 리허설을 준비하기 위해선 누군가에게 부탁해서 한 번 더 들여야 한다.</>)\n...\n11월 12일, 새로운 마이크 3개 교체 완료. 확인자: 그린델 (참고: 마이크 하나가 소리가 엄청 크다. 푸치 단장님이 그대로 괜찮다고, 바꾸지 말라고 하셨다.)\n11월 14일, 빨간 무대 커튼 교체 완료, 금빛 무대 커튼 창고로 반환 완료. 확인자: 벨\n...\n11월 24일, 잃어버렸던 가발 5개 회수 완료. 확인자: 벨 (참고: 탈의실 구석에 물건이 들어가면 찾기 어렵다. 오늘 가서 한번 치워야겠다.)\n11월 25일, 화관 15개 준비 완료, 승마화 9켤레 준비 완료. 확인자: 몬델리",
          DialogueId = 10032214,
          DialoguePanelType = "{type:showtext;topic:READ_NAME_2000046;content:READ_TEXT_2000046}",
          GUID = "191D55F2",
          VoiceName = "voice/$Locale$/story/1003/100322/191D55F2"
        },
        [10032301] = {
          Camera = "27.207031,22.800903,135.363281,7.222204,-1.399963,-168.822205,30.000002,334.113678,false,DoNotOverride,2.014144,16:9 Digital Film",
          Content = "你的喉咙太紧张了，放松，将口腔打开，用气来托住你的声音，发声位置要靠后，想象将你的声音集中在后脑勺上的一点。",
          ContentKR = "목에 힘이 너무 들어갔어요, 힘 빼고 입을 여세요. 공기로 목소리를 받쳐주는 거예요. 발성 위치는 조금 더 뒤로 와야 해요. 소리를 뒤통수 위쪽의 한 점에 집중시킨다고 상상해 보세요.",
          DialogueId = 10032301,
          FinalCamera = "27.207031,22.800903,135.363281,7.22229,-0.199885,-168.62204,30.000002,334.113678,false,DoNotOverride,2.014144,16:9 Digital Film",
          GUID = "191D6462",
          LookAt = {
            [1] = "100318:n(100319)"
          },
          NextDialogue = 10032302,
          Scripts = "SEQ{PlayAnimation{_delay{2},ActorId{100318},AnimationId{\"Explain01_Start\"},Duration{2}},CameraMoveTo{_delay{3},TargetPosition{\"-164.449219,9.727783,158.671875,7.202853,-7.800021,-13.643471,30.0,334.113678,false,Manual,2.014144,16:9 Digital Film\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-164.449219,9.727783,158.671875,7.203086,-6.799986,-12.844124,30.000002,334.113678,false,Manual,2.014144,16:9 Digital Film\"},duration{5}}}",
          SpeakNpcId = 100318,
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100323/191D6462"
