        [10032302] = {
          Camera = "87.0,17.469238,161.0,-10.803343,-34.997726,-25.183821,35.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "抱歉，薇奥莱塔老师。我，我再试试……",
