        [10032303] = {
          Camera = "-27.283203,5.417847,146.285156,0.000012,-1.000759,-169.428741,30.0,507.051575,false,DoNotOverride,1.888818,16:9 Digital Film",
          Content = "巡演这么久回来，这孩子还是没什么长进……果然不是谁都能像帕西法尔那样，有副天生的好嗓子。",
          ContentKR = "투어를 이렇게나 오래 다녀왔는데, 이 아이는 여전히 발전이 없어... 역시 파르지팔처럼 좋은 목소리를 타고나는 사람은 드무네. ",
          DialogueId = 10032303,
          FinalCamera = "-28.900391,13.89624,146.285156,0.000012,-1.000759,-165.827866,30.0,507.051575,false,DoNotOverride,1.888818,16:9 Digital Film",
