          },
          ToFinalCameraBlendTime = 0.25,
          VoiceName = "voice/$Locale$/story/1003/100323/191D64E0"
        },
        [10032305] = {
          Camera = "-480.984375,-299.570007,14.378906,0.000082,7.997612,22.783634,30.0,507.051575,false,DoNotOverride,1.888818,16:9 Digital Film",
          Content = "加油，加油，我可以的……这是今年最重要的演出……我们排练了这么久，一定没问题的，没问题的……",
          ContentKR = "힘내, 난 할 수 있다... 이건 올해 들어 가장 중요한 공연이야... 오랫동안 연습했으니까, 꼭 아무 문제 없을 거야...",
          DialogueId = 10032305,
          FinalCamera = "-446.701172,-285.171936,19.574219,0.000082,7.997612,22.783634,30.0,507.051575,false,DoNotOverride,1.888818,16:9 Digital Film",
