        [10032306] = {
          Camera = "76.632812,-203.543945,113.671875,0.00036,-21.404112,-99.75795,35.000023,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "喂——别走啊！魔王大人在和你说话呢！",
          ContentKR = "야, 가지 마! 마왕님이 말하고 있잖아!",
          DialogueId = 10032306,
