        [10032312] = {
          Camera = "60.613281,172.818604,110.851562,0.00027,3.197088,-73.568634,35.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "不会的，不会的。<H>大家都把自己关在这里，连门都没出过。</>不信，你去看那边的日程表……在银烛狂欢结束前，我们要一直排练……",
          ContentKR = "그럴 리가 없습니다. <H>다들 여기 콕 박혀서 문밖을 나서지도 않았어요. </>못 믿겠다면 저기 일정표를 봐요... 우린 은촛불 축제가 끝나기 전까지 연습을 멈출 수 없어요...",
          DialogueId = 10032312,
          FinalCamera = "74.958984,177.049438,110.851562,0.00027,3.197088,-76.368439,35.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
