        },
        [10032315] = {
          Camera = "17.898438,-172.325745,200.007812,0.002227,-29.792526,-136.767868,35.0,100000.0,false,DoNotOverride,2.8,16:9 Digital Film",
          Content = "这一刻没有人管面具背后的你是索拉还是卡戎，只要一起唱，一起跳，一起喊就够了。",
          ContentKR = "그 순간만큼은 가면 뒤에 카론이든 솔라든 상관 없이, 그냥 같이 노래하고 춤추고 소리 지르는 걸로 충분한 거지.",
          DialogueId = 10032315,
          FinalCamera = "20.896484,-175.429382,200.007812,0.002231,-29.79254,-140.567673,35.0,100000.0,false,DoNotOverride,2.8,16:9 Digital Film",
          GUID = "191D66AE",
          NextDialogue = 10032316,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D66AE"
        },
        [10032316] = {
          Camera = "76.511719,-140.939392,119.402344,-0.00003,11.462054,-69.546867,35.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "真难想象冰湖城还有这样的节日。我觉得这儿的人还挺……严肃的。",
          ContentKR = "아이스레이크 시티에 그런 축제가 있다는 건 정말 상상하기 어렵네. 난 여기 사람들이 꽤... 엄숙하다고 생각했거든.",
          DialogueId = 10032316,
          FinalCamera = "76.511719,-140.939392,119.402344,-0.000031,9.461997,-66.347099,35.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "191D66D8",
          NextDialogue = 10032317,
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D66D8"
        },
        [10032317] = {
          Camera = "160.525391,-52.564697,106.691406,0.00035,9.3942,-138.753281,45.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "哈哈，人啊，不就是平时越憋得透不过气，就越想大声喊叫出来么。",
          ContentKR = "하하, 인간이 그렇잖아. 평소에 숨 막히는 느낌을 많이 받을수록 큰 소리로 외치고 싶어 하지.",
          DialogueId = 10032317,
          FinalCamera = "152.615234,-43.393677,106.691406,0.000343,9.3942,-136.353165,45.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "191D6702",
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"4283.351562,3130.114258,1144.804688,0.000308,-11.204836,-141.568665,55.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"4543.302734,3336.384766,1210.519531,0.000308,-11.204836,-141.568665,55.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film\"},duration{5}}}",
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D6702"
        },
        [10032318] = {
          Content = "厚厚的点名册，详细地记录了每位工作人员一天的行程，除了排练，连吃饭睡觉和如厕的行程都被记录在内。\n不知是剧团长狠心地将所有人“软禁”在剧院之内，还是剧团长为了保护自己的演员，而不得不时刻关注每个人的动向。",
          ContentKR = "두툼한 출석부, 스태프들마다의 하루 일과가 상세하게 기록되어 있다. 리허설 외, 식사와 취침, 심지어 화장실에 다녀온 것까지 전부 기록되어 있다.\n극단장이 독한 마음을 먹고 사람들을 극장 속에 '가둔' 것인지, 아니면 극단장이 자신의 배우들을 보호하기 위해 \n어쩔 수 없이 그들의 일거수일투족을 지켜보는 것인지 알 수 없다.",
          DialogueId = 10032318,
          GUID = "191D672C",
          VoiceName = "voice/$Locale$/story/1003/100323/191D672C"
        },
        [10032401] = {
          Camera = "-1135.283203,2455.108398,-2052.257812,7.20768,17.796782,-75.54464,20.086287,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "哇，那个麦克风好大声！",
          ContentKR = "우와, 저 마이크 소리 엄청 크네!",
          DialogueId = 10032401,
          FinalCamera = "-1135.283203,2455.108398,-2052.257812,7.207845,20.796669,-75.344231,20.086287,100000.0,false,Manual,22.0,16:9 Digital Film",
