        [10032403] = {
          Camera = "-1084.892578,2085.785645,-1882.074219,-0.000794,-20.80938,110.409325,35.000008,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "我看了眼点名册，大家确实都一个多月没出剧院了，冬眠的熊都比他们出门勤快。",
          ContentKR = "출석부를 확인해 봤는데, 다들 한 달 동안 극장 바깥으로 안 나간 게 맞는 것 같아, 동면 중인 곰도 이 사람들보다는 외출이 잦겠더라고.",
          DialogueId = 10032403,
          FinalCamera = "-1096.111328,2081.808105,-1882.074219,-0.000793,-20.80938,105.409744,35.000008,100000.0,false,Manual,22.0,16:9 Digital Film",
          GUID = "191D751E",
