        },
        [10032503] = {
          Camera = "118.575439,1.040527,107.395508,0.000438,5.801542,-99.6222,35.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "可惜剧院没查到什么有用的线索。工厂那边呢？",
          ContentKR = "극장에선 쓸만한 단서를 찾지 못한 게 아쉽지만 말이죠. 공장 쪽은요?",
          DialogueId = 10032503,
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "128.399414,-0.741699,107.395508,0.000438,5.801542,-103.222313,35.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "191D855D",
          NextDialogue = 10032505,
          Scripts = "PlayAnimation{_delay{5.5},ActorId{100304},AnimationId{\"Give\"},Duration{2}}",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:DisagreeHead",
            [2] = "100304:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D855D"
        },
        [10032504] = {
          Content = "因为剧院没有什么线索，所以查得比较快。",
          ContentKR = "극장은 쓸만한 단서가 없어서 조사가 빠르게 끝났어요.",
          DialogueId = 10032504,
          GUID = "191D8586",
          ImprPlusId = 1007,
          NextDialogue = 10032505
        },
        [10032505] = {
          Camera = "139.100586,559.121094,255.143799,0.000448,-14.799346,-99.026108,35.000011,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "工厂那边，工人们的嫌疑都排除了，但我在一家机车工厂找到了这个。",
          ContentKR = "공장 쪽 일꾼들의 혐의는 다 배제했습니다. 그런데 한 바이크 공장에서 이걸 찾았습니다.",
