        [10032507] = {
          Camera = "103.700073,-16.408691,103.009521,0.000502,8.39629,95.988274,35.000015,149.275681,false,Manual,22.0,16:9 Digital Film",
          Content = "你闻闻。",
          ContentKR = "냄새를 한번 맡아보세요.",
          DialogueId = 10032507,
          GUID = "191D8604",
          NextDialogue = 10032508,
