        [10032508] = {
          Camera = "83.609619,-27.326172,111.722656,0.000411,-23.398956,-52.766521,35.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "唔……！好腥好腥——这是……霜脊鱼的味道！水仙平原前段时间才买过一批，白收拾它们收拾了很久呢。",
          ContentKR = "윽...! 비린내, 이건... 마블 피쉬의 냄새야! 지난번 아스포델에서 사 봤는데, 스노우 이거 치우느라 엄청 고생했어.",
          DialogueId = 10032508,
          FacialId = {
            [1] = "200002:Shock01"
          },
          FinalCamera = "80.201172,-29.955078,111.722656,0.000412,-23.398956,-51.566967,35.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "191D862E",
          LookAt = {
