        },
        [10032509] = {
          Camera = "126.557007,23.318359,114.344238,0.00044,4.800209,-130.965836,30.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "哦呦，小矮子是不是很会跳芭蕾啊，刚才在剧院该让你来一手的。",
          ContentKR = "하이고, 우리 꼬맹이 발레 좀 추나 봐. 아까 극장에서 한번 시켜볼 걸 그랬네.",
          DialogueId = 10032509,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "131.013794,19.098633,114.344238,0.000441,4.800209,-132.566101,30.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "191D8658",
          LookAt = {
