          },
          NextDialogue = 10032510,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:ConfidentLR_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D8658"
        },
        [10032510] = {
          Camera = "-38.285278,-94.880859,166.193604,0.000415,-29.598597,-7.961472,30.000013,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          CameraBlendCurve = "easeInQuad",
          Content = "芭蕾？我不会呀……怎么啦？",
          ContentKR = "발레? 나 발레 할 줄 모르는데... 왜?",
          DialogueId = 10032510,
          FacialId = {
            [1] = "200002:Happy01"
          },
          FinalCamera = "-37.809326,-91.476074,166.193604,0.000415,-29.598597,-9.561579,30.000013,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
