        [10032511] = {
          Camera = "260.250977,-33.956055,52.295166,0.000392,13.198178,-153.158432,30.000002,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "真可惜，我想你天天在水仙平原收拾餐桌，肯定要一直狠狠踮着脚尖，这么好的底子不学芭蕾可惜了。",
          ContentKR = "아쉽네, 아니 너 아스포델에서 밥상 치울 때면 맨날 까치발 들고 할 것 같아서 말이야. 기초가 좋은데 발레를 안 배우면 너무 아깝잖아.",
          DialogueId = 10032511,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "261.581543,-36.869141,52.295166,0.000392,13.198186,-154.158371,30.000002,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
