            [2] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D86AC"
        },
        [10032512] = {
          Camera = "34.129639,-43.955566,119.972656,0.000447,-25.599173,-26.162193,30.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "哪有那么麻烦，踩个板条箱就够……可恶！给你一拳！",
          ContentKR = "그렇게 번거롭진 않아. 상자 하나 놓고 그 위에 올라가서 하면 충분... 젠장! 한 대 맞을래?!",
          DialogueId = 10032512,
