        },
        [10032513] = {
          Camera = "82.171143,-65.495605,193.210693,0.000503,-28.600132,-144.951599,40.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "不闹了不闹了。长官，你是什么意思？工人把霜脊鱼泡在了月髓液里？",
          ContentKR = "장난이야 장난. 리듬 장교님, 방금 그게 무슨 뜻이죠? 일꾼들이 마블 피쉬를 액체 폭시코르 속에 담갔다는 말씀인가요?",
          DialogueId = 10032513,
          FacialId = {
            [1] = "200021:None"
          },
          FinalCamera = "83.917847,-68.359375,193.210693,0.000498,-28.600119,-147.551743,40.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "191D8700",
          LookAt = {
            [1] = "100304:n(200021)",
            [2] = "200002:n(200002)"
          },
          NextDialogue = 10032514,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{4},TargetPosition{\"139.094971,188.817871,126.572998,0.000448,-0.80002,-121.158913,40.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"142.020386,187.085938,126.572998,0.000448,-0.80002,-122.359116,40.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film\"},duration{5}}},PlayAnimation{_delay{5},ActorId{200021},AnimationId{\"Talk01_Start\"}},LookAt{_delay{2},LookAtDescription{\"200021:n(100304)\"}}}",
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200002:Angry01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D8700"
        },
        [10032514] = {
          Camera = "-1.008301,-498.653809,218.979004,0.000549,-14.798089,81.42189,40.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "不，你仔细看，这不是月髓液，是霜脊鱼的<H>鱼油</>，只是它们颜色看起来相似而已。",
          ContentKR = "아닙니다, 잘 보세요. 이건 액체 폭시코르가 아니라, 마블 피쉬의 <H>생선 기름</>입니다. 그냥 색깔이 비슷할 뿐이죠.",
          DialogueId = 10032514,
          FinalCamera = "-1.008301,-498.653809,218.979004,0.000546,-13.998042,81.221817,40.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "191D872A",
          LookAt = {
