        [10032601] = {
          Content = "这一片住着的都是渔夫，长官你要先从哪家找起？",
          ContentKR = "이 근처에 사는 사람들은 전부 어부예요. 리듬 장교님, 어디서부터 찾아야 할까요?",
          DialogueId = 10032601,
          GUID = "191D959A",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100326/191D959A"
        },
        [10032602] = {
          Content = "喵——喵——",
          ContentKR = "야옹~ 야옹~",
          DialogueId = 10032602,
          GUID = "191D95C4",
          SpeakNpcId = 100320,
          SpeakNpcName = "Cp2CharacterName29",
          VoiceName = "voice/$Locale$/story/1003/100326/191D95C4"
        },
        [10032603] = {
          Content = "喵……呜喵？",
          ContentKR = "야옹... 냥?",
          DialogueId = 10032603,
          GUID = "191D95EE",
          NextDialogue = 10032604,
          SpeakNpcId = 100320,
          SpeakNpcName = "Cp2CharacterName29",
          VoiceName = "voice/$Locale$/story/1003/100326/191D95EE"
        },
        [10032604] = {
          Content = "（这只猫一直在盯着黎瑟看……是闻到了什么特别的味道吗？）",
          ContentKR = "(고양이가 리듬을 빤히 쳐다보고 있다... 뭔가 특별한 냄새를 맡은 걸까?)",
          DialogueId = 10032604,
          DisableMouth = 1,
          GUID = "191D9618",
          NextDialogue = 10032605,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100326/191D9618"
        },
        [10032605] = {
          Content = "黎瑟长官，那罐鱼油借用一下。",
          ContentKR = "리듬 장교님, 그 생선 기름 잠시 줘 보세요.",
          DialogueId = 10032605,
          GUID = "191D9642",
          NextDialogue = 10032606,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100326/191D9642"
        },
        [10032606] = {
          Content = "给，你是发现什么了吗？",
          ContentKR = "여기요, 뭔가 발견하셨나요?",
          DialogueId = 10032606,
          GUID = "191D966C",
          NextDialogue = 10032607,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100326/191D966C"
        },
        [10032607] = {
          Content = "嗯，我确认一下。",
          ContentKR = "네, 확인해 볼 게 있어요.",
          DialogueId = 10032607,
          GUID = "191D9696",
          NextDialogue = 10032608,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100326/191D9696"
        },
        [10032608] = {
          Content = "喵——喵喵！",
          ContentKR = "냥... 냥냥!",
          DialogueId = 10032608,
          GUID = "191D96C0",
          SpeakNpcId = 100320,
          SpeakNpcName = "Cp2CharacterName29",
          VoiceName = "voice/$Locale$/story/1003/100326/191D96C0"
        },
        [10032609] = {
          Content = "我们跟着那只猫走吧，它似乎想带我们去什么地方。",
          ContentKR = "저 고양이를 따라가 봐요. 우릴 어딘가로 데려가려는 것 같아요.",
          DialogueId = 10032609,
          GUID = "191D96EA",
          NextDialogue = 10032610,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100326/191D96EA"
        },
        [10032610] = {
          Content = "真敏锐，不愧是驯兽师出身。",
          ContentKR = "예리하시군요, 조련사 출신답습니다.",
          DialogueId = 10032610,
          GUID = "191D96EB",
          NextDialogue = 10032611,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100326/191D96EB"
        },
        [10032611] = {
          Content = "（……奥特赛德，我谢谢你。）",
          ContentKR = "(...아웃사이더, 나중에 보자.)",
          DialogueId = 10032611,
          DisableMouth = 1,
          GUID = "191D96EC",
          NextDialogue = 10032612,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100326/191D96EC"
        },
        [10032612] = {
          Content = "喵——喵喵喵喵！",
          ContentKR = "야옹~ 냥냥냥냥!",
          DialogueId = 10032612,
          GUID = "191D9714",
          SpeakNpcId = 100320,
          SpeakNpcName = "Cp2CharacterName29",
          VoiceName = "voice/$Locale$/story/1003/100326/191D9714"
        },
        [10032613] = {
          Content = "猫咪消失在了前方。",
          ContentKR = "고양이가 앞쪽에서 사라졌다.",
          DialogueId = 10032613,
          GUID = "191D973E",
          VoiceName = "voice/$Locale$/story/1003/100326/191D973E"
        },
        [10032614] = {
          Content = "你这个伤害小仆从的坏家伙，居然藏在这里！",
          ContentKR = "내 시종을 괴롭힌 나쁜 놈, 여기 숨어 있었네!",
          DialogueId = 10032614,
          GUID = "191D9768",
          NextDialogue = 10032615,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100326/191D9768"
        },
        [10032615] = {
          Content = "啊？卫戍部队的？别打我别打我，我招，我招！",
          ContentKR = "엇? 방위대? 때리지 말아 주십쇼. 다 얘기할게요, 다!",
          DialogueId = 10032615,
          GUID = "191D9792",
          SpeakNpcId = 100314,
          VoiceName = "voice/$Locale$/story/1003/100326/191D9792"
