          GUID = "191DB790",
          NextDialogue = 10032809
        },
        [10032809] = {
          Camera = "151.968018,0.902451,133.101074,0.000211,0.200609,-95.606949,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "不是的，我没有质疑卫戍部队的意思……咳、咳！",
          ContentKR = "아닙니다, 방위대를 거스를 의도는 없었어요... 쿨럭, 쿨럭!",
