        [10032817] = {
          Camera = "363.140869,-823.144897,336.696289,0.00064,-16.018269,108.05632,40.0,974.299927,false,Manual,1.2,16:9 Digital Film",
          Content = "第一件事是，如果我回不来，就请你们去卫戍部队下属治安署，找达米安署长，把我的……死讯告诉他，请他继续调查“卡戎狩猎”，千万不要中止。",
          ContentKR = "첫 번째 일은, 만약에 제가 돌아오지 못한다면 방위대 산하 치안서의 다미안 서장을 찾아가셔서 저의... 사망 소식을 전해주세요. 그리고 '카론 사냥'의 조사를 무슨 일이 있어도 멈추지 말아 달라고 전해주세요.",
          DialogueId = 10032817,
          FinalCamera = "367.579041,-821.69812,336.696289,0.00064,-16.018269,108.05632,40.0,974.299927,false,Manual,1.2,16:9 Digital Film",
