        [10032818] = {
          Camera = "190.108154,132.64003,140.636475,0.000663,-2.617219,-105.706673,45.000011,283.341888,false,Manual,4.333576,16:9 Digital Film",
          Content = "第二件事是，请署长帮我把这枚奖章转交给驻扎在内城的第六军团，交给一个叫布鲁斯·费西尔的年轻人。",
          ContentKR = "두 번째는 서장님께 부탁해서 이 훈장을 내성에 주둔하고 있는 제6군단의 블루스 페실이라는 젊은이에게 전달해 주세요.",
          DialogueId = 10032818,
          FacialId = {
