        [10032825] = {
          Content = "那怪物打人疼死了，我得亲自报仇才行。",
          ContentKR = "그 괴물 녀석에게 맞은 게 너무 아파. 직접 복수해야겠어.",
          DialogueId = 10032825,
          GUID = "191DBA5A",
