        },
        [10032826] = {
          Camera = "73.926605,-238.322037,143.751465,0.00736,-3.820944,66.994003,35.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "天快黑了，黎瑟长官，你也不想磨磨蹭蹭的，害得今天晚上又有无辜的人被袭击吧？",
          ContentKR = "날이 저물고 있어요, 리듬 장교님. 설마 꾸물거리다가 오늘 밤 또 죄 없는 사람들이 공격당하게 만들고 싶으신 건 아니겠죠?",
          DialogueId = 10032826,
          FinalCamera = "65.447815,-234.789932,143.750977,0.007359,-3.820944,63.794052,35.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
