        },
        [10032829] = {
          Camera = "181.988678,85.651779,83.525391,0.007393,10.776809,-102.371201,30.0,210.83786,false,Manual,6.454089,16:9 Digital Film",
          Content = "哦，我原本是打算把秘密基地的钥匙给你们。我所有积蓄都放在那儿，如果我回不来，你们就可以自己拿报酬。",
          ContentKR = "아, 원래는 비밀 아지트의 열쇠를 당신들에게 드리려 했습니다. 제 모든 재산이 거기 있거든요. 만약 제가 돌아오지 못한다면, 직접 가서 보수를 가져가시라고요.",
          DialogueId = 10032829,
          FacialId = {
            [1] = "100304:None"
          },
          FinalCamera = "181.988678,85.651779,88.937988,0.007396,10.776809,-102.371193,30.0,210.83786,false,Manual,6.454089,16:9 Digital Film",
