        },
        [10032830] = {
          Camera = "148.493927,27.434708,144.814453,0.00731,-6.81881,-93.240387,30.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "不过既然{nickname}那样说了，我相信以我们第一次见面时你们的实力……我们一定能平安回来的。",
          ContentKR = "그런데 {nickname} 씨도 그렇게 얘기하시니까, 처음에 당신들을 만났을 때의 실력을 믿겠습니다... 우린 반드시 무사히 돌아올 수 있을 겁니다.",
          DialogueId = 10032830,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "149.026001,36.830658,145.938721,0.00731,-6.418793,-93.240837,30.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "191DBB2C",
