          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-764.08551,466.744812,142.1875,0.007305,-1.81905,-29.224564,35.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-775.528442,446.289978,142.189941,0.007305,-1.81905,-27.42462,35.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film\"},duration{10}}}",
