        [10032901] = {
          Content = "走这边。",
          ContentKR = "이쪽으로.",
          DialogueId = 10032901,
          GUID = "191DC6D2",
          NextDialogue = 10032902,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC6D2"
        },
        [10032902] = {
          Content = "黎瑟长官对这里似乎很熟悉？",
          ContentKR = "리듬 장교님은 이곳에 익숙하신가 보네요?",
          DialogueId = 10032902,
          GUID = "191DC6FC",
          NextDialogue = 10032903,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC6FC"
        },
        [10032903] = {
          Content = "这些年帝国很注重各城镇地下设施的建设，卫戍部队也要出力维护。",
          ContentKR = "제국은 최근 몇 년 동안 각 도시의 지하 시설 건설에 큰 주의를 기울이고 있습니다. 따라서 방위대도 유지보수를 책임져야죠.",
          DialogueId = 10032903,
          GUID = "191DC726",
          NextDialogue = 10032904,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC726"
        },
        [10032904] = {
          Content = "刚加入卫戍部队时，我每天都被安排打扫这里。",
          ContentKR = "처음 방위대에 들어왔을 땐, 매일 이곳의 청소를 배정받았습니다.",
          DialogueId = 10032904,
          GUID = "191DC750",
          NextDialogue = 10032905,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC750"
        },
        [10032905] = {
          Content = "天天清理下水道……卡戎就算加入军团也还是会被欺负吗？",
          ContentKR = "매일 하수도 청소라니... 카론은 군단에 들어가도 괴롭힘을 당하는 건가요?",
          DialogueId = 10032905,
          GUID = "191DC77A",
          NextDialogue = 10032906,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC77A"
        },
        [10032906] = {
          Content = "偏见是根深蒂固的，但在军团至少我们还可以靠功绩来赢得尊重。",
          ContentKR = "편견의 뿌리는 깊습니다. 하지만 적어도 군단에선 공적을 쌓는 것을 통해 존경을 받을 수 있습니다.",
          DialogueId = 10032906,
          GUID = "191DC7A4",
          NextDialogue = 10032907,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC7A4"
        },
        [10032907] = {
          Content = "这也是身为“恶魔的孩子”，偿还自己罪业的方式之一。",
          ContentKR = "이 또한 '악마의 아이'로서 속죄할 수 있는 방법 중 하나죠.",
          DialogueId = 10032907,
          GUID = "191DC7CE",
          NextDialogue = 10032908,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC7CE"
        },
        [10032908] = {
          Content = "等等……你们有没有听到什么声音？",
          ContentKR = "잠깐... 무슨 소리 못 들었어?",
          DialogueId = 10032908,
          GUID = "191DC7F8",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC7F8"
        },
        [10032909] = {
          Content = "救，救救我……我……不想死……",
          ContentKR = "살, 살려줘... 난... 죽고싶지 않아...",
          DialogueId = 10032909,
          GUID = "191DC822",
          NextDialogue = 10032910,
          SpeakNpcId = 100321,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC822"
        },
        [10032910] = {
          Content = "……呼救声！我马上过来！",
          ContentKR = "...구조 요청 소리! 바로 갈게요!",
          DialogueId = 10032910,
          GUID = "191DC84C",
          NextDialogue = 10032911,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC84C"
        },
        [10032911] = {
          Content = "喂，你都不确认一下是不是陷阱吗……啧，我们也快跟上去吧。",
          ContentKR = "저기요, 함정인지 아닌지 확인도 안 해보고... 쩝, 우리도 따라가자.",
          DialogueId = 10032911,
          GUID = "191DC876",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC876"
        },
