        [10033303] = {
          Content = "废水处理区与下水道其他区域相连，我们把这里的废水排出去，彻查整片区域吧。",
          ContentKR = "폐수 처리 구역은 하수도의 기타 구역과 연결되어 있습니다, 이곳의 폐수를 전부 내보내고 이 구역을 철저하게 조사합시다.",
          DialogueId = 10033303,
          GUID = "191E08C6",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100333/191E08C6"
        },
        [10033304] = {
          Content = "长官，我们来支援了。",
          ContentKR = "리듬 장교님, 저희가 도와드리러 왔습니다.",
          DialogueId = 10033304,
          GUID = "191E08F0",
          NextDialogue = 10033305,
          SpeakNpcId = 100344,
          VoiceName = "voice/$Locale$/story/1003/100333/191E08F0"
        },
        [10033305] = {
          Content = "两位市民呢？",
          ContentKR = "시민 두 분은요?",
          DialogueId = 10033305,
          GUID = "191E091A",
          NextDialogue = 10033306,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100333/191E091A"
        },
        [10033306] = {
          Content = "送去医院了。我们还呼叫了上级，到这份上他们终于肯支援了。",
          ContentKR = "병원으로 보내 드렸습니다. 상급에 호출까지 넣었습니다, 이렇게까지 하니까 결국 지원해 주겠다고 하더라고요.",
          DialogueId = 10033306,
          GUID = "191E0944",
          NextDialogue = 10033307,
          SpeakNpcId = 100345,
          VoiceName = "voice/$Locale$/story/1003/100333/191E0944"
        },
        [10033307] = {
          Content = "这几个人就是您提到的帮手吗？",
          ContentKR = "이 몇분이 말씀하셨던 조력자인가요?",
          DialogueId = 10033307,
          GUID = "191E096E",
          NextDialogue = 10033308,
          SpeakNpcId = 100345,
          VoiceName = "voice/$Locale$/story/1003/100333/191E096E"
        },
        [10033308] = {
          Content = "是的，若不是“夜航者”这样优秀的狩月人，我也找不到这里。",
          ContentKR = "네, '녹토 보이저'처럼 훌륭한 월석 사냥꾼들의 도움이 아니었다면, 여길 찾을 수 없었을 겁니다.",
          DialogueId = 10033308,
          GUID = "191E0998",
          NextDialogue = 10033309,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100333/191E0998"
        },
        [10033309] = {
          Content = "哇，好多人帮忙呀！哼哼，对付打伤{nickname}的坏家伙，必须出重拳！",
          ContentKR = "우와, 도와주러 온 사람 진짜 많네! 흥, {nickname}을(를) 다치게 한 녀석, 혼쭐을 내주겠다!",
          DialogueId = 10033309,
          GUID = "191E09C2",
          NextDialogue = 10033310,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100333/191E09C2"
        },
        [10033310] = {
          Content = "要准备迎战了。",
          ContentKR = "전투 준비를 해야겠어.",
          DialogueId = 10033310,
          GUID = "191E09EC",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100333/191E09EC"
        },
        [10033311] = {
          Content = "吼……！",
          ContentKR = "크르르르...!",
          DialogueId = 10033311,
          GUID = "191E0A16",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName01",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0A16"
        },
        [10033312] = {
          Content = "目标并非秽兽，采取牵制战术！",
          ContentKR = "적은 필토이드가 아닙니다, 견제 전술을 써요!",
          DialogueId = 10033312,
          GUID = "191E0A40",
          NextDialogue = 10033313,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100333/191E0A40"
        },
        [10033313] = {
          Content = "活捉目标，还受害者一个交代！",
          ContentKR = "목표를 사로잡아 피해자들에게 데려갑시다!",
          DialogueId = 10033313,
          GUID = "191E0A6A",
          NextDialogue = 10033314,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100333/191E0A6A"
        },
        [10033314] = {
          Content = "收到！",
          ContentKR = "알겠습니다!",
          DialogueId = 10033314,
          GUID = "191E0A94",
          SpeakNpcId = 100344,
          VoiceName = "voice/$Locale$/story/1003/100333/191E0A94"
        },
        [10033315] = {
          Content = "粉……碎……",
          ContentKR = "부... 숴...",
          DialogueId = 10033315,
          GUID = "191E0ABE",
          NextDialogue = 10033316,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName01",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0ABE"
        },
        [10033316] = {
          Content = "呃啊……好大的力气……",
          ContentKR = "으윽... 무슨 힘이...",
          DialogueId = 10033316,
          GUID = "191E0AE8",
          NextDialogue = 10033317,
          SpeakNpcId = 100345,
          VoiceName = "voice/$Locale$/story/1003/100333/191E0AE8"
        },
        [10033317] = {
          Content = "小心！",
          ContentKR = "조심하세요!",
          DialogueId = 10033317,
          GUID = "191E0B12",
          NextDialogue = 10033318,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100333/191E0B12"
        },
        [10033318] = {
          Content = "可恶……腾不出手！",
          ContentKR = "제기랄... 손을 뗄 수가 없어!",
          DialogueId = 10033318,
          GUID = "191E0B3C",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100333/191E0B3C"
        },
        [10033319] = {
          Content = "消……除……",
          ContentKR = "소... 멸...",
          DialogueId = 10033319,
          GUID = "191E0B66",
          NextDialogue = 10033320,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName01",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0B66"
        },
        [10033320] = {
          Content = "我来掩护伤员后撤，大家不要慌张。",
          ContentKR = "부상자들은 철수해, 내가 엄호할게, 다들 당황하지 말고.",
          DialogueId = 10033320,
          GUID = "191E0B90",
          NextDialogue = 10033321,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100333/191E0B90"
        },
        [10033321] = {
          Content = "拜托了。",
          ContentKR = "부탁할게요.",
          DialogueId = 10033321,
          GUID = "191E0BBA",
          NextDialogue = 10033322,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100333/191E0BBA"
        },
        [10033322] = {
          Content = "咳……谢谢。",
          ContentKR = "쿨럭... 감사합니다.",
          DialogueId = 10033322,
          GUID = "191E0BE4",
          SpeakNpcId = 100344,
          VoiceName = "voice/$Locale$/story/1003/100333/191E0BE4"
        },
        [10033323] = {
          Content = "奥特赛德，左边有破绽。",
          ContentKR = "아웃사이더, 왼쪽에 빈틈이 있어.",
          DialogueId = 10033323,
          GUID = "191E0C0E",
          NextDialogue = 10033324,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100333/191E0C0E"
        },
        [10033324] = {
          Content = "交给我。",
          ContentKR = "맡겨만 두라구.",
          DialogueId = 10033324,
          GUID = "191E0C38",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100333/191E0C38"
        },
        [10033325] = {
          Content = "牵制住了。黎瑟！",
          ContentKR = "견제했어요, 리듬!",
          DialogueId = 10033325,
          GUID = "191E0C62",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100333/191E0C62"
        },
        [10033401] = {
          Content = "快……撤……",
          ContentKR = "어서... 철수...",
          DialogueId = 10033401,
          GUID = "191E18DA",
          SpeakNpcId = 100311,
          VoiceName = "voice/$Locale$/story/1003/100334/191E18DA"
        },
        [10033402] = {
          Content = "……怪物……不止一只……有同伙！",
          ContentKR = "괴물... 혼자가 아닙니다... 동료가 있어요!",
          DialogueId = 10033402,
          GUID = "191E1904",
          SpeakNpcId = 100311,
          VoiceName = "voice/$Locale$/story/1003/100334/191E1904"
        },
        [10033403] = {
          Content = "拦住它们两个……",
          ContentKR = "저 둘을 막아야 합니다...",
          DialogueId = 10033403,
          GUID = "191E192E",
          SpeakNpcId = 100311,
          VoiceName = "voice/$Locale$/story/1003/100334/191E192E"
        },
        [10033404] = {
          Content = "……不行……防线被突破了……",
          ContentKR = "...안 되겠어요... 방어선이 돌파 당했어요...",
          DialogueId = 10033404,
          GUID = "191E1958",
          SpeakNpcId = 100311,
          VoiceName = "voice/$Locale$/story/1003/100334/191E1958"
        },
        [10033405] = {
          Content = "营救伤员，快，先去营救伤员！",
          ContentKR = "부상자를 구출해요, 어서, 먼저 부상자부터 구출해요!",
          DialogueId = 10033405,
          GUID = "191E1982",
          SpeakNpcId = 100311,
