        },
        [10033508] = {
          Camera = "-138.914062,-208.657227,182.986816,-0.000002,-38.999802,-104.019676,35.000023,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "啧，通讯器故障了吗……算了，反正你们走一会儿就能见到他们了。我们得封锁你们进来时的整条通道，你们就自己往那边走吧。",
          ContentKR = "무전기 고장인가... 어쩔 수 없군요, 조금만 걸으시면 저희 동료들을 만나실 수 있을 겁니다. 저희는 당신들이 들어오신 통로를 전부 봉쇄해야 하니 먼저 밖을 향해 가십시오.",
          DialogueId = 10033508,
          FinalCamera = "-125.476562,-154.847595,227.898438,18.000706,-38.999802,-104.019608,35.000023,100000.0,false,Manual,22.0,16:9 Digital Film",
