        },
        [10033522] = {
          Camera = "-225.560547,-129.777405,118.852295,0.000196,-27.401426,176.001938,35.000011,3519.813721,false,DoNotOverride,1.257729,16:9 Digital Film",
          Content = "对哦……我们一开始找她，是为了让她帮你打探家人的消息！差点就忘了！",
          ContentKR = "맞네... 그러고 보니 우리가 처음에 리듬 장교님을 찾아간 것도 네 가족의 소식 때문이었잖아! 까먹을 뻔했네!",
          DialogueId = 10033522,
          FacialId = {
            [1] = "200002:Smile01"
          },
          FinalCamera = "-209.878906,-130.874634,127.011353,0.000196,-27.401426,176.001938,35.000011,3519.813721,false,DoNotOverride,1.257729,16:9 Digital Film",
