          VoiceName = "voice/$Locale$/story/1003/100335/191E2CB4"
        },
        [10033523] = {
          Content = "刚才，是她救了我。",
          ContentKR = "아까 그녀가 날 구해줬어.",
          DialogueId = 10033523,
          GUID = "191E2CDE",
          ImprPlusId = 1009,
          NextDialogue = 10033524
        },
        [10033524] = {
          Content = "没关系的，保护市民是我的责任……你们没事……就好。",
          ContentKR = "괜찮습니다, 시민들을 보호하는 건 제 책임입니다... 당신들이 괜찮다면... 됐어요.",
          DialogueId = 10033524,
          GUID = "191E2D08",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10033524.T_Story_Recall_10033524'",
          NextDialogue = 10033525,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2D08"
        },
        [10033525] = {
          Camera = "2442.072266,-1239.279053,1486.851685,0.000195,-26.801941,154.004623,55.0,3519.813721,false,Manual,1.257729,16:9 Digital Film",
          Content = "好吧，好吧，听你们的。那现在就走？",
          ContentKR = "알았어, 알았다고, 너희들 의견대로 할게, 지금 가면 되지?",
          DialogueId = 10033525,
          FinalCamera = "2433.271484,-1257.322388,1486.851562,0.000196,-27.001888,153.805222,55.0,3519.813721,false,Manual,1.257729,16:9 Digital Film",
          GUID = "191E2D32",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextOptions = {
            [1] = 10033526,
            [2] = 10033527
          },
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200002:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2D32",
          bForbidSkipOptions = true
        },
        [10033526] = {
          Content = "嗯，走吧。先离开下水道。",
          ContentKR = "응, 일단 이 하수도부터 빠져나가자.",
          DialogueId = 10033526,
          GUID = "191E2D33",
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}"
        },
        [10033527] = {
          Content = "再等等吧。",
          ContentKR = "조금만 기다려줘.",
          DialogueId = 10033527,
          GUID = "191E2D34",
          NextDialogue = 10033528,
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}"
        },
        [10033528] = {
          Content = "行啊，那等你准备好了我们再出去。",
          ContentKR = "그래, 그럼 준비가 다 되면 바로 나가자.",
          DialogueId = 10033528,
          GUID = "191E2D35",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2D35"
        },
        [10033601] = {
          Content = "咦？不是说有人在这儿接我们嘛，他们人呢？",
          ContentKR = "응? 누가 데리러 와준다고 하지 않았어? 어디 있는 거지?",
          DialogueId = 10033601,
          GUID = "191E39AA",
          NextDialogue = 10033602,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100336/191E39AA"
        },
        [10033602] = {
          Content = "看这里，墙上有一大片密集的弹孔。",
          ContentKR = "여길 봐, 벽에 총알 자국이 빽빽하게 있어.",
          DialogueId = 10033602,
          GUID = "191E39D4",
          NextDialogue = 10033603,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100336/191E39D4"
        },
        [10033603] = {
          Content = "啧……接我们的人跟凶手撞上了？这下麻烦了啊。",
          ContentKR = "쯧... 우릴 데리러 온 사람들이 범인이랑 마주친 건가? 골치 아프게 됐네.",
          DialogueId = 10033603,
          GUID = "191E39FE",
          NextDialogue = 10033604,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100336/191E39FE"
        },
        [10033604] = {
          Content = "……从弹孔的分布来看，凶手应该是往这边去了。我们也顺路去看看吧。",
          ContentKR = "...총알 자국의 흔적으로 봐선, 범인은 이쪽으로 간 것 같아. 우리도 한번 가보자.",
          DialogueId = 10033604,
          GUID = "191E3A28",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100336/191E3A28"
        },
        [10033605] = {
          Content = "真是这边吗？附近什么也没有呀……",
          ContentKR = "진짜 여기 맞아? 근처에 아무것도 없잖아...",
          DialogueId = 10033605,
          GUID = "191E3A52",
          NextDialogue = 10033606,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100336/191E3A52"
        },
        [10033606] = {
          Content = "你们有没有感觉，这里的风力比其他地方强？",
          ContentKR = "여기 바람이 다른 곳보다 더 강하다는 느낌이 들지 않아?",
          DialogueId = 10033606,
          GUID = "191E3A7C",
          NextDialogue = 10033607,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100336/191E3A7C"
        },
        [10033607] = {
          Content = "我上去看看。",
          ContentKR = "내가 올라가 볼게.",
          DialogueId = 10033607,
          GUID = "191E3AA6",
          NextDialogue = 10033608,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100336/191E3AA6"
        },
        [10033608] = {
          Content = "哈，你的感觉还挺敏锐，上面这个管道不久前才被人破坏过。",
          ContentKR = "호오, 촉이 꽤 날카롭네. 여기 있는 파이프가 방금 누군가에 의해 파괴당한 것 같아.",
          DialogueId = 10033608,
          GUID = "191E3AD0",
          NextDialogue = 10033609,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100336/191E3AD0"
        },
        [10033609] = {
          Content = "从管道延伸的方向来看，凶手会从前面的出口附近出来。",
          ContentKR = "파이프가 이어진 방향으로 봤을 때 범인은 저 앞에 있는 출구 근처에서 나올 것 같아.",
