        [10033802] = {
          Content = "小仆从小仆从，走这边。",
          ContentKR = "시종, 시종, 이쪽으로 가자.",
          DialogueId = 10033802,
          GUID = "191E5AA4",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100338/191E5AA4"
        },
        [10033803] = {
          Content = "前方是内城，卡戎之民没有特殊许可禁止通行！",
          ContentKR = "이 앞은 내성이다, 카론은 특수 허가가 없으면 지나갈 수 없다!",
          DialogueId = 10033803,
          GUID = "191E5ACE",
          NextDialogue = 10033804,
          SpeakNpcId = 100325,
          VoiceName = "voice/$Locale$/story/1003/100338/191E5ACE"
        },
        [10033804] = {
          Content = "哦哦，是你们啊。别那么凶，{性别：他们|她们}刚刚给卫戍部队帮了大忙。",
          ContentKR = "아아, 당신들이군요. 너무 팍팍하게 그러지 말자고요. 이분들은 조금 전 방위대에 큰 도움을 줬던 분들입니다.",
          DialogueId = 10033804,
          GUID = "191E5AF8",
          NextDialogue = 10033805,
          SpeakNpcId = 100325,
          VoiceName = "voice/$Locale$/story/1003/100338/191E5AF8"
        },
        [10033805] = {
          Content = "你们来内城做什么？",
          ContentKR = "내성엔 무슨 일로 오셨습니까?",
          DialogueId = 10033805,
          GUID = "191E5B22",
          NextDialogue = 10033806,
          SpeakNpcId = 100325,
          VoiceName = "voice/$Locale$/story/1003/100338/191E5B22"
        },
        [10033806] = {
          Content = "我们想看看黎瑟长官的状况。",
          ContentKR = "리듬 장교님의 상황을 살피러 왔습니다.",
          DialogueId = 10033806,
          GUID = "191E5B4C",
          NextDialogue = 10033807,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100338/191E5B4C"
        },
        [10033807] = {
          Content = "听说救回来一条命，还昏迷着。真要看她的话，我带你们进去吧。低调点，跟着我。",
          ContentKR = "목숨은 건졌지만, 아직 혼수상태라고 들었습니다. 정말 리듬 님의 상황을 살피러 오셨다면 제가 안내하겠습니다. 조용히 따라오세요.",
          DialogueId = 10033807,
          GUID = "191E5B76",
          SpeakNpcId = 100325,
          VoiceName = "voice/$Locale$/story/1003/100338/191E5B76"
        },
        [10033901] = {
          Camera = "24.498535,102.712585,126.646484,0.000073,-6.999646,-158.394653,35.000008,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "（空气中弥漫的消毒水让鼻腔感到些许的刺激，落针可闻的房间中回荡着黎瑟平缓的呼吸。）",
          ContentKR = "(공기 중의 소독제 냄새가 코를 찌르고, 쥐 죽은 듯이 고요한 방엔 리듬의 잔잔한 숨소리만 울려 퍼진다.)",
