        [10033911] = {
          Camera = "22.721191,147.070129,213.337891,14.478269,-31.792528,169.829453,40.000027,699.855347,false,DoNotOverride,1.599285,16:9 Digital Film",
          Content = "看她的双手，那是常年高强度工作的人才会有的老茧。她是个认真的好士兵。",
          ContentKR = "그녀의 손을 봐, 이건 오랜 시간 동안 강도 높은 일을 해온 사람들만 가질 수 있는 굳은살이야. 그녀는 모든 일을 열심히 한 훌륭한 병사야.",
          DialogueId = 10033911,
          FinalCamera = "22.27002,142.886963,212.416016,14.479208,-31.792534,167.828476,40.000027,699.855347,false,DoNotOverride,1.599285,16:9 Digital Film",
          GUID = "191E6C86",
          NextDialogue = 10033912,
          SpeakNpcId = 200021,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6C86"
        },
        [10033912] = {
          Camera = "-147.882324,242.155945,207.876953,0.000033,-21.398981,-37.788219,35.0,699.855347,false,DoNotOverride,1.599285,16:9 Digital Film",
          Content = "而且她还是个固执的笨家伙。那双充满干劲的眼睛是我最烦的，因为这种人不知道放弃和变通，非得把自己搞得头破血流才知道疼。",
          ContentKR = "게다가 그녀는 고집불통인 바보야. 내가 제일 짜증 나는 건 그 의욕 넘치는 눈빛이야, 그런 사람들은 포기하거나 적응하는 법을 모르거든. 꼭 자기 자신의 머리가 깨지고 피가 흐를 때까지 망가져야 아픈 줄 알지.",
          DialogueId = 10033912,
          FinalCamera = "-147.882324,242.155945,207.876953,0.000033,-18.398855,-37.787617,35.0,699.855347,false,DoNotOverride,1.599285,16:9 Digital Film",
          GUID = "191E6CB0",
          NextDialogue = 10033913,
          Scripts = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"91.999512,-31.641846,83.878906,0.000177,0.801796,22.820667,35.0,699.855347,false,DoNotOverride,1.599285,16:9 Digital Film\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"89.305664,-25.238281,83.878906,0.000177,0.801796,22.820667,35.0,699.855347,false,DoNotOverride,1.599285,16:9 Digital Film\"},duration{8}}}",
          SpeakNpcId = 200021,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6CB0"
        },
        [10033913] = {
          Camera = "134.203613,109.259399,124.238281,-0.000946,6.40391,164.582108,35.000011,699.855347,false,DoNotOverride,1.599285,16:9 Digital Film",
          Content = "正因如此，在解决“卡戎狩猎”之前，她是不会就此一睡不醒的。而我们现在要做的，就是好好休息，慢慢等她醒。",
          ContentKR = "그렇기 때문에 '카론 사냥' 사건을 해결하기 전엔, 절대 이대로 영원히 잠들지 않을 거야. 지금 우리가 해야 할 일은 푹 쉬면서 그녀가 깨어나길 기다리는 거야.",
          DialogueId = 10033913,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "135.833008,115.049255,124.238281,-0.000946,6.40391,166.781784,35.000011,699.855347,false,DoNotOverride,1.599285,16:9 Digital Film",
