        [10033917] = {
          Camera = "46.933594,-142.992432,70.192139,0.000176,5.9446,109.526016,35.000011,306.744568,false,Manual,7.109471,16:9 Digital Film",
          Content = "好像是……卡戎之民的……“罪业”？那、那是什么来着……",
