        [10033919] = {
          Camera = "22.104492,41.488037,139.45166,10.816259,-23.854141,115.722862,35.000023,106.301834,false,DoNotOverride,7.109471,16:9 Digital Film",
          Content = "嘿嘿……晚上工作太困了……这不是还有布鲁斯你给我补课嘛。",
          ContentKR = "헤헤... 밤에 일하면 너무 피곤해서... 우리 블루스가 과외 해줄 건데 뭐 어때.",
          DialogueId = 10033919,
          FacialId = {
            [1] = "100359:Ahaha01"
          },
          FinalCamera = "14.884766,37.489014,138.013672,10.817234,-22.054098,108.921974,35.000023,106.301834,false,DoNotOverride,7.109471,16:9 Digital Film",
          GUID = "191E6DD6",
          NextDialogue = 10033920,
          SpeakNpcId = 100359,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6DD6"
        },
        [10033920] = {
          Camera = "105.572266,235.572021,152.555908,-0.000184,-12.201387,-122.479736,35.000015,106.301834,false,DoNotOverride,7.109471,16:9 Digital Film",
          Content = "唉，工作的话我也在一起做呀。我们总共就没两年书可读，你还不好好听讲……回到卡戎的“罪业”上来，那还得从<H>“泪湖之夜”</>说起……",
          ContentKR = "휴, 일은 나도 같이 하고 있잖아. 학교 다닐 날이 2년 밖에 안 남았는데 아직도 수업을 제대로 안 듣고 있으면 어떡해...\n아무튼 카론의 '죄업' 얘기로 돌아가면, 역시 <H>눈물의 호수의 밤</> 이야기부터 시작해야 해...",
          DialogueId = 10033920,
          FinalCamera = "119.550781,226.407837,152.555908,-0.000183,-12.201387,-127.679604,35.000015,106.301834,false,DoNotOverride,7.109471,16:9 Digital Film",
          GUID = "191E6E00",
          NextDialogue = 10033921,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{4},TargetPosition{\"57.916016,117.509399,78.924561,-0.000183,9.39821,-114.472267,35.000019,106.301834,false,DoNotOverride,7.109471,16:9 Digital Film\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"62.908203,115.10022,78.924561,-0.000182,9.398203,-117.471146,35.000019,106.301834,false,DoNotOverride,7.109471,16:9 Digital Film\"},duration{10}}},PlayAnimation{_delay{6},ActorId{100359},AnimationId{\"Explain02_Start\"},Duration{2}}}",
          SpeakNpcId = 100357,
          TalkActionId = {
            [1] = "100357:Angry01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6E00"
        },
        [10033921] = {
          Camera = "21.583984,37.977295,146.400635,-0.000183,-24.001146,-114.668968,35.000015,106.301834,false,DoNotOverride,7.109471,16:9 Digital Film",
          Content = "一千年前，就在我们的冰湖城，长着犄角的“恶魔”们——卡戎之民，假装和索拉之民一起在泪湖畔举行庆典，却在庆典那夜干了很坏很坏的事！在场的索拉人几乎都被杀掉了……",
          ContentKR = "천 년 전, 바로 우리 아이스레이크 시티에서, 뿔 달린 '악마' 카론들이 솔라와 함께 눈물의 호수에서 축제를 여는 척하다가, 그날 밤 아주 나쁜 짓을 저질렀어! 그 자리에 있던 솔라들은 거의 다 목숨을 잃었지...",
          DialogueId = 10033921,
          FacialId = {
            [1] = "100357:Sad01"
          },
          FinalCamera = "21.583984,37.977295,146.400635,-0.000187,-19.60116,-115.469559,35.000015,106.301834,false,DoNotOverride,7.109471,16:9 Digital Film",
          GUID = "191E6E2A",
          NextDialogue = 10038401,
          Scripts = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"208.77832,286.108398,72.5625,-0.000182,9.583554,-134.240799,35.000023,106.301834,false,DoNotOverride,7.109471,16:9 Digital Film\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"208.77832,286.108398,72.5625,-0.000183,3.783597,-132.241501,35.000023,106.301834,false,DoNotOverride,7.109471,16:9 Digital Film\"},duration{10}}}",
          SpeakNpcId = 100357,
          TalkActionId = {
            [1] = "100359:Explain02_End",
            [2] = "100357:Angry01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6E2A"
        },
        [10033922] = {
          Camera = "23.90625,145.747559,110.425293,-0.000397,-0.998471,-109.465141,35.000019,183.023834,false,Manual,5.506591,16:9 Digital Film",
          Content = "但因为“泪湖之夜”的过错，卡戎的后代必须用自己的人生，去偿还祖先犯下的罪。",
          ContentKR = "'눈물의 호수의 밤'에 저지른 잘못 때문에, 카론의 후손들은 평생에 걸쳐 선조들이 지은 죄를 갚아야만 해.",
          DialogueId = 10033922,
          FacialId = {
            [1] = "100357:None"
          },
          FinalCamera = "28.929688,143.939087,110.425293,-0.000397,-0.998471,-111.464867,35.000019,183.023834,false,Manual,5.506591,16:9 Digital Film",
