        [10033933] = {
          Camera = "52.249023,50.819092,164.266846,0.000087,-15.773091,-158.304077,35.0,68.717873,false,Manual,8.520827,16:9 Digital Film",
          Content = "那就是不太适应喽？唉，所以我说别急着加入卫戍部队，安心为明年的第六军团考核做准备多好。",
          ContentKR = "그럼 적응 잘 안된다는 얘기네? 에휴, 그러니까 방위대는 서두르지 말고 내년에 있을 제6군단 시험이나 준비하면 얼마나 좋아.",
          DialogueId = 10033933,
          FinalCamera = "53.777344,46.745605,164.266846,0.000087,-15.773057,-160.903915,35.0,68.717873,false,Manual,8.520827,16:9 Digital Film",
