        [10033935] = {
          Camera = "-85.761719,55.762695,140.799561,0.002314,-2.075899,-18.472183,35.000019,176.232666,false,Manual,3.23825,16:9 Digital Film",
          Content = "如果能在卫戍部队做出点功绩，也有机会成为桂冠卡戎吧？而且，也多少能帮到冰湖城的人们……",
          ContentKR = "방위대에서 열심히 공적을 쌓으면 계관카론이 될 기회가 생기지 않을까? 게다가 아이스레이크 시티 사람들도 어느 정도 도와줄 수 있잖아...",
          DialogueId = 10033935,
          FinalCamera = "-85.06543,57.947021,140.799561,0.002315,-2.075899,-19.472168,35.000019,176.232666,false,Manual,3.23825,16:9 Digital Film",
          GUID = "191E7076",
          NextDialogue = 10033936,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7076"
        },
        [10033936] = {
          Camera = "11.327148,69.848389,135.454102,0.002309,0.323915,-35.471474,35.000019,207.040939,false,DoNotOverride,3.23825,16:9 Digital Film",
          Content = "能一起通过考核自然是好，但是没那个天分的话，也不能强求。就用笨方法摸索着走走看吧。",
          ContentKR = "물론 같이 시험에 합격할 수 있으면 좋겠지만, 재능이 없다면 강요할 수도 없잖아. 조금 어리석긴 하지만, 일단 해봐야지.",
          DialogueId = 10033936,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "13.211914,72.253418,135.454102,0.002309,0.323915,-38.071762,35.000019,207.040939,false,DoNotOverride,3.23825,16:9 Digital Film",
