        [10033941] = {
          Camera = "329.514648,-197.759277,252.08667,0.002183,-22.681835,142.327667,30.000008,7420.709473,false,DoNotOverride,2.157511,16:9 Digital Film",
          Content = "嗯嗯——确切来说，是哨塔上那盏灯。那是整座冰湖城最高的地方！",
          ContentKR = "그래, 정확하게는 초소 위의 저 등불이야. 저곳이 아이스레이크 시티에서 제일 높은 곳이야!",
          DialogueId = 10033941,
          FinalCamera = "297.395508,-234.10498,252.08667,0.002188,-22.481806,132.727509,30.000008,7420.709473,false,DoNotOverride,2.157511,16:9 Digital Film",
          GUID = "191E7172",
          NextDialogue = 10033942,
          Scripts = "PlayAnimation{_delay{2},ActorId{100358},AnimationId{\"Talk01_Start\"},Duration{2}}",
          SpeakNpcId = 100358,
          TalkActionId = {
            [1] = "100358:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7172"
        },
        [10033942] = {
          Camera = "272.657227,-228.072998,65.852295,0.002184,11.115211,134.331268,30.000008,7420.709473,false,DoNotOverride,2.157511,16:9 Digital Film",
          Content = "我每次站在这儿往内城看，都觉得它那么高，那么远，那么亮。就像书本上写的灯塔，只能远远看着，但永远都摸不到。",
          ContentKR = "매번 여기 서서 내성을 바라보면, 너무 높고, 너무 멀고, 너무 밝다고 느껴졌어. 멀리서 바라볼 수만 있고 영원히 가까이 다가가지 못하는, 책 속에 나오는 등대처럼 말이야.",
          DialogueId = 10033942,
          FacialId = {
            [1] = "100304:Confident01"
