        [10033943] = {
          Camera = "111.371094,-113.845703,177.456787,0.002008,-26.280388,156.343842,30.000013,7420.709473,false,DoNotOverride,2.157511,16:9 Digital Film",
          Content = "但是现在，我和之前不一样了，我成“桂冠卡戎”了！之前的好多好多愿望，表演啊弹琴啊，都不再是白日做梦了！",
          ContentKR = "하지만 지금의 난 달라, 난 '계관카론'이 됐어! 과거의 수많은 소망, 공연, 연주와 같은 것들은 더 이상 꿈이 아니야! ",
          DialogueId = 10033943,
          FinalCamera = "108.759766,-119.812256,177.456787,0.002008,-26.28038,151.74408,30.000013,7420.709473,false,DoNotOverride,2.157511,16:9 Digital Film",
