        },
        [10033944] = {
          Camera = "77.242188,-175.824219,156.161133,0.002098,-10.087157,100.349434,30.000013,7420.709473,false,DoNotOverride,2.157511,16:9 Digital Film",
          Content = "我可以到内城，爬到哨塔上面，站在那盏灯下……我觉得自己就像是冰湖城的皇帝！",
          ContentKR = "난 이제 내성에 들어가서 저 초소 위에 있는 등불 밑에 설 수 있어... 아이스레이크 시티의 황제라도 된 느낌이야!",
          DialogueId = 10033944,
          FinalCamera = "77.242188,-175.824219,156.161133,0.002093,-6.687103,100.549789,30.000013,7420.709473,false,DoNotOverride,2.157511,16:9 Digital Film",
