        },
        [10033945] = {
          Camera = "154.736328,-179.322754,105.369629,0.002146,9.71145,139.943695,30.000013,7420.709473,false,DoNotOverride,2.157511,16:9 Digital Film",
          Content = "“士兵们听令——全军出击！为了海伯利亚的荣耀！”",
          ContentKR = "“병사들이여, 내 명을 받들라, 전군 진격이다! 휘페르보레아의 영광을 위하여!”",
