        [10033948] = {
          Camera = "127.84375,-20.15332,112.732666,0.002085,15.912045,-140.45549,30.000013,108.648788,false,Manual,3.232587,16:9 Digital Film",
          Content = "对了，第六军团还是蛮辛苦的，长官说入伍前三年都是封闭式训练，回不了家……如果姐姐想我的话，就经常看看内城那盏灯吧。",
          ContentKR = "맞다, 제6군단은 꽤 힘들어, 상관이 입대 후 3년은 폐쇄적인 훈련이라 집에 못 간댔어... 누나는 내가 보고 싶으면 내성의 저 등불을 자주 봐.",
          DialogueId = 10033948,
          FinalCamera = "133.529297,-27.189453,112.732666,0.002083,15.91197,-145.655502,30.000013,108.648788,false,Manual,3.232587,16:9 Digital Film",
