        },
        [10033949] = {
          Camera = "867.347656,-2098.635498,629.636597,0.002082,-14.284138,117.329636,45.0,2254.919678,false,Manual,1.2,16:9 Digital Film",
          Content = "我会好好在内城等你的。我会把薪水好好攒起来，让你过上好日子。到时候我们想看戏就看戏，想吃好吃的就吃好吃的……再也不会有人欺负我们了。",
          ContentKR = "내성에서 기다릴게. 월급도 꽁꽁 모아뒀다가 나중에 호강시켜 줄게. 나중엔 공연 보고 싶을 땐 보면 되고, 맛있는 거 먹고 싶으면 먹으면 돼... 아무도 우릴 괴롭힐 수 없게 될 거야.",
          DialogueId = 10033949,
          FinalCamera = "881.833008,-2091.153564,629.636597,0.002081,-14.284138,117.72963,45.0,2254.919678,false,Manual,1.2,16:9 Digital Film",
