        [10034108] = {
          Camera = "-113.304688,236.751953,107.111328,0.000155,-26.791348,130.790771,30.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "为什么废弃检修间会有这么多矿灯跟矿镐？",
          ContentKR = "버려진 정비실에 웬 광산용 램프와 곡괭이가 이렇게 많지?",
          DialogueId = 10034108,
          FinalCamera = "-113.304688,236.751953,107.111328,0.000152,-33.191277,130.190399,30.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
