        [10034110] = {
          Camera = "-27.976562,359.482422,156.25,0.00017,-1.390585,-141.406723,30.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "这里应该就是那群矿工藏东西的地方，后来被黎瑟发现，当成了一个隐秘的仓库。不过我要你看的不是这些。",
          ContentKR = "여기가 아마 그 물건들을 감춰 놓은 곳일 거야. 나중에 리듬이 찾아서 비밀 창고로 쓴 거지. 하지만 네가 봤으면 하는 건 그게 아니야.",
          DialogueId = 10034110,
          FinalCamera = "-16.988281,344.918945,156.25,0.000169,-1.590608,-147.206284,30.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "191E8D2C",
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-178.03125,-58.620117,217.142578,-0.000061,-16.397821,77.969307,30.000002,100000.0,false,DoNotOverride,22.0,16:9 Digital Film\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-178.03125,-58.620117,217.142578,-0.00006,-14.397696,77.768784,30.000002,100000.0,false,DoNotOverride,22.0,16:9 Digital Film\"},duration{5}}},LookAt{_delay{5},LookAtDescription{\"200021:p(Point04)\"}}}",
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "100001:Talk03_End",
            [2] = "200021:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8D2C"
        },
        [10034111] = {
          Content = "系着歪扭蝴蝶结的朴素礼盒，礼盒边是一瓶帝国最顶尖的止痛剂，和一封不知是什么原因没被塞入礼盒的纸条，上面写着“希望你能早日康复”。",
          ContentKR = "삐뚤어진 리본이 달린 소박한 선물 상자. 선물 상자 옆에는 제국 최고의 진통제 한 병, 그리고 무슨 이유에서인지 선물 상자에 넣지 못한 쪽지가 있다. 쪽지에는 \"쾌유하시길 바랍니다.\"라는 글귀가 적혀있다.",
          DialogueId = 10034111,
          GUID = "191E8D56",
          VoiceName = "voice/$Locale$/story/1003/100341/191E8D56"
        },
        [10034201] = {
          Camera = "219.984375,651.333008,126.039062,0.000189,-0.595449,-128.390549,35.000008,527.224426,false,Manual,2.038203,16:9 Digital Film",
          Content = "我还好奇是哪个傻瓜在你昏迷的时候送止痛剂呢，看到这个，确实是黎瑟这种傻傻的家伙能干出来的。",
          ContentKR = "의식을 잃은 사이 진통제를 보낸 바보가 누군지 궁금했는데, 이걸 보니 알 것 같아. 리듬 같은 바보가 한 일 답네.",
          DialogueId = 10034201,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "226.792969,645.869141,126.039062,0.000189,-0.795451,-129.390228,35.000008,527.224426,false,Manual,2.038203,16:9 Digital Film",
