        [10034202] = {
          Camera = "6.648438,363.008789,131.244141,0.000182,3.603758,-146.77739,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          Content = "好了，我这边就找到这些，你呢，找到印章了吗？",
          ContentKR = "됐어, 내가 찾은 건 이것뿐이야. 넌? 도장은 찾았어?",
