          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "13.488281,352.691406,131.244141,0.000182,3.603758,-149.576935,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
