        [10034203] = {
          Camera = "-275.664062,320.675781,156.072266,0.000189,-3.796267,-32.382538,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          Content = "还没。但我知道了另一件事……",
          ContentKR = "아니, 아직. 하지만 또 한 가지 알아낸 게 있어...",
          DialogueId = 10034203,
          FinalCamera = "-271.5625,327.202148,156.072266,0.000189,-3.796267,-35.982929,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          GUID = "191E9C6E",
