          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9C6E"
        },
        [10034204] = {
          Camera = "-106.195312,289.816406,169.058594,0.000185,-23.795893,-51.580635,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          Content = "黎瑟还小的时候……她父母被秽蚀者变成的秽兽害死了，那只秽兽还杀掉了很多人。",
          ContentKR = "리듬이 어렸을 때... 부모님이 필토이드로 변한 침식자에게 죽었나 봐. 그 필토이드가 사람들을 엄청 많이 죽인 것 같아.",
          DialogueId = 10034204,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "-101.417969,293.541992,169.058594,0.000177,-23.795885,-56.380722,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          GUID = "191E9C98",
          NextDialogue = 10034205,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-91.234375,264.868164,130.25,0.000933,-24.992582,92.009041,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-100.582031,264.547852,130.25,0.000933,-24.992582,92.009041,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film\"},duration{5}}}",
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9C98"
        },
        [10034205] = {
          Content = "秽兽异常凶险，虽然它现在停止了攻击，但很可能只是暂时休眠。你们尽快去城内避难，这里交给卫戍部队应付。",
          ContentKR = "필토이드는 매우 위험합니다. 지금은 공격을 멈췄지만, 일시적인 휴면 상태일 가능성이 높습니다. 어서 성안으로 피하십시오. 이곳은 방위대가 맡겠습니다.",
          DialogueId = 10034205,
          GUID = "191E9CC2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10031809.T_Story_Recall_10031809'",
          NextDialogue = 10034206,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9CC2"
        },
        [10034206] = {
          Content = "……保护市民……是我的责任，你们没事……就好。",
          ContentKR = "괜찮습니다... 시민들을 보호하는 건... 제 책임입니다. 당신들이 괜찮다면... 됐어요.",
          DialogueId = 10034206,
          GUID = "191E9CEC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10034206.T_Story_Recall_10034206'",
          NextDialogue = 10034207,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9CEC"
        },
        [10034207] = {
          Camera = "-83.59375,619.290039,74.404297,0.000918,8.607185,-95.991829,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          Content = "她不想再看到任何人死在秽兽手上，也许正因为如此她才会加入卫戍部队吧。",
          ContentKR = "리듬은 누군가 또다시 필토이드에게 죽는 걸 보고 싶지 않았던 거야, 그래서 방위대에 들어갔나 봐.",
          DialogueId = 10034207,
          FinalCamera = "-65.59375,616.701172,74.404297,0.000924,8.607192,-98.191681,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          GUID = "191E9D16",
