        [10034209] = {
          Camera = "74.128906,313.707031,115.523438,0.00091,8.006245,-156.795731,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          Content = "那么，那晚的事情，你是原谅她了？",
          ContentKR = "그럼, 그날 밤 일 말인데, 이제 리듬을 용서한 거야?",
          DialogueId = 10034209,
          FacialId = {
            [1] = "200021:Confident01"
          },
          FinalCamera = "67.410156,328.6875,115.523438,0.000912,8.006245,-151.796326,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          GUID = "191E9D6A",
          NextOptions = {
            [1] = 10034210,
            [2] = 10034215
          },
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:ConfidentLR_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9D6A"
        },
        [10034210] = {
          Content = "嗯，我不恨她了。",
          ContentKR = "응, 이제 미워하지 않아.",
          DialogueId = 10034210,
          GUID = "191E9D94",
          NextDialogue = 10034211
        },
        [10034211] = {
          Camera = "-87.1875,283.529297,139.589844,0.000929,0.00597,-72.795937,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          Content = "……或者说，其实我早就知道，我并没有恨她。",
          ContentKR = "...사실 훨씬 전부터, 그녀를 미워하지 않는다는 걸 알고 있었어.",
          DialogueId = 10034211,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          FinalCamera = "-79.628906,285.871094,139.589844,0.000929,0.00597,-72.795937,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          GUID = "191E9DBE",
          NextDialogue = 10034212,
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9DBE"
        },
        [10034212] = {
          Camera = "-278.289062,544.645508,272.761719,0.000823,-24.392176,-64.799492,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          Content = "我只是……下意识找了个借口，想让自己心里好受些。",
          ContentKR = "난 그냥... 무의식적으로 핑계가 필요했나 봐, 그래야 마음이 좀 나아질 거라고 생각했지.",
          DialogueId = 10034212,
          FacialId = {
            [1] = "100001:Unhappy02"
          },
          FinalCamera = "-266.535156,550.174805,272.761719,0.000823,-24.392176,-68.599632,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          GUID = "191E9DE8",
          NextDialogue = 10034213,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9DE8"
        },
        [10034213] = {
          Camera = "-247.742188,295.758789,178.650391,0.000831,-14.39187,-24.799393,35.000011,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          Content = "我真正怨恨的，是无法扭转的秽蚀，还有那时的无能为力。",
          ContentKR = "네가 진짜 원망한 건, 되돌릴 수 없는 침식, 그리고 그때 아무것도 할 수 없었던 내 자신이었어.",
          DialogueId = 10034213,
          FinalCamera = "-250.34375,290.249023,178.650391,0.000827,-14.39187,-22.798668,35.000011,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          GUID = "191E9E12",
          NextDialogue = 10034214,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9E12"
        },
        [10034214] = {
          Camera = "-99.214844,448.524414,117.580078,0.000858,7.807739,-110.798241,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          Content = "嗯，赛琪那件事没有任何人有错。一定要说哪个该死，那大概只有这个扭曲的时代吧。",
          ContentKR = "음, 프시케의 일은 아무도 잘못한 게 없어. 꼭 누군가를 탓해야 한다면, 그건 이 뒤틀린 시대밖에 없겠지.",
          DialogueId = 10034214,
          FinalCamera = "-89.992188,445.055664,117.580078,0.000856,7.807739,-113.997963,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          GUID = "191E9E3C",
          NextDialogue = 10034219,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-44.121094,598.605469,88.085938,0.000868,6.607477,-102.801109,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-39.066406,621.015625,85.417969,0.000871,6.807472,-103.001343,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film\"},duration{5}}},PlayAnimation{_delay{3},ActorId{200021},AnimationId{\"ConfidentLRToTalk01_End\"},Duration{2}}}",
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:ConfidentLRToTalk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9E3C"
        },
        [10034215] = {
          Content = "不，我还是无法谅解。",
          ContentKR = "아니, 아직은 용서 못 해.",
          DialogueId = 10034215,
          GUID = "191E9E66",
          NextDialogue = 10034216
        },
        [10034216] = {
          Camera = "31.164062,344.773438,103.396484,0.000867,11.206885,-154.599243,35.000011,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          Content = "我明白的，有些事很沉重，太沉重了……绝不是一句“算了吧”就能轻飘飘带过。",
          ContentKR = "알아, 너무 무겁고 무거워서 '그냥 잊어버려'라고 하면서 가볍게 넘길 수 있는 일이 아니지.",
          DialogueId = 10034216,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          FinalCamera = "35.367188,335.894531,103.396484,0.000868,11.206885,-157.59964,35.000011,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          GUID = "191E9E90",
          NextDialogue = 10034217,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9E90"
        },
        [10034217] = {
          Camera = "-64.0625,325.602539,167.652344,0.000887,-56.191696,118.603279,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          Content = "不用逼着自己原谅什么，按自己的本心来就好。",
          ContentKR = "꼭 뭔가를 납득하려고 자신을 강요하지 않아도 돼, 그저 본심을 따르면 되는 거야.",
          DialogueId = 10034217,
          FinalCamera = "-70.183594,322.261719,167.652344,0.000858,-55.591667,110.602448,35.000008,527.224426,false,DoNotOverride,2.038203,16:9 Digital Film",
          GUID = "191E9EBA",
          NextDialogue = 10034218,
