        [10034322] = {
          Camera = "62.244629,67.1026,108.648438,0.0002,9.797967,-38.907223,30.0,107.425705,false,Manual,1.2,16:9 Digital Film",
          Content = "在我小时候，我的父母不慎收留了一名伪装成普通人的秽蚀者……后来的事你们大概可以猜到了。那名秽蚀者变成秽兽，袭击了整片街区，很多人丧生。",
          ContentKR = "제가 어렸을 때, 저의 부모님은 실수로 평범한 사람으로 위장한 침식자를 받아들였습니다... 그 후의 일은 여러분도 대충 짐작하실 수 있을 겁니다. 그 침식자는 필토이드가 되어 온 동네를 습격했고, 많은 사람들이 목숨을 잃었습니다.",
          DialogueId = 10034322,
          FacialId = {
            [1] = "100361:Disappoint01"
          },
          FinalCamera = "62.244629,67.1026,108.648438,0.000201,9.997955,-39.907112,31.0,106.964676,false,Manual,1.2,16:9 Digital Film",
          GUID = "191EAFF4",
          NextDialogue = 10034323,
          SpeakNpcId = 100361,
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1003/100343/191EAFF4"
        },
        [10034323] = {
          Camera = "-130.825195,82.583252,114.78125,0.000176,1.399355,-16.117037,37.000015,311.120117,false,Manual,1.2,16:9 Digital Film",
          Content = "按照海伯利亚的律法，收留秽蚀者的市民与秽蚀者同罪。",
          ContentKR = "휘페르보레아의 법에 따르면, 침식자를 받아들인 시민은 침식자와 같은 죄를 지은 것으로 간주합니다.",
          DialogueId = 10034323,
          FinalCamera = "-127.814941,91.322998,114.78125,0.000176,1.799379,-19.516514,37.000015,311.120117,false,Manual,1.2,16:9 Digital Film",
          GUID = "191EB01E",
          NextDialogue = 10034324,
          SpeakNpcId = 100361,
