        [10034545] = {
          Camera = "58.495117,-31.134766,130.94043,0.000255,1.197216,122.468346,35.0,198.150391,false,DoNotOverride,2.669626,16:9 Digital Film",
          Content = "我看看……嗯，物资清单上还有最后一项，送到雾区的鱼。",
          ContentKR = "어디 보자... 음, 물자 목록에 마지막 항목이 남아 있네요. 안개 구역으로 보내야 할 생선이에요.",
