        [10034546] = {
          Camera = "-12.336914,-66.583008,102.745605,0.000291,-9.999444,-97.554825,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "哇，是钓鱼诶——我也要钓我也要钓！",
          ContentKR = "우와, 낚시라니, 나도 할래, 나도 할래!",
          DialogueId = 10034546,
          FacialId = {
            [1] = "200002:Smile02"
          },
