        [10034601] = {
          Content = "呵呵……",
          ContentKR = "하하...",
          DialogueId = 10034601,
          GUID = "191EDDBA",
          NextDialogue = 10034602,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDDBA"
        },
        [10034602] = {
          Content = "你笑什么？",
          ContentKR = "왜 웃는 거죠?",
          DialogueId = 10034602,
          GUID = "191EDDE4",
          NextDialogue = 10034603,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDDE4"
        },
        [10034603] = {
          Content = "我想起上次这样在湖边钓鱼，还是三年前和布鲁斯一起。",
          ContentKR = "그러고 보니, 호숫가에서 이렇게 낚시했던 건 3년 전 블루스와 함께였던 때였네요.",
          DialogueId = 10034603,
          GUID = "191EDE0E",
          NextDialogue = 10034604,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE0E"
        },
        [10034604] = {
          Content = "那家伙虽然聪明，但太好动了，根本坐不住。所以他钓一整天，篓子都是空的。",
          ContentKR = "그 녀석은 똑똑하긴 한데, 너무 산만해서 가만히 못 앉아 있어요. 그래서 하루 종일 낚시해도 바구니가 텅 비어 있었죠.",
          DialogueId = 10034604,
          GUID = "191EDE38",
          NextDialogue = 10034605,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE38"
        },
        [10034605] = {
          Content = "……不知道他现在在内城过得怎么样了，有没有学会钓鱼。",
          ContentKR = "...그 녀석, 내성에선 어떻게 지내고 있을지, 낚시하는 법은 좀 배웠으려나요.",
          DialogueId = 10034605,
          GUID = "191EDE62",
          NextDialogue = 10034606,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE62"
        },
        [10034606] = {
          Content = "哼哼，你们这些凡人啊，总被这些乱七八糟的感情羁绊，不像本魔王大人。",
          ContentKR = "흥, 인간들은 항상 이런저런 감정에 얽매이네. 본 마왕님처럼 초연하지도 못하고 말이야.",
          DialogueId = 10034606,
          GUID = "191EDE8C",
          NextDialogue = 10034607,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE8C"
        },
        [10034607] = {
          Content = "没事的小矮子，我们也是你的家人。只要你开心，让我管你叫奶奶都行。",
          ContentKR = "걱정 마, 꼬맹이. 우리도 너의 가족이니까. 네가 즐겁다면, 내가 널 할머니로 모셔도 상관없어.",
          DialogueId = 10034607,
          GUID = "191EDEB6",
          NextDialogue = 10034608,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDEB6"
        },
        [10034608] = {
          Content = "你，你怎么突然这么好……",
          ContentKR = "너, 너 왜 갑자기 나한테 잘해줘...",
          DialogueId = 10034608,
          GUID = "191EDEE0",
          NextDialogue = 10034609,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDEE0"
        },
        [10034609] = {
          Content = "奶奶，我饿，给点零用钱。",
          ContentKR = "할머니, 배고파요, 용돈 좀 주세요.",
          DialogueId = 10034609,
          GUID = "191EDF0A",
          NextDialogue = 10034610,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF0A"
        },
        [10034610] = {
          Content = "可恶！",
          ContentKR = "젠장!",
          DialogueId = 10034610,
          GUID = "191EDF34",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF34"
        },
        [10034611] = {
          Content = "这样就齐了，把物资送到雾区吧。",
          ContentKR = "이제 다 준비됐어요. 물자를 안개 구역으로 가져갑시다.",
          DialogueId = 10034611,
          GUID = "191EDF5E",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF5E"
        },
        [10034612] = {
          Content = "宵禁期间禁止通行，请各位市民配合！",
          ContentKR = "야간 통행금지 기간입니다! 시민 여러분의 협조 바랍니다!",
          DialogueId = 10034612,
          GUID = "191EDF60",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF60"
        },
        [10034613] = {
          Content = "（<H>地面都被士兵封锁了</>……或许可以试试别的路——比如<H>楼顶</>？）",
          ContentKR = "(<H>지상은 병사들이 전부 막고 있네</>... 다른 길로 가 봐야겠어... <H>옥상</>은 어떠려나?)",
          DialogueId = 10034613,
          GUID = "191EDF61",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF61"
        },
        [10034701] = {
          Camera = "652.730713,189.380859,547.563965,0.000151,-33.996532,-163.577209,35.000008,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "哇，黎瑟长官，你真的把吃的送来了！而且比之前说好的还快！",
          ContentKR = "와, 리듬 장교님! 정말 음식을 가져오셨네요! 게다가 약속했던 것보다 더 빨리요!",
          DialogueId = 10034701,
