        [10034813] = {
          Camera = "1.158203,334.078125,122.950684,-0.00177,4.227047,-0.062805,35.000023,427.577942,false,DoNotOverride,3.623266,16:9 Digital Film",
          Content = "好的。",
          ContentKR = "알겠습니다.",
          DialogueId = 10034813,
          FacialId = {
            [1] = "100304:Confident01"
          },
          GUID = "191F0082",
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100348/191F0082"
        },
        [10034814] = {
          Content = "与剧院帷幕材质十分接近的布料，虽然老旧但十分整洁，显然被什么人认真打理过。\n仔细观察和触摸会发现，和袭击现场发现的帷幕是同一块布料。",
          ContentKR = "극장 커튼의 재질과 매우 유사한 천으로, 비록 낡았지만 매우 깔끔하게 정리되어 있다. 누군가가 신경 써서 관리한 것이 분명하다.\n\n자세히 관찰하고 만져보면, 이 천이 습격 현장에서 발견된 커튼과 동일한 천이라는 것을 알 수 있다.",
          DialogueId = 10034814,
          GUID = "191F00AC",
          VoiceName = "voice/$Locale$/story/1003/100348/191F00AC"
        },
        [10034815] = {
          Content = "假人模型虽然很旧，但造型和姿势明显经过了精心设计，看起来端庄而优雅，如同在舞台上纵情表演的演员。",
          ContentKR = "마네킹 모형은 비록 오래되었지만, 형태와 자세가 정성스럽게 디자인되어, 무대에서 한껏 연기를 펼치는 배우처럼 단정하면서도 우아한 느낌을 풍긴다.",
          DialogueId = 10034815,
          GUID = "191F00D6",
          VoiceName = "voice/$Locale$/story/1003/100348/191F00D6"
        },
        [10034816] = {
          Content = "四周遍布着巨大的爪痕，密集而凌乱，似是在极度的痛苦和疯狂中留下的。",
          ContentKR = "사방이 거대한 발톱 자국으로 가득하다. 극심한 고통과 광기 속에서 미친 듯이 할퀴며 남긴 흔적 같다.",
          DialogueId = 10034816,
          GUID = "191F0100",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0100"
        },
        [10034817] = {
          Camera = "-470.862305,336.71875,225.989624,0.000123,-12.395741,-25.18132,31.654133,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "我彻查了下方区域，没有异常，你们有什么发现吗？",
          ContentKR = "아래쪽 구역은 제가 전부 확인했습니다만, 이상은 없었습니다. 여러분은 뭔가 발견하셨나요?",
          DialogueId = 10034817,
          FinalCamera = "-470.862305,336.71875,205.012207,0.000122,-11.195704,-25.18092,31.654133,100000.0,false,Manual,22.0,16:9 Digital Film",
