        [10035226] = {
          Camera = "-767.976807,-468.421631,1021.622314,0.000127,-46.820312,30.559282,35.0,1471.360107,false,Manual,22.0,16:9 Digital Film",
          Content = "你还记得我说过一件事吗？我的父母是被秽兽杀害的，因为他们收留了一名伪装成常人的秽蚀者……",
          ContentKR = "제가 예전에 한 가지 말씀드린 거 기억하시나요? 제 부모님은 필토이드에게 살해당했어요. 평범한 사람으로 위장한 침식자를 받아들였기 때문이었죠...",
          DialogueId = 10035226,
          FinalCamera = "-783.698853,-437.067078,1022.494141,0.000135,-46.820293,30.359089,35.0,1471.360107,false,Manual,22.0,16:9 Digital Film",
          GUID = "191F4444",
          LookAt = {
            [1] = "200002:n(100304)"
          },
          NextDialogue = 10035227,
          Scripts = [[
