MoveTo{ActorId{200002},TargetPoint{"TargetPoint_cp2fixsimple47_xiaobaiHide"},MoveSpeed{60},Visibility{"Show"}}
}]],
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1003/100352/191F4444"
        },
        [10035227] = {
          Camera = "-31.82811,20.605799,47.986328,-10.012484,51.563259,6.457195,18.0,105.517471,false,Manual,3.0,16:9 Digital Film",
          Content = "但……没有人知道……真正的罪人，是我。那个晚上，是我央求妈妈，“那个大哥哥好像快不行了，我们帮帮他好不好。”",
          ContentKR = "하지만... 아무도 몰라요... 진짜 죄인은 저라는 걸요. 그날 밤, 제가 엄마에게 부탁했거든요. “저 오빠가 너무 힘들어 보여요. 우리가 좀 도와주면 안 될까요?” 하고요.",
          DialogueId = 10035227,
          FacialId = {
            [1] = "100304:Sad01"
          },
          FinalCamera = "-6.432026,22.505722,89.076172,-10.01455,51.962456,0.059592,16.0,57.592651,false,Manual,3.0,16:9 Digital Film",
          GUID = "191F446E",
          NextDialogue = 10035228,
          Scripts = [[
