        [10035229] = {
          Camera = "-234.232544,-55.80162,49.559814,0.000288,15.979787,17.355488,45.0,312.70285,false,Manual,3.0,16:9 Digital Film",
          Content = "我的妈妈……她不恨我，一直到秽兽的爪子刺穿她的身体，她都没有指责过我半句。可是我多希望、多希望她能打我，骂我……而不是原谅我。",
          ContentKR = "엄마는... 저를 미워하지 않으셨습니다. 필토이드의 발톱이 그녀의 몸을 꿰뚫는 순간까지도, 단 한 마디도 저를 탓하지 않으셨죠. 하지만 저는 얼마나 바랐는지 몰라요. 제발 저를 때려주시길, 저를 꾸짖어주시길... 용서가 아니라, 그런 걸 원했습니다.",
          DialogueId = 10035229,
          FacialId = {
            [1] = "100304:Sad02"
          },
          FinalCamera = "-223.185394,-52.350403,52.874756,0.000288,15.979787,17.355488,45.0,312.70285,false,Manual,3.0,16:9 Digital Film",
          GUID = "191F44C2",
