        },
        [10035232] = {
          Camera = "-514.289307,44.722595,247.631836,0.000043,-15.820329,-3.607711,35.0,612.436279,false,Manual,22.0,16:9 Digital Film",
          Content = "抱歉，拉着你们絮叨了这么多陈年旧事……该继续行动了！趁着天色还不晚。",
          ContentKR = "죄송합니다, 여러분을 붙잡아 놓고 이렇게 오래된 이야기를 늘어놓다니... 이제 다시 움직여야겠어요! 아직 해가 지기 전에 말입니다.",
          DialogueId = 10035232,
          FacialId = {
