        },
        [10035235] = {
          Camera = "-152.189682,50.255051,133.710449,0.000057,0.579876,-3.407065,35.000008,194.348434,false,Manual,5.0,16:9 Digital Film",
          Content = "这是我自己的选择，而且我已经没有其他可以调动的下属了。所以各位不必陪我继续涉险。",
          ContentKR = "이건 제 스스로 내린 선택입니다. 게다가 이제 더 이상 저를 도울 수 있는 부하도 없어요. 그러니 여러분은 굳이 저를 따라 위험에 뛰어들 필요는 없습니다.",
          DialogueId = 10035235,
