        [10035252] = {
          Camera = "-56.100571,-8.342358,115.075195,0.000082,8.198917,-0.569315,30.000013,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "抱歉，我说过我五音不全……唉，如果当时布鲁斯缠着我听录音带的时候，我没有偷偷睡觉就好了。",
          ContentKR = "죄송해요, 저도 음치라고 말씀드렸잖아요... 하아, 그때 블루스가 저에게 녹음테이프를 들려주겠다고 졸라댔을 때 몰래 잠만 자지 않았더라면 좋았을 텐데요.",
          DialogueId = 10035252,
          FacialId = {
