          Content = "好家伙！谢谢布鲁斯，哥们儿帮大忙了。队长，咱们再回一趟那个秘密基地吧。",
          ContentKR = "좋았어! 블루스, 고맙다, 친구야. 큰 도움이 됐어. 대장, 우리 다시 한번 그 비밀 아지트로 가보자!",
          DialogueId = 10035254,
          GUID = "191F48DC",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(200021)",
            [3] = "100304:n(200021)",
            [4] = "100001:n(200021)"
          },
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100352/191F48DC"
        },
        [10035255] = {
          Content = "由冰湖城开往迪斯玛尼亚的列车将在一小时后出发。祝第十三军团返程顺利，荣耀尽归吾皇！",
          ContentKR = "아이스레이크 시티에서 디즈마니아로 향하는 열차가 한 시간 후 출발합니다. 제13군단의 귀환이 순조롭기를 바랍니다, 황제 폐하께 영광을!",
          DialogueId = 10035255,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "191F4906",
          SpeakNpcName = "Cp2CharacterName30",
          VoiceName = "voice/$Locale$/story/1003/100352/191F4906"
        },
        [10035301] = {
          Content = "收集这么多录音带，你弟弟是不是很富有呀！",
          ContentKR = "이렇게 많은 녹음테이프를 모으다니, 동생 분은 꽤 형편이 좋으신가 봐!",
          DialogueId = 10035301,
          GUID = "191F5092",
          NextDialogue = 10035302,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5092"
        },
        [10035302] = {
          Content = "不是的，那些都是他从朋友那里翻录的。",
          ContentKR = "아니에요, 그건 전부 블루스가 친구들 테이프를 복사해 온 겁니다.",
          DialogueId = 10035302,
          GUID = "191F50BC",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F50BC"
        },
        [10035303] = {
          Content = "旋律很像，但不太一样，凶手的声音更悲伤一些。",
          ContentKR = "멜로디가 비슷하긴 한데, 조금 달라. 범인의 목소리는 더 슬픈 느낌이었어.",
          DialogueId = 10035303,
          GUID = "191F50E6",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100353/191F50E6"
        },
        [10035304] = {
          Content = "耳朵，我的耳朵！这也能叫歌吗！布鲁斯暗算我！",
          ContentKR = "귀, 내 귀! 이것도 노래라고 할 수 있는 건가! 블루스가 날 속였어!",
          DialogueId = 10035304,
          GUID = "191F5110",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5110"
        },
        [10035305] = {
          Content = "这个……感觉不太像。",
          ContentKR = "이건... 뭔가 좀 아닌 것 같아.",
          DialogueId = 10035305,
          GUID = "191F513A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100353/191F513A"
        },
        [10035306] = {
          Camera = "375.742188,-433.851562,288.041016,0.00005,-17.800415,125.025429,25.000002,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "这些就是全部了吗？",
          ContentKR = "이게 전부인가?",
          DialogueId = 10035306,
          FinalCamera = "317.1875,-472.192383,288.041016,0.000045,-19.000452,121.826225,25.000002,100000.0,false,Manual,22.0,16:9 Digital Film",
