        [10035412] = {
          Camera = "749.542969,-320.927246,358.976562,0.000014,-16.229792,146.761581,50.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "布鲁斯？你为什么打扮成这样……你的嗓子怎么了……？",
          ContentKR = "블루스? 왜 그런 옷을 입고 있어...? 목소리는 또 왜 그래...?",
          DialogueId = 10035412,
          FacialId = {
            [1] = "100304:Shock02"
          },
          FinalCamera = "720.9375,-367.028809,358.976562,0.000011,-16.029818,142.962021,50.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          GUID = "191F62C8",
          LookAt = {
            [1] = "100304:n(100327)"
          },
          NextDialogue = 10035413,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100354/191F62C8"
        },
        [10035413] = {
          Camera = "720.9375,-367.028809,358.976562,0.000011,-16.029818,142.962021,50.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "你不是一直在内城服役吗？为什么……你会……",
          ContentKR = "내성에서 복무하고 있던 거 아니었어? 왜... 네가...",
          DialogueId = 10035413,
          GUID = "191F62F2",
          NextDialogue = 10035414,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100354/191F62F2"
        },
        [10035414] = {
          Camera = "720.9375,-367.028809,358.976562,0.000011,-16.029818,142.962021,50.0,100000.0,false,Manual,22.00,16:9 Digital Film",
          Content = "呵……",
          ContentKR = "허...",
          DialogueId = 10035414,
          GUID = "191F631C",
          NextDialogue = 10035415,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName09",
          VoiceName = "voice/$Locale$/story/1003/100354/191F631C"
        },
        [10035415] = {
          Camera = "221.476562,-7.47168,109.081543,0.0,8.568786,171.554718,35.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "不对，你在说谎。我的弟弟布鲁斯热诚又善良，他视他人的痛苦为自己的痛苦，视所有同胞为手足！他不可能犯下<H>卡戎狩猎</>这种暴行！",
          ContentKR = "아니야, 거짓말이야. 내 동생 블루스는 열정적이고 착한 사람이야. 그는 타인의 고통을 자신의 고통으로 여기고, 모든 동포를 형제처럼 여겼어! 그런 그가 <H>카론 사냥</> 같은 잔혹한 짓을 저질렀을 리 없잖아!",
          DialogueId = 10035415,
          FacialId = {
            [1] = "100304:Unhappy01"
          },
          FinalCamera = "196.777344,-3.805176,112.84082,0.0,8.568786,171.554718,35.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          GUID = "191F6346",
          LookAt = {
            [1] = "100304:n(100304)"
          },
          NextDialogue = 10035425,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Think_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F6346"
        },
        [10035416] = {
          Camera = "196.777344,-3.805176,112.84082,0.0,8.568786,171.554718,35.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "这是，小时候……我给布鲁斯做的链子……",
          ContentKR = "이건, 어릴 때... 내가 블루스를 위해 만든 체인이잖아...",
          DialogueId = 10035416,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter02_HarmonicaChain.T_Guide_Chapter02_HarmonicaChain'}",
          GUID = "191F6370",
          NextDialogue = 10035417,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/02/chainpocket\"},PlayAs2D{true}}",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100354/191F6370"
        },
        [10035417] = {
          Camera = "-29.5625,-71.805176,165.97998,0.0,11.16768,18.558241,50.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "还给你吧。军团，背叛了我。再也，用不到它了。",
          ContentKR = "돌려줄게. 군단은, 날 배신했어. 이젠, 그건, 더 이상 필요 없어.",
          DialogueId = 10035417,
          GUID = "191F639A",
          LookAt = {
            [1] = "100304:n(100327)"
          },
          NextDialogue = 10035418,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName09",
          TalkActionId = {
            [1] = "100304:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100354/191F639A"
        },
        [10035418] = {
          Camera = "119.15625,42.66748,164.325195,0.00001,-11.431517,-163.217941,35.000008,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "黎瑟，先别激动。我们之前领教过它的狡猾，它很可能是在借你弟弟的名头，实际别有所图。",
          ContentKR = "리듬 씨, 일단 흥분하지 마세요. 우리 전에 그놈의 교활함을 겪어봤잖아요. 동생의 이름을 훔쳐서 다른 속셈을 꾸미고 있을 가능성이 커요.",
          DialogueId = 10035418,
          FinalCamera = "156.070312,53.80127,172.121582,0.00001,-11.431517,-163.217941,35.000008,100000.0,false,Manual,22.0,16:9 Digital Film",
          GUID = "191F63C4",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          NextDialogue = 10035419,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F63C4"
        },
        [10035419] = {
          Camera = "-331.53125,-373.69873,96.422363,10.800302,6.167674,40.957329,35.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "……我多希望你说的是真的。但它的每一个动作，我都太熟悉了……",
          ContentKR = "...당신 말이 사실이길 얼마나 바라는지 모릅니다. 하지만 저 녀석의 모든 동작은, 저에겐 너무나 익숙한걸요...",
          DialogueId = 10035419,
          FinalCamera = "-289.46875,-337.193848,102.441895,7.200046,6.167674,40.957287,35.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          GUID = "191F63EE",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10035420,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "100304:DisagreeHead"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F63EE"
        },
        [10035420] = {
          Camera = "40.863281,-1146.140381,-4.161133,0.000027,7.377881,83.959587,50.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "尤其是那个伸手在背后找东西的样子，和小时候的布鲁斯一模一样。",
          ContentKR = "특히 손을 뒤로 뻗어 뭔가를 찾는 그 모습, 어린 시절의 블루스랑 똑같습니다.",
          DialogueId = 10035420,
          FacialId = {
            [1] = "100304:Sad01"
          },
          GUID = "191F6418",
          LookAt = {
            [1] = "100304:n(100327)"
          },
          NextDialogue = 10035421,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100354/191F6418"
        },
        [10035421] = {
          Camera = "145.246094,50.835938,159.95459,0.000014,-7.221675,-164.220459,35.000008,100000.0,false,Manual,13.900117,16:9 Digital Film",
          Content = "……这么说来，它在见到黎瑟后，的确<H>一直在留手，没有伤害我们</>。",
          ContentKR = "...그러고 보니, 리듬을 만난 뒤로 계속 <H>우리를 공격하지 않고 봐주고 있었던 것 같아</>.",
          DialogueId = 10035421,
          GUID = "191F6442",
          LookAt = {
            [1] = "100001:n(100327)"
          },
          NextDialogue = 10035422,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100354/191F6442"
        },
        [10035422] = {
          Camera = "145.246094,50.835938,159.95459,0.000014,-7.221675,-164.220459,35.000008,100000.0,false,Manual,13.900117,16:9 Digital Film",
          Content = "你还有意识，而且<H>你身上那些好像并不是铠甲</>……更像是……身体的一部分。你经历了什么？“军团背叛了你”是什么意思？",
          ContentKR = "넌 아직 의식이 있어. 게다가 <H>네 몸에 있는 저건 갑옷이 아니라</>... 그냥 몸의 일부처럼 보여. 대체 무슨 일이 있었던 거야? \"군단이 배신했다\"는 건 또 무슨 뜻이야?",
          DialogueId = 10035422,
          GUID = "191F646C",
          NextDialogue = 10035423,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100354/191F646C"
        },
        [10035423] = {
          Camera = "-1343.695312,-699.813721,314.711426,10.834046,-7.832737,28.140293,50.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "……你的，直觉，很敏锐。但这在帝国，不一定是，好事……",
          ContentKR = "...너의, 직감, 꽤 날카로워. 하지만 제국에서, 그건 꼭 좋은 일만은, 아니지...",
          DialogueId = 10035423,
          FinalCamera = "-1351.945312,-685.367432,310.913574,10.833482,-7.832731,28.140591,50.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          GUID = "191F6496",
          LookAt = {
            [1] = "100327:n(100001)"
          },
          NextDialogue = 10035424,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F6496"
        },
        [10035424] = {
          Camera = "-1351.945312,-685.367432,310.913574,10.833482,-7.832731,28.140591,50.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "……黎瑟，我的姐姐……让我来告诉你吧，“桂冠卡戎”的，真相……",
          ContentKR = "...리듬, 내 누나... 내가 알려줄게. '계관카론'의, 진실을...",
          DialogueId = 10035424,
          GUID = "191F64C0",
          LookAt = {
            [1] = "100327:n(100304)"
          },
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100354/191F64C0"
        },
        [10035425] = {
          Camera = "53.945312,-48.872559,263.330078,0.000002,-24.832872,18.36636,28.000006,100000.0,false,Manual,22.0,16:9 Digital Film",
          DialogueId = 10035425,
          DialoguePanelType = "None",
          Duration = 7,
          GUID = "191F6347",
          NextDialogue = 10035416,
          Scripts = "PlayAnimation{_delay{0},ActorId{100327},AnimationId{\"Tuosi02_Story_Find02_Start\"},Duration{5}}"
        },
        [10035501] = {
          Content = "“桂冠卡戎”——我曾视它为一颗最璀璨的金刚石。\n它在梦想的尽头熠熠生辉，如冰湖城最高处，那盏不灭的明灯。",
          ContentKR = "'계관카론', 난 한때 그걸 가장 빛나는 다이아몬드로 여겼어.\n꿈의 끝에서 반짝이며, 마치 아이스레이크 시티 가장 높은 곳에 있는 꺼지지 않는 등불처럼 말이야.",
          DialogueId = 10035501,
          Duration = 4,
          GUID = "191F7162",
          NextDialogue = 10035502,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7162"
        },
        [10035502] = {
          Content = "后来我才知道，那并非坚硬的金刚石。\n它是玻璃——折射着虚幻的光，美丽，夺目，\n但一颗卵石，一块泥砖，便将它轻易打碎。",
          ContentKR = "나중에야 알게 됐어, 그건 단단한 다이아몬드가 아니었어.\n그건 유리야. 허상의 빛을 반사하며 아름답고 눈부셨지만,\n조약돌 하나, 진흙 벽돌 한 조각에도 쉽게 산산조각이 났어.",
          DialogueId = 10035502,
          Duration = 4,
          GUID = "191F718C",
          NextDialogue = 10035503,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F718C"
        },
        [10035503] = {
          Content = "通过第六军团考核的卡戎之民，与任人宰割的困兽没有任何区别。\n倒不如说我们宁愿成为一头无知麻木的野兽——\n这样我们便不会为破灭的梦而痛苦，不会因无法完成的约定而恸哭。",
          ContentKR = "제6군단의 시험을 통과한 카론은 도살당할 운명의 가엾은 짐승과 다를 바가 없었어.\n오히려 무지하고 무감각한 짐승이 되는 편이 나았을지도 몰라.\n그랬다면 무너진 꿈에 고통받지도, 이루지 못한 약속에 통곡하지도 않았을 테니까.",
          DialogueId = 10035503,
          Duration = 4,
          GUID = "191F71B6",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F71B6"
        },
        [10035504] = {
          Content = "（好刺眼的灯光……这是哪里？我记得通过考核后，被派到第六军团炼金院工作，然后……）",
          ContentKR = "(윽 눈부셔... 여긴 어디지? 분명 시험을 통과한 후 제6군단 연금원에서 일하게 되었는데...)",
          DialogueId = 10035504,
          GUID = "191F71E0",
          RelatedWikiId = {
            [1] = 407003,
            [2] = 201024
          },
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F71E0"
        },
        [10035505] = {
          Content = "老师，改造体的意识好像提前苏醒了。它看起来很痛苦，我再取一点麻醉剂。",
          ContentKR = "선생님, 개조체가 예상보다 일찍 깨어났는데요. 아주 괴로워 보이는데 마취제를 좀 더 가져오겠습니다.",
          DialogueId = 10035505,
          GUID = "191F720A",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100355/191F720A"
        },
        [10035506] = {
          Content = "无妨，醒了就醒了吧。做好准备，2分钟后开始采集它的抗性数据。",
          ContentKR = "괜찮으니 그대로 둬. 2분 뒤에 저항성 데이터를 수집할 수 있게 준비한다.",
          DialogueId = 10035506,
          GUID = "191F7234",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7234"
        },
        [10035507] = {
          DialogueId = 10035507,
          GUID = "191F725E",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F725E"
        },
        [10035508] = {
          Content = "老师，数据出来了。它在这批改造体中的抗性表现优异，电流未能直接击穿您移植进去的第二心脏，火焰损伤了它的人造皮肤，导致它的体温远高于正常值。",
          ContentKR = "데이터가 나왔습니다. 개조체의 저항성은 이번 실험체 중에 뛰어난 편입니다. 전류는 이식한 두 번째 심장을 직접 관통하지 못했고, 화염이 인공 피부를 손상시켜 체온이 정상치를 크게 상회합니다.",
          DialogueId = 10035508,
          GUID = "191F7288",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7288"
        },
        [10035509] = {
          Content = "数据记录完毕。我先带它回去休息吧，它的体力恐怕撑不住了。",
          ContentKR = "데이터는 기록했습니다. 일단 좀 쉬게 하죠, 놈의 체력이 버티지 못할 것 같습니다.",
          DialogueId = 10035509,
          GUID = "191F72B2",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100355/191F72B2"
        },
        [10035510] = {
          Content = "不要对这些恶魔报以无谓的怜悯。注射镇定剂，固定好四肢，接下来要进行强化实验了。",
          ContentKR = "이 악마들에게 쓸데없는 동정을 품지 말거라. 진정제를 주사하고 사지를 고정해. 강화 실험을 시작하겠다.",
          DialogueId = 10035510,
          GUID = "191F72DC",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100355/191F72DC"
        },
        [10035511] = {
          Content = "（痛……好痛啊……你们到底对我做了什么，全身每一处毛孔都在哀嚎着疼痛，你们听不到吗！）",
          ContentKR = "(아파... 너무 아파... 대체 나한테 무슨 짓을 한 거야. 온몸의 모든 모공마저도 고통에 비명을 지르고 있는데... 안 들리는 거냐고!)",
          DialogueId = 10035511,
          GUID = "191F7306",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7306"
        },
        [10035512] = {
          Content = "多么丰富的表情。怎么？想要吠叫什么？可惜没机会了。",
          ContentKR = "표정이 참 풍부하군. 왜? 짖어 보고 싶은 건가? 안타깝지만 기회는 없을 거야.",
          DialogueId = 10035512,
          GUID = "191F7330",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7330"
        },
        [10035513] = {
          Content = "镇定剂注射完毕。老师，我还是觉得——",
          ContentKR = "진정제 주사 완료했습니다. 선생님, 제 생각엔 아무래도...",
          DialogueId = 10035513,
          GUID = "191F735A",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100355/191F735A"
        },
        [10035514] = {
          Content = "听我吩咐。从它最敏感的尖角开始取样，这样我们才能得到更精确的数据。",
          ContentKR = "내 말대로 해. 가장 민감한 뿔 끝부분부터 샘플을 채취해. 그래야 더 정확한 데이터를 얻을 수 있다.",
          DialogueId = 10035514,
          GUID = "191F7384",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7384"
        },
        [10035515] = {
          Content = "……是，老师……",
          ContentKR = "...네, 선생님...",
          DialogueId = 10035515,
          GUID = "191F73AE",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100355/191F73AE"
        },
        [10035516] = {
          Content = "（好痛……好痛……这就是身为“恶魔的孩子”，必须经受的惩罚吗……）",
          ContentKR = "(너무 아파... 너무 아파... 이게 바로 '악마의 아이'로서 반드시 받아야 할 벌인 건가...)",
          DialogueId = 10035516,
          GUID = "191F73D8",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F73D8"
        },
        [10035517] = {
          Content = "（但无论是怎样的罪孽，这样的痛苦……也早该还清了吧……！）",
          ContentKR = "(하지만 아무리 큰 죄라 해도, 이런 고통은... 진작에 다 갚았어야 맞는 거잖아...!)",
          DialogueId = 10035517,
          GUID = "191F7402",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7402"
        },
        [10035518] = {
          Content = "我们不知道这样的日子过去了多久，只知道自己的身体正一步步变成可怖的怪物。心也变得越发冰冷，碎裂在泪湖的冷风之中。",
          ContentKR = "우린 이런 날들이 얼마나 흘렀는지도 알 수 없었어...\n그저 우리 몸이 점점 흉측한 괴물로 변해가고 있다는 것만 느껴졌지.\n마음도 점점 얼어붙었고, 눈물의 호수 위로 불어오는 차가운 바람 속에서 산산조각이 나버렸어...",
          DialogueId = 10035518,
          GUID = "191F742C",
          NextDialogue = 10035519,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F742C"
        },
        [10035519] = {
          Content = "生而为人的旧日记忆渐行渐远。最终，连名字都被遗忘。",
          ContentKR = "사람으로 태어났던 옛 기억은 점점 멀어져 갔어. 결국, 이름조차 잊히고 말았지.",
          DialogueId = 10035519,
          GUID = "191F7456",
          NextDialogue = 10035520,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7456"
        },
        [10035520] = {
          Content = "布鲁斯·费西尔死了。取而代之的是<W>47号</>——这个新的“称呼”。",
          ContentKR = "블루스 페실은 죽었어. 이제 남은 건 <W>47번</>이라는 새 '호칭'뿐이야.",
          DialogueId = 10035520,
          GUID = "191F7480",
          NextDialogue = 10035521,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName02",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7480"
        },
        [10035521] = {
          Content = "可即使如此，我们的肉体依旧在苟延残喘地挣扎着。",
          ContentKR = "하지만 그런데도, 우리의 육체는 여전히 비참하게 발버둥 치며 버티고 있었어.",
          DialogueId = 10035521,
          GUID = "191F74AA",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName02",
          VoiceName = "voice/$Locale$/story/1003/100355/191F74AA"
        },
        [10035522] = {
          Camera = "-4.90918,-156.237305,105.101868,-0.000091,10.758511,116.110672,35.0,100000.0,false,DoNotOverride,2.8,16:9 Digital Film",
          Content = "报告老师，排异反应终止了，各项指标趋于平稳。就是β型抑制剂好像使用太多了，精神状态不稳定。",
          ContentKR = "보고드립니다, 선생님. 배척 반응은 멈췄고, 각종 지표도 안정 상태로 접어들었습니다. 다만 β형 억제제를 너무 많이 사용한 탓인지 정신 상태가 불안정합니다.",
          DialogueId = 10035522,
          FinalCamera = "-9.579102,-158.523438,105.101868,-0.000092,10.758511,114.710289,35.0,100000.0,false,DoNotOverride,2.8,16:9 Digital Film",
          GUID = "191F74D4",
          NextDialogue = 10035523,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-53.197266,-469.569336,49.268738,0.000069,7.559721,84.699837,35.0,100000.0,false,DoNotOverride,2.8,16:9 Digital Film\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-53.197266,-469.569336,49.268738,0.000061,11.159675,84.499451,35.0,100000.0,false,DoNotOverride,2.8,16:9 Digital Film\"},duration{5}}}",
          SpeakNpcId = 100336,
          SpeakNpcName = "Cp2CharacterName05",
          TalkActionId = {
            [1] = "100337:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100355/191F74D4"
        },
        [10035523] = {
          Camera = "-179.390625,29.248047,164.763611,0.000084,-5.841492,-25.696522,35.0,251.812622,false,Manual,2.797869,16:9 Digital Film",
          Content = "精神不过是生命代谢的废料，改造体能回答“是”就足够了。带它去试验场。",
          ContentKR = "정신 따위는 생명 대사의 부산물일 뿐이야. 개조체가 '예'라고 대답할 수 있으면 그걸로 충분하다. 실험장으로 데리고 가라.",
          DialogueId = 10035523,
          FinalCamera = "-182.842773,22.280273,164.763611,0.000086,-5.841492,-21.695681,35.0,251.812622,false,Manual,2.797869,16:9 Digital Film",
          GUID = "191F74FE",
          NextDialogue = 10035524,
          SpeakNpcId = 100337,
          SpeakNpcName = "Cp2CharacterName04",
          TalkActionId = {
            [1] = "100337:Explain01_End",
            [2] = "100336:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100355/191F74FE"
        },
        [10035524] = {
          Camera = "20.333008,-203.238281,111.764038,0.00009,4.758661,116.695335,35.0,251.812622,false,Manual,2.797869,16:9 Digital Film",
          Content = "是，老师。",
          ContentKR = "네, 선생님.",
          DialogueId = 10035524,
          FinalCamera = "20.333008,-203.238281,111.764038,0.000089,7.758616,116.69487,35.0,251.812622,false,Manual,2.797869,16:9 Digital Film",
          GUID = "191F7528",
          SpeakNpcId = 100336,
