        },
        [10036242] = {
          Camera = "1270.355469,72.632324,16.277832,-0.000549,15.796513,-175.065521,35.000011,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "不要跟来。",
          ContentKR = "따라오지 마.",
          DialogueId = 10036242,
          FinalCamera = "1270.355469,72.632324,16.277832,-0.000549,3.996487,-174.865509,35.000011,100000.0,false,Manual,22.0,16:9 Digital Film",
