        [10036508] = {
          Camera = "-0.925781,-102.438721,6.324219,0.000062,27.593143,90.266426,35.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "你还记得你加入军团那天，在三头狼旗下发过的誓言吗？“将此生奉献给皇帝陛下，成为海伯利亚的忠诚战士，至死方休。”",
          ContentKR = "군단에 입단하던 날, 삼두늑대 깃발 아래에서 맹세했던 말을 기억하나? “이번 생을 황제 폐하께 바치고, 휘페르보레아의 충성스러운 전사가 되어 죽을 때까지 싸우겠습니다.”",
          DialogueId = 10036508,
          FinalCamera = "-0.925781,-102.438721,6.324219,0.000062,27.593143,90.266426,35.0,100000.0,false,Manual,22.0,16:9 Digital Film",
