        [10036559] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8,16:9 Digital Film",
          Content = "如果你不是布鲁斯，熟知炼金院那些往事的……就只能是故事里的另一个改造体。",
          ContentKR = "블루스가 아닌데 연금원의 과거를 그렇게 잘 아는 사람은... 이야기 속 또 다른 개조체밖에 없을거고.",
          DialogueId = 10036559,
          GUID = "19201EF6",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100001)"
          },
          NextDialogue = 10036560,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100365/19201EF6"
        },
        [10036560] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8,16:9 Digital Film",
          Content = "此前我也一直想不通，我们大家看到的凶手明明丧失了理智，但你为什么如此冷静？冷静到可以清晰地和我们讲述那么多往事？",
          ContentKR = "계속 이해가 안 됐어. 우리가 본 범인은 분명 이성을 잃은 상태였는데, 어떻게 우리한테 그 많은 과거 얘기를 해줄 수 있을 만큼 침착할 수 있었을까?",
          DialogueId = 10036560,
          GUID = "19201F20",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036560.T_Story_Recall_10036560'",
          NextDialogue = 10036561,
          SnapShot = "MEMORY",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100365/19201F20"
        },
        [10036561] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8,16:9 Digital Film",
          Content = "会不会，你并不是那个犯下“卡戎狩猎”的家伙，只是在扮演它？……不过，这些都是猜的。但你的反应证明……我猜中了。",
          ContentKR = "혹시 넌 진짜 '카론 사냥'을 저지른 사람이 아니라, 그걸 연기하고 있는 거 아닐까?... 뭐, 이건 그냥 추측일 뿐이야. 그런데 네 반응을 보니... 내가 맞춘 것 같네.",
          DialogueId = 10036561,
          GUID = "19201F4A",
          NextDialogue = 10036562,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201F4A"
        },
        [10036562] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8,16:9 Digital Film",
          Content = "你擅长表演，可以模仿布鲁斯的一举一动。你精湛的演技甚至骗过了黎瑟，布鲁斯唯一的亲人。",
          ContentKR = "너는 연기에 능숙해서 블루스의 모든 행동 하나하나를 완벽히 흉내 낼 수 있어. 네 뛰어난 연기력은 블루스의 유일한 가족인 리듬마저 속였을 정도야.",
          DialogueId = 10036562,
          GUID = "19201F74",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036562.T_Story_Recall_10036562'",
          NextDialogue = 10036563,
          SnapShot = "MEMORY",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100365/19201F74"
        },
        [10036563] = {
          Camera = "166.142578,-735.137329,169.679688,0.000134,24.978464,-163.348846,35.000008,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "你喉咙上那道<H>新伤</>，也是故意的吧……你割破喉咙，毁掉了自己的嗓音，是因为你知道，那个声音是无法完全模仿的……",
          ContentKR = "네 목에 있는 그 <H>새 상처</>도 일부러 낸 거겠지... 네가 스스로 목을 그어 목소리를 망가뜨린 건, 그 목소리만큼은 완벽하게 흉내 낼 수 없다는 걸 알고 있었기 때문이야...",
          DialogueId = 10036563,
          FinalCamera = "142.306641,-742.268066,181.257812,0.000135,24.978464,-163.348846,35.000008,100000.0,false,Manual,22.0,16:9 Digital Film",
          GUID = "19201F9E",
          LookAt = {
            [1] = "100327:n(100327)"
          },
          NextDialogue = 10036564,
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100365/19201F9E"
        },
        [10036564] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8,16:9 Digital Film",
          Content = "但是为什么，你要做到这种地步？为什么非得伪装布鲁斯不可？为了担下罪责，帮你的朋友逃脱吗？还是……",
          ContentKR = "하지만 왜? 왜 그렇게까지 해야 했던 거지? 왜 굳이 블루스를 연기해야만 했던 거지? 친구의 죄를 대신 뒤집어쓰고 도망칠 수 있게 도와주려는 거야? 아니면...?",
          DialogueId = 10036564,
          GUID = "19201FC8",
          LookAt = {
            [1] = "100327:n(100001)"
          },
          NextDialogue = 10036565,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201FC8"
        },
        [10036565] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8,16:9 Digital Film",
          Content = "……难道是因为……！",
