        [10037007] = {
          Camera = "524.496094,-71.344421,57.726562,0.000236,0.241358,-133.546417,22.0,449.12384,false,DoNotOverride,3.005529,16:9 Digital Film",
          CameraBlendCurve = "easeOutQuad",
          Content = "是啊，《雪国的孩子》的最后一场。你不是为此准备了很久吗？",
          ContentKR = "그래, 〈설국의 아이〉 마지막 공연. 오늘을 위해 오랫동안 준비한 거 아니야?",
          DialogueId = 10037007,
          FinalCamera = "553.824219,-40.515305,57.5625,0.000236,0.241358,-133.546417,22.0,449.12384,false,DoNotOverride,3.005529,16:9 Digital Film",
