CameraMoveTo{TargetPosition{"252.603516,-1139.067505,153.863281,0.000024,-1.34707,138.250031,100.0,894.799927,false,Manual,8.0,16:9 Digital Film"},Blend{"easeOutQuad"},duration{4.5}}
},
]],
          SpeakNpcId = 100318,
          TalkActionId = {
            [1] = "100318:Talk02_End",
            [2] = "100312:Explain02_Start"
          },
          ToFinalCameraBlendTime = 3.8,
          VoiceName = "voice/$Locale$/story/1003/100370/19206876"
        },
        [10037008] = {
          Camera = "-515.626953,-292.956024,163.917969,0.000079,-2.54723,-53.34362,80.000008,911.690552,false,Manual,8.0,16:9 Digital Film",
          CameraBlendCurve = "easeOutQuad",
          Content = "对、是……是的。老师，我想起来了。",
          ContentKR = "네, 마... 맞아요. 선생님, 저 기억 났어요.",
          DialogueId = 10037008,
          FacialId = {
            [1] = "100312:Confident01"
          },
          FinalCamera = "-510.757812,-289.32901,163.917969,0.000079,-2.54723,-53.34362,80.000008,911.690552,false,Manual,8.0,16:9 Digital Film",
          GUID = "192068A0",
          NextDialogue = 10037009,
          SpeakNpcId = 100312,
          TalkActionId = {
            [1] = "100318:Explain01_End",
            [2] = "100312:Explain02_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100370/192068A0"
        },
        [10037009] = {
          Camera = "-54.876953,-874.34314,116.808594,0.000103,10.605344,-44.881695,50.000008,172.15979,false,Manual,5.0,16:9 Digital Film",
          Content = "这是我必须做的事——<H>完成这场演出</>。",
          ContentKR = "이건 내가 반드시 해야 할 일이야. <H>이 공연을 완성하는 것</>.",
          DialogueId = 10037009,
          FinalCamera = "-54.876953,-874.34314,118.550781,0.000104,10.605344,-45.282009,60.0,172.15979,false,Manual,5.0,16:9 Digital Film",
          GUID = "192068CA",
          SpeakNpcId = 100312,
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1003/100370/192068CA"
        },
        [10037101] = {
          Content = "很久以前，雪国城堡里，冰霜的妖精被两个孩子唤醒",
          ContentKR = "옛날 옛적에, 설국의 성에서 잠에 든 얼음 요정이 두 아이에 의해 깨어났어요",
          DialogueId = 10037101,
          GUID = "192077E2",
          VoiceName = "voice/$Locale$/story/1003/100371/192077E2"
        },
        [10037102] = {
          Content = "孩子们点燃灯火，但火焰也融化不了坚冰的心脏",
          ContentKR = "아이들은 등불을 밝혔지만, 그 불길로도 얼어붙은 마음은 녹일 수 없었어요",
          DialogueId = 10037102,
          GUID = "1920780C",
          VoiceName = "voice/$Locale$/story/1003/100371/1920780C"
        },
        [10037103] = {
          Content = "迎着霜雪，日复一日，他们依旧来城堡与妖精嬉戏",
          ContentKR = "눈보라를 맞으며, 날이 가고 해가 바뀌어도 여전히 성에 찾아와 요정과 놀았어요",
          DialogueId = 10037103,
          GUID = "19207836",
          VoiceName = "voice/$Locale$/story/1003/100371/19207836"
        },
        [10037104] = {
          Content = "渐渐地，妖精习惯了他们的笑语欢歌",
          ContentKR = "요정은 점차 웃음소리와 노랫소리에 익숙해졌어요",
          DialogueId = 10037104,
          GUID = "19207860",
          VoiceName = "voice/$Locale$/story/1003/100371/19207860"
        },
        [10037105] = {
          Content = "“如果我也能像他们一样笑就好了。”",
          ContentKR = "“나도 그들처럼 웃어볼 수 있다면,”",
          DialogueId = 10037105,
          GUID = "1920788A",
          VoiceName = "voice/$Locale$/story/1003/100371/1920788A"
        },
        [10037106] = {
          Content = "“如果我那颗寒冰的心，也能变暖些就好了。”",
          ContentKR = "“내 얼어붙은 마음도 조금이라도 따뜻해질 수 있다면.”",
          DialogueId = 10037106,
          GUID = "192078B4",
          VoiceName = "voice/$Locale$/story/1003/100371/192078B4"
        },
        [10037201] = {
          Content = "有一天，野兽的爪牙伸向了雪国",
          ContentKR = "어느 날, 야수의 발톱이 설국을 향해 뻗쳐왔어요",
          DialogueId = 10037201,
          GUID = "1920884A",
          NextDialogue = 10037202,
          VoiceName = "voice/$Locale$/story/1003/100372/1920884A"
        },
        [10037202] = {
          Content = "大地和天空被染成朱红",
          ContentKR = "대지와 하늘이 주홍빛으로 물들었어요",
          DialogueId = 10037202,
          GUID = "19208874",
          NextDialogue = 10037203,
          VoiceName = "voice/$Locale$/story/1003/100372/19208874"
        },
        [10037203] = {
          Content = "妖精离开了它的城堡，为了男孩的遗愿",
          ContentKR = "요정은 소년의 마지막 소원을 위해 자신의 성을 떠났어요",
          DialogueId = 10037203,
          GUID = "1920889E",
          NextDialogue = 10037204,
          VoiceName = "voice/$Locale$/story/1003/100372/1920889E"
        },
        [10037204] = {
          Content = "“我答应你，我会到山下，找到你的亲人，保护她平安。”",
          ContentKR = "\"약속할게. 산을 내려가 네 가족을 찾고 그녀를 무사히 지켜줄게.\"",
          DialogueId = 10037204,
          GUID = "192088C8",
          VoiceName = "voice/$Locale$/story/1003/100372/192088C8"
        },
        [10037205] = {
          Content = "镇上群兽环伺，女孩被巨兽围困在废墟中央",
          ContentKR = "마을에는 야수들이 들끓고, 소녀는 폐허 한가운데서 거대한 야수들에게 포위당했어요",
          DialogueId = 10037205,
          GUID = "192088F2",
          VoiceName = "voice/$Locale$/story/1003/100372/192088F2"
        },
        [10037206] = {
          Content = "“该如何让战火远离他的故乡，让她不再躲躲藏藏？”",
          ContentKR = "\"어떻게 해야 전쟁의 불꽃을 멀리하고, 그녀가 더는 숨지 않게 할 수 있을까?\"",
          DialogueId = 10037206,
          Duration = 10,
          GUID = "1920891C",
          NextDialogue = 10037207,
          VoiceName = "voice/$Locale$/story/1003/100372/1920891C"
        },
        [10037207] = {
          Content = "“该如何驱赶那些巨兽，即使代价是我冰冻的心脏？”",
          ContentKR = "“어떻게 해야 야수들을 몰아낼 수 있을까, 내 얼어붙은 마음을 대가로 바친다 해도.\"",
          DialogueId = 10037207,
          Duration = 10,
          GUID = "19208946",
          VoiceName = "voice/$Locale$/story/1003/100372/19208946"
        },
        [10037208] = {
          Content = "渺小的妖精飞向巨兽，但巨兽稍稍用力，就折断了它的四肢",
          ContentKR = "작은 요정은 야수에게 날아갔지만, 야수는 가볍게 요정의 사지를 꺾어버렸어요",
          DialogueId = 10037208,
          GUID = "19208970",
          NextDialogue = 10037209,
          VoiceName = "voice/$Locale$/story/1003/100372/19208970"
        },
        [10037209] = {
          Content = "它听到心脏的声音，第一次鼓动着，呐喊着它的命运——",
          ContentKR = "요정은 처음으로 자신의 마음이 뛰는 소리를 들었어요, 그건 자신의 운명을 외치는 소리였어요",
          DialogueId = 10037209,
          GUID = "1920899A",
          VoiceName = "voice/$Locale$/story/1003/100372/1920899A"
        },
        [10037210] = {
          Content = "“妖精是无法战胜野兽的，与野兽搏斗者要先让自己化身野兽。”",
          ContentKR = "“요정은 야수를 이길 수 없어, 야수와 싸우려면 먼저 야수가 돼야 해.”",
          DialogueId = 10037210,
          GUID = "192089C4",
          VoiceName = "voice/$Locale$/story/1003/100372/192089C4"
        },
        [10037211] = {
          Content = "“那便舍弃我的身躯吧，让我的四肢变成撕碎敌人的利爪……”",
          ContentKR = "“그렇다면 이 몸을 버리자, 내 사지를 적을 찢는 발톱으로 바꾸겠어...”",
          DialogueId = 10037211,
          Duration = 10,
          GUID = "192089EE",
          NextDialogue = 10037212,
          VoiceName = "voice/$Locale$/story/1003/100372/192089EE"
        },
        [10037212] = {
          Content = "“舍弃我的容貌吧，让我的脸庞变成面目狰狞的魔鬼……”",
          ContentKR = "“이 용모도 버리자, 내 얼굴을 사나운 악마로 바꾸겠어...”",
          DialogueId = 10037212,
          Duration = 10,
          GUID = "19208A18",
          NextDialogue = 10037213,
          VoiceName = "voice/$Locale$/story/1003/100372/19208A18"
        },
        [10037213] = {
          Content = "“舍弃我的歌喉吧，让我的吟唱变成震耳欲聋的嘶吼……”",
          ContentKR = "“이 목청도 버리자, 내 노랫소리를 고막을 울리는 함성으로 바꾸겠어...”",
          DialogueId = 10037213,
          Duration = 10,
          GUID = "19208A42",
          NextDialogue = 10037214,
          VoiceName = "voice/$Locale$/story/1003/100372/19208A42"
        },
        [10037214] = {
          Content = "“舍弃我的心脏吧，让那块坚冰变成贯穿巨兽的锋刃……”",
          ContentKR = "“이 마음도 버리자, 그 얼음을 야수를 꿰뚫는 칼날로 바꾸겠어...”",
          DialogueId = 10037214,
          Duration = 10,
          GUID = "19208A6C",
          VoiceName = "voice/$Locale$/story/1003/100372/19208A6C"
        },
        [10037215] = {
          Content = "“这样，我便可以实现我的约定了。”",
          ContentKR = "“그러면, 내 약속을 지킬 수 있으니까.”",
          DialogueId = 10037215,
          Duration = 24,
          GUID = "19208A96",
          VoiceName = "voice/$Locale$/story/1003/100372/19208A96"
        },
        [10037301] = {
          Content = "我……完成这场表演了吗？",
          ContentKR = "난... 이 공연을 완성한 건가?",
          DialogueId = 10037301,
          GUID = "192098B2",
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100373/192098B2"
        },
        [10037302] = {
          Content = "是的，帕西法尔。",
          ContentKR = "그래 파르지팔",
          DialogueId = 10037302,
          GUID = "192098DC",
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100373/192098DC"
        },
        [10037303] = {
          Content = "嗯，演出结束了。",
          ContentKR = "응, 공연은 끝났어.",
          DialogueId = 10037303,
          GUID = "19209906",
          SpeakNpcName = "ChatCharacter20",
          VoiceName = "voice/$Locale$/story/1003/100373/19209906"
        },
        [10037304] = {
          Content = "你完成得很好。",
          ContentKR = "넌 아주 잘했어.",
          DialogueId = 10037304,
          GUID = "19209930",
          SpeakNpcName = "UI_Npc_Name_Aote",
          VoiceName = "voice/$Locale$/story/1003/100373/19209930"
        },
        [10037305] = {
          Content = "你是最优秀的演员。",
          ContentKR = "넌 최고의 배우야.",
          DialogueId = 10037305,
          GUID = "1920995A",
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          VoiceName = "voice/$Locale$/story/1003/100373/1920995A"
        },
        [10037306] = {
          Content = "全体准备，射击——",
          ContentKR = "전원 준비, 사격!",
          DialogueId = 10037306,
          GUID = "19209984",
          SpeakNpcName = "UI_Npc_Name_Linen",
          VoiceName = "voice/$Locale$/story/1003/100373/19209984"
        },
        [10037307] = {
          Content = "我是——最优秀的演员。",
          ContentKR = "난, 최고의 배우야.",
          DialogueId = 10037307,
          GUID = "192099AE",
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100373/192099AE"
        },
        [10037401] = {
          Content = "任务完成。",
          ContentKR = "퀘스트 완료",
          DialogueId = 10037401,
          GUID = "1920A91A",
          NextDialogue = 10037402,
          SpeakNpcId = 200022,
          VoiceName = "voice/$Locale$/story/1003/100374/1920A91A"
        },
        [10037402] = {
          Content = "二号目标生命体征尚存，确认回收。",
          ContentKR = "2번 타깃 생명징후 확인. 회수 완료.",
          DialogueId = 10037402,
          GUID = "1920A944",
          SpeakNpcId = 200022,
          VoiceName = "voice/$Locale$/story/1003/100374/1920A944"
        },
        [10037501] = {
          Camera = "-63.583008,10.710693,109.947021,-0.00003,9.381203,61.161171,35.000008,1.5,false,DoNotOverride,1.2,16:9 Digital Film",
          Content = "哨塔上的灯……熄灭了。",
          ContentKR = "초소 위의 등불이... 꺼졌어.",
