          VoiceName = "voice/$Locale$/story/1003/100375/1920BCF5"
        },
        [10037601] = {
          Camera = "-333.064697,-321.197266,145.730469,-0.000031,-2.797106,54.238285,32.000004,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "欢迎回来，你要先喝点什么还是先吃点什么呢？慰问品我都放在你左手边的柜子里喽，种类繁多任君挑选，总有一款适合你。",
          ContentKR = "어서 와. 먼저 뭐 좀 마실래, 아니면 뭐 좀 먹을래? 위문품은 전부 네 왼쪽에 있는 캐비닛에 넣어뒀어. 종류도 다양하니까 마음껏 골라봐. 분명 취향에 맞는 게 있을 거야.",
          DialogueId = 10037601,
          FacialId = {
            [1] = "100006:None"
          },
          FinalCamera = "-333.064697,-321.197266,145.730469,-0.000031,-2.997032,49.238327,32.000004,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
