        [10037602] = {
          Camera = "-121.563477,-202.702637,164.126953,0.000196,-8.599856,76.996925,35.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "给你一枪最适合我。",
