        [10037603] = {
          Camera = "-167.920898,164.282227,90.818359,0.000226,7.996334,-76.168259,45.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "好难过啊……明明给你提了那么好一个钓大鱼的主意却只能收到一通臭骂。",
          ContentKR = "정말 속상하네... 분명 너에게 그렇게 큰 고기를 낚을 아이디어를 선물해 줬는데, 돌아오는 건 욕 한 바가지라니.",
          DialogueId = 10037603,
          FinalCamera = "-175.953613,162.272461,90.818359,0.000227,7.996334,-73.96772,45.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1920CA3E",
          NextDialogue = 10037604,
          SpeakNpcId = 100006,
          TalkActionId = {
            [1] = "200022:Talk03_Start",
            [2] = "100006:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
