        },
        [10037604] = {
          Camera = "-146.45752,-22.482178,140.748047,0.000275,3.595323,-62.979397,45.000023,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "唉，亏我还满心期待地幻想着，善良的琳恩小姐回来以后会感谢我的出谋划策呢。",
          ContentKR = "휴, 내가 얼마나 기대에 부풀어서 상상했는데, 착한 린이 돌아와서 내 계책에 고마워할 거라고 말이야.",
          DialogueId = 10037604,
          FinalCamera = "-151.791016,-25.168945,140.748047,0.000274,3.595323,-60.579292,45.000023,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1920CA68",
          NextDialogue = 10037605,
          SpeakNpcId = 100006,
          TalkActionId = {
            [1] = "100006:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CA68"
        },
        [10037605] = {
          Camera = "-128.90625,-70.791016,131.251953,0.0002,1.796155,80.625771,45.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "……“敬爱的兰迪长官，万分感谢感激感动感恩您聪慧的谋略！”……行了吧。",
          ContentKR = "...“존경하는 랜디님, 정말 감사하고, 감격스럽고, 감동하며, 감탄스럽습니다! 당신의 지혜로운 계략에 말이죠!”... 됐지?",
          DialogueId = 10037605,
          FacialId = {
            [1] = "200022:None"
          },
          FinalCamera = "-133.658203,-99.58252,130.353516,0.0002,1.796155,80.625771,45.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1920CA92",
          NextDialogue = 10037606,
          Scripts = "PlayAnimation{_delay{4},ActorId{200022},AnimationId{\"Confident_Start\"},Duration{2}}",
          SpeakNpcId = 200022,
          TalkActionId = {
