        },
        [10038001] = {
          Content = "长官们……当心……",
          ContentKR = "장교님들... 조심하세요...",
          DialogueId = 10038001,
          GUID = "191DEA43",
          NextDialogue = 10038002,
          SpeakNpcId = 100322,
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA43"
        },
        [10038002] = {
          Content = "小宝贝们又来了，真是一会儿也不得闲。",
          ContentKR = "자식들이 또 왔구나, 정말 잠시도 쉴 틈이 없네.",
          DialogueId = 10038002,
          GUID = "191DEA44",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA44"
        },
        [10038004] = {
          Content = "好，下一个。",
          ContentKR = "이것도요!",
          DialogueId = 10038004,
          GUID = "191DEA46",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA46"
        },
        [10038006] = {
          Content = "好……好难转……我累啦，小仆从，接下来你加油……",
          ContentKR = "우와... 너무 어려워... 스노우는 너무 힘들어. 시종, 이제 네가 좀 해줘...",
          DialogueId = 10038006,
          GUID = "191DEA48",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA48"
        },
        [10038007] = {
          Content = "看样子是最后一个了。",
          ContentKR = "마지막인 것 같습니다.",
          DialogueId = 10038007,
          GUID = "191DEA49",
          NextDialogue = 10038008,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA49"
        },
        [10038008] = {
          Content = "好耶……终于要搞定啦！",
          ContentKR = "야호... 드디어 다 끝낼 수 있겠어!",
          DialogueId = 10038008,
          GUID = "191DEA4A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA4A"
        },
        [10038009] = {
          Content = "控制台恢复运转了，用它停下防御机关吧。",
          ContentKR = "컨트롤러 스테이션이 다시 작동합니다. 이걸로 방위 장치를 멈추죠.",
          DialogueId = 10038009,
          GUID = "191DEA4B",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA4B"
        },
        [10038012] = {
          Content = "迈尔斯，再给我拿两个弹匣过来！喂，听得见吗！啧……通讯器又出问题了？",
          ContentKR = "마일스, 탄창 두 개나 더 가져와! 야, 안 들려? 쯧... 통신기 또 고장인가?",
          DialogueId = 10038012,
          GUID = "191EF0C3",
          NextDialogue = 10038013,
          SpeakNpcId = 100340,
          VoiceName = "voice/$Locale$/story/1003/100380/191EF0C3"
        },
        [10038013] = {
          Content = "嗯？是你们啊。",
          ContentKR = "음? 너희구나.",
          DialogueId = 10038013,
          GUID = "191EF0C4",
          NextDialogue = 10038014,
          SpeakNpcId = 100340,
          TurnTo = {
            [1] = "100341:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1003/100380/191EF0C4"
        },
        [10038014] = {
          Content = "你们的行动地点不是在前面吗？快去吧，这次行动决不允许有任何闪失。",
          ContentKR = "너희 작전 지역은 앞쪽이잖아? 어서 가라. 이번 작전에는 조금의 실수도 용납되지 않는다니까.",
          DialogueId = 10038014,
          GUID = "191EF0C5",
          NextDialogue = 10038015,
          SpeakNpcId = 100340,
          VoiceName = "voice/$Locale$/story/1003/100380/191EF0C5"
        },
        [10038015] = {
          Content = "收到。",
          ContentKR = "알겠습니다.",
          DialogueId = 10038015,
          GUID = "191EF0C6",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100380/191EF0C6"
        },
        [10038101] = {
          Content = "冰湖城宵禁期间，此处禁止通行",
          ContentKR = "아이스레이크 시티는 현재 통행금지 시간입니다. 이곳을 지날 수 없습니다.",
          DialogueId = 10038101,
          GUID = "19210B0D"
        },
        [10038102] = {
          Content = "下水道防御机关也启动了，能帮点忙。",
          ContentKR = "하수도의 방위 장치가 작동한 것 같습니다. 도움이 될 거예요.",
          DialogueId = 10038102,
          GUID = "191DE875",
          NextDialogue = 10038103,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100381/191DE875"
        },
        [10038103] = {
          Content = "为什么下水道这种地方会有防御机关啊！",
          ContentKR = "근데... 하수도에 왜 방위 장치가 있어요!",
          DialogueId = 10038103,
          GUID = "191DE876",
          NextDialogue = 10038104,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100381/191DE876"
        },
        [10038104] = {
          Content = "下水道很多设备都是工程炼金院添置的，他们只说别多问。",
          ContentKR = "여기에 있는 장치 대부분은 공학 연금원이 설치한 것이에요. 캐묻지 말라고 하길래, 저도 자세히는 잘 모릅니다.",
          DialogueId = 10038104,
          GUID = "191DE877",
          NextDialogue = 10038105,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100381/191DE877"
        },
        [10038105] = {
          Content = "下水道里放军事设施……他们到底有什么打算啊……",
          ContentKR = "하수도에서 군사 장치를... 도대체 무슨 속셈이 있는 거야...",
          DialogueId = 10038105,
          GUID = "191DE878",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100381/191DE878"
        },
        [10038201] = {
          DialogueId = 10038201,
          DialoguePanelType = "None",
          Duration = 1,
          GUID = "19210B0E",
          NextOptions = {
            [1] = 10038202
          }
        },
        [10038202] = {
          Content = "进入军团医院",
          ContentKR = "군단 병원에 들어가기",
          DialogueId = 10038202,
          GUID = "19210B0F"
        },
        [10038301] = {
          Camera = "-352.324951,420.12915,199.878906,0.000157,-10.802886,-58.593517,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "哎呀，这不是听说你伤得不轻，特地来慰问一下嘛。",
          ContentKR = "아이고, 네가 많이 다쳤다고 해서 특별히 위로하러 왔잖아.",
          DialogueId = 10038301,
          FinalCamera = "-377.254883,404.907959,199.878906,0.000155,-10.602905,-55.19278,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1920CA15",
          NextDialogue = 10038302,
          SpeakNpcId = 100006,
          TalkActionId = {
            [1] = "100006:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100383/1920CA15"
        },
        [10038302] = {
          Camera = "-158.971191,-46.777344,212.847656,0.000162,-24.602238,66.810852,55.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "免了，没死就是没事。我又不是你这种娇生惯养的少爷。",
          ContentKR = "됐어. 안 죽었으면 문제없는 거지. 난 너 같은 약골 도련님이 아니니까.",
          DialogueId = 10038302,
          FacialId = {
            [1] = "200022:Confident01"
          },
          FinalCamera = "-152.550293,-49.527588,212.847656,0.000171,-24.402216,70.010948,55.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1920CA16",
          NextDialogue = 10037603,
          SpeakNpcId = 200022,
          TalkActionId = {
            [1] = "200022:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100383/1920CA16"
        },
        [10038401] = {
          Content = "那之后，卡戎之民更是在整个海伯利亚燃起战火，四处杀戮，直到帝国的缔造者——仁慈的迪斯·盖雷亚陛下结束了战争，带来了和平。",
          ContentKR = "그러고 나서, 카론들은 휘페르보레아 제국 전역에 전쟁의 불씨를 지피고, 곳곳에서 살육을 저질렀어. 제국의 창건자이자 자비로우신 디스 갈레아 폐하께서 전쟁을 종식시키고, 평화를 가져오시기 전까지는 말이야.",
          DialogueId = 10038401,
          GUID = "191E6E2B",
          NextDialogue = 10033922,
          SpeakNpcId = 100357,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6E2B"
        },
        [10040101] = {
          Content = "“在远方，或许有一家属于你自己的书店或是酒馆。”",
          ContentKR = "\"머나먼 곳 어딘가엔 오직 당신만을 위한 서점이나 술집이 있을지도 모릅니다.\"",
          DialogueId = 10040101,
          GUID = "19226412",
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405003,
            [3] = 201005,
            [4] = 201004,
            [5] = 201009
          },
          SnapShot = "TELEPHONE",
          SpeakNpcName = "UI_SpeakName_Guangbo",
          VoiceName = "voice/$Locale$/story/1004/100401/19226412"
        },
        [10040102] = {
          Content = "“远方，一个聚合了梦想、等待与不确定的词汇。“",
          ContentKR = "\"머나먼 곳이란, 수많은 꿈과 기다림, 그리고 알 수 없는 내일로 이루어진 단어입니다.\"",
          DialogueId = 10040102,
          GUID = "1922643C",
          SnapShot = "TELEPHONE",
          SpeakNpcName = "UI_SpeakName_Guangbo",
          VoiceName = "voice/$Locale$/story/1004/100401/1922643C"
        },
        [10040103] = {
          Content = "“在远方，或许有你想念的人也在日夜等待着你的突然出现。”",
          ContentKR = "\"머나먼 곳에 당신의 깜짝방문을 밤낮으로 기다리는 누군가가 있을지도 모릅니다.\"",
          DialogueId = 10040103,
          GUID = "19226466",
          SnapShot = "TELEPHONE",
          SpeakNpcName = "UI_SpeakName_Guangbo",
          VoiceName = "voice/$Locale$/story/1004/100401/19226466"
        },
        [10040104] = {
          Content = "“在远方，有着无数的未知，但一定和现在大不一样。”",
          ContentKR = "\"머나먼 그곳에서 어떤 내일이 펼쳐질지는 알 수 없지만, 분명히 오늘과는 전혀 다를 겁니다.\"",
          DialogueId = 10040104,
          GUID = "19226490",
          SnapShot = "TELEPHONE",
          SpeakNpcName = "UI_SpeakName_Guangbo",
          VoiceName = "voice/$Locale$/story/1004/100401/19226490"
        },
        [10040105] = {
          Content = "“但远方并不遥远，你与远方之间，真的只隔着一张薄薄的车票！”",
          ContentKR = "\"하지만 머나먼 그곳은 멀리 있지 않습니다. 얇은 티켓 한 장이면 닿을 수 있는 거리입니다!\"",
          DialogueId = 10040105,
          GUID = "192264BA",
          SnapShot = "TELEPHONE",
          SpeakNpcName = "UI_SpeakName_Guangbo",
          VoiceName = "voice/$Locale$/story/1004/100401/192264BA"
        },
        [10040106] = {
          Content = "“欢迎乘坐帝国铁道的最新专列——极光号！她那由装甲列车改装的车体坚固而又安全。她携带的列车炮足以应对一切危险。”",
          ContentKR = "\"제국 철도의 최신 특별 열차 '오로라호'에 오신 여러분을 환영합니다! 장갑열차 기반의 안전한 차체와 강력한 열차포는 모든 위협에 완벽히 대응합니다.\"",
          DialogueId = 10040106,
          GUID = "192264E4",
          SnapShot = "TELEPHONE",
          SpeakNpcName = "UI_SpeakName_Guangbo",
          VoiceName = "voice/$Locale$/story/1004/100401/192264E4"
        },
        [10040107] = {
          Content = "“干净，明亮，富丽堂皇！在声声鸣笛中，让一切对于远方的幻想成为现实！",
          ContentKR = "\"티끌 하나 없이 깨끗하고 눈부시게 화려한 공간! 힘찬 기적 소리와 함께, 머나먼 곳을 향한 환상을 현실로 만드세요!\"",
          DialogueId = 10040107,
          GUID = "1922650E",
          SnapShot = "TELEPHONE",
          SpeakNpcName = "UI_SpeakName_Guangbo",
          VoiceName = "voice/$Locale$/story/1004/100401/1922650E"
        },
        [10040108] = {
          Content = "干净，明亮，富丽堂皇，是最好的旅行手段！",
          ContentKR = "깨끗하고, 눈부시고, 화려하다는데? 그럼 최고의 여행 수단이네!",
          DialogueId = 10040108,
          GUID = "19226538",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100401/19226538"
        },
        [10040109] = {
          Content = "所以这个叫做火车的东西，真像广播里说的一样好吗？",
          ContentKR = "그러니까 열차라는 게, 진짜 저기서 말한 것처럼 그렇게 엄청난 거야?",
          DialogueId = 10040109,
          GUID = "19226562",
          RelatedWikiId = {
            [1] = 403010
          },
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100401/19226562"
        },
        [10040110] = {
          Content = "如果你能够买得起头等车厢车票的话，应该会是真的吧。只不过，头等车厢的票价昂贵，怕是整个外城也没几个人能坐得起。",
          ContentKR = "일등석 승차권을 살 수만 있다면, 틀린 말은 아닐걸. 워낙 비싸서, 외성을 다 뒤져도, 그럴 만한 사람은 몇 명 없겠지만.",
          DialogueId = 10040110,
          GUID = "1922658C",
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1004/100401/1922658C"
        },
        [10040111] = {
          Content = "至于普通的车厢，大概会和水仙平原里一样吵吵闹闹。",
          ContentKR = "일반석 쪽 객차는, 아스포델 못지않게 시끌시끌하겠지.",
          DialogueId = 10040111,
          GUID = "192265B6",
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1004/100401/192265B6"
        },
        [10040112] = {
          Content = "那不是正好，白本来就不认识什么贵族老爷，去那边一定浑身不自在，但如果说那里像是水仙平原，那我可就太熟悉啦。",
          ContentKR = "오히려 좋아. 스노우는 딱히 아는 귀족 나리도 없어서 거기 끼면 눈치 봐야 되는데, 아스포델 같은 분위기면 훨씬 익숙하니까.",
          DialogueId = 10040112,
          GUID = "192265E0",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100401/192265E0"
        },
        [10040113] = {
          Content = "但，你们这次前往车站，应该并不是去游山玩水吧。",
          ContentKR = "근데, 너희 이번에 기차역에 놀러 가는 건 아니잖아?",
          DialogueId = 10040113,
          GUID = "1922660A",
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1004/100401/1922660A"
        },
        [10040114] = {
          Content = "我当然知道，所以才正在听广播和看书，收集资料嘛，一定要帮助小仆从把对{性别：他|她}很重要的人带回来！",
          ContentKR = "물론이지. 그래서 이렇게 방송도 듣고, 책도 보면서 정보 모으고 있는걸. 시종이 소중한 사람을 다시 찾을 수 있게 도와줘야 하니까!",
          DialogueId = 10040114,
          GUID = "19226634",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100401/19226634"
        },
        [10040115] = {
          Content = "好心的黎瑟已经告诉我们足够多消息了——",
          ContentKR = "마음씨 착한 리듬 언니가 우리한테 정보도 잔뜩 알려 줬고...",
          DialogueId = 10040115,
          GUID = "1922665E",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100401/1922665E"
        },
        [10040116] = {
          Content = "一个月后，第十三军团会押解一名重要的囚犯，乘列车从冰湖城出发，前往皇都迪斯玛尼亚。第六军团也接到了协助命令。",
          ContentKR = "한 달 후, 제13군단에서 중요한 죄수 한 명을 호송할 예정입니다. 열차를 타고 아이스레이크 시티에서 출발해 황성 디즈마니아로 향한다고 하더군요. 제6군단도 협조 명령을 받은 상태입니다.",
          DialogueId = 10040116,
          GUID = "19226688",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BCA0"
        },
        [10040117] = {
          Content = "那名囚犯的身份是一级机密，我只知道她正在内城接受治疗，身边有最严密的防护。不过有人看到了她的背影，是一位身着黑衣、<H>二十岁出头的年轻姑娘</>。",
          ContentKR = "그 죄수의 신분은 1급 기밀로 분류되어 있습니다. 제가 아는 건 그녀가 내성에서 치료를 받고 있다는 것과, 그녀 주위에 철저한 경호가 이루어지고 있다는 것뿐이에요. 하지만 누군가 그녀의 뒷모습을 봤다고 하더군요. 검은 옷을 입은, <H>20대 초반의 젊은 아가씨</>였다고 해요.",
          DialogueId = 10040117,
          GUID = "192266B2",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BCCA"
        },
        [10040118] = {
          Content = "这和贝蕾妮卡的信息对得上。如果真的是她，那<H>一个月后的列车</>，也许是你唯一的机会。",
          ContentKR = "이건 베레니카의 정보와 일치합니다. 정말 베레니카가 맞으면 <H>한 달 뒤의 열차</>가 당신의 유일한 기회일 수도 있어요.",
          DialogueId = 10040118,
          GUID = "192266DC",
          RelatedWikiId = {
            [1] = 201001
          },
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BCF4"
        },
        [10040119] = {
          Content = "哎，不过算日子不是应该是五天后吗？小仆从怎么这么早就要出发？",
          ContentKR = "어? 근데 날짜를 계산해 보면 5일이나 남았는데? 시종은 왜 벌써부터 가려는 거야?",
          DialogueId = 10040119,
          GUID = "19226706",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100401/19226706"
        },
        [10040120] = {
          Content = "干大事当然要提前踩点啊。踩点，懂吗。",
          ContentKR = "미리 현장에 가서 사전 답사를 해 둬야 하잖아. 사전 답사, 알지?",
          DialogueId = 10040120,
          GUID = "19226730",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100401/19226730"
        },
        [10040121] = {
          Content = "喂，我明明是受害者家属，怎么被你说得像是做贼。白，你可不要学坏了，别什么踩点踩点的，我们这叫“事先调查”。",
          ContentKR = "아니, 내가 무슨 도둑이야? 난 엄연히 피해자 가족 신분이라고. 스노우, 저런 거 배우면 못 써. 사전 답사라니, 우리가 하려는 건 '사전 조사'야.",
          DialogueId = 10040121,
          GUID = "1922675A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100401/1922675A"
        },
        [10040122] = {
          Content = "……之前阴差阳错去了趟华胥，好在回来得及时，时间还算充裕……但愿一切顺利吧。",
          ContentKR = "...어쩌다 보니까 화서까지 다녀왔지만, 그래도 제때 돌아와서 시간은 넉넉하네... 일이 잘 풀려야 할 텐데.",
          DialogueId = 10040122,
          GUID = "19226784",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100401/19226784"
        },
        [10040123] = {
          Content = "当然会顺利啦！我记得，{nickname}说过那位贝蕾做饭不太好吃，所以庆功宴上，卡米拉你得多做几道拿手菜，让她也能尝一尝好吃的。",
          ContentKR = "다 잘될 거야! 전에 {nickname} 네가 나한테, 베레는 요리를 엄청 못 한다고 그랬지? 그러니까 성공 축하 파티 때는, 카밀라가 자신 있는 요리들을 잔뜩 준비해 줘! 맛있는 거 먹게 해 줘야지!",
          DialogueId = 10040123,
          GUID = "192267AE",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100401/192267AE"
        },
        [10040124] = {
          Content = "这么乐观当然是好事。不过，你们的计划商量得如何？反正白负责的这部分很顺利，她已经快把庆功宴的菜单拟定好了。",
          ContentKR = "긍정적으로 생각하니까 좋네. 그런데, 다들 계획은 세웠어? 벌써부터 축하 파티 메뉴까지 정하고 있는 걸 보면, 스노우 쪽은 문제없어 보이긴 하지만.",
          DialogueId = 10040124,
          GUID = "192267D8",
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1004/100401/192267D8"
        },
        [10040125] = {
          Content = "不、不是只有菜单哦！我还是做了很多其他准备的，听听广播看看资料之类的。至于打架，有他们两个就行。",
          ContentKR = "메, 메뉴 생각만 한 거 아니거든! 나도 다른 준비 엄청 많이 했어! 방송도 챙겨 듣고, 자료도 찾아봤다고. 싸우는 건, 쟤네 둘한테 맡기면 되는걸.",
          DialogueId = 10040125,
          GUID = "19226802",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100401/19226802"
        },
        [10040126] = {
          Content = "{nickname}刚刚说的你是完全没听进去啊。再说一遍，这次行动可不是打架，而是探查。唉，我强调了八百遍的行动准则，你也早就忘得一干二净了吧。",
          ContentKR = "방금 {nickname} 얘긴 귓등으로도 안 들었네. 다시 말하지만, 이번 작전은 싸우러 가는 게 아니라, 정찰이라고. 하아, 내가 귀에 딱지가 앉게 말한 행동 수칙, 너 다 까먹었지?",
          DialogueId = 10040126,
          GUID = "1922682C",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100401/1922682C"
        },
        [10040127] = {
          Content = "我才没忘！打架只是我随便说说，谁让小仆从不管干什么最后总会变成打架……总之，咳！",
          ContentKR = "까먹긴 누가! 싸운다는 건 그냥 해 본 소리거든! 시종은 원래 뭘 하기만 하면, 마지막에 꼭 싸움으로 흘러가니까... 어쨌든, 크흠!",
          DialogueId = 10040127,
          GUID = "19226856",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100401/19226856"
        },
        [10040128] = {
          Content = "第一条准则呢，是尽可能低调，让自己像是一个扔进人堆里都找不出来的普通人！这样才能尽可能多的收集到信息。",
          ContentKR = "수칙 제1조! 최대한 눈에 띄지 않기! 사람들 틈에 스윽 섞여서 튀지 않게 행동해야 한다. 그래야 정보를 쏙쏙 빼낼 수 있으니까!",
          DialogueId = 10040128,
          GUID = "19226880",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100401/19226880"
        },
        [10040129] = {
          Content = "第二条准则，是注意收集有效信息，不是随便问！否则最后获得最多的情报一定是火车站内店铺的优惠信息。",
          ContentKR = "수칙 제2조! 아무한테나 물어보고 다니지 말고 진짜 쓸모 있는 정보만 캐기! 안 그러면 기차역 안 가게들 할인 정보만 잔뜩 알아 오게 될 테니까.",
          DialogueId = 10040129,
          GUID = "192268AA",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100401/192268AA"
        },
        [10040130] = {
          Content = "居然还真是把我的话一字不落地背了下来。为了你的小仆从，你也算很努力了。",
          ContentKR = "내 말 토씨 하나 안 틀리고 다 외웠네. 시종 돕겠다고, 나름 애 많이 썼구나.",
          DialogueId = 10040130,
          GUID = "192268D4",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100401/192268D4"
        },
        [10040131] = {
          Content = "等下我们需要注意两点：一个是打听一下军团那位特殊囚犯的身份，确认消息真伪；另一个是调查火车站的结构。",
          ContentKR = "이따가 우리가 할 일은 두 가지야. 먼저 군단이 호송한다는 그 죄수의 정체를 캐내서 소문이 진짜인지 확인할 거고, 그러면서 기차역 내부 구조도 파악해 둘 거야.",
          DialogueId = 10040131,
          GUID = "192268FE",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100401/192268FE"
        },
        [10040132] = {
          Content = "等这些信息都掌握差不多了，我们再制定一个稳妥的营救计划，避免引起他们警觉，提前把囚犯运走。",
          ContentKR = "정보를 얼추 모아놓고 나서 확실한 구출 계획을 짜자. 놈들이 먼저 눈치채고 죄수를 딴 데로 빼돌리면 골치 아파지니까.",
          DialogueId = 10040132,
          GUID = "19226928",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100401/19226928"
        },
        [10040133] = {
          Content = "最好的情况下，是我们能在火车站内找到帮手……嗯……要不要提前介绍一下车站的结构……不过眼见为实应该会更好……",
          ContentKR = "제일 좋은 건, 기차역 안에서 우릴 도와줄 조력자를 찾는 건데... 음... 역 구조를 미리 알려 줘야 하나... 아니, 직접 보는 게 나을 거야...",
          DialogueId = 10040133,
          GUID = "19226952",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100401/19226952"
        },
        [10040134] = {
          Content = "咳咳……可不要嫌我像老婆婆一样啰嗦，这是多年以来我作为狩月人的经验之谈。",
          ContentKR = "크흠... 늙은이처럼 잔소리한다고 귀찮아하지 마. 다 내가 월석 사냥꾼으로 구르면서 얻은 피 같은 경험담이라고.",
          DialogueId = 10040134,
          GUID = "1922697C",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100401/1922697C"
        },
        [10040136] = {
          Content = "知道了，奥特赛德妈妈！",
          ContentKR = "다 알아요, 엄마!",
          DialogueId = 10040136,
          GUID = "192269D0"
        },
        [10040137] = {
          Content = "作为队友太可靠了，奥特赛德！",
          ContentKR = "네가 우리 팀원이라 정말 든든해, 아웃사이더!",
          DialogueId = 10040137,
          GUID = "192269FA"
        },
        [10040138] = {
          Content = "确实谨慎一点没什么坏处，反正确实还有一段时间。",
          ContentKR = "어차피 아직 시간도 남았으니까, 신중하게 움직여서 나쁠 건 없겠지.",
          DialogueId = 10040138,
          GUID = "19226A24"
        },
        [10040139] = {
          Content = "喂！不要给我随便添加奇怪的印象！",
          ContentKR = "어이! 사람한테 이상한 별명 좀 갖다 붙이지 마!",
          DialogueId = 10040139,
          GUID = "19226A4E",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100401/19226A4E"
        },
        [10040140] = {
          Content = "你又不是第一天认识我，突然这么夸我，怪不好意思的……",
          ContentKR = "하루이틀 본 사이도 아닌데, 갑자기 대놓고 칭찬하니까 엄청 민망하네...",
          DialogueId = 10040140,
          GUID = "19226A78",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100401/19226A78"
        },
        [10040141] = {
          Content = "是的，我们留出的时间应该是足够的。",
          ContentKR = "응, 그 정도면 시간은 충분할 거야.",
          DialogueId = 10040141,
          GUID = "19226AA2",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100401/19226AA2"
        },
        [10040142] = {
          Content = "我要说的差不多就这些了，就等你这个“夜航者”小队队长，一声令下出发了。",
          ContentKR = "내 잔소리는 이게 다야. 이제 우리 '녹토 보이저' 대장님이 출동 명령만 내리시면 돼.",
          DialogueId = 10040142,
          GUID = "19226ACC",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100401/19226ACC"
        },
        [10040143] = {
          Content = "卡米拉还有没有什么嘱咐？",
          ContentKR = "카밀라 씨는 더 해 주고 싶은 말 없어요?",
          DialogueId = 10040143,
          GUID = "19226AF6"
        },
        [10040144] = {
          Content = "因为你们接下来的行动，最近“水仙平原”里但凡有客人说话时提到车站，尤其是那些总是大半夜来喝啤酒的车站工人，我都多留了留心。",
          ContentKR = "너희가 기차역에 가는 걸 아니까, 얼마 전부터 '아스포델'에 온 손님들이 기차역 얘기를 하면, 유심히 잘 들어 뒀었어. 매일 밤늦게 맥주 마시러 오는 역 인부들 대화는 특히 더.",
          DialogueId = 10040144,
          GUID = "19226B20",
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1004/100401/19226B20"
        },
        [10040145] = {
          Content = "说好的说坏的都有，而唯一的共同点是，他们提到车站的站长——艾森巴恩·瓦格纳这个名字时，都会神色一变，说是能将车站管得井井有条的能人。",
          ContentKR = "별별 얘기가 다 오갔지만 한 가지 공통점은, 역장 아이젠반 바그너 이름만 나오면, 다들 표정이 싹 굳더라는 거야. 엄격하면서도 능력 있는 관리자란 느낌이었어.",
          DialogueId = 10040145,
          GUID = "19226B4A",
          RelatedWikiId = {
            [1] = 201030
          },
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1004/100401/19226B4A"
        },
        [10040146] = {
          Content = "所以可能的话，最好不要与他接触，万一被他盯上，不管他对你态度如何，都不是什么好事。",
          ContentKR = "그러니까 웬만하면 그 사람하곤 엮이지 마. 그쪽에서 호의적으로 나오든 아니든, 괜히 눈에 띄어서 좋을 게 없을 것 같아.",
          DialogueId = 10040146,
          GUID = "19226B74",
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1004/100401/19226B74"
        },
        [10040147] = {
          Content = "顺带一提，那边工人的薪水都不太高，因为他们总喝最廉价的啤酒。如果调查没什么进展，一点小小的心意也许能帮你和工人们套上近乎。",
          ContentKR = "참고로, 인부들이 매번 제일 싼 맥주만 시키는 걸 보면, 급여가 많지는 않은 모양이었어. 조사가 잘 안 풀리면, 뭐라도 쥐여 주면서 그쪽 인부들하고 친해져 보면 도움이 될 거야.",
          DialogueId = 10040147,
          GUID = "19226B9E",
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1004/100401/19226B9E"
        },
        [10040148] = {
          Content = "谢谢你，卡米拉女士，我们会小心的。那么，我们出发吧。",
          ContentKR = "고마워요, 카밀라 씨. 조심할게요. 자, 그럼 출발하자.",
          DialogueId = 10040148,
          GUID = "19226BC8",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100401/19226BC8"
        },
        [10040149] = {
          Content = "好耶！那么拯救很重要的人计划，正式开始！",
          ContentKR = "응! 지금부터 우리 시종의 소중한 사람 구출 작전, 시작!",
          DialogueId = 10040149,
          GUID = "19226BF2",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100401/19226BF2"
        },
        [10040201] = {
          Content = "哇，好多人……屋顶好高……那个纪念碑，是不是比冰湖城广场上的那个还要高呀。",
          ContentKR = "와, 사람 엄청 많다... 천장도 진짜 높고... 저 기념비, 아이스레이크 시티 광장에 있는 것보다 더 큰 것 같아.",
          DialogueId = 10040201,
          GUID = "1922747A",
          RelatedWikiId = {
            [1] = 408003,
            [2] = 403010,
            [3] = 201005,
            [4] = 201009
          },
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100402/1922747A"
        },
        [10040202] = {
          Content = "之前翻书都说冰湖城的车站是什么体量惊人，帝国建筑的皇冠上的大明珠之类的，可这也太大啦，简直像是什么城堡一样。",
          ContentKR = "책에서 아이스레이크 시티의 기차역은 규모도 엄청나고, 제국 건축의 빛나는 진주 같은 거라고 하긴 했지만, 그래도 이건 너무 큰데? 완전 성 같아.",
          DialogueId = 10040202,
          GUID = "192274A4",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100402/192274A4"
        },
        [10040203] = {
          Content = "忍不住了，必须要说上一句，小仆从哟，我要封你做钢之穹顶的铁壁上卿，奥特赛德则是那忠诚的机枢战士……",
          ContentKR = "안 되겠다. 이 말은 꼭 해야겠어. 시종, 널 강철 돔의 철벽상경으로 임명할게. 아웃사이더 넌 충직한 기추 전사...",
          DialogueId = 10040203,
          GUID = "192274CE",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100402/192274CE"
        },
        [10040204] = {
          Content = "（去了趟华胥，白嘴里的的奇怪爵位又增加了……）",
          ContentKR = "(화서 한 번 갔다 오니까, 스노우가 갖다 붙이는 이상한 작위가 더 늘었네...)",
          DialogueId = 10040204,
          DisableMouth = 1,
          GUID = "192274F8",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100402/192274F8"
        },
        [10040205] = {
          Content = "叽里咕噜说什么呢。这才只是站前穹顶而已，我们的目标可是站厅里，得过了检票口才行。",
          ContentKR = "뭘 중얼거리고 있는 거야. 여긴 역전 아트리움이라고. 우리 목적지는 역 대합실이니까, 검표소부터 통과해야 해.",
          DialogueId = 10040205,
          GUID = "19227522",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100402/19227522"
        },
        [10040206] = {
          Content = "我还是给你专门介绍一下吧，坐火车呢，是需要火车票的，是一张四四方方的纸张，上面写着出发地和目的地。",
          ContentKR = "잘 모를까 봐 설명해 주는데, 기차를 탈 땐 '표'라는 게 필요해. 네모난 종이인데, 출발지랑 목적지가 딱 적혀 있거든?",
          DialogueId = 10040206,
          GUID = "1922754C",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100402/1922754C"
        },
        [10040207] = {
          Content = "拿到火车票，经过检票口，负责治安的卫兵咔嚓一下，在票上打个孔，才能进到站厅里等待火车……",
          ContentKR = "그 기차표를 들고 검표소로 가면, 치안 담당 경비병이 찰칵하고 표에 구멍을 뚫어 줘. 그래야 대합실에 들어가서 기차를 기다릴 수...",
          DialogueId = 10040207,
          GUID = "19227576",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100402/19227576"
        },
        [10040208] = {
          Content = "奥——特——赛——德——！少瞧不起人了。",
          ContentKR = "아! 웃! 사! 이! 더! 너 사람 너무 무시하는 거 아냐?!",
          DialogueId = 10040208,
          GUID = "192275A0",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100402/192275A0"
        },
        [10040209] = {
          Content = "虽然我自己是第一次来，但我在冰湖城待了这么久，出发前也好好查了资料，可不会对这里一无所知，你听好了——",
          ContentKR = "내가 기차역에 처음 와 보는 건 맞는데, 아이스레이크 시티에서 지낸 지도 오래됐고, 여기 오기 전에 공부도 했단 말이야. 나름 아는 게 꽤 된다구. 그러니까 잘 들어...",
          DialogueId = 10040209,
          GUID = "192275CA",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100402/192275CA"
        },
        [10040210] = {
          Content = "冰湖城车站，正式名称是芙罗蒂娅百花车站。",
          ContentKR = "아이스레이크 시티 기차역의 정식 명칭은, 플로렌티아 블룸필드역이야.",
          DialogueId = 10040210,
          GUID = "192275F4",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100402/192275F4"
        },
        [10040211] = {
          Content = "之所以叫这个名字，是因为车站开通的那一天，请求当时还在位的上一任皇帝赐予名字的时候，正好传来了芙罗蒂娅公主诞生的消息。",
          ContentKR = "왜 이런 이름이 붙었냐면, 역이 처음 개통된 날, 선대 황제께 이름을 내려 달라고 부탁했는데, 마침 그때 플로렌티아 공주가 태어났단 소식이 도착했거든.",
          DialogueId = 10040211,
          GUID = "1922761E",
          RelatedWikiId = {
            [1] = 408022
          },
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100402/1922761E"
        },
        [10040212] = {
          Content = "作为帝国铁路网北方的重要枢纽，拥有三个始发站台和六个通过站台。从建立至今从未发生过任何恶性人身安全事故，因此也被称为冰湖花冠。",
          ContentKR = "제국 북부 철도망의 중심지답게, 출발 승강장은 3개고, 경유 승강장은 6개야. 지금까지 큰 인명 사고가 한 번도 안 일어나서, '아이스레이크의 화관'이란 별명으로도 불리지.",
          DialogueId = 10040212,
          GUID = "19227648",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100402/19227648"
        },
        [10040213] = {
          Content = "……居然记这么清楚。",
          ContentKR = "...어떻게 그걸 다 외웠네.",
          DialogueId = 10040213,
          GUID = "19227672",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100402/19227672"
        },
        [10040214] = {
          Content = "那当然了，我可是事先做好了功课的！我有认识的前辈，可比你更了解火车，知道的比你多——多啦！",
          ContentKR = "당연하지! 나 진짜 열심히 공부했단 말이야! 아는 선배 중에 너하곤 비교도 안 될 만큼 아는 게 많은 기차 박사가 있거든!",
          DialogueId = 10040214,
          GUID = "1922769C",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100402/1922769C"
        },
        [10040215] = {
          Content = "哦？我说怎么有吵吵闹闹的声音，原来是白呀。",
          ContentKR = "어? 뭔가 시끌시끌하다 했는데, 스노우였구나?",
          DialogueId = 10040215,
          GUID = "192276C6",
          SpeakNpcId = 100405,
          SpeakNpcName = "UI_SpeakName_DuduZandai",
          VoiceName = "voice/$Locale$/story/1004/100402/192276C6"
        },
        [10040216] = {
          Content = "啊，嘟嘟皎皎前辈！",
          ContentKR = "아, 철도원 루나 선배!",
          DialogueId = 10040216,
          GUID = "192276F0",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100402/192276F0"
        },
        [10040217] = {
          Content = "嘟嘟皎皎……？",
          ContentKR = "철도원 루나...?",
          DialogueId = 10040217,
          GUID = "1922771A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100402/1922771A"
        },
        [10040301] = {
          Content = "您好您好，我就是嘟嘟皎皎，是小白的老相识了，和她认识的时候我只是一个火车爱好者，而现在是百花车站的引导员兼宣传员兼义务乘务员！",
          ContentKR = "안녕, 반가워. 난 철도원 루나고, 스노우랑은 예전부터 잘 아는 사이야. 처음엔 그냥 평범한 기차 마니아였지만, 지금은 블룸필드역의 안내원 겸 홍보원 겸 명예 승무원을 맡고 있어!",
          DialogueId = 10040301,
          GUID = "192284E2",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 201005,
            [3] = 201009,
            [4] = 403010
          },
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100403/192284E2"
        },
        [10040302] = {
          Content = "火车虽然已经出现了很久，但最早的时候是作为运输武器的工具来使用的。",
          ContentKR = "기차는 사실 꽤 오래전에 등장한 운송수단이야. 사실 처음엔 무기를 실어 나르는 용도였지.",
          DialogueId = 10040302,
          GUID = "1922850C",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100403/1922850C"
        },
        [10040303] = {
          Content = "虽然现在已经有一部分火车转为民用，但每一辆火车仍旧搭载着武器。如果你出发前有足够时间的话，可以去火车的最前面，看看非常酷炫的列车炮哦。",
          ContentKR = "이젠 민간용으로 바뀐 열차도 있는데, 그래도 무기는 여전히 실려 있어. 시간 남으면, 맨 앞 칸에 가서 한 번 구경해 봐. 정말 멋진 열차포거든.",
          DialogueId = 10040303,
          GUID = "19228536",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100403/19228536"
        },
        [10040304] = {
          Content = "不过，相比很多火车爱好者口中的“机械美学”，我最喜欢火车的一点是“平等”。",
          ContentKR = "그런데 내가 기차를 좋아하는 건, 기차 마니아들이 흔히 말하는 '기계의 아름다움' 때문이 아니라, '평등함' 때문이야.",
          DialogueId = 10040304,
          GUID = "19228560",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100403/19228560"
        },
        [10040305] = {
          Content = "一车旅客，无论之前是习惯了步行、乘坐马车、驾驶汽车还是乘坐最新潮的飞艇，上了火车，都能平等地同时抵达目的地。",
          ContentKR = "평소에 걷는 게 익숙한 사람이든, 마차나 자동차, 아니면 요즘 유행하는 비행선을 타는 사람이든, 일단 기차에 타면, 누구나 똑같은 시간에 목적지에 도착하잖아.",
          DialogueId = 10040305,
          GUID = "1922858A",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100403/1922858A"
        },
        [10040306] = {
          Content = "所以我想努努力，让更多人知道火车是非常好的交通工具——就算你是卡戎之民，也可以平等地享受远处的山峦，吹入车厢的凉风，以及鸣笛的嘟嘟声！",
          ContentKR = "그래서 난 더 많은 사람한테 기차란 멋진 이동 수단을 알리고 싶어. 기차라면, 카론도 저 멀리 보이는 언덕이랑 차창으로 들어오는 시원한 바람, 그리고 칙칙폭폭 기차 소리를 똑같이 누릴 수 있으니까!",
          DialogueId = 10040306,
          GUID = "192285B4",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100403/192285B4"
        },
        [10040307] = {
          Content = "所以我在这里自愿帮助大家，时间久了，好心的站长说我确实能帮上忙，所以我就成为了车站的职员了！",
          ContentKR = "그래서 여기서 사람들을 돕기 시작한 거야. 그러다 마음씨 좋은 역장님이 내가 정말 큰 힘이 된다면서, 날 아예 직원으로 채용해 주신 거고!",
          DialogueId = 10040307,
          GUID = "192285DE",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100403/192285DE"
        },
        [10040308] = {
          Content = "第一次见到有正式工作的皎皎，看来你是相当喜欢火车啊。",
          ContentKR = "제대로 된 직업을 갖고 일하는 루나라니, 기차 사랑이 정말 대단하네.",
          DialogueId = 10040308,
          GUID = "19228608",
          ImprPlusId = 1009
        },
        [10040309] = {
          Content = "好心的站长？他是个怎样的人？",
          ContentKR = "마음씨 좋은 역장님? 어떤 분인데?",
          DialogueId = 10040309,
          GUID = "19228632",
          ImprPlusId = 1008
        },
        [10040310] = {
          Content = "做车站的职员坐火车有优惠吗？",
          ContentKR = "역 직원이 되면, 기차 탈 때 할인받을 수 있어?",
          DialogueId = 10040310,
          GUID = "1922865C",
          ImprPlusId = 1006
        },
        [10040311] = {
          Content = "嘿嘿，不过也不算啦，毕竟什么工作之类的是要获得报酬的，但我可没有要报酬，就是纯粹的出于兴趣！嘟嘟——",
          ContentKR = "헤헤, 제대로 된 직업이라긴 좀 그래. 그런 건 보통 월급을 받는데, 난 아니거든. 순전히 내 취미 생활이야! 칙칙!",
          DialogueId = 10040311,
          GUID = "19228686",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100403/19228686"
        },
        [10040312] = {
          Content = "嘟嘟！",
          ContentKR = "폭폭!",
          DialogueId = 10040312,
          GUID = "192286B0",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100403/192286B0"
        },
        [10040313] = {
          Content = "就是艾森巴恩站长。他看到我和卡戎介绍火车，高兴地说这样可以改善帝国的形象什么的，就让我在这边继续干下去了。",
          ContentKR = "아이젠반 역장님이야. 내가 카론한테 기차 소개하는 걸 보고, 제국 이미지에 도움이 되겠다면서 엄청 기뻐하시더니, 나한테 계속 여기서 일해도 된다고 하셨어.",
          DialogueId = 10040313,
          GUID = "192286DA",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100403/192286DA"
        },
        [10040314] = {
          Content = "听起来和其他帝国官员不太一样？",
          ContentKR = "제국 쪽 관료치곤 꽤 유연한 분인가 보네?",
          DialogueId = 10040314,
          GUID = "19228704",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100403/19228704"
        },
        [10040315] = {
          Content = "唔……我也没接触过其他帝国官员啦，只知道站长他人还挺负责的，车站里发生什么事情他都会过问。",
          ContentKR = "음... 제국 쪽 다른 관료들은 못 만나 봐서 잘 모르겠는데, 우리 역장님은 책임감이 진짜 대단하신 분이야. 역에 무슨 일이 생기면, 다 하나하나 직접 챙기시거든.",
          DialogueId = 10040315,
          GUID = "1922872E",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100403/1922872E"
        },
        [10040316] = {
          Content = "（卡米拉也提到过这个站长，这么看来确实不太好对付。）",
          ContentKR = "(카밀라 씨도 역장 얘길 했었지. 확실히 만만히 볼 상대는 아닌 것 같아.)",
          DialogueId = 10040316,
          DisableMouth = 1,
          GUID = "19228758",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100403/19228758"
        },
        [10040317] = {
          Content = "啊，没有哦……我是在这里自愿在这里帮忙的啦。并且有时候我也会去列车上帮忙，所以实际上不需要优惠啦。",
          ContentKR = "아, 할인 같은 건 따로 없어... 내가 좋아서 하는 거고, 가끔 일손이 필요할 땐 기차에 타기도 하니까, 사실 할인이 필요하진 않아.",
          DialogueId = 10040317,
          GUID = "19228782",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100403/19228782"
        },
        [10040318] = {
          Content = "这么好，我要是爱好者的话估计也想来这边做职员了。",
          ContentKR = "좋겠다. 나도 너만큼 기차를 좋아했으면, 여기서 일하고 싶었을 것 같아.",
          DialogueId = 10040318,
          GUID = "192287AC",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100403/192287AC"
        },
        [10040319] = {
          Content = "不是每个职位都可以这样啦，只有列车相关的职位才可以，像车站工厂里的工人们，他们想要坐火车也得攒很久很久的车票钱才行。",
          ContentKR = "역에서 일한다고 다 되는 건 아니고, 기차랑 관련된 업무를 해야 가능한 거야. 차량 정비단에서 일하시는 분들은, 기차 한 번 타려면 돈을 엄청 오래 모아야 해.",
          DialogueId = 10040319,
          GUID = "192287D6",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100403/192287D6"
        },
        [10040320] = {
          Content = "好啦，刚刚开始我一口气说了好多，现在该你们来说啦，你们想要去哪里呀？皇都？还是远方的丹流城？",
          ContentKR = "아차차, 너무 신나서 나만 잔뜩 떠들어 버렸네. 이제 너희 얘기도 해 봐. 어디 가려는 거야? 황성? 아니면 저 멀리 있는 스칼렛?",
          DialogueId = 10040320,
          GUID = "19228800",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100403/19228800"
        },
        [10040321] = {
          Content = "啊……嗯……我们想去皇都，但是还没有定好具体时间，而我的家是偏僻的小岛，没有见过火车这样城市里的事物，所以想来提前参观一下。",
          ContentKR = "아... 음... 황성에 갈까 하는데, 아직 언제 출발할지는 못 정했어. 그리고 내가 외딴섬 출신이라 기차 같은 건 구경도 못 해 봤거든. 그래서 미리 좀 보러 온 거야.",
          DialogueId = 10040321,
          GUID = "1922882A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100403/1922882A"
        },
        [10040322] = {
          Content = "原来是这样，那买一张站台票就行，只要几个银币就能看一整天火车！非常实惠！",
          ContentKR = "그렇구나. 그럼 입장권만 사면 돼. 실버 몇 닢만 주면, 하루 종일 기차 구경할 수 있거든! 실속 만점이지!",
          DialogueId = 10040322,
          GUID = "19228854",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100403/19228854"
        },
        [10040323] = {
          Content = "跟我来！",
          ContentKR = "날 따라와!",
          DialogueId = 10040323,
          GUID = "1922887E",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100403/1922887E"
        },
        [10040401] = {
          Content = "好啦，这里就是售票口啦，和里面的售票员说：站台票，两张成人，一张儿童就行。",
          ContentKR = "짜잔, 여기가 바로 매표소야! 창구 직원한테 성인 2장, 어린이 1장 달라고 하면 돼.",
          DialogueId = 10040401,
          GUID = "1922954A",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 201005,
            [3] = 201009,
            [4] = 403010
          },
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100404/1922954A"
        },
        [10040402] = {
          Content = "不过因为你们是第一次来，所以我就帮你们代劳啦，稍微等一等哦。",
          ContentKR = "근데 너희는 기차역에 처음 온 거니까, 내가 대신 끊어다 줄게. 잠깐만 기다려!",
          DialogueId = 10040402,
          GUID = "19229574",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100404/19229574"
        },
        [10040403] = {
          Content = "儿童……",
          ContentKR = "어린이라는데...",
          DialogueId = 10040403,
          GUID = "1922959E",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100404/1922959E"
        },
        [10040404] = {
          Content = "儿童？！",
          ContentKR = "어린이라고?!",
          DialogueId = 10040404,
          GUID = "192295C8",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100404/192295C8"
        },
        [10040405] = {
          Content = "不，不要儿童票，买三张成人票！",
          ContentKR = "아니, 어린이 말고! 어른 표 3장 사다 줘!",
          DialogueId = 10040405,
          GUID = "192295F2",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100404/192295F2"
        },
        [10040406] = {
          Content = "别闹别闹，听起来儿童票能便宜一点！剩下来的钱给你买好吃的好不好。",
          ContentKR = "진정해, 스노우. 어린이 표가 더 싸서 그런 걸 거야! 아낀 돈으로 이따 맛있는 거 사 줄게.",
          DialogueId = 10040406,
          GUID = "1922961C",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100404/1922961C"
        },
        [10040407] = {
          Content = "虽然能买好吃的确实是好消息啦，但是感觉你还是把我当做小孩对待。",
          ContentKR = "맛있는 거 사 주는 건 좋지만, 왠지 너도 날 꼬맹이 취급하는 것 같은데.",
          DialogueId = 10040407,
          GUID = "19229646",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100404/19229646"
        },
        [10040408] = {
          Content = "所有人，停下你们的脚步！",
          ContentKR = "여러분, 잠시 주목해 주십시오!",
          DialogueId = 10040408,
          GUID = "19229670",
          SpeakNpcName = "UI_SpeakName_YansuShibing",
          VoiceName = "voice/$Locale$/story/1004/100404/19229670"
        },
        [10040409] = {
          Content = "接下来，让我们迎接为帝国献身的老兵们，迎接他们再次回家！",
          ContentKR = "지금부터, 제국을 위해 헌신하고 무사히 복귀한 우리 용사들을 환영해 주십시오!",
          DialogueId = 10040409,
          GUID = "1922969A",
          SpeakNpcId = 100410,
          SpeakNpcName = "UI_SpeakName_YansuShibing",
          VoiceName = "voice/$Locale$/story/1004/100404/1922969A"
        },
        [10040410] = {
          Content = "他们成功镇压了神弃者同盟在帝国南方的叛乱，让我们以掌声与欢呼迎接他们的凯旋！",
          ContentKR = "남부에서 일어난 포세이큰 동맹의 반란을 완벽히 진압하고 돌아온 우리 군의 자랑들입니다! 큰 박수와 환호로 맞이해 주십시오!",
          DialogueId = 10040410,
          GUID = "192296C4",
          SpeakNpcId = 100410,
          SpeakNpcName = "UI_SpeakName_YansuShibing",
          VoiceName = "voice/$Locale$/story/1004/100404/192296C4"
        },
        [10040411] = {
          Content = "父亲！母亲！冰湖城！我终于活着回来了！",
          ContentKR = "아버지! 어머니! 제가 드디어 아이스레이크 시티로 돌아왔어요!",
          DialogueId = 10040411,
          GUID = "192296EE",
          SpeakNpcId = 100409,
          SpeakNpcName = "UI_SpeakName_FuyuanShibing",
          VoiceName = "voice/$Locale$/story/1004/100404/192296EE"
        },
        [10040412] = {
          Content = "孩子……我的孩子，你总算回来了……",
          ContentKR = "아들아... 우리 아들... 드디어 돌아왔구나...",
          DialogueId = 10040412,
          GUID = "19229718",
          SpeakNpcId = 100417,
          VoiceName = "voice/$Locale$/story/1004/100404/19229718"
        },
        [10040413] = {
          Content = "你一定吃了许多苦吧……回来就好，回来就好……",
          ContentKR = "그동안 얼마나 고생이 많았니... 돌아와서 정말 다행이구나, 참 다행이야...",
          DialogueId = 10040413,
          GUID = "19229742",
          SpeakNpcId = 100417,
          VoiceName = "voice/$Locale$/story/1004/100404/19229742"
        },
        [10040414] = {
          Content = "……？",
          ContentKR = "......?",
          DialogueId = 10040414,
          GUID = "1922976C",
          SpeakNpcId = 100409,
          SpeakNpcName = "UI_SpeakName_FuyuanShibing",
          VoiceName = "voice/$Locale$/story/1004/100404/1922976C"
        },
        [10040415] = {
          Content = "老人家，你是不是……认错人了？",
          ContentKR = "할머니, 사람을... 잘못 보신 것 같은데요?",
          DialogueId = 10040415,
          GUID = "19229796",
          SpeakNpcId = 100409,
          SpeakNpcName = "UI_SpeakName_FuyuanShibing",
          VoiceName = "voice/$Locale$/story/1004/100404/19229796"
        },
        [10040416] = {
          Content = "我没有认错，我怎么会认错，你手上的这枚铁戒指，是我亲手给我的孩子戴上的……这是他的东西！",
          ContentKR = "사람을 잘못 보다니, 그럴 리가. 네가 손에 끼고 있는 반지, 그건 내가 우리 아들 손에 끼워 줬던 거야... 우리 아들 거라고!",
          DialogueId = 10040416,
          GUID = "192297C0",
          SpeakNpcId = 100417,
          VoiceName = "voice/$Locale$/story/1004/100404/192297C0"
        },
        [10040417] = {
          Content = "我送他去了战场，为什么会在你手上！告诉我，他还活着吗？他不应该是你的战友吗？",
          ContentKR = "전쟁터에 내보낸 내 새끼 물건이, 대체 왜 네 손에 있는 거야? 우리 아들, 살아는 있는 거야? 네 전우였잖아?",
          DialogueId = 10040417,
          GUID = "192297EA",
          SpeakNpcId = 100417,
          VoiceName = "voice/$Locale$/story/1004/100404/192297EA"
        },
        [10040418] = {
          Content = "你在说什么啊？什么你的孩子？这戒指是我自己在丹流城买的！",
          ContentKR = "네? 아드님을 왜 저한테서 찾으세요? 이 반지는 제가 스칼렛에서 산 거라고요!",
          DialogueId = 10040418,
          GUID = "19229814",
          RelatedWikiId = {
            [1] = 408006
          },
          SpeakNpcId = 100409,
          SpeakNpcName = "UI_SpeakName_FuyuanShibing",
          VoiceName = "voice/$Locale$/story/1004/100404/19229814"
        }
      }
    end
  },
  {
    MinKey = 10040501,
    MaxKey = 10041603,
    Loader = function()
      return {
        [10040501] = {
          Content = "发现危险分子，为避免混乱进一步扩大，准备进行就地处理……",
          ContentKR = "위험인물이 포착되었습니다. 현장 혼란을 막기 위해, 즉시 제압 절차를...",
          DialogueId = 10040501,
          GUID = "1922A5B2",
          SpeakNpcId = 100410,
          SpeakNpcName = "UI_SpeakName_YansuShibing",
          VoiceName = "voice/$Locale$/story/1004/100405/1922A5B2"
        },
        [10040502] = {
          Content = "啊，艾森巴恩阁下……",
          ContentKR = "앗, 아이젠반 님...",
          DialogueId = 10040502,
          GUID = "1922A5DC",
          RelatedWikiId = {
            [1] = 201030
          },
          SpeakNpcId = 100410,
          SpeakNpcName = "UI_SpeakName_YansuShibing",
          VoiceName = "voice/$Locale$/story/1004/100405/1922A5DC"
        },
        [10040503] = {
          Content = "别急着开枪，这种事有更好的处理方式。",
          ContentKR = "총부터 들이대는 버릇은 버려라. 이런 사안은 얼마든지 원만하게 해결할 방안이 있다.",
          DialogueId = 10040503,
          GUID = "1922A606",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A606"
        },
        [10040504] = {
          Content = "上次类似的事情你们开了枪，还误伤了平民，结果在那之后几个月里我们的乘客数都一直低迷，好不容易才恢复正常。",
          ContentKR = "지난번에도 성급하게 발포했다가 무고한 민간인이 다치는 불상사가 발생했지. 그 사고의 여파로 곤두박질쳤던 승객 수가 이제야 겨우 회복세로 돌아섰다.",
          DialogueId = 10040504,
          GUID = "1922A630",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A630"
        },
        [10040505] = {
          Content = "所以说别只会用枪说话，偶尔也要动一动头脑。",
          ContentKR = "즉, 총기에 의존하지 말고, 가끔은 머리를 쓰란 얘기다.",
          DialogueId = 10040505,
          GUID = "1922A65A",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A65A"
        },
        [10040506] = {
          Content = "是，站长阁下，我立刻开动头脑。",
          ContentKR = "네, 역장님! 지금 당장 머리를 써보겠습니다!",
          DialogueId = 10040506,
          GUID = "1922A684",
          SpeakNpcId = 100410,
          SpeakNpcName = "UI_SpeakName_YansuShibing",
          VoiceName = "voice/$Locale$/story/1004/100405/1922A684"
        },
        [10040507] = {
          Content = "留着下次吧，现在开始想主意，怕不是要等到明天。",
          ContentKR = "이번엔 됐다. 지금 고민해 봐야 대책은 내일이나 나올 테니까.",
          DialogueId = 10040507,
          GUID = "1922A6AE",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A6AE"
        },
        [10040508] = {
          Content = "你们当中，个子最小的人。到前面去，去和她说“老人家，我能懂你的心情，千万不要寻短见”之类的套话，稳住她。",
          ContentKR = "너희 중, 체구가 가장 작은 녀석을 앞으로 보내서, \"어르신, 그 마음 다 이해하니까, 일단 진정하세요\" 같은 뻔한 위로로 노인을 진정시켜.",
          DialogueId = 10040508,
          GUID = "1922A6D8",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A6D8"
        },
        [10040509] = {
          Content = "让烟囱方向的包围撤走，慢一点撤，让她无意识靠近烟囱那个方向。",
          ContentKR = "굴뚝 쪽 포위망을 풀어라, 서서히. 노인이 무의식적으로 그쪽을 향해 뒷걸음질 치도록.",
          DialogueId = 10040509,
          GUID = "1922A702",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A702"
        },
        [10040510] = {
          Content = "告诉我，我的孩子在哪里？你是不是在他背后放了黑枪！",
          ContentKR = "말해, 우리 애 어디 있어? 네가 등 뒤에서 우리 아들을 쏜 거지!",
          DialogueId = 10040510,
          GUID = "1922A72C",
          SpeakNpcId = 100417,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A72C"
        },
        [10040511] = {
          Content = "……喂、喂！我真不认识你，失心疯了吧！",
          ContentKR = "...아니, 할머니! 대체 누구신데 이러세요! 이상한 할머니네!",
          DialogueId = 10040511,
          GUID = "1922A756",
          SpeakNpcId = 100409,
          SpeakNpcName = "UI_SpeakName_FuyuanShibing",
          VoiceName = "voice/$Locale$/story/1004/100405/1922A756"
        },
        [10040512] = {
          Content = "差不多了，就是现在，出来吧。",
          ContentKR = "슬슬 때가 됐군. 지금이다, 나와라.",
          DialogueId = 10040512,
          GUID = "1922A780",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A780"
        },
        [10040513] = {
          Content = "犯人已经擒获，先押送至禁闭室。",
          ContentKR = "신병 확보 완료. 즉시 구금실로 압송하겠습니다.",
          DialogueId = 10040513,
          GUID = "1922A7AA",
          SpeakNpcId = 100410,
          SpeakNpcName = "UI_SpeakName_YansuShibing",
          VoiceName = "voice/$Locale$/story/1004/100405/1922A7AA"
        },
        [10040514] = {
          Content = "且慢。",
          ContentKR = "잠깐.",
          DialogueId = 10040514,
          GUID = "1922A7D4",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A7D4"
        },
        [10040515] = {
          Content = "这位老人，我理解您担心孩子的安危，而做出过激行为，我也曾经在战场上失去了重要的朋友，那种痛苦钻心剜骨，会让人失去理智。",
          ContentKR = "어르신, 자식 걱정에 격한 언행을 보이신 그 심정, 충분히 이해합니다. 저 역시 전장에서 소중한 전우들을 잃어 본 경험이 있습니다. 처절하고 애끓는 마음이 때로는 이성을 무너뜨리기도 하지요.",
          DialogueId = 10040515,
          GUID = "1922A7FE",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A7FE"
        },
        [10040516] = {
          Content = "但是，您也许并不知道，后续还有数列承载复员老兵的列车。而这样的戒指，每座城市都有几十个雕金匠可以造出来。",
          ContentKR = "아직 모르시겠지만, 병사들을 실은 열차가 앞으로도 몇 대나 더 도착할 예정입니다. 게다가 이런 반지는, 도시의 세공사라면 얼마든지 만들어낼 수 있는 물건이죠.",
          DialogueId = 10040516,
          GUID = "1922A828",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A828"
        },
        [10040517] = {
          Content = "所以说，我想，您的孩子说不定此时正在另一辆列车上准备返乡。而这位士兵也绝非逃兵，他只是刚巧戴着相似戒指的帝国勇士。",
          ContentKR = "그러니, 아드님께선 다른 열차에 몸을 싣고 돌아오는 중일지도 모릅니다. 여기 이 병사 역시, 탈영병이 아니라, 우연히 비슷한 반지를 가지고 있는 제국의 용사일 뿐입니다.",
          DialogueId = 10040517,
          GUID = "1922A852",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A852"
        },
        [10040518] = {
          Content = "早说过了，丹流城，一家叫“白银之心”的首饰店买的，不信自己去查。",
          ContentKR = "말씀드렸잖아요, 스칼렛에 있는 '실버 하트'라는 장신구 가게에서 샀다니까요. 직접 확인해 보시든가요.",
          DialogueId = 10040518,
          GUID = "1922A87C",
          SpeakNpcId = 100409,
          SpeakNpcName = "UI_SpeakName_FuyuanShibing",
          VoiceName = "voice/$Locale$/story/1004/100405/1922A87C"
        },
        [10040519] = {
          Content = "你们……没有骗我？",
          ContentKR = "당신들... 날 속이는 건 아니겠지?",
          DialogueId = 10040519,
          GUID = "1922A8A6",
          SpeakNpcId = 100417,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A8A6"
        },
        [10040520] = {
          Content = "当然，我们敬重为国作战的士兵，也同样敬重愿意让自己的孩子奔赴战场的英雄母亲，我相信，您会等来好消息的。",
          ContentKR = "물론입니다. 나라를 위해 싸우는 용사들도 위대하지만, 자식을 전장으로 떠나보낸 어머니의 희생 또한 숭고한 법이니까요. 분명, 머지않아 좋은 소식이 있을 겁니다.",
          DialogueId = 10040520,
          GUID = "1922A8D0",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A8D0"
        },
        [10040521] = {
          Content = "呜……对不起，对不起……孩子，吓到你了，我实在是等了太久了，等了太久了。",
          ContentKR = "으흑... 미안하구나, 미안해... 얘야, 많이 놀랐지? 우리 아들을 오래, 너무 오래 기다리다 보니 이렇게 됐구나.",
          DialogueId = 10040521,
          GUID = "1922A8FA",
          SpeakNpcId = 100417,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A8FA"
        },
        [10040522] = {
          Content = "您不必着急，这样吧，您可以到我们的站内慢慢休息。至于其他的乘客们，让各位受到惊吓，我在此向大家致以歉意。",
          ContentKR = "너무 조급해하실 것 없습니다. 우선, 역 안에서 천천히 안정을 취하시죠. 아울러 승객 여러분, 예기치 못한 소란으로 놀라게 해 드린 점, 정중히 사과드립니다.",
          DialogueId = 10040522,
          GUID = "1922A924",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A924"
        },
        [10040523] = {
          Content = "不过我向各位承诺，只要我艾森巴恩·瓦格纳还作为站长管理着百花车站，就不会让列车的运行出现意外，还请各位放心！",
          ContentKR = "하지만 이 아이젠반 바그너가 블룸필드역의 역장으로 있는 한, 열차 운행에 차질이 생길 일은 결코 없을 테니, 다들 안심하십시오!",
          DialogueId = 10040523,
          GUID = "1922A94E",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A94E"
        },
        [10040524] = {
          Content = "站长一番话说完不久，因为一连串意外而被中断了日常氛围的站前穹顶也恢复了正常运转。",
          ContentKR = "역장의 말이 끝나기가 무섭게, 잠시 소동으로 어수선했던 역전 아트리움은 이내 평온한 일상으로 돌아간다.",
          DialogueId = 10040524,
          GUID = "1922A978",
          VoiceName = "voice/$Locale$/story/1004/100405/1922A978"
        },
        [10040525] = {
          Content = "那个人，就是站长艾森巴恩……这么轻易地就平息了一场骚动，难怪嘟嘟皎皎和卡米拉都会特意提及他。",
          ContentKR = "저 사람이 바로 아이젠반 역장이구나... 저렇게 단숨에 소동을 가라앉히다니, 철도원 루나랑 카밀라가 따로 이야기할 만했네.",
          DialogueId = 10040525,
          GUID = "1922A9A2",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A9A2"
        },
        [10040526] = {
          Content = "……不仅安排士兵有条不紊，并且还安抚了乘客，可以说是心思缜密了。",
          ContentKR = "...병사들을 솜씨 좋게 지휘하면서 승객들까지 안심시키는 걸 보면, 아주 빈틈없는 성격인가 보네.",
          DialogueId = 10040526,
          GUID = "1922A9CC",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A9CC"
        },
        [10040527] = {
          Content = "现在可不是夸他的时候哦，我们要做的事情不就是在他的地盘上收集情报。",
          ContentKR = "칭찬하고 있을 때가 아니야. 우린 지금 저 사람 앞마당에서 정보를 캐내야 한다고.",
          DialogueId = 10040527,
          GUID = "1922A9F6",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100405/1922A9F6"
        },
        [10040528] = {
          Content = "我清楚得很。唉，帝国这么多官员都是酒囊饭袋，偏偏这个不是。",
          ContentKR = "그러게 말이야. 어휴, 제국 관리들은 하나같이 무능한 밥벌레들이던데, 왜 하필 저 사람만 예외인 거야.",
          DialogueId = 10040528,
          GUID = "1922AA20",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100405/1922AA20"
        },
        [10040529] = {
          Content = "我买好票回来啦！刚刚似乎发生了什么小意外？",
          ContentKR = "표 사 가지고 왔어! 근데 아까 여기서 무슨 일 있었어?",
          DialogueId = 10040529,
          GUID = "1922AA4A",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100405/1922AA4A"
        },
        [10040530] = {
          Content = "（向嘟嘟皎皎陈述了事件的起因结果……）",
          ContentKR = "(철도원 루나에게 방금 일어난 사건의 자초지종을 설명해 준다...)",
          DialogueId = 10040530,
          DisableMouth = 1,
          GUID = "1922AA74",
          VoiceName = "voice/$Locale$/story/1004/100405/1922AA74"
        },
        [10040531] = {
          Content = "嗯……因为车站这里人来人往，各种意外总是免不了的，前一段时间还有神弃者同盟的家伙想要潜入站内，但也被站长识破了。",
          ContentKR = "음... 역은 워낙 오가는 사람이 많으니까, 이런저런 사고가 끊이질 않아. 얼마 전에는 포세이큰 동맹 녀석들이 여기 몰래 숨어 들어오려다가, 역장님한테 들통난 적도 있거든.",
          DialogueId = 10040531,
          GUID = "1922AA9E",
          RelatedWikiId = {
            [1] = 101004
          },
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100405/1922AA9E"
        },
        [10040532] = {
          Content = "神弃者同盟？",
          ContentKR = "포세이큰 동맹?",
          DialogueId = 10040532,
          GUID = "1922AAC8",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100405/1922AAC8"
        },
        [10040533] = {
          Content = "嗯，我听说同盟最近在帝国南方又有一些小规模的叛乱，可能这些同盟成员想要乘车去南方帮助同伴？",
          ContentKR = "응, 얼마 전에 그 녀석들이 또 제국 남부에서 소규모 반란을 일으켰다고 하더라고. 아마 남쪽으로 가서 동료를 도우려던 거 아닐까?",
          DialogueId = 10040533,
          GUID = "1922AAF2",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100405/1922AAF2"
        },
        [10040534] = {
          Content = "不过叛乱已经被解决了，所以接下来这种意外应该也会减少。到时候就可以有更多人安心乘坐火车啦！",
          ContentKR = "근데 반란은 벌써 다 진압됐대. 그러니까 앞으론 그런 소동도 줄어들 거고, 더 많은 사람이 마음 놓고 기차를 탈 수 있을 거야!",
          DialogueId = 10040534,
          GUID = "1922AB1C",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100405/1922AB1C"
        },
        [10040535] = {
          Content = "你真的好喜欢火车，在这里工作应该也很开心。",
          ContentKR = "기차를 정말 좋아하는구나. 일하면서도 꽤 즐겁겠네.",
          DialogueId = 10040535,
          GUID = "1922AB46",
          ImprPlusId = 1009
        },
        [10040536] = {
          Content = "噫，我不要这种话，锦鲤皎皎说，华胥有句俗话叫怕什么来什么。",
          ContentKR = "입방정 떨지 마. 화서에 있을 때 행운아 루나한테 들었는데, 말이 씨가 되는 법이래.",
          DialogueId = 10040536,
          GUID = "1922AB70",
          ImprPlusId = 1010
        },
        [10040537] = {
          Content = "前一阵子听说冰湖城也有神弃者同盟的活动，希望这些事之前不要有所关联。",
          ContentKR = "저번에 포세이큰 동맹이 아이스레이크 시티에서도 뭔가 하려고 했단 소문을 들었어. 그 일과는 상관없어야 할 텐데.",
          DialogueId = 10040537,
          GUID = "1922AB9A",
          ImprPlusId = 1008
        },
        [10040538] = {
          Content = "嘿嘿，我们皎皎之民是这样的，认定了某件事就会一直坚持做下去。就好像白，一直在跟着你们，看样子也是认定了要跟着你们哦。",
          ContentKR = "헤헤, 우리 루나들은 원래 이래. 한 번 꽂히면 끝까지 파고들거든. 스노우도 계속 너희를 따라다니는 걸 보면, 너한테 앞으로 쭉 같이 다니기로 마음먹은 모양이야.",
          DialogueId = 10040538,
          GUID = "1922ABC4",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100405/1922ABC4"
        },
        [10040539] = {
          Content = "才不是呢，是我怕他们遇到麻烦事，所以想要照顾他们！虽然……虽然他们也确实帮了不少忙啦。",
          ContentKR = "그런 거 아니야! 얘네가 골치 아픈 일에 휘말릴까 봐 내가 챙겨 주려는 거라구! 뭐... 내가 도움을 받은 적도 좀 많긴 하지만.",
          DialogueId = 10040539,
          GUID = "1922ABEE",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100405/1922ABEE"
        },
        [10040540] = {
          Content = "放心啦，哪怕真出现意外，车站里的守卫们也能解决的！",
          ContentKR = "걱정 마, 진짜 무슨 일이 생겨도, 역 안에 있는 경비병들이 다 알아서 해결해 줄 테니까!",
          DialogueId = 10040540,
          GUID = "1922AC18",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100405/1922AC18"
        },
        [10040541] = {
          Content = "那……他们是不是很厉害，很难对付？",
          ContentKR = "그럼... 다들 엄청 세겠네? 상대하기도 힘들지?",
          DialogueId = 10040541,
          GUID = "1922AC42",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100405/1922AC42"
        },
        [10040542] = {
          Content = "咦？怎么，白是想和他们比划比划吗？我建议你最好还是不要这样做哦，车站里人来人往，他们也很忙的。",
          ContentKR = "어? 왜 그래, 설마 저 사람들이랑 누가 센지 싸워 보려고? 안 그러는 게 좋아. 여긴 오가는 사람도 많고, 다들 엄청 바쁘단 말이야.",
          DialogueId = 10040542,
          GUID = "1922AC6C",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100405/1922AC6C"
        },
        [10040543] = {
          Content = "没……没事！我就是好奇，毕竟我也去过好多地方了，会好奇这些守卫和华胥的应天尉比起来谁更厉害什么的，才不会做去和守卫打架这种傻事。",
          ContentKR = "그, 그럴 리가! 나도 여기저기 많이 다녀봤으니까, 이 경비병들이랑 화서의 응천위 중에서 누가 더 센지 궁금해서 물어본 거라구. 괜히 경비병이랑 싸우는 바보 같은 짓은 안 해.",
          DialogueId = 10040543,
          GUID = "1922AC96",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100405/1922AC96"
        },
        [10040544] = {
          Content = "咦，是不是之前琳恩长官乘坐火车过来的那次？我有印象，不过听说也已经了结了。",
          ContentKR = "아, 혹시 린 님이 기차 타고 오셨을 때 말하는 거야? 기억은 나는데, 그 일도 이미 해결됐다고 들었어.",
          DialogueId = 10040544,
          GUID = "1922ACC0",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100405/1922ACC0"
        },
        [10040545] = {
          Content = "是哦，那件事白也有帮忙呢！你看，虽然我买儿童票，但是他们也缺少不了我的照顾。",
          ContentKR = "맞아, 그 사건은 스노우도 힘을 보탰었다구! 이거 봐, 내가 어린이 표를 끊긴 했지만, 얘네는 내가 안 챙겨 주면 안 된다니까.",
          DialogueId = 10040545,
          GUID = "1922ACEA",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100405/1922ACEA"
        },
        [10040546] = {
          Content = "知道啦知道啦。那么，票已经买好了，你就带着{性别：他们|她们}去检票吧，我还要去招待新的乘客！",
          ContentKR = "그래, 알았어. 자, 표도 다 샀으니까, 이 친구들 데리고 가서 검표 받아. 난 새로운 승객들을 맞이하러 가야 해!",
          DialogueId = 10040546,
          GUID = "1922AD14",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100405/1922AD14"
        },
        [10040547] = {
          Content = "再见，{nickname}，再见，白！",
          ContentKR = "잘 가, {nickname}! 잘 가, 스노우!",
          DialogueId = 10040547,
          GUID = "1922AD3E",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100405/1922AD3E"
        },
        [10040548] = {
          Content = "再见，谢谢你的帮助。",
          ContentKR = "응, 도와줘서 정말 고마웠어.",
          DialogueId = 10040548,
          GUID = "1922AD68",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100405/1922AD68"
        },
        [10040549] = {
          Content = "哼哼，说了我的前辈很可靠吧，那么，既然已经拿到票了，我们出发，去检票口。",
          ContentKR = "후후, 진짜 믿음직스러운 선배라니깐! 자, 표도 구했으니까, 우리도 출발하자. 검표하러 가야지.",
          DialogueId = 10040549,
          GUID = "1922AD92",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100405/1922AD92"
        },
        [10040550] = {
          Content = "记住，过检票口时一定要自然，放轻松，不要紧张。",
          ContentKR = "명심해. 검표소 지날 때는 무조건 자연스럽게, 긴장하지 말고 아무렇지 않게 행동해야 해.",
          DialogueId = 10040550,
          GUID = "1922ADBC",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100405/1922ADBC"
        },
        [10040551] = {
          Content = "没问题，走吧。",
          ContentKR = "문제없어, 가자.",
          DialogueId = 10040551,
          GUID = "1922ADE6",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100405/1922ADE6"
        },
        [10040601] = {
          Content = "您好，欢迎来到冰湖城百花车站，我们手中的枪、列车顶的巨炮和翱翔天空的飞艇都会竭诚保障您旅途的安全。",
          ContentKR = "안녕하세요, 아이스레이크 시티 블룸필드역에 오신 걸 환영합니다. 저희 경비병들의 총과 열차 위의 대포, 그리고 하늘 위의 비행선이 승객 여러분의 안전한 여행을 위해 최선을 다할 겁니다.",
          DialogueId = 10040601,
          GUID = "1922B61A",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 201005,
            [3] = 201009
          },
          SpeakNpcId = 100420,
          SpeakNpcName = "UI_SpeakName_RenzhenWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922B61A"
        },
        [10040602] = {
          Content = "希望您能够享受这段最新月髓技术的旅程。",
          ContentKR = "최신 폭시코르 기술이 집약된 여정을 만끽하시길 바랍니다.",
          DialogueId = 10040602,
          GUID = "1922B644",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_SpeakName_LimaoWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922B644"
        },
        [10040603] = {
          Content = "那么，为了您，为了其他乘客，更是为了帝国动脉的安全，接下来我会进行安全检查。",
          ContentKR = "자, 그러면 승객 여러분과 제국 핵심 철로의 안전을 위해, 잠시 보안 검색을 진행하겠습니다.",
          DialogueId = 10040603,
          GUID = "1922B66E",
          SpeakNpcId = 100420,
          SpeakNpcName = "UI_SpeakName_RenzhenWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922B66E"
        },
        [10040604] = {
          Content = "嗯？之前我也来过几次车站，怎么没听说过有什么安全检查啊？哎呀您瞧，我就是一老实本分的狩月人，能有什么危险物品。",
          ContentKR = "네? 제가 전에도 여기 몇 번 왔었는데, 그땐 보안 검색 같은 거 없었잖아요? 에이, 전 누가 봐도 얌전히 일만 하는 월석 사냥꾼인데, 위험물을 들고 다닐 리 없잖아요.",
          DialogueId = 10040604,
          GUID = "1922B698",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100406/1922B698"
        },
        [10040605] = {
          Content = "还不是因为神弃者同盟嘛，可能你在冰湖城没什么感觉，其他地界神弃者同盟现在又闹腾起来了。",
          ContentKR = "포세이큰 동맹 때문에 어쩔 수 없습니다. 아이스레이크 시티에만 계셔서 잘 모르시겠지만, 지금 다른 지역은 그 녀석들이 또 난리를 치고 있거든요.",
          DialogueId = 10040605,
          GUID = "1922B6C2",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_SpeakName_LimaoWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922B6C2"
        },
        [10040606] = {
          Content = "总能传出这儿着火了那儿爆炸了的事，所以不得不防啊，我们铁路是帝国动脉，可不能被这帮疯子给破坏了。",
          ContentKR = "여기저기서 폭발에 화재 소식까지 끊이질 않으니 철저히 대비해야죠. 그 미치광이들이, 철도라는 우리 제국의 대동맥을 짓밟게 내버려둘 순 없으니까요.",
          DialogueId = 10040606,
          GUID = "1922B6EC",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_SpeakName_LimaoWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922B6EC"
        },
        [10040607] = {
          Content = "原来是这样，你们辛苦了，我是没见过神弃者同盟，但也听说过他们做事不择手段，出人意料。真要见到，一定用手里这把刀给他们劈成两半。",
          ContentKR = "그런 사정이 있었군요. 다들 수고가 많으시네요. 직접 본 적은 없어도, 그 녀석들이 수단과 방법을 안 가리는 놈들이란 얘긴 들었어요. 마주치기만 하면, 제가 이 칼로 아주 두 동강을 내 버릴게요.",
          DialogueId = 10040607,
          GUID = "1922B716",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100406/1922B716"
        },
        [10040608] = {
          Content = "不错，有志气，是可塑之才，可惜是个卡戎。有机会的话，可以尝试来报名成为桂冠卡戎。",
          ContentKR = "훌륭하군요. 카론이라는 게 아쉬울 정도로, 멋진 자신감입니다. 기회가 되면, 계관카론에 지원해 보세요.",
          DialogueId = 10040608,
          GUID = "1922B740",
          RelatedWikiId = {
            [1] = 407003
          },
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_SpeakName_LimaoWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922B740"
        },
        [10040609] = {
          Content = "好好，下次一定，下次一定。",
          ContentKR = "아, 네네, 다음번에요.",
          DialogueId = 10040609,
          GUID = "1922B76A",
          ImprPlusId = 1010
        },
        [10040610] = {
          Content = "身为卡戎没什么可惜的，索拉和卡戎除了头上有没有角，其他也没有什么不同。",
          ContentKR = "카론이라고 딱히 아쉬운 건 없어요. 솔라나 카론이나, 머리에 뿔이 있고 없고, 그 정도 차이밖에 없는걸요.",
          DialogueId = 10040610,
          GUID = "1922B794",
          ImprPlusId = 1007
        },
        [10040611] = {
          Content = "那就不必了，据我所知去做桂冠卡戎也不是什么好出路，还有可能赔上身家性命。",
          ContentKR = "그건 사양할게요. 계관카론도 대단할 거 없다고 들었거든요. 심지어 목숨을 내놔야 할 수도 있다던데요.",
          DialogueId = 10040611,
          GUID = "1922B7BE",
          ImprPlusId = 1009
        },
        [10040612] = {
          Content = "你这家伙，是不是这么应付朋友应付习惯了，对谁都这么说。",
          ContentKR = "...평소에 친구들한테도 대충 그렇게 건성으로 대답하나 보죠?",
          DialogueId = 10040612,
          GUID = "1922B7E8",
          SpeakNpcId = 100420,
          SpeakNpcName = "UI_SpeakName_RenzhenWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922B7E8"
        },
        [10040613] = {
          Content = "道理是这个道理，但这话在帝国嘛，你也知道，索拉要是当真没啥问题，卡戎要是当了真，就麻烦了。",
          ContentKR = "말이야 그렇죠. 하지만 여긴 제국입니다. 솔라야 뭐라고 믿든 상관없어도, 카론이 저런 말을 곧이곧대로 받아들이면 상황이 곤란해지죠. 그쪽도 잘 아시잖아요.",
          DialogueId = 10040613,
          GUID = "1922B812",
          SpeakNpcId = 100420,
          SpeakNpcName = "UI_SpeakName_RenzhenWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922B812"
        },
        [10040614] = {
          Content = "瞧你说的，我也听说过一些传闻，不过八成就是好事者编的都市传说。至于你选择相信哪一种事实，我也没法强迫你就是了。",
          ContentKR = "비약이 심하시네요. 저도 그런 소문은 들었습니다만, 대부분은 할 일 없는 사람들이 퍼뜨린 헛소문일 겁니다. 물론 어느 쪽을 믿으실지는 그쪽 선택이고요.",
          DialogueId = 10040614,
          GUID = "1922B83C",
          SpeakNpcId = 100420,
          SpeakNpcName = "UI_SpeakName_RenzhenWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922B83C"
        },
        [10040615] = {
          Content = "啊……？哪儿不通过了，你看我这打扮，老实巴交。看我这面相，忠厚淳朴。没有比我更安全的人了。",
          ContentKR = "네...? 왜요? 제 차림새만 봐도 착실해 보이잖아요. 인상도 선하고 순박하고요. 저만큼 안전한 사람이 어디 있다고 그러세요.",
          DialogueId = 10040615,
          GUID = "1922B866",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100406/1922B866"
        },
        [10040616] = {
          Content = "呃，油嘴滑舌没有用，老实面对你的问题——",
          ContentKR = "음, 능청 떨어도 소용없습니다. 딴소리 말고 솔직히 대답하세요.",
          DialogueId = 10040616,
          GUID = "1922B890",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_SpeakName_LimaoWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922B890"
        },
        [10040617] = {
          Content = "就说你身上戴着的这个吊坠吧，做工精致材料名贵。如果我记得没错的话，是产自赫墨的宝石。",
          ContentKR = "당신이 목에 걸고 있는 그 펜던트, 만듦새도 정교하고 재료도 상당히 고급이네요. 제가 알기로 그건, 케메트에서나 나는 귀한 보석이에요.",
          DialogueId = 10040617,
          GUID = "1922B8BA",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_SpeakName_LimaoWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922B8BA"
        },
        [10040618] = {
          Content = "我看你虽说是穿着衣服吧，但是也不是什么正经衣服，裹着布条子露个肚子的。我有理由怀疑这个吊坠不是你捡了后据为己有，就是从哪里顺的！",
          ContentKR = "그런데 당신은, 옷 같지도 않은 천 쪼가리를 두르고, 배꼽을 다 내놓고 다니고 있고요. 그러니 당연히 의심이 가지 않겠습니까? 그 펜던트는 분명히 당신 게 아니라, 어디서 주웠거나, 슬쩍한 거겠죠!",
          DialogueId = 10040618,
          GUID = "1922B8E4",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_SpeakName_LimaoWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922B8E4"
        },
        [10040619] = {
          Content = "呃，这是我妹妹做的护身符……",
          ContentKR = "아니, 이건 제 여동생이 만들어 준 부적이에요...",
          DialogueId = 10040619,
          GUID = "1922B90E",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100406/1922B90E"
        },
        [10040620] = {
          Content = "好，那就让你妹妹过来，我们来核对一下。在那之前呢，就先由车站保管了。",
          ContentKR = "좋습니다. 그렇다면 사실 여부를 확인하기 위해, 그 여동생분을 이쪽으로 모셔 오시죠. 그때까지 펜던트는 이쪽에서 보관하고 있겠습니다.",
          DialogueId = 10040620,
          GUID = "1922B938",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_SpeakName_LimaoWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922B938"
        },
        [10040621] = {
          Content = "可是这样一来我们就赶不上车了……",
          ContentKR = "하지만 그래 버리면 기차 시간을 놓치게 되는데요...",
          DialogueId = 10040621,
          GUID = "1922B962",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100406/1922B962"
        },
        [10040622] = {
          Content = "怎么回事，吵什么呢？第一次坐火车不知道要买票还是？能让我先过去吗，我这边快发车了。",
          ContentKR = "무슨 일이지? 웬 소란이야? 기차를 타려면 표가 있어야 한다는 것도 모르는 건가? 어서 비켜, 이쪽은 기차 출발 시간 다 됐으니까.",
          DialogueId = 10040622,
          GUID = "1922B98C",
          SpeakNpcId = 100479,
          VoiceName = "voice/$Locale$/story/1004/100406/1922B98C"
        },
        [10040623] = {
          Content = "好，那您先过吧，但是安全检查也还是必要的。",
          ContentKR = "네, 먼저 들여보내 드릴 수는 있지만, 보안 검색부터 마치셔야 합니다.",
          DialogueId = 10040623,
          GUID = "1922B9B6",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_SpeakName_LimaoWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922B9B6"
        },
        [10040624] = {
          Content = "什么？我也要检查？",
          ContentKR = "뭐라고? 나도 보안 검색을 받아야 한단 거야?",
          DialogueId = 10040624,
          GUID = "1922B9E0",
          SpeakNpcId = 100479,
          VoiceName = "voice/$Locale$/story/1004/100406/1922B9E0"
        },
        [10040625] = {
          Content = "那也没有办法，刚刚大厅里那个老太太在闹事你应该也看见了，这要是发生在站内的话，还指不定有什么乱子出现。所以，理解一下。",
          ContentKR = "어쩔 수 없습니다. 방금 대합실에서 어떤 노부인께서 소란을 피운 걸 보셨을 텐데요. 역 내부에서 그런 일이 벌어졌다간, 무슨 사고로 이어질지 모릅니다. 그러니 양해 부탁드립니다.",
          DialogueId = 10040625,
          GUID = "1922BA0A",
          SpeakNpcId = 100420,
          SpeakNpcName = "UI_SpeakName_RenzhenWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922BA0A"
        },
        [10040626] = {
          Content = "你们也一样，我也不是想要私吞你的东西什么的。但是站长让我们多留心，实在不敢大意啊，回去把你妹妹叫来，她的证词没问题我们就还你。",
          ContentKR = "당신들도 마찬가지입니다. 물건을 가로채려는 게 아니라, 역장님께서 각별히 주의를 주셨기 때문에, 저희도 어쩔 수 없습니다. 여동생분을 통해 사실 여부가 확인되면, 바로 돌려드리겠습니다.",
          DialogueId = 10040626,
          GUID = "1922BA34",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_SpeakName_LimaoWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922BA34"
        },
        [10040627] = {
          Content = "总之呢，安全检查不通过，都下次再来吧。",
          ContentKR = "어쨌든, 보안 검색에 통과하지 못하셨습니다. 다음에 다시 오세요.",
          DialogueId = 10040627,
          GUID = "1922B83D",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_SpeakName_RenzhenWeibing",
          VoiceName = "voice/$Locale$/story/1004/100406/1922B83D"
        },
        [10040701] = {
          Content = "唉，怎么会发生这种事，早知道出门前把护身符放家里了。",
          ContentKR = "으아, 어쩌다 일이 이렇게 꼬였냐. 이럴 줄 알았으면 부적은 집에다 두고 오는 거였는데.",
          DialogueId = 10040701,
          GUID = "1922C682",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100407/1922C682"
        },
        [10040702] = {
          Content = "倒也不怪你，谁也不会想到他们连个吊坠都要管。要先回去找菲娜吗？",
          ContentKR = "네 탓이 아니야. 펜던트 하나 가지고 저렇게 물고 늘어질 줄 누가 알았겠어. 일단 가서 피나 데리고 올까?",
          DialogueId = 10040702,
          GUID = "1922C6AC",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100407/1922C6AC"
        },
        [10040703] = {
          Content = "不太行，现在天色已经不早了，一来一回，等我们回来的时候，最后一班车都应该开走了。",
          ContentKR = "그건 무리야. 벌써 날도 꽤 어두워졌고, 오가는 시간까지 치면, 다시 도착했을 때쯤엔 막차도 떠났을 테니까.",
          DialogueId = 10040703,
          GUID = "1922C6D6",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100407/1922C6D6"
        },
        [10040704] = {
          Content = "要不，在这里新买一套衣服换上，说不定他们就认不出你了？",
          ContentKR = "그럼, 아예 새 옷을 사서 쫙 빼입고 가는 건 어때? 그럼 못 알아볼 수도 있잖아?",
          DialogueId = 10040704,
          GUID = "1922C700",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100407/1922C700"
        },
        [10040705] = {
          Content = "别犯傻啦，这里只有卖吃的卖喝的卖车票的，哪有卖衣服的。再说了，那些卫兵只是固执，又不是瞎。",
          ContentKR = "바보냐. 여기 옷 파는 데가 어디 있어. 먹는 거랑 기차표밖에 안 팔잖아. 그리고, 저 경비병들은 융통성이 없는 거지, 시력이 없는 게 아니라고.",
          DialogueId = 10040705,
          GUID = "1922C72A",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100407/1922C72A"
        },
        [10040706] = {
          Content = "唉……你说得也有道理，要是本魔王有隐形衣就好了……",
          ContentKR = "하아... 하긴 그렇네. 이 마왕님한테 투명 망토가 있으면 좋았을걸...",
          DialogueId = 10040706,
          GUID = "1922C754",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100407/1922C754"
        },
        [10040707] = {
          Content = "隐形衣……也不是没有可能。",
          ContentKR = "투명 망토라... 아예 불가능한 건 아냐.",
          DialogueId = 10040707,
          GUID = "1922C77E",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100407/1922C77E"
        },
        [10040708] = {
          Content = "咦？小仆从，你什么时候有的这么厉害的东西，莫非是止流掌柜偷偷塞给你的宝物？",
          ContentKR = "어? 시종, 너 언제부터 그런 엄청난 보물을 가지고 있었어? 설마 지류 사장님이 몰래 챙겨 준 거야?",
          DialogueId = 10040708,
          GUID = "1922C7A8",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100407/1922C7A8"
        },
        [10040709] = {
          Content = "那倒不是，我的意思是，也许我们可以换一个身份。",
          ContentKR = "아니, 내 말은 그게 아니라, 차라리 아예 신분을 위장해 보자는 거야.",
          DialogueId = 10040709,
          GUID = "1922C7D2",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100407/1922C7D2"
        },
        [10040710] = {
          Content = "我听其他狩月人提过这样一个潜入技巧：“工作服是最好的隐形衣，只要穿着工作制服扛着梯子扮作工人，就能走到任何地方。”",
          ContentKR = "어떤 월석 사냥꾼이 잠입 기술이라면서, \"작업복이야말로 최고의 투명 망토다\"라는 얘길 했었거든. 작업복 입고, 사다리 들고 인부 행세를 하면, 어디든 그냥 들어갈 수 있대.",
          DialogueId = 10040710,
          GUID = "1922C7FC",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100407/1922C7FC"
        },
        [10040711] = {
          Content = "卡米拉也提到，当调查没有头绪的时候，可以和这边的工人套套近乎。也许我们可以试一试。",
          ContentKR = "카밀라 씨도, 조사하다 뭔가 막힌다 싶으면 여기 인부들이랑 친해져 보라고 했었잖아. 시도해 볼 가치는 있어.",
          DialogueId = 10040711,
          GUID = "1922C826",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100407/1922C826"
        },
        [10040712] = {
          Content = "有道理，我刚刚进入站前穹顶的时候就注意到了，左边有很大一片脚手架，应该是工人在进行什么维修，也许可以去看一看。",
          ContentKR = "그러네, 아까 들어오면서 보니까 왼쪽에 커다랗게 비계를 쳐 놨더라고. 인부들이 거기서 뭔가 수리하고 있는 모양인데, 거기 가 보는 건 어때?",
          DialogueId = 10040712,
          GUID = "1922C850",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100407/1922C850"
        },
        [10040713] = {
          Content = "如果能进入到锻铁厂的话，就应该有办法进入站厅了。",
          ContentKR = "제철소 안으로만 들어가면, 거기서 대합실로 빠지는 샛길이 있을 거야.",
          DialogueId = 10040713,
          GUID = "1922C87A",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100407/1922C87A"
        },
        [10040714] = {
          Content = "哇，没想到你还能记得这么零零碎碎的事情。",
          ContentKR = "우와, 그렇게 세세한 것까지 다 기억하고 있을 줄이야.",
          DialogueId = 10040714,
          GUID = "1922C8A4",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100407/1922C8A4"
        },
        [10040715] = {
          Content = "那当然了，既然我们是来收集情报的，那么我从踏入站厅的那一刻起，就在往脑子里记东西了。好了，走吧，探探去。",
          ContentKR = "당연하잖아. 우린 정보 수집하러 온 거니까. 대합실에 딱 들어온 순간부터, 눈에 보이는 건 싹 다 머릿속에 집어넣고 있었다고. 자, 얼른 가서 살펴보자.",
          DialogueId = 10040715,
          GUID = "1922C8CE",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100407/1922C8CE"
        },
        [10040801] = {
          Content = "您好……这里正在招人。",
          ContentKR = "안녕... 여긴 일할 사람을 구하는 중이야.",
          DialogueId = 10040801,
          GUID = "1922D6EA",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 201005,
            [3] = 201009
          },
          SpeakNpcId = 100407,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D6EA"
        },
        [10040802] = {
          Content = "您好。",
          ContentKR = "안녕하세요.",
          DialogueId = 10040802,
          GUID = "1922D714",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D714"
        },
        [10040803] = {
          Content = "嗯。",
          ContentKR = "어.",
          DialogueId = 10040803,
          GUID = "1922D73E",
          SpeakNpcId = 100407,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D73E"
        },
        [10040804] = {
          Content = "不多介绍一点吗？",
          ContentKR = "소개는 그게 다예요?",
          DialogueId = 10040804,
          GUID = "1922D768",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D768"
        },
        [10040805] = {
          Content = "如果你想要这份工作的话就会主动追问，既然你不问的话，那就只是好奇心旺盛的乘客罢了。",
          ContentKR = "진짜 일할 생각이 있으면, 네가 먼저 꼬치꼬치 캐물었겠지. 가만히 있는 거 보니까, 그냥 궁금한 게 많은 승객일 거고.",
          DialogueId = 10040805,
          GUID = "1922D792",
          SpeakNpcId = 100407,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D792"
        },
        [10040806] = {
          Content = "并且实话说，这份工作也不适合你，你穿着的衣服看起来太整洁，一看就是体面人，所以没必要和你介绍。",
          ContentKR = "솔직히 말해서, 너한테 어울리는 일도 아니야. 옷도 멀끔한 걸 보니까, 딱 봐도 고생 안 해 본 티가 나는데, 굳이 입 아프게 설명해서 뭐 해.",
          DialogueId = 10040806,
          GUID = "1922D7BC",
          SpeakNpcId = 100407,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D7BC"
        },
        [10040807] = {
          Content = "你这么说是带着偏见的，好像不富裕的人就一定脏兮兮的一样。",
          ContentKR = "그건 편견이에요. 형편이 넉넉하지 않으면, 꾀죄죄하게 다녀야 한다는 건가요?",
          DialogueId = 10040807,
          GUID = "1922D7E6",
          ImprPlusId = 1007
        },
        [10040808] = {
          Content = "那我得要说了，你这幅懒懒散散的样子，真的能招到人吗？",
          ContentKR = "에이, 그렇게 게을러 빠진 태도로, 사람을 구할 수나 있겠어요?",
          DialogueId = 10040808,
          GUID = "1922D810",
          ImprPlusId = 1010
        },
        [10040809] = {
          Content = "哪怕出于理性考虑，找工作的时候穿身好衣服也是正常的吧。",
          ContentKR = "상식적으로, 일자리 구하러 올 때 깔끔하게 입고 오는 건 당연한 거잖아요.",
          DialogueId = 10040809,
          GUID = "1922D83A",
          ImprPlusId = 1006
        },
        [10040810] = {
          Content = "行吧， 行吧。你说的是，那么我倒要看看你愿不愿意干这个脏活。",
          ContentKR = "그래, 네 말이 다 맞다고 해줄게. 그럼 네가 이런 궂은일을 하겠다고 할지 한번 보자고.",
          DialogueId = 10040810,
          GUID = "1922D864",
          SpeakNpcId = 100407,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D864"
        },
        [10040811] = {
          Content = "你说什么就是什么，我懒得和你斗嘴。只要我坐在这，总会有人来干活的，有的是人干。",
          ContentKR = "말싸움하기도 귀찮으니까, 네 마음대로 생각해. 내가 여기 가만히 앉아만 있어도, 일하러 오겠단 놈들은 쌔고 쌨으니까.",
          DialogueId = 10040811,
          GUID = "1922D88E",
          SpeakNpcId = 100407,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D88E"
        },
        [10040812] = {
          Content = "也是，也是。能说会道的，希望你是真的来找活干的。",
          ContentKR = "뭐, 틀린 말은 아니지. 말주변은 좋네. 진짜 일하러 온 거면 좋겠군.",
          DialogueId = 10040812,
          GUID = "1922D8B8",
          SpeakNpcId = 100407,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D8B8"
        },
        [10040813] = {
          Content = "既然你和我这么较真，那我还是给你们介绍吧，这里招烟囱清扫工：",
          ContentKR = "아무튼 그렇게까지 나온다면, 대충 설명은 해 줄게. 여기선 굴뚝 청소부를 구하고 있어.",
          DialogueId = 10040813,
          GUID = "1922D8E2",
          SpeakNpcId = 100407,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D8E2"
        },
        [10040814] = {
          Content = "喏，你看我后面就是一个大烟囱，下面连着火车站的附属锻铁厂，制造火车，贮存月髓。",
          ContentKR = "자, 내 뒤로 커다란 굴뚝 보이지? 저 아래에 기차역 부속 제철소가 있어. 저기서 기차도 만들고, 폭시코르도 보관해.",
          DialogueId = 10040814,
          GUID = "1922D90C",
          RelatedWikiId = {
            [1] = 406007
          },
          SpeakNpcId = 100407,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D90C"
        },
        [10040815] = {
          Content = "废气呢，就从这里涌出，不清理的话就会堵塞。",
          ContentKR = "폐가스가 저기로 뿜어져 나오는데, 청소를 안 하면 꽉 막혀 버려.",
          DialogueId = 10040815,
          GUID = "1922D936",
          SpeakNpcId = 100407,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D936"
        },
        [10040816] = {
          Content = "为了避免堵塞而造成生产的延误，影响到我们伟大的帝国铁道运输事业，所以我们需要有人可以钻进烟囱中，沿着内壁清理污垢。",
          ContentKR = "굴뚝이 막혀서 생산이 지연되면, 우리의 위대한 제국 철도 운송 사업 전체에 지장이 간단 말이지. 그래서 저 안에 기어들어 가서 벽에 붙은 때를 싹싹 벗겨낼 사람이 필요한 거야.",
          DialogueId = 10040816,
          GUID = "1922D960",
          SpeakNpcId = 100407,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D960"
        },
        [10040817] = {
          Content = "那么，你对这份工作有兴趣吗？一个月能给你七百个铜币，但如果因为疏忽导致了一次排烟不畅造成投诉那么作为罚金会没收三百铜币……",
          ContentKR = "그래서, 이 일에 관심 있어? 한 달에 700쿠퍼 줄 건데, 대충 일해서 연기가 잘 안 빠진다는 항의라도 들어오면, 벌금으로 네 급여에서 300쿠퍼를 깔 거야...",
          DialogueId = 10040817,
          GUID = "1922D98A",
          SpeakNpcId = 100407,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D98A"
        },
        [10040818] = {
          Content = "很有兴趣！",
          ContentKR = "엄청 관심 있어요!",
          DialogueId = 10040818,
          GUID = "1922D9B4",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D9B4"
        },
        [10040819] = {
          Content = "邪了门了，我说你难道是哪家的{性别：小少爷|小姐}出来体验生活不成？",
          ContentKR = "별일이 다 있네. 설마 세상 물정 체험하러 나온 어느 귀한 집 {性别:도련님이|아가씨}라도 되는 거야?",
          DialogueId = 10040819,
          GUID = "1922D9DE",
          SpeakNpcId = 100407,
          VoiceName = "voice/$Locale$/story/1004/100408/1922D9DE"
        },
        [10040820] = {
          Content = "算了算了，这样吧，你们去那边，先清洁一下车站的幕墙，要是能做好了，我就当你们是真的想做工。",
          ContentKR = "됐어, 됐고. 일단 저기 가서 역 바깥 유리창이나 한번 닦아 봐. 제대로 해내면 진짜 일할 마음이 있다고 믿어 줄게.",
          DialogueId = 10040820,
          GUID = "1922DA08",
          SpeakNpcId = 100407,
          VoiceName = "voice/$Locale$/story/1004/100408/1922DA08"
        },
        [10040821] = {
          Content = "没问题。",
          ContentKR = "알겠어요.",
          DialogueId = 10040821,
          GUID = "1922DA32",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100408/1922DA32"
        },
        [10040822] = {
          Content = "（话说完后，这位不耐烦的中年人职员低下了头，继续看起了手上的书，封面上写着《如何从一个成功走向另一个成功》。）",
          ContentKR = "(말을 마친 중년 직원은 귀찮다는 듯 고개를 푹 숙이고, 다시 손에 든 책을 읽기 시작한다. 표지에는 〈지속 가능한 성공을 향해〉라고 적혀 있다.)",
          DialogueId = 10040822,
          DisableMouth = 1,
          GUID = "1922DA5C",
          VoiceName = "voice/$Locale$/story/1004/100408/1922DA5C"
        },
        [10040901] = {
          Content = "锻铁厂重地，闲杂人等不许靠近！",
          ContentKR = "제철소는 출입 통제 구역입니다. 외부인은 접근하실 수 없습니다!",
          DialogueId = 10040901,
          GUID = "1922E752",
          SpeakNpcId = 100454,
          VoiceName = "voice/$Locale$/story/1004/100409/1922E752"
        },
        [10040902] = {
          Content = "向他出示工卡。",
          ContentKR = "출입 카드를 제시한다.",
          DialogueId = 10040902,
          GUID = "1922E77C"
        },
        [10040903] = {
          Content = "报上监工名字。",
          ContentKR = "현장 감독의 이름을 댄다.",
          DialogueId = 10040903,
          GUID = "1922E7A6"
        },
        [10040904] = {
          Content = "哦，烟囱工啊，去吧去吧。",
          ContentKR = "아, 굴뚝 청소부구나. 들어가, 들어가.",
          DialogueId = 10040904,
          GUID = "1922E7D0",
          SpeakNpcId = 100454,
          VoiceName = "voice/$Locale$/story/1004/100409/1922E7D0"
        },
        [10040905] = {
          Content = "现在年成是真不好啊，连皎皎都得做苦工谋生了……不对，皎皎也不是非要吃东西，为什么要做工……",
          ContentKR = "요즘 경기가 어렵긴 어려운가 보네. 루나까지 이런 막노동을 다 하고... 아니지, 루나는 뭘 안 먹어도 되는 녀석들인데, 굳이 왜 이런 일을...",
          DialogueId = 10040905,
          GUID = "1922E7FA",
          SpeakNpcId = 100454,
          VoiceName = "voice/$Locale$/story/1004/100409/1922E7FA"
        },
        [10040906] = {
          Content = "……",
          ContentKR = "......",
          DialogueId = 10040906,
          GUID = "1922E824",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100409/1922E824"
        },
        [10040907] = {
          Content = "算了，管它呢，皎皎本来就是爱管闲事的。你们过去吧，好好干！",
          ContentKR = "뭐, 아무렴 어때. 루나는 원래 오지랖이 넓은 녀석들이니까. 들어가, 일 제대로 하고!",
          DialogueId = 10040907,
          GUID = "1922E84E",
          SpeakNpcId = 100454,
          VoiceName = "voice/$Locale$/story/1004/100409/1922E84E"
        },
        [10040908] = {
          Content = "呼，吓死我了。",
          ContentKR = "휴, 간 떨어지는 줄 알았네.",
          DialogueId = 10040908,
          GUID = "1922E878",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100409/1922E878"
        },
        [10040909] = {
          Content = "哦，原来是你啊，我刚刚听监工大人说过了，听说你赞助我们的改修工作。还想参观锻铁厂？",
          ContentKR = "아, 후원자님이시군요. 조금 전에 현장 감독관님께 말씀 들었습니다. 보수 공사를 후원해 주셨는데, 제철소를 둘러보고 싶으시다고요?",
          DialogueId = 10040909,
          GUID = "1922E8A2",
          SpeakNpcId = 100454,
          VoiceName = "voice/$Locale$/story/1004/100409/1922E8A2"
        },
        [10040910] = {
          Content = "谢谢你给我们这么费心，这根烟囱往下就是锻铁厂了。不过这边又热又脏，您看，是不是换个地方？",
          ContentKR = "관심을 가져 주셔서 감사합니다. 제철소는 바로 이 굴뚝 아래에 있습니다. 하지만 상당히 덥고 지저분한 곳인데, 다른 곳을 둘러보시는 건 어떻겠습니까?",
          DialogueId = 10040910,
          GUID = "1922E8CC",
          SpeakNpcId = 100454,
          VoiceName = "voice/$Locale$/story/1004/100409/1922E8CC"
        },
        [10040911] = {
          Content = "对了，需要陪同吗？需要的话我找两个活不重的工人一起？",
          ContentKR = "참, 안내해 줄 사람이 필요하십니까? 원하시면 한가한 일꾼 몇 명을 붙여 드리겠습니다.",
          DialogueId = 10040911,
          GUID = "1922E8F6",
          SpeakNpcId = 100454,
          VoiceName = "voice/$Locale$/story/1004/100409/1922E8F6"
        },
        [10040912] = {
          Content = "不用了，就我们几个人就好。",
          ContentKR = "아니에요, 그냥 저희끼리 둘러보면 돼요.",
          DialogueId = 10040912,
          GUID = "1922E920",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100409/1922E920"
        },
        [10040913] = {
          Content = "好好，好，您怎么开心怎么来，把这里当成自己家一样就好。",
          ContentKR = "네, 그럼 편하신 대로 하세요. 집처럼 생각하시고 천천히 둘러보시면 됩니다.",
          DialogueId = 10040913,
          GUID = "1922E94A",
          SpeakNpcId = 100454,
          VoiceName = "voice/$Locale$/story/1004/100409/1922E94A"
        },
        [10041001] = {
          Content = "咳咳……好呛，这里和上面完全不一样。上面的入站穹顶亮堂堂的，怎么这里又热又黑。",
          ContentKR = "콜록콜록... 숨 막혀. 여긴 위쪽이랑 아예 딴판이네. 아트리움 쪽은 환하던데, 여긴 왜 이렇게 덥고 깜깜한 거야.",
          DialogueId = 10041001,
          GUID = "1922F7BA",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100410/1922F7BA"
        },
        [10041002] = {
          Content = "……卡米拉提到过，他们的工作环境和收入都很不好，看起来可能很可能是真的。",
          ContentKR = "...카밀라가 여기 인부들은 작업 환경이랑 보수가 엉망이라고 했었는데, 그 말이 사실이었나 본데.",
          DialogueId = 10041002,
          GUID = "1922F7E4",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100410/1922F7E4"
        },
        [10041003] = {
          Content = "不过我们的目的并不是真的做工和帮人调查，先向前走，想办法进入站厅吧。",
          ContentKR = "어쨌든 우린 진짜로 일하거나, 남 대신 조사해 주러 온 건 아니잖아. 일단 앞으로 쭉 가면서, 대합실로 갈 방법을 생각해 보자.",
          DialogueId = 10041003,
          GUID = "1922F80E",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100410/1922F80E"
        },
        [10041101] = {
          Content = "怎么回事？难道被发现了？不应该啊……",
          ContentKR = "뭐가 어떻게 된 거야? 들킨 건가? 그럴 리 없는데...",
          DialogueId = 10041101,
          GUID = "19230822",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 406007
          },
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100411/19230822"
        },
        [10041102] = {
          Content = "你们没事吧？刚刚我在这里调试工具，发生了一点小意外，所以惊动了这些机器警卫。",
          ContentKR = "괜찮으신가요? 여기서 장치를 조금 손보고 있었는데, 살짝 문제가 생겨서 경비 로봇들이 작동해 버린 모양이에요.",
          DialogueId = 10041102,
          GUID = "1923084C",
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100411/1923084C"
        },
        [10041103] = {
          Content = "啊，你是刚刚的那位……叫做卡诺的老师傅？",
          ContentKR = "아, 조금 전에 뵀던... 카르노라는 베테랑 기술자님이시죠?",
          DialogueId = 10041103,
          GUID = "19230876",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100411/19230876"
        },
        [10041104] = {
          Content = "哦，是你们啊，你们这是要去站厅吗？要是去站厅的话，能不能帮我一个小忙？",
          ContentKR = "아, 아까 그분들이셨군요. 혹시 대합실에 가시는 길인가요? 그렇다면, 제 부탁 하나만 들어주시겠어요?",
          DialogueId = 10041104,
          GUID = "192308A0",
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100411/192308A0"
        },
        [10041105] = {
          Content = "什么忙？",
          ContentKR = "어떤 부탁인데요?",
          DialogueId = 10041105,
          GUID = "192308CA",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100411/192308CA"
        },
        [10041106] = {
          Content = "倒不是什么大事，我一直在这里做技术工。有个叫史蒂芬的儿子，在站厅里做钢架清理工，每天使用钩索在站厅顶的钢架上飞来飞去。",
          ContentKR = "별건 아니고요, 제 아들 스테판이 대합실에서 철골 청소부로 일하고 있거든요. 매일 갈고리를 타고 대합실 천장의 철골들 위를 날아다니고 있죠.",
          DialogueId = 10041106,
          GUID = "192308F4",
          RelatedWikiId = {
            [1] = 406008
          },
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100411/192308F4"
        },
        [10041107] = {
          Content = "他很喜欢火车，每天即便工作完成也还会在天桥上看火车进站出站。",
          ContentKR = "기차를 워낙 좋아하는 애라서, 매일 일이 끝나고도 육교 위에서 기차가 다니는 걸 구경하곤 해요.",
          DialogueId = 10041107,
          GUID = "1923091E",
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100411/1923091E"
        },
        [10041108] = {
          Content = "我一直答应他要攒钱，带他坐一次极光号专列。我攒了好久，算了算，今天发工钱应该终于够了，明天就能出发！",
          ContentKR = "그래서 제가 돈을 모아서 꼭 한 번 오로라호에 태워 주겠다는 약속을 했어요. 모은 지 한참 됐는데, 계산해 보니까, 오늘 급여를 받으면 표를 살 만큼이 돼요! 당장 내일이라도 출발할 수 있는 거죠!",
          DialogueId = 10041108,
          GUID = "19230948",
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100411/19230948"
        },
        [10041109] = {
          Content = "所以如果你见到他的话，能不能告诉他这个好消息，另外让他早点回到家里收拾行李。",
          ContentKR = "제 아들을 보게 되시면, 이 기쁜 소식을 전해 주실 수 있을까요? 참, 짐을 챙겨야 하니까 오늘은 집에 일찍 돌아가라고도 해 주세요.",
          DialogueId = 10041109,
          GUID = "19230972",
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100411/19230972"
        },
        [10041110] = {
          Content = "这种事情应该你亲自告诉他比较合适吧？",
          ContentKR = "그런 건 직접 말씀해 주시는 게 훨씬 좋지 않을까요?",
          DialogueId = 10041110,
          GUID = "1923099C",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100411/1923099C"
        },
        [10041111] = {
          Content = "……没办法，我距离下工还有四个钟头，在那之前都不能离开锻铁厂。要做的事我都写在这张纸条上了，遇见他的话带给他就行。",
          ContentKR = "...그건 어려울 것 같아서요. 퇴근하려면 아직 4시간이나 남았는데, 그전엔 절대 제철소 밖으로 나갈 수가 없거든요. 할 말은 이 종이에 다 적어 뒀으니까, 만나면 꼭 좀 전해 주세요.",
          DialogueId = 10041111,
          GUID = "192309C6",
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100411/192309C6"
        },
        [10041112] = {
          Content = "没遇到就算了。他戴着红色的帽子，圆脸黑头发，右手背有一道做工时烫伤留下的疤痕，很好认。",
          ContentKR = "못 만나시면 어쩔 수 없고요. 까만 머리에 빨간 모자를 쓰고 있을 거예요. 얼굴은 동글동글하고요, 오른쪽 손등에 일하다 덴 흉터가 있어서 찾기 쉬울 거예요.",
          DialogueId = 10041112,
          GUID = "192309F0",
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100411/192309F0"
        },
        [10041113] = {
          Content = "唔……这个也给你们，是清理工常用的钩索，要是在地面找不到史蒂芬的话，也许可能在钢架上。",
          ContentKR = "아... 이것도 챙겨 가세요. 청소부들이 자주 쓰는 갈고리인데, 밑에서 안 보이면, 철골 위를 살펴보시면 될 거예요.",
          DialogueId = 10041113,
          GUID = "19230A1A",
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100411/19230A1A"
        },
        [10041114] = {
          Content = "好的，谢谢你。如果遇见他的话，我会帮你转达的。",
          ContentKR = "네, 감사합니다. 만나게 되면, 제가 꼭 전해 드릴게요.",
          DialogueId = 10041114,
          GUID = "19230A44",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100411/19230A44"
        },
        [10041115] = {
          Content = "好，谢谢你，谢谢你们。",
          ContentKR = "네, 정말 감사합니다.",
          DialogueId = 10041115,
          GUID = "19230A6E",
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100411/19230A6E"
        },
        [10041201] = {
          Content = "等这台升降机打开，就能回到地面了。",
          ContentKR = "이 승강기 문만 열리면, 바로 지상에 올라갈 수 있어.",
          DialogueId = 10041201,
          GUID = "1923188A",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 406007,
            [3] = 406008
          },
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100412/1923188A"
        },
        [10041202] = {
          Content = "地上的老爷们乘车游乐，地下的锻铁工们累死累活。这车站怎么看都是个缩小的冰湖城嘛——",
          ContentKR = "위에선 높으신 분들이 기차 타고 놀러 다니고, 아래에선 인부들이 뼈 빠지게 일하고 있네. 무슨 미니 버전 아이스레이크 시티냐고...",
          DialogueId = 10041202,
          GUID = "192318B4",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100412/192318B4"
        },
        [10041203] = {
          Content = "嘘——",
          ContentKR = "쉿!",
          DialogueId = 10041203,
          GUID = "192318DE",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100412/192318DE"
        },
        [10041204] = {
          Content = "嘘——",
          ContentKR = "쉿!",
          DialogueId = 10041204,
          GUID = "19231908",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100412/19231908"
        },
        [10041205] = {
          Content = "嗯？怎么了？",
          ContentKR = "응? 왜 그래?",
          DialogueId = 10041205,
          GUID = "19231932",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100412/19231932"
        },
        [10041206] = {
          Content = "谁？",
          ContentKR = "응? 누구냐?",
          DialogueId = 10041206,
          GUID = "1923195C",
          SpeakNpcId = 100423,
          VoiceName = "voice/$Locale$/story/1004/100412/1923195C"
        },
        [10041207] = {
          Content = "升降机怎么自己打开了？难道有人怠工？",
          ContentKR = "승강기 문이 왜 저절로 열린 거야? 누가 농땡이라도 피우는 건가?",
          DialogueId = 10041207,
          GUID = "19231986",
          SpeakNpcId = 100423,
          VoiceName = "voice/$Locale$/story/1004/100412/19231986"
        },
        [10041208] = {
          Content = "晚些时候让人检查一下吧，总感觉最近车站里怪事特别多，要是出什么事站长大人肯定会责怪的。",
          ContentKR = "이따 사람을 불러서 점검해 보라고 해야겠군. 요새 역에서 별의별 일이 다 있어서, 무슨 일이라도 터지면 역장님이 가만히 안 두실 테니까.",
          DialogueId = 10041208,
          GUID = "192319B0",
          SpeakNpcId = 100423,
          VoiceName = "voice/$Locale$/story/1004/100412/192319B0"
        },
        [10041301] = {
          Content = "吓死我了，还以为要被发现了。",
          ContentKR = "깜짝이야, 들키는 줄 알았네.",
          DialogueId = 10041301,
          GUID = "192328F2",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100413/192328F2"
        },
        [10041302] = {
          Content = "这车站还真是意料之外的警备森严，进来没法走正道，还要费这么大工夫。",
          ContentKR = "이 기차역, 생각보다 경비가 삼엄하네. 정문으로 못 들어와서 이렇게까지 생고생을 해야 하다니.",
          DialogueId = 10041302,
          GUID = "1923291C",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100413/1923291C"
        },
        [10041303] = {
          Content = "不过刚刚我们要是直接堂堂正正地说“我们是锻铁厂的清洁工！”会不会其实也能蒙混过关？",
          ContentKR = "근데 아까 당당하게 \"우린 제철소에서 일하는 청소부예요!\"라고 우겼으면, 그냥 어물쩍 넘어갈 수 있지 않았을까?",
          DialogueId = 10041303,
          GUID = "19232946",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100413/19232946"
        },
        [10041304] = {
          Content = "我看未必，刚刚她还在自言自语怀疑是不是有人怠工，说明锻铁厂的工人们应该不能随意离开岗位。",
          ContentKR = "글쎄, 그건 아닐걸. 누가 농땡이 피우는 거 아니냐고 중얼거리던 걸 보면, 제철소 인부들은 마음대로 자리를 못 비우는 게 분명해.",
          DialogueId = 10041304,
          GUID = "19232970",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100413/19232970"
        },
        [10041305] = {
          Content = "无论如何，我们现在已经进入了站厅，可以准备调查——呃，我们现在的位置有点高过头了，得沿着钢架找个法子下去。",
          ContentKR = "어쨌든, 이제 대합실에 들어왔으니까 조사를 시작하자. 윽... 그런데 여긴 너무 높잖아. 일단 철골을 타고 내려갈 방법부터 찾아야겠어.",
          DialogueId = 10041305,
          GUID = "1923299A",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100413/1923299A"
        },
        [10041306] = {
          Content = "看到前面那个大表盘了吗？车站的准点报时和钟声都是从那里发出的，我们先向那个方向走。钟表日常需要有人维修，肯定有方法上来下去。",
          ContentKR = "저 앞에 있는 커다란 시계 보이지? 시보랑 종소리는 다 저기서 나는 거니까, 일단 저쪽에 가 보자. 시계는 주기적으로 수리해야 하니까, 오르내리는 길이 분명히 있을 거야.",
          DialogueId = 10041306,
          GUID = "192329C4",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100413/192329C4"
        },
        [10041401] = {
          Content = "呼，终于踏足平地了，虽然很是惊险，但总算平安潜入了。你们都还好吗？",
          ContentKR = "휴, 겨우 내려왔네. 아찔하긴 했지만, 무사히 잠입했어. 다들 다친 데 없지?",
          DialogueId = 10041401,
          GUID = "1923395A",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 406007,
            [3] = 406008
          },
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100414/1923395A"
        },
        [10041402] = {
          Content = "我……我还好……",
          ContentKR = "나... 난 괜찮아...",
          DialogueId = 10041402,
          GUID = "19233984",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100414/19233984"
        },
        [10041403] = {
          Content = "看你腿抖成这样，难道恐高？",
          ContentKR = "다리가 후들거리는데, 혹시 고소공포증 있어?",
          DialogueId = 10041403,
          GUID = "192339AE",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100414/192339AE"
        },
        [10041404] = {
          Content = "才……才没有！就这么点高度，我可一点都不怕！",
          ContentKR = "아, 아니거든! 이 정도 높이는 하나도 안 무서워!",
          DialogueId = 10041404,
          GUID = "192339D8",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100414/192339D8"
        },
        [10041405] = {
          Content = "哎呀，别逞强了，还是稍微休息一会儿吧。{nickname}你呢？",
          ContentKR = "에이, 너무 무리하지 말고 좀 쉬어. {nickname}, 넌 어때?",
          DialogueId = 10041405,
          GUID = "19233A02",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100414/19233A02"
        },
        [10041406] = {
          Content = "在高空上走这么久还挺刺激的，有机会的话想多走一走。",
          ContentKR = "높은 데서 돌아다니니까 스릴 있는데? 시간 날 때 한 번 또 오면 좋겠다.",
          DialogueId = 10041406,
          GUID = "19233A2C",
          ImprPlusId = 1010
        },
        [10041407] = {
          Content = "我还好，毕竟也当了很久的狩月人了。只是在想平时在钢架上维护的工人们每天都这么危险。",
          ContentKR = "난 괜찮아. 하루이틀 월석 사냥꾼 생활을 한 건 아니니까. 근데 철골 위에서 작업하는 사람들은 매일매일 이렇게 위험하게 일하는 거구나.",
          DialogueId = 10041407,
          GUID = "19233A56",
          ImprPlusId = 1009
        },
        [10041408] = {
          Content = "居然还有人想多走几次。要我说啊，这个车站就应该允许人上钢架参观，吸引你这样的人过去，向你们收门票！",
          ContentKR = "이걸 또 하고 싶단 사람도 있네. 차라리 역장한테 철골 위를 유료 관광지로 개방하라고 하면 어때? 스릴 좋아하는 애들한테 입장료 장사를 하는 거지!",
          DialogueId = 10041408,
          GUID = "19233A80",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100414/19233A80"
        },
        [10041409] = {
          Content = "是哦……我看一眼都觉得要晕过去，结果他们每天都得在这边工作。唉，也是不容易。",
          ContentKR = "그러게... 난 아래를 쳐다보기만 해도 머리가 막 어질어질하던데, 저 사람들은 맨날 이런 데서 일해야 하는 거잖아. 에휴, 힘들겠다.",
          DialogueId = 10041409,
          GUID = "19233AAA",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100414/19233AAA"
        },
        [10041410] = {
          Content = "不错，看来你游刃有余啊。",
          ContentKR = "제법인데, 여유가 넘치는걸.",
          DialogueId = 10041410,
          GUID = "19233AD4",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100414/19233AD4"
        },
        [10041411] = {
          Content = "不许动——",
          ContentKR = "동작 그만!",
          DialogueId = 10041411,
          GUID = "19233AFE",
          SpeakNpcId = 100423,
          VoiceName = "voice/$Locale$/story/1004/100414/19233AFE"
        },
        [10041412] = {
          Content = "你们是什么人？刚刚我在站台上可没看见你们，哪儿来的？",
          ContentKR = "너희는 누구냐? 승강장에서 너희를 본 기억은 없는데, 어디서 나타난 거지?",
          DialogueId = 10041412,
          GUID = "19233B28",
          SpeakNpcId = 100423,
          VoiceName = "voice/$Locale$/story/1004/100414/19233B28"
        },
        [10041413] = {
          Content = "……",
          ContentKR = "......",
          DialogueId = 10041413,
          GUID = "19233B52",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100414/19233B52"
        },
        [10041414] = {
          Content = "我们……",
          ContentKR = "저희는...",
          DialogueId = 10041414,
          GUID = "19233B7C",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100414/19233B7C"
        },
        [10041415] = {
          Content = "报……报告长官！我是白衣皎皎，这两位是我的助手！我们是随着列车一起来的医务小队，随时监控列车上的伤员的身体状况。",
          ContentKR = "추, 충성! 의... 의무 소대 의무병 간호사 루나! 얘네 둘은 내 조수야! 탑승한 부상자들의 상태를 체크하려고, 방금 열차로 같이 도착했어.",
          DialogueId = 10041415,
          GUID = "19233BA6",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100414/19233BA6"
        },
        [10041416] = {
          Content = "刚刚在这里清点了复员士兵的人数，可以自行行动者50人，伤员16人！",
          ContentKR = "방금 귀환병들 인원을 파악했는데, 혼자서 움직일 수 있는 병사는 50명이었고, 부상자는 16명이야!",
          DialogueId = 10041416,
          GUID = "19233BD0",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100414/19233BD0"
        },
        [10041417] = {
          Content = "嗯……数目倒是对得上，没事了。最近车站需要执行一则特殊运输任务，所以会对可疑人士严加防备，抱歉了。",
          ContentKR = "음... 숫자는 딱 맞는군, 좋아. 얼마 전에 이 역에 특별 운송 임무가 내려와서, 거동 수상자는 철저히 확인 중이거든. 미안하게 됐어.",
          DialogueId = 10041417,
          GUID = "19233BFA",
          SpeakNpcId = 100423,
          VoiceName = "voice/$Locale$/story/1004/100414/19233BFA"
        },
        [10041418] = {
          Content = "请问……是什么运输任务？",
          ContentKR = "실례지만... 어떤 운송 임무인지 여쭤봐도 될까요?",
          DialogueId = 10041418,
          GUID = "19233C24",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100414/19233C24"
        },
        [10041419] = {
          Content = "我没有被授权向车站卫兵以外的人透露，你也别多打听。白衣皎皎，怎么回事，没有告诉你的助手管好自己，不该问的别问吗？",
          ContentKR = "비인가자에게는 기밀을 누설할 수 없으니까, 더는 캐묻지 마. 간호사 루나, 조수 관리 똑바로 안 해? 선 넘는 참견은 하지 말라고 주의시켰어야지.",
          DialogueId = 10041419,
          GUID = "19233C4E",
          SpeakNpcId = 100423,
          VoiceName = "voice/$Locale$/story/1004/100414/19233C4E"
        },
        [10041420] = {
          Content = "咦？啊……对！说了好多次怎么还没记住，不该问的别问！",
          ContentKR = "어? 아... 맞아! 너네 내 말이 우습냐? 쓸데없는 건 물어보지 말라고 했잖아!",
          DialogueId = 10041420,
          GUID = "19233C78",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100414/19233C78"
        },
        [10041421] = {
          Content = "这才像话！话说回来，我也要向你们表达敬意，感谢你们照顾我们冰湖城出来的弟兄们。",
          ContentKR = "그래, 바로 그거야! 아무튼, 감사 인사는 할게. 우리 아이스레이크 시티 출신 전우들을 보살펴 줘서 고마워.",
          DialogueId = 10041421,
          GUID = "19233CA2",
          SpeakNpcId = 100423,
          VoiceName = "voice/$Locale$/story/1004/100414/19233CA2"
        },
        [10041422] = {
          Content = "我们的站长也教导过我们，需要尊敬医生，尤其是军医，是伤兵的再生父母。",
          ContentKR = "우리 역장님께서, 의사, 특히 군의관은 부상병의 생명의 은인이니까, 항상 존경하는 마음을 가져야 한다고 가르치셨거든.",
          DialogueId = 10041422,
          GUID = "19233CCC",
          SpeakNpcId = 100423,
          VoiceName = "voice/$Locale$/story/1004/100414/19233CCC"
        },
        [10041423] = {
          Content = "没事，这都是我们应该做的。",
          ContentKR = "아니에요, 당연히 해야 할 일인걸요.",
          DialogueId = 10041423,
          GUID = "19233CF6",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100414/19233CF6"
        },
        [10041424] = {
          Content = "嗯，那么你们快点去医务室吧，我去准备迎接下一班列车了。",
          ContentKR = "음, 그럼 어서 의무실로 가 봐. 난 다음 열차를 맞이하러 가야겠어.",
          DialogueId = 10041424,
          GUID = "19233D20",
          SpeakNpcId = 100423,
          VoiceName = "voice/$Locale$/story/1004/100414/19233D20"
        },
        [10041425] = {
          Content = "演技见长啊各位。",
          ContentKR = "다들 연기력이 엄청 늘었네.",
          DialogueId = 10041425,
          GUID = "19233D4A",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100414/19233D4A"
        },
        [10041426] = {
          Content = "尤其是白衣皎皎，值得表扬，还好有你，否则可就惨了。",
          ContentKR = "특히 우리 간호사 루나, 아주 잘했어. 너 아니었으면 우리 진짜 망할 뻔했어.",
          DialogueId = 10041426,
          GUID = "19233D74",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100414/19233D74"
        },
        [10041427] = {
          Content = "哎呀，大惊小怪，白不是一直都在关键时刻出场嘛。",
          ContentKR = "에이, 뭘 이런 걸로~ 스노우는 원래 결정적인 순간에 활약하는 스타일이라고.",
          DialogueId = 10041427,
          GUID = "19233D9E",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100414/19233D9E"
        },
        [10041428] = {
          Content = "你做得好啊，白衣皎皎。",
          ContentKR = "정말 잘했어, 간호사 루나.",
          DialogueId = 10041428,
          GUID = "19233DC8",
          VoiceName = "voice/$Locale$/story/1004/100414/19233DC8"
        },
        [10041429] = {
          Content = "嘿嘿……其实我刚刚确实因为太高了所以害怕，不过为了转移注意力，就开始数士兵和伤员的数目，转移注意力……没想到真派上了用场。",
          ContentKR = "헤헤... 사실 아까 높은 데 있으니까 무서워서, 딴생각이라도 해 보려고 병사들이랑 부상자들 수를 셌던 건데... 그걸 써먹을 기회가 생겨 버렸네.",
          DialogueId = 10041429,
          GUID = "19233DF2",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100414/19233DF2"
        },
        [10041430] = {
          Content = "对了，伤员，趁他们还没走远，我们跟上去，肯定就能知道医务室在哪里。",
          ContentKR = "맞다, 부상자! 아직 멀리 못 갔을 테니까 빨리 따라가자. 그럼 의무실이 어딘지 알아낼 수 있을 거야.",
          DialogueId = 10041430,
          GUID = "19233E1C",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100414/19233E1C"
        },
        [10041501] = {
          Content = "您好，打扰了……",
          ContentKR = "저기, 실례합니다...",
          DialogueId = 10041501,
          GUID = "192349C2",
          RelatedWikiId = {
            [1] = 408022,
