  {
    MinKey = 10044104,
    MaxKey = 10045305,
    Loader = function()
      return {
        [10044104] = {
          Content = "那个总是摆老资历的仓库管理员，施蒂尔出事儿了！今天的爆炸案就是他干的。唉，也能理解。换了谁是他，不会一肚子气？",
          ContentKR = "뻑하면 \"나 때는\"만 읊어대던 그 스틸러가 드디어 사고를 쳤대! 이번 폭발 사건이 그 인간 짓이었다는 거야. 하기야 스틸러 입장에선, 속이 안 뒤틀렸겠어?",
          DialogueId = 10044104,
          GUID = "1924F4D0",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_Npc_Name_EnigmaticGuard",
          VoiceName = "voice/$Locale$/story/1004/100441/1924F4D0"
        },
        [10044105] = {
          Content = "听说他当年是和艾森巴恩站长一起从军团退役，到车站任职的，还是艾森巴恩站长的长官。",
          ContentKR = "아이젠반 역장님이랑 같은 군단 소속이었다가, 퇴역하고 이리로 오게 된 거래. 현역 때는 스틸러 쪽이 오히려 상관이었다더라고.",
          DialogueId = 10044105,
          GUID = "1924F4FA",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_Npc_Name_EnigmaticGuard",
          VoiceName = "voice/$Locale$/story/1004/100441/1924F4FA"
        },
        [10044106] = {
          Content = "但人往高处走水往低处流，艾森巴恩站长步步高升，他却越混越回去，这换了谁能受得了。",
          ContentKR = "그런 인간이 쭉 미끄러져서, 자기 밑에 있던 아이젠반 님은 역장이 되고, 자기는 저 모양 저 꼴이 됐으니 배가 안 아프고 배기겠냐는 거지.",
          DialogueId = 10044106,
          GUID = "1924F524",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_Npc_Name_EnigmaticGuard",
          VoiceName = "voice/$Locale$/story/1004/100441/1924F524"
        },
        [10044107] = {
          Content = "不过这么一说，要是我的话，我心里也会有想法，不过我不会走极端就是啦。不像他，也没个妻小的，一旦想不开只会越来越想不开。",
          ContentKR = "입장 바꿔서 나였어도, 그런 기분이 들긴 했겠지. 그렇지만 난 그 인간이랑 다르게 딸린 식구가 있어서, 그런 극단적인 짓을 저질러야겠단 생각까진 안 해.",
          DialogueId = 10044107,
          GUID = "1924F54E",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_Npc_Name_EnigmaticGuard",
          VoiceName = "voice/$Locale$/story/1004/100441/1924F54E"
        },
        [10044108] = {
          Content = "人还是要有家庭的支持啊，女儿的笑容就是我每天工作的最大动力，要看看她的相片吗？",
          ContentKR = "그래서 사람은 가족이 있어야 하는 거야. 우리 딸 웃는 얼굴만 보면 매일 힘이 나거든. 어때, 사진 좀 보여 줄까?",
          DialogueId = 10044108,
          GUID = "1924F578",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_Npc_Name_EnigmaticGuard",
          VoiceName = "voice/$Locale$/story/1004/100441/1924F578"
        },
        [10044109] = {
          Content = "呃……这倒不用，总之谢谢你。",
          ContentKR = "음... 본 걸로 할게요. 어쨌든, 감사해요.",
          DialogueId = 10044109,
          GUID = "1924F5A2",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100441/1924F5A2"
        },
        [10044110] = {
          Content = "喂，你不是还有话要说吗？不说啦？",
          ContentKR = "참, 아까 무슨 얘기 하려고 했더라? 안 해도 돼?",
          DialogueId = 10044110,
          GUID = "1924F5CC",
          SpeakNpcId = 100421,
          SpeakNpcName = "UI_Npc_Name_EnigmaticGuard",
          VoiceName = "voice/$Locale$/story/1004/100441/1924F5CC"
        },
        [10044201] = {
          Content = "你好，你觉得施蒂尔这个人怎么样？",
          ContentKR = "안녕하세요, 스틸러 씨는 평소에 어떤 분이셨나요?",
          DialogueId = 10044201,
          GUID = "192504BA",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100442/192504BA"
        },
        [10044202] = {
          Content = "嗯……品味蛮差的，酒品也差。",
          ContentKR = "음... 인간성은 별로고, 술버릇은 더 가관이야.",
          DialogueId = 10044202,
          GUID = "192504E4",
          SpeakNpcId = 100443,
          SpeakNpcName = "UI_Npc_Name_DrunkedWorker",
          VoiceName = "voice/$Locale$/story/1004/100442/192504E4"
        },
        [10044203] = {
          Content = "说来有些不好意思，我这人没什么其他爱好，就喜欢每天下工后来上一口，就喜欢那种轻飘飘的感觉。",
          ContentKR = "솔직히 자랑은 아닌데, 난 다른 취미는 없고, 매일 퇴근하고 나서 알딸딸하게 술 한잔 걸치는 게 삶의 낙이거든.",
          DialogueId = 10044203,
          GUID = "1925050E",
          SpeakNpcId = 100443,
          SpeakNpcName = "UI_Npc_Name_DrunkedWorker",
          VoiceName = "voice/$Locale$/story/1004/100442/1925050E"
        },
        [10044204] = {
          Content = "所以在车站里工作里的好酒之人，我都或多或少有点联系，时不时三五成群去喝酒，大家心照不宣轮流做东。",
          ContentKR = "그래서 이 역에서 술 좀 마신다는 녀석들은 대충 다 꿰고 있어. 가끔 여럿이 모여서 마시면, 술값도 돌아가면서 내곤 해.",
          DialogueId = 10044204,
          GUID = "19250538",
          SpeakNpcId = 100443,
          SpeakNpcName = "UI_Npc_Name_DrunkedWorker",
          VoiceName = "voice/$Locale$/story/1004/100442/19250538"
        },
        [10044205] = {
          Content = "唯独这个施蒂尔就从来没做过东，一毛不拔。喝酒嘛又总是只抱着他在军团喝习惯了的“军团狼血”，那玩意儿和医用酒精没多大区别。",
          ContentKR = "스틸러 그 인간만 빼고 말이야. 그 인간은 지갑을 연 적이 없어. 술도 매번 '군단용 울프 블러드'만 달고 사는데, 그건 술이 아니라 거의 소독약 수준이고.",
          DialogueId = 10044205,
          GUID = "19250562",
          SpeakNpcId = 100443,
          SpeakNpcName = "UI_Npc_Name_DrunkedWorker",
          VoiceName = "voice/$Locale$/story/1004/100442/19250562"
        },
        [10044206] = {
          Content = "他一喝多，就又总喜欢说他在军团时候如何如何精明利落，现在这些活对他来说轻轻松松，大材小用。",
          ContentKR = "그리고 술만 좀 들어갔다 하면, 자기가 군단에 있었을 때는 어쩌고저쩌고 하면서, 창고 일은 자기 급에 안 맞는다면서 투덜거린다니까.",
          DialogueId = 10044206,
          GUID = "1925058C",
          SpeakNpcId = 100443,
          SpeakNpcName = "UI_Npc_Name_DrunkedWorker",
          VoiceName = "voice/$Locale$/story/1004/100442/1925058C"
        },
        [10044207] = {
          Content = "然后就开始嫌弃这嫌弃那的，什么没有危机意识，什么帝国上下就是个草台班子，烂透了。",
          ContentKR = "그러곤 다들 위기의식이 없다느니, 제국은 위나 아래나 싹 다 구멍가게 수준이라느니 하면서 온갖 불평을 쏟아내는 거야.",
          DialogueId = 10044207,
          GUID = "192505B6",
          SpeakNpcId = 100443,
          SpeakNpcName = "UI_Npc_Name_DrunkedWorker",
          VoiceName = "voice/$Locale$/story/1004/100442/192505B6"
        },
        [10044208] = {
          Content = "说实话，大家本来就是被生活压得喘不过气来才想喝喝酒，谁爱听他说这说那的。",
          ContentKR = "솔직히, 다들 먹고살기 팍팍하니까, 술이나 한잔하면서 기분이나 풀려는 건데, 누가 그런 소리를 듣고 싶겠어.",
          DialogueId = 10044208,
          GUID = "192505E0",
          SpeakNpcId = 100443,
          SpeakNpcName = "UI_Npc_Name_DrunkedWorker",
          VoiceName = "voice/$Locale$/story/1004/100442/192505E0"
        },
        [10044209] = {
          Content = "总之，我不喜欢他。但没想到他居然真的把对帝国的不满付诸行动了，说明他还有点军人的血性，倒让我高看了他两眼。",
          ContentKR = "어쨌든, 난 그 인간 싫어. 그런데 제국에 불만이 있다고, 그걸 행동으로 옮겨 버린 걸 보면, 아직 군인 기질이 죽진 않았나 봐. 의외로 사람 다시 봤어.",
          DialogueId = 10044209,
          GUID = "1925060A",
          SpeakNpcId = 100443,
          SpeakNpcName = "UI_Npc_Name_DrunkedWorker",
          VoiceName = "voice/$Locale$/story/1004/100442/1925060A"
        },
        [10044210] = {
          Content = "好的。",
          ContentKR = "얘기 잘 들었어요.",
          DialogueId = 10044210,
          GUID = "19250634",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100442/19250634"
        },
        [10044301] = {
          Content = "哦，是你们，我这边刚刚统计完关于施蒂尔的意见。",
          ContentKR = "아, 너희였나. 마침 스틸러 건으로 들어온 정보 취합이 끝났다.",
          DialogueId = 10044301,
          GUID = "19251522",
          NextDialogue = 10044302,
          RelatedWikiId = {
            [1] = 408022,
            [2] = 101004,
            [3] = 201030,
            [4] = 201031,
            [5] = 403012
          },
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100443/19251522"
        },
        [10044302] = {
          Content = "结果怎么样？他刚刚说自己实际上人缘不错，但我猜……应该不是这样。",
          ContentKR = "좀 어떤가요? 스틸러 씨는 본인 인간관계가 상당히 좋다고 하셨는데... 그건 아닌 것 같아서요.",
          DialogueId = 10044302,
          GUID = "1925154C",
          NextDialogue = 10044303,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100443/1925154C"
        },
        [10044303] = {
          Content = "嗯，结果非常惨烈，清一色的坏话，几乎没有人为他辩解。",
          ContentKR = "음, 매우 처참하더군. 두둔하는 사람은 거의 없는 수준에 가까웠어.",
          DialogueId = 10044303,
          GUID = "19251576",
          NextDialogue = 10044304,
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100443/19251576"
        },
        [10044304] = {
          Content = "虽然我对他不讨人喜欢这件事是有预期的，但是招人厌到这种程度还是有点出乎意料了。",
          ContentKR = "호감을 살 만한 인물이 아니라는 건 알고 있었지만, 이 정도로 미움을 샀을 줄은 나도 예상하지 못했다.",
          DialogueId = 10044304,
          GUID = "192515A0",
          NextDialogue = 10044305,
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100443/192515A0"
        },
        [10044305] = {
          Content = "啧。",
          ContentKR = "쯧.",
          DialogueId = 10044305,
          GUID = "192515CA",
          NextDialogue = 10044306,
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100443/192515CA"
        },
        [10044306] = {
          Content = "唔……这样一来的话，就没办法用我们之前的那个，看谁说凶巴巴管理员坏话，谁就有嫌疑的方法了。",
          ContentKR = "으음... 이러면 창고 관리자가 나쁜 사람이라고 말하는 사람을 찾아서, 용의자 범위를 줄이는 방법은 못 쓰겠네.",
          DialogueId = 10044306,
          GUID = "192515F4",
          NextDialogue = 10044307,
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100443/192515F4"
        },
        [10044307] = {
          Content = "等等，站长你是说“几乎没有人为他辩解”，那就是还有人给他说好话的意思？",
          ContentKR = "잠깐만요, 방금 '두둔하는 사람은 거의 없었다'고 하셨죠? 그럼 좋게 말해 준 사람이 아예 없진 않았다는 거네요?",
          DialogueId = 10044307,
          GUID = "1925161E",
          NextDialogue = 10044308,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100443/1925161E"
        },
        [10044308] = {
          Content = "嗯，是有一封匿名信为他说好话，你们看看？",
          ContentKR = "그래, 익명으로 투서가 하나 들어왔다. 읽어 보겠나?",
          DialogueId = 10044308,
          GUID = "19251648",
          NextDialogue = 10044309,
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100443/19251648"
        },
        [10044309] = {
          Content = "匿名信？",
          ContentKR = "익명의 투서요?",
          DialogueId = 10044309,
          GUID = "19251672",
          NextDialogue = 10044310,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100443/19251672"
        },
        [10044310] = {
          Content = "\"尊敬的艾森巴恩站长：",
          ContentKR = "존경하는 아이젠반 역장님께,",
          DialogueId = 10044310,
          GUID = "19251673",
          NextDialogue = 10044311
        },
        [10044311] = {
          Content = "虽然仓库管理员施蒂尔工作对人态度恶劣，但是他本职工作一直做得非常认真。职员们出入仓库时也会一一询问。",
          ContentKR = "창고 관리자 스틸러 씨는 업무 태도는 좋지 않아도, 늘 업무에 성실히 임하셨습니다. 직원들이 창고에 드나들 때도 항상 꼼꼼히 확인하셨습니다.",
          DialogueId = 10044311,
          GUID = "19251674",
          NextDialogue = 10044312
        },
        [10044312] = {
          Content = "虽然他的态度可能不是很好，但他熟悉车站的每一个岗位，热爱铁路事业。",
          ContentKR = "좀 퉁명스러울지는 몰라도, 기차역에 대해서는 누구보다도 잘 알고, 철도 사업을 향한 애정을 갖고 계시죠.",
          DialogueId = 10044312,
          GUID = "19251675",
          NextDialogue = 10044313
        },
        [10044313] = {
          Content = "我相信这样的人不会里通神弃者同盟，还大费周章组装起炸弹，去毁坏自己热爱的这一切。\"",
          ContentKR = "그런 분께서 자신의 모든 것이나 다름없는 역을 부수기 위해, 포세이큰 동맹과 내통하여 일부러 폭탄을 조립했을 리가 없습니다.",
          DialogueId = 10044313,
          GUID = "19251676",
          NextDialogue = 10044314
        },
        [10044314] = {
          Content = "从内容上来看的话，想必他也被施蒂尔询问过，所以才会知道他工作认真，于是对施蒂尔抱有良好印象。",
          ContentKR = "내용을 보니, 이 투서를 쓴 자도 스틸러에게 한 소리 들었나 보군. 그래도 스틸러가 성실히 일하는 점에 좋은 인상을 받았나 봐.",
          DialogueId = 10044314,
          GUID = "19251744",
          NextDialogue = 10044315,
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100443/19251744"
        },
        [10044315] = {
          Content = "看起来确实也没法作为线索……",
          ContentKR = "딱히 단서가 될 만한 내용은 없는 것 같기도...",
          DialogueId = 10044315,
          GUID = "1925176E",
          NextDialogue = 10044316,
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100443/1925176E"
        },
        [10044316] = {
          Content = "不对，这封信有问题……上面有一段内容我们并没有和车站职员提到过。{nickname}，你也觉得不对吧。",
          ContentKR = "아니에요, 이 편지엔... 직원들에게 알리지 않았던 사실이 하나 적혀 있어요! {nickname} 씨, 눈치채셨나요?",
          DialogueId = 10044316,
          GUID = "19251798",
          NextDialogue = 10044317,
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100443/19251798"
        },
        [10044317] = {
          Content = "（指出有问题的内容：）",
          ContentKR = "(문제가 되는 부분을 선택한다.)",
          DialogueId = 10044317,
          DisableMouth = 1,
          GUID = "192517C2",
          NextOptions = {
            [1] = 10044318,
            [2] = 10044319,
            [3] = 10044320
          },
          VoiceName = "voice/$Locale$/story/1004/100443/192517C2"
        },
        [10044318] = {
          Content = "施蒂尔的身份。",
          ContentKR = "스틸러의 직무",
          DialogueId = 10044318,
          GUID = "192517EC",
          NextDialogue = 10044321
        },
        [10044319] = {
          Content = "施蒂尔的工作态度。",
          ContentKR = "스틸러 씨의 업무 태도",
          DialogueId = 10044319,
          GUID = "19251816",
          NextDialogue = 10044322
        },
        [10044320] = {
          Content = "犯罪者的手法。",
          ContentKR = "범행을 저지른 수법",
          DialogueId = 10044320,
          GUID = "19251840",
          NextDialogue = 10044323
        },
        [10044321] = {
          Content = "这封信里提到施蒂尔的身份是仓库的管理员，没什么问题。问题是，写这封信的人是怎么知道炸弹是组装的？",
          ContentKR = "편지에서 스틸러 씨를 창고 관리자라고 부른 건 이상할 게 없죠. 문제는, 이 사람은 폭탄이 조립됐단 사실을 어떻게 아는 걸까요?",
          DialogueId = 10044321,
          GUID = "1925186A",
          NextDialogue = 10044324,
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100443/1925186A"
        },
        [10044322] = {
          Content = "施蒂尔虽然待人接物不太好，但是他确实有好好记录所有入库的内容，这一点倒是问题不大。只是……写这封信的人是怎么知道炸弹是组装的？",
          ContentKR = "스틸러 씨가 좀 퉁명스러운 건 맞지만, 창고에 드나드는 사람을 꼼꼼히 기록해 둔 건 사실이고, 별달리 문제 될 부분도 없어요. 하지만... 이 사람은 폭탄이 조립됐단 사실을 어떻게 아는 걸까요?",
          DialogueId = 10044322,
          GUID = "19251894",
          NextDialogue = 10044324,
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100443/19251894"
        },
        [10044323] = {
          Content = "没错。知道炸弹是在仓库组装的人是极少数，写下这封信的人根本不应该知道这种事情。",
          ContentKR = "맞아요. 폭탄이 창고 안에서 조립됐다는 건 극소수만 아는 사실이죠. 이 편지를 쓴 사람도 그 부분은 몰랐어야 해요.",
          DialogueId = 10044323,
          GUID = "192518BE",
          NextDialogue = 10044324,
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100443/192518BE"
        },
        [10044324] = {
          Content = "但是它是和其他意见书混在一起被收上来的，我们无法断定这封信的作者。",
          ContentKR = "그렇지만 투서들이 한꺼번에 섞여 들어와서, 발신자를 특정할 방법은 없어.",
          DialogueId = 10044324,
          GUID = "192518E8",
          NextDialogue = 10044325,
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100443/192518E8"
        },
        [10044325] = {
          Content = "唉，奥特赛德……可怜的奥特赛德……",
          ContentKR = "히잉, 아웃사이더... 불쌍해서 어떡해...",
          DialogueId = 10044325,
          GUID = "19251912",
          NextDialogue = 10044326,
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100443/19251912"
        },
        [10044326] = {
          Content = "我还没对你朋友怎么样，不至于哭成这样。",
          ContentKR = "아직 네 친구에겐 아무 짓도 하지 않았다. 그만 징징대라.",
          DialogueId = 10044326,
          GUID = "1925193C",
          NextDialogue = 10044327,
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100443/1925193C"
        },
        [10044327] = {
          Content = "总感觉这封信上面的字迹有点熟悉，像是在哪儿见过……",
          ContentKR = "아무래도 어디선가 이런 글씨체를 본 느낌이 드는데...",
          DialogueId = 10044327,
          GUID = "19251966",
          NextDialogue = 10044328,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100443/19251966"
        },
        [10044328] = {
          Content = "啊……是史蒂芬……",
          ContentKR = "그래... 스테판...",
          DialogueId = 10044328,
          GUID = "19251990",
          NextDialogue = 10044329,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100443/19251990"
        },
        [10044329] = {
          Content = "史蒂芬？那是谁？听起来有些耳熟……",
          ContentKR = "스테판? 그게 누구지? 어디선가 들어 본 것 같다만...",
          DialogueId = 10044329,
          GUID = "192519BA",
          NextDialogue = 10044330,
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100443/192519BA"
        },
        [10044330] = {
          Content = "是我在站厅里遇见的钢架清洁工，我曾经受他父亲卡诺所托，带一张字条给他。",
          ContentKR = "대합실에서 만난 철골 청소하는 아이예요. 걔 아버지 카르노 씨 부탁으로 쪽지를 전해 줬었어요.",
          DialogueId = 10044330,
          GUID = "192519E4",
          NextDialogue = 10044331,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100443/192519E4"
        },
        [10044331] = {
          Content = "来人，让下层工厂的负责人把卡诺叫过来。",
          ContentKR = "경비병, 지하층 제철소 책임자 카르노를 불러와.",
          DialogueId = 10044331,
          GUID = "19251A0E",
          NextDialogue = 10044332,
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100443/19251A0E"
        },
        [10044332] = {
          Content = "站长大人，卡诺说是明天准备和儿子一起搭乘极光号去迪斯玛尼亚度假，打算今天提前准备一下，已经请假回家了。",
          ContentKR = "역장님, 카르노는 내일 아들과 함께 오로라호를 타고 디즈마니아로 휴가를 떠난다며, 오늘 반차를 내고 이미 귀가한 상태입니다.",
          DialogueId = 10044332,
          GUID = "19251A38",
          NextDialogue = 10044333,
          SpeakNpcId = 100421,
          VoiceName = "voice/$Locale$/story/1004/100443/19251A38"
        },
        [10044333] = {
          Content = "去迪斯玛尼亚，度假？极光号？我们的锻铁工什么时候工钱这么高了？他大概率从其他地方搞到了一笔钱。",
          ContentKR = "디즈마니아에서 휴가를 보내? 오로라호를 타고? 언제부터 제철소 인부 월급이 그렇게 두둑했지? 어디선가 뒷돈을 챙겼다는 소리군.",
          DialogueId = 10044333,
          GUID = "19251A62",
          NextDialogue = 10044334,
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100443/19251A62"
        },
        [10044334] = {
          Content = "你们立刻去找到卡诺，把他带回来。他就住在站台尽头的员工住宅区。",
          ContentKR = "지금 당장 카르노를 찾아내서 이리로 데려와. 녀석은 승강장 끝에 있는 직원 숙소 구역에 살고 있다.",
          DialogueId = 10044334,
          GUID = "19251A8C",
          NextDialogue = 10044335,
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100443/19251A8C"
        },
        [10044335] = {
          Content = "没问题。",
          ContentKR = "네.",
          DialogueId = 10044335,
          GUID = "19251AB6",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100443/19251AB6"
        },
        [10044336] = {
          Content = "没错。知道炸弹是在仓库组装的人是极少数，写下这封信的人根本不应该知道这种事情。",
          ContentKR = "맞아요. 폭탄이 창고 안에서 조립됐다는 건 극소수만 아는 사실이죠. 이 편지를 쓴 사람도 그 부분은 몰랐어야 해요.",
          DialogueId = 10044336,
          GUID = "19251AE0",
          VoiceName = "voice/$Locale$/story/1004/100443/19251AE0"
        },
        [10044401] = {
          Content = "啊，是你们……我记得我们分开过后不久车站就发生了爆炸，还担心你们受伤。没事就好。",
          ContentKR = "아, 또 만났네요... 우리 그때 헤어지고 나서 기차역에 폭발이 일어나서, 혹시 다쳤을까 봐 걱정했는데, 괜찮아 보여서 다행이에요.",
          DialogueId = 10044401,
          GUID = "1925258A",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 101004,
            [3] = 201030,
            [4] = 201031,
            [5] = 403012
          },
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/1925258A"
        },
        [10044402] = {
          Content = "不过，我记得当时和我说话的除了{性别：大哥哥|大姐姐}，皎皎以外，还有一个大哥哥，他去了哪里哇？",
          ContentKR = "근데, 그때 {性别:형이랑|누나랑} 루나 말고, 한 명 더 있었는데, 그 형은 어디 갔어요?",
          DialogueId = 10044402,
          GUID = "192525B4",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/192525B4"
        },
        [10044403] = {
          Content = "他有一点事，先回去了。",
          ContentKR = "일이 좀 생겨서, 먼저 돌아갔어.",
          DialogueId = 10044403,
          GUID = "192525DE",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100444/192525DE"
        },
        [10044404] = {
          Content = "这样……",
          ContentKR = "그렇구나...",
          DialogueId = 10044404,
          GUID = "19252608",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/19252608"
        },
        [10044405] = {
          Content = "史蒂芬，我们是以艾森巴恩站长的名义来调查一些事情……你能告诉我……",
          ContentKR = "스테판, 우리 지금 아이젠반 역장님 부탁으로 알아볼 일이 있어서 온 건데... 혹시...",
          DialogueId = 10044405,
          GUID = "19252632",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100444/19252632"
        },
        [10044406] = {
          Content = "你们，是想要找我爸吧，怀疑他帮助神弃者同盟。",
          ContentKR = "알아요, 우리 아빠 찾으러 온 거죠? 아빠가 포세이큰 동맹을 도와준 거라고 의심해서요.",
          DialogueId = 10044406,
          GUID = "1925265C",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/1925265C"
        },
        [10044407] = {
          Content = "他就在前面，刚刚有个男人找他，说要和他聊一些事情，让我在这里应付一下其他人。",
          ContentKR = "아빠는 이 앞에 계세요. 아까 어떤 남자가 아빠랑 할 얘기가 있다면서, 저한테 여기서 망보고 있으라고 했거든요.",
          DialogueId = 10044407,
          GUID = "19252686",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/19252686"
        },
        [10044408] = {
          Content = "……？！",
          ContentKR = "......?!",
          DialogueId = 10044408,
          GUID = "192526B0",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100444/192526B0"
        },
        [10044409] = {
          Content = "那你为什么这么直接告诉了我们……",
          ContentKR = "그런데 왜 그걸 우리한테 바로 말해 주는 거야?",
          DialogueId = 10044409,
          GUID = "192526DA",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100444/192526DA"
        },
        [10044410] = {
          Content = "当你们找到这里的时候，我就明白，我爸肯定已经被盯上了。",
          ContentKR = "여기까지 찾아온 걸 보고, 아빠가 벌써 들켰다는 걸 알아 버렸거든요.",
          DialogueId = 10044410,
          GUID = "19252704",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/19252704"
        },
        [10044411] = {
          Content = "虽然我年纪不大，但也在车站工作很久。每天都是差不多，早上在太阳升起之前开始做工，月亮落下后再回到这里。",
          ContentKR = "전 어리지만, 이 기차역에서 일을 꽤 오래 했어요. 거의 매일 아침 해가 뜨자마자 일을 시작해서, 달이 뉘엇뉘엇해질 때 여기로 돌아와요.",
          DialogueId = 10044411,
          GUID = "1925272E",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/1925272E"
        },
        [10044412] = {
          Content = "每天赚到的钱，想买一张去皇都的车票，掰掰手指头能算出来。每天吃黑面包的话需要一整年，如果换成白面包，需要两年。",
          ContentKR = "매일 버는 돈으로, 황성에 가는 기차표를 사려면 얼마나 걸릴진 대충 계산해 봐도 알아요. 검은 빵만 먹으면 1년을 꼬박 모아야 하고, 흰 빵을 먹으면 2년이 걸리죠.",
          DialogueId = 10044412,
          GUID = "19252758",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/19252758"
        },
        [10044413] = {
          Content = "听到他准备好车票的消息的时候，我一开始是很开心的，我知道他肯定用了什么手段，但不管是赌钱还是变卖了什么遗物，我都不太想多问。",
          ContentKR = "처음에 아빠가 기차표를 구해왔다고 했을 땐 진짜 신났어요. 그 큰돈이 어디서 났을진 모르지만, 돈내기를 했든 아니면 집에 있는 비싼 걸 팔았든, 굳이 묻고 싶지 않았어요.",
          DialogueId = 10044413,
          GUID = "19252782",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/19252782"
        },
        [10044414] = {
          Content = "毕竟这是去迪斯玛尼亚的车票啊：远方，一个聚合了梦想、等待与不确定的词汇……",
          ContentKR = "왜냐하면 그 표가 있으면 디즈마니아에 갈 수 있으니까요! 멀고, 꿈같고, 기대로 가득한 미지의 세계 말이에요...",
          DialogueId = 10044414,
          GUID = "192527AC",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/192527AC"
        },
        [10044415] = {
          Content = "但听到神弃者同盟的广播后，我……多少猜到了车票怎么来的。",
          ContentKR = "근데 포세이큰 동맹이 한 방송을 듣자마자... 아빠가 어떻게 표를 구했는지 대충 눈치챘어요.",
          DialogueId = 10044415,
          GUID = "192527D6",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/192527D6"
        },
        [10044416] = {
          Content = "自从那个男人第一次找到爸爸之后，他就一直不对劲。过了几天，他就在没人的街角研究怎么让棉花爆炸。但我问起来，他只说，想试着做个烟花玩……",
          ContentKR = "어떤 남자가 아빠를 찾아왔었는데, 그때부터 아빠가 좀 이상해지셨어요. 그리고 며칠 뒤부터 사람이 별로 없는 구석에 가셔서 솜으로 폭발 실험을 하시더라고요. 이유를 물어보면, 그냥 불꽃놀이에 쓸 거라고 하셨고...",
          DialogueId = 10044416,
          GUID = "19252800",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/19252800"
        },
        [10044417] = {
          Content = "神弃者同盟确实会用“烟花”代指炸弹，品位倒还不错。",
          ContentKR = "포세이큰 동맹은 폭탄을 '폭죽'이라고 부르던데, 센스가 나쁘진 않네.",
          DialogueId = 10044417,
          GUID = "1925282A",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100444/1925282A"
        },
        [10044418] = {
          Content = "我现在一点也不期待明天，相反，我很怕，真的很怕……听说神弃者同盟是一群很凶恶的家伙，我怕他们真的像他们说的那样，逼爸爸炸毁车站。",
          ContentKR = "전 이제 내일이 오는 게 하나도 안 기다려지고, 오히려 너무너무 무서워요... 포세이큰 동맹은 엄청 나쁜 사람들이라던데, 방송에서 말한 것처럼 우리 아빠한테 역을 뻥 터뜨려 버리라 그러면 어떡해요.",
          DialogueId = 10044418,
          GUID = "19252854",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/19252854"
        },
        [10044419] = {
          Content = "虽然车站的叔叔们有的也凶巴巴的，乘客们也不是所有都友善……但他们中也有很多很好很好的人，我真的不希望他们死掉！",
          ContentKR = "역에 있는 아저씨들 중엔 무서운 사람도 있고, 승객들도 다 착한 건 아니지만... 그래도 진짜 좋은 사람들도 많단 말이에요. 그 사람들이 다 죽어 버리는 건 싫어요!",
          DialogueId = 10044419,
          GUID = "1925287E",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/1925287E"
        },
        [10044420] = {
          Content = "更重要的是，爸爸又被那个男人带走了，如果真的被逼着炸掉车站，爸爸就真的活不成了！所以，如果你们是来调查的，求求你们、求求你们救救他！",
          ContentKR = "그리고 저번에 그 남자가 우리 아빠를 또 데려갔어요. 억지로 역을 터뜨리라고 시키면, 우리 아빠 진짜 큰일 나요! 그러니까, 조사하러 오신 거면, 제발, 제발 우리 아빠를 구해 주세요!",
          DialogueId = 10044420,
          GUID = "192528A8",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/192528A8"
        },
        [10044421] = {
          Content = "别哭，史蒂芬。别怕，别怕。",
          ContentKR = "울지 마, 스테판. 무서워하지 않아도 돼.",
          DialogueId = 10044421,
          GUID = "192528D2",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100444/192528D2"
        },
        [10044422] = {
          Content = "我会找到你爸爸，不让那个坏人伤害到他。另外你放心，他在布设炸弹的时候似乎特意避免了伤及普通人，没有人受伤。",
          ContentKR = "너희 아빠를 꼭 찾아서, 나쁜 사람이 괴롭히지 못하게 해 줄게. 그리고 너무 걱정 안 해도 돼. 너희 아빠가 폭탄을 설치하실 때, 아무도 안 다치게 하려고 신경을 많이 쓰셨었거든.",
          DialogueId = 10044422,
          GUID = "192528FC",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100444/192528FC"
        },
        [10044423] = {
          Content = "所以……别哭，等我把爸爸带回来，好吗？",
          ContentKR = "그러니까... 울지 말고, 여기서 아빠 모시고 올 때까지 얌전히 기다리는 거야? 알았지?",
          DialogueId = 10044423,
          GUID = "19252926",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100444/19252926"
        },
        [10044424] = {
          Content = "太好了……那，你们去吧，顺着这条路一直往前走就好。",
          ContentKR = "네... 그럼 알겠어요. 이 길 따라 쭉 앞으로만 가면 돼요.",
          DialogueId = 10044424,
          GUID = "19252950",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100444/19252950"
        },
        [10044425] = {
          Content = "好，谢谢你。",
          ContentKR = "응, 고마워.",
          DialogueId = 10044425,
          GUID = "1925297A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100444/1925297A"
        },
        [10044501] = {
          Content = "谢谢你……谢谢，这两张车票，真要我自己慢慢攒，我不知道要攒多久才行。",
          ContentKR = "감사합니다... 정말 감사해요. 저 혼자 돈을 모았으면, 표 두 장을 마련하려고 시간이 얼마나 걸렸을지...",
          DialogueId = 10044501,
          GUID = "192535F2",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 101004,
            [3] = 201030,
            [4] = 201031,
            [5] = 403012
          },
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100445/192535F2"
        },
        [10044502] = {
          Content = "不，卡诺，你似乎有一些误会，我到这里来，并不是为了把车票交给你。",
          ContentKR = "이봐, 카르노, 단단히 착각했나 본데, 난 너한테 표를 주려고 여기 온 게 아니야.",
          DialogueId = 10044502,
          GUID = "1925361C",
          SpeakNpcId = 100444,
          VoiceName = "voice/$Locale$/story/1004/100445/1925361C"
        },
        [10044503] = {
          Content = "你……之前我们不是谈好条件了吗？哈洛吉？你想要违背约定？",
          ContentKR = "무슨 소리를... 그게 조건이었잖아요? 하로기 씨? 약속을 어기시겠다는 건가요?",
          DialogueId = 10044503,
          GUID = "19253646",
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100445/19253646"
        },
        [10044504] = {
          Content = "车票我带来了。很可惜，是你违背约定在先。我当初的要求是尽可能的把事情闹大，闹大！我要看见炸弹把高墙炸毁，把人炸飞。",
          ContentKR = "표는 가져왔어. 애석하게도 네가 약속을 깬 거지. 내가 처음에 건 조건은 최대한 일을 크게 벌이라는 거였잖아! 크게! 벽을 다 부숴 버리고, 사람들을 죄다 날려 버렸어야지!",
          DialogueId = 10044504,
          GUID = "19253670",
          SpeakNpcId = 100444,
          VoiceName = "voice/$Locale$/story/1004/100445/19253670"
        },
        [10044505] = {
          Content = "而你干了什么？把那些炸弹放在了墙壁最坚固，离人群最远的地方！一个人都没死！怎么？一面想着和神弃者同盟做交易，却还在手里攥着自己的良心？",
          ContentKR = "그런데 넌 뭘 했어? 그 폭탄들을 제일 튼튼한 벽에, 그것도 사람들 발길도 안 닿는 구석에 처박아 놨잖아! 죽은 사람이 아무도 없다고! 왜? 포세이큰 동맹이랑 거래는 하고 싶은데, 알량한 양심은 지키고 싶었나 보지?",
          DialogueId = 10044505,
          GUID = "1925369A",
          SpeakNpcId = 100444,
          VoiceName = "voice/$Locale$/story/1004/100445/1925369A"
        },
        [10044506] = {
          Content = "虽然我们的计划暂时没有受到影响，但这确实让我感到烦躁。所以对于你的处置，我想要换一个方式，能够避免你那可笑的良心病再次发作。",
          ContentKR = "뭐, 당장 우리 계획에 차질이 생긴 건 아니지만, 난 심기가 영 불편해. 그래서 네 처분을 바꿔 보기로 했어. 그 웃기지도 않는 양심 타령이 두 번 다시 안 튀어나오게 말이야.",
          DialogueId = 10044506,
          GUID = "192536C4",
          SpeakNpcId = 100444,
          VoiceName = "voice/$Locale$/story/1004/100445/192536C4"
        },
        [10044507] = {
          Content = "挑一个喜欢的方法吧，哪怕是痛苦少点也没事，我会尽量满足你。",
          ContentKR = "방법 정도는 고르게 해 줄게. 덜 고통스러운 방법을 써 달라고 하면, 그 정도는 들어줄 수 있어.",
          DialogueId = 10044507,
          GUID = "192536EE",
          SpeakNpcId = 100444,
          VoiceName = "voice/$Locale$/story/1004/100445/192536EE"
        },
        [10044508] = {
          Content = "住手！",
          ContentKR = "그만둬!",
          DialogueId = 10044508,
          GUID = "19253718",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100445/19253718"
        },
        [10044509] = {
          Content = "啧，半大毛孩子也来搅局。正好，用你们的骨头磨磨刀。",
          ContentKR = "쳇, 웬 애들까지 끼어들어서 귀찮게 구네. 칼이 무뎌진 것 같았는데, 마침 잘됐어.",
          DialogueId = 10044509,
          GUID = "19253742",
          SpeakNpcId = 100444,
          VoiceName = "voice/$Locale$/story/1004/100445/19253742"
        },
        [10044601] = {
          Content = "有两下子，只不过神弃者同盟是不会……",
          ContentKR = "꽤 하는데? 그래도 우리 포세이큰 동맹은...",
          DialogueId = 10044601,
          GUID = "1925465A",
          SpeakNpcId = 100444,
          VoiceName = "voice/$Locale$/story/1004/100446/1925465A"
        },
        [10044602] = {
          Content = "给他嘴里塞点什么，让他闭嘴",
          ContentKR = "입을 틀어막는다.",
          DialogueId = 10044602,
          GUID = "19254684"
        },
        [10044603] = {
          Content = "神弃者同盟的成员，据说特别善于进行冗长而枯燥的理论宣讲和无力的恫吓，这些话还是留给艾森巴恩去听吧。",
          ContentKR = "포세이큰 동맹 녀석들은 길고 지루한 강연과 의미 없는 협박질의 선수라더니, 역시 소문대로네요. 그런 소리는 아이젠반 역장한테나 해요.",
          DialogueId = 10044603,
          GUID = "192546AE",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100446/192546AE"
        },
        [10044604] = {
          Content = "至于你，也一起跟着去见艾森巴恩吧。{性别：他|她}的朋友正因为你犯下的罪行而蒙受不白之冤。",
          ContentKR = "그리고, 카르노 씨도 저희와 함께 역장을 만나러 가야 해요. 그쪽이 저지른 일 때문에, 이분의 친구가 억울하게 누명을 쓰고 붙잡혀 있거든요.",
          DialogueId = 10044604,
          GUID = "192546D8",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100446/192546D8"
        },
        [10044605] = {
          Content = "谢谢你们，也对不起……明明你帮了我的忙，结果却还因为我的一时糊涂，卷入进来。",
          ContentKR = "구해 주셔서 감사합니다. 그리고 정말 죄송해요... 저를 도와주셨는데, 제가 어리석은 선택을 하는 바람에 이런 일에 휘말리셨네요.",
          DialogueId = 10044605,
          GUID = "19254702",
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100446/19254702"
        },
        [10044606] = {
          Content = "你更需要对史蒂芬说对不起才是。",
          ContentKR = "저한테 미안해하실 게 아니라, 스테판한테 사과하세요.",
          DialogueId = 10044606,
          GUID = "1925472C",
          ImprPlusId = 1009
        },
        [10044607] = {
          Content = "没有人受伤是不幸中的万幸。",
          ContentKR = "그래도 다친 사람이 없어서 정말 다행이에요.",
          DialogueId = 10044607,
          GUID = "19254756",
          ImprPlusId = 1006
        },
        [10044608] = {
          Content = "你说得没错，但……我不知道怎么面对他。",
          ContentKR = "그렇네요. 하지만... 제가 무슨 낯으로 그 아이 얼굴을 봐야 할지...",
          DialogueId = 10044608,
          GUID = "19254780",
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100446/19254780"
        },
        [10044609] = {
          Content = "是啊，也许你可能觉得我虚伪，但我也确实松了一口气。",
          ContentKR = "네, 위선자라고 욕하셔도 할 말 없지만, 솔직히 저도 참 다행이라고 생각했어요.",
          DialogueId = 10044609,
          GUID = "192547AA",
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100446/192547AA"
        },
        [10044701] = {
          Content = "……以上就是我们抓到这两个人的全部经过。希望你信守承诺，尽快释放我的朋友。",
          ContentKR = "...이렇게 해서 저 두 사람을 붙잡아 온 거예요. 이제 약속대로, 당장 제 친구를 풀어 주세요.",
          DialogueId = 10044701,
          GUID = "192556C2",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 101004,
            [3] = 201030,
            [4] = 201031,
            [5] = 403012
          },
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100447/192556C2"
        },
        [10044702] = {
          Content = "报告站长大人，卡诺的笔迹与那封匿名信的笔迹一致。被称为哈洛吉的青年身上也搜出了神弃者同盟的信物，阶级为渡鸦！",
          ContentKR = "역장님! 보고드립니다! 익명 투서의 필적이 카르노의 필적과 정확히 일치합니다. 또한, 하로기라는 남자에게서 포세이큰 동맹의 증표가 발견됐습니다. 계급은 레이븐입니다!",
          DialogueId = 10044702,
          GUID = "192556EC",
          RelatedWikiId = {
            [1] = 201032
          },
          SpeakNpcId = 100421,
          VoiceName = "voice/$Locale$/story/1004/100447/192556EC"
        },
        [10044703] = {
          Content = "知道了，明天把他们送去迪斯玛尼亚进行进一步审讯吧。",
          ContentKR = "알겠다. 두 놈 다 내일 디즈마니아로 압송해서 추가 신문을 진행해.",
          DialogueId = 10044703,
          GUID = "19255716",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100447/19255716"
        },
        [10044704] = {
          Content = "另外，十三军团下了最后通牒，寒鸦号明早九时必须发车。列车等级定为特快专列，其他车次全部避让，中间不停靠任何站点。",
          ContentKR = "그리고, 제13군단에서 최후통첩이 내려왔다. 갈까마귀호는 내일 오전 9시에 반드시 발차한다. 중간 기착지 없는 특급 직통 열차로 편성할 테니, 타 열차들은 전부 후순위로 미뤄.",
          DialogueId = 10044704,
          GUID = "19255740",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100447/19255740"
        },
        [10044705] = {
          Content = "所有卫兵今夜全部监视寒鸦号，任何人不得靠近。火车工人也不准走，都留下来把寒鸦号车厢内全部检查一遍，确保没有炸弹之类的可疑物品。",
          ContentKR = "모든 경비병은 오늘 밤 갈까마귀호 주변을 철통같이 경계하고, 외부인의 접근을 일체 통제한다. 정비공들도 비상근무로 전환한다. 전원 남아서 폭탄 등 수상한 물건이 숨겨져 있지는 않은지, 객차 내부를 이 잡듯이 수색해.",
          DialogueId = 10044705,
          GUID = "1925576A",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100447/1925576A"
        },
        [10044706] = {
          Content = "明白。",
          ContentKR = "알겠습니다!",
          DialogueId = 10044706,
          GUID = "19255794",
          SpeakNpcId = 100421,
          VoiceName = "voice/$Locale$/story/1004/100447/19255794"
        },
        [10044707] = {
          Content = "（寒鸦号……明天就要走？！）",
          ContentKR = "(갈까마귀호가... 당장 내일 출발한다고?!)",
          DialogueId = 10044707,
          DisableMouth = 1,
          GUID = "192557BE",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100447/192557BE"
        },
        [10044708] = {
          Content = "卡诺和哈洛吉这两个犯人安排另外的车辆运送。嗯，就用极光号好了。重复一遍指令。",
          ContentKR = "죄수 카르노와 하로기는 별도의 열차로 이송한다. 음, 오로라호가 적당하겠군. 복명복창, 실시.",
          DialogueId = 10044708,
          GUID = "192557E8",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100447/192557E8"
        },
        [10044709] = {
          Content = "严密把守寒鸦号，彻查车厢内部，明日九时出发，列车等级为特快专列，其他车次全部避让，中间不停靠站点。卡诺与哈洛吉用极光号押运。",
          ContentKR = "갈까마귀호 철통 경계 및 객차 내부 정밀 수색! 갈까마귀호는 내일 오전 9시 특급 직통 열차로 편성되어 발차하며, 타 열차는 전부 대기! 죄수 카르노와 하로기는 오로라호로 이송! 이상입니다!",
          DialogueId = 10044709,
          GUID = "19255812",
          SpeakNpcId = 100421,
          VoiceName = "voice/$Locale$/story/1004/100447/19255812"
        },
        [10044710] = {
          Content = "可以，安排下去吧。对了，和工人们说，彻夜检修辛苦，今天的薪水发双倍。",
          ContentKR = "좋다, 즉시 지시 사항 전달해. 아, 그리고 정비공들에겐 철야 작업을 위로하는 의미로, 오늘 일당은 두 배로 쳐서 지급하겠다고 전해라.",
          DialogueId = 10044710,
          GUID = "1925583C",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100447/1925583C"
        },
        [10044711] = {
          Content = "至于你们几个狩月人的工作，就到此结束吧。我会释放你们的朋友，但我也还是要提醒你们，不要在车站做出任何可疑的行为。",
          ContentKR = "너희 월석 사냥꾼들의 임무도 여기까지다. 약속대로 동료는 풀어 주겠지만, 한 가지는 명심해. 이 기차역 안에서 수상한 짓거리 하지 마라.",
          DialogueId = 10044711,
          GUID = "19255866",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100447/19255866"
        },
        [10044712] = {
          Content = "不会的，我们遵守法律，老实本分。",
          ContentKR = "그럴 일 없어요. 저희는 성실한 준법 시민이거든요.",
          DialogueId = 10044712,
          GUID = "19255890",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100447/19255890"
        },
        [10044713] = {
          Content = "不过我还有一个疑问，那个广播的声音明明是女声，说明哈洛吉还有同伙。你不管了么？",
          ContentKR = "그런데 한 가지 궁금한 게 있어요. 역 안에 울려 퍼진 방송은 여자 목소리였잖아요. 그건 하로기한테 동료가 있다는 소린데... 그냥 내버려두실 거예요?",
          DialogueId = 10044713,
          GUID = "192558BA",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100447/192558BA"
        },
        [10044714] = {
          Content = "这就不劳你多关心了，我干什么，自有我的道理。",
          ContentKR = "그건 네가 신경 쓸 바가 아니야. 뭘 어떻게 처리할지는, 내가 판단한다.",
          DialogueId = 10044714,
          GUID = "192558E4",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100447/192558E4"
        },
        [10044715] = {
          Content = "行吧，尊重你的判断，祝福车站接下来平安无事。对了，还有一件事。",
          ContentKR = "알겠어요, 그러면 역장님 판단을 존중할게요. 이 역이 아무 일도 안 생기길 바라죠. 참, 하나만 더요.",
          DialogueId = 10044715,
          GUID = "1925590E",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100447/1925590E"
        },
        [10044716] = {
          Content = "卡诺的儿子还在等他父亲回来。和亲人一别再无音讯的感觉很不好受，如果可以，让他们父子俩再见上一面吧。",
          ContentKR = "카르노 씨의 아들이 아버지를 기다리고 있어요. 가족과 생이별하고 아무 소식도 못 듣고 지내는 건 너무 슬픈 일이잖아요. 괜찮다면, 두 사람이 마지막으로 얼굴만이라도 보게 해 주세요.",
          DialogueId = 10044716,
          GUID = "19255938",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100447/19255938"
        },
        [10044801] = {
          Content = "半天不见，分外想念，朋友们。",
          ContentKR = "반나절만인데도 엄청 보고 싶었어, 얘들아.",
          DialogueId = 10044801,
          GUID = "1925672A",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100448/1925672A"
        },
        [10044802] = {
          Content = "你还好吗？没受伤吧？",
          ContentKR = "몸은 좀 어때? 어디 다친 덴 없어?",
          DialogueId = 10044802,
          GUID = "19256754",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100448/19256754"
        },
        [10044803] = {
          Content = "倒没什么事，还从看守那边套了一些消息，什么神弃者同盟又在帝国南部掀起动乱，烧毁天之树，阻断交通，迟迟无法扑灭之类的。",
          ContentKR = "멀쩡해. 오히려 간수 녀석들 구슬려서 쏠쏠한 정보도 좀 캐냈다고. 그 포세이큰 동맹인지 뭔지가 제국 남쪽에서 난리를 쳐 놨더라. 천국의 나무를 불태우고, 길을 다 끊어놓는 바람에, 아직 불길도 못 잡고 있다던데.",
          DialogueId = 10044803,
          GUID = "1925677E",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100448/1925677E"
        },
        [10044804] = {
          Content = "还想问更多，没想到你们这么快就来了。",
          ContentKR = "좀 더 캐물어 볼 생각이었는데, 생각보다 빨리 구하러 와 줬네.",
          DialogueId = 10044804,
          GUID = "192567A8",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100448/192567A8"
        },
        [10044805] = {
          Content = "嘿嘿，这还多亏了你的护身符提醒了我，我又提醒了{性别：他们|她们}！给你给你。",
          ContentKR = "헤헤, 이게 다 네 부적 덕분이야. 내가 그걸 보고 '이거다!' 싶어서 싹 다 알려 줬거든! 자, 이거 돌려줄게.",
          DialogueId = 10044805,
          GUID = "192567D2",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100448/192567D2"
        },
        [10044806] = {
          Content = "护身符？怎么回事？我刚刚就听到看守在讨论你们调查的经过，说是利落，漂亮。就是没想到那个卡诺居然是内鬼。",
          ContentKR = "부적? 그건 또 무슨 소리야? 아무튼 아까 간수들이 너희가 조사를 깔끔하게 잘 끝냈다고 떠드는 건 들었어. 근데 그 카르노 씨가 내통자일 줄은 몰랐네.",
          DialogueId = 10044806,
          GUID = "192567FC",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100448/192567FC"
        },
        [10044807] = {
          Content = "以及我也很好奇，为什么她会和我们站在一起。",
          ContentKR = "내가 너무 궁금해서 물어보는 건데, 이 여자는 왜 우리랑 같이 서 있는 거야?",
          DialogueId = 10044807,
          GUID = "19256826",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100448/19256826"
        },
        [10044808] = {
          Content = "这些等回去之后我再和你讲。现在我要去找她的主人——十三军团的监军。",
          ContentKR = "그건 나중에 돌아가서 다 설명해 줄게. 일단 지금은 이 친구가 모시는 분을 만나러 가야 해. 제13군단의 감찰실장님이야.",
          DialogueId = 10044808,
          GUID = "19256850",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100448/19256850"
        },
        [10044809] = {
          Content = "刚刚艾森巴恩说了，寒鸦号会在明天维修结束后会立刻发车。我们没有多少时间了。",
          ContentKR = "아까 아이젠반 역장이 갈까마귀호는 내일 아침에 정비가 끝나면 바로 출발할 거라고 했으니까, 우리한테 남은 시간이 별로 없어.",
          DialogueId = 10044809,
          GUID = "1925687A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100448/1925687A"
        },
        [10044810] = {
          Content = "跟我走吧，我想监军大人也迫不及待想要见到您了。",
          ContentKR = "따라오세요. 감찰실장님께서도 그쪽을 무척 보고 싶어 하실 겁니다.",
          DialogueId = 10044810,
          GUID = "192568A4",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100448/192568A4"
        },
        [10044901] = {
          Content = "好安静啊……白天明明那么多人，结果到了晚上一个人都没有，只有黑黢黢的列车……不愧叫寒鸦号。",
          ContentKR = "엄청 조용하네... 낮에는 사람이 바글바글하더니, 밤이 되니까 새까만 기차 말곤 아무것도 없어... 그래서 갈까마귀호란 이름을 붙였나 봐.",
          DialogueId = 10044901,
          GUID = "19257792",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 101004,
            [3] = 201030,
            [4] = 201031
          },
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100449/19257792"
        },
        [10044902] = {
          Content = "毕竟现在已经这个点了，末班车也已经发车，有人反而奇怪。",
          ContentKR = "이 시간이면 그럴 만도 해. 막차도 끊겼을 시간인데, 서성거리는 사람이 있으면 그게 더 이상하지.",
          DialogueId = 10044902,
          GUID = "192577BC",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100449/192577BC"
        },
        [10044903] = {
          Content = "不……情况不太对……有点太安静了……刚刚艾森巴恩还特意吩咐要加强寒鸦号的防卫。",
          ContentKR = "아니요... 뭔가 이상해요... 이상하게 조용해요... 아이젠반이 방금 갈까마귀호 주변의 경계를 강화하라는 특별 지시까지 내렸잖아요.",
          DialogueId = 10044903,
          GUID = "192577E6",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100449/192577E6"
        },
        [10044904] = {
          Content = "这种异乎寻常的安静简直就像是……",
          ContentKR = "이 비정상적인 정적은 마치...",
          DialogueId = 10044904,
          GUID = "19257810",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100449/19257810"
        },
        [10044905] = {
          Content = "像是捕获你们的陷阱。",
          ContentKR = "너희를 옭아매기 위한 함정 같겠지.",
          DialogueId = 10044905,
          GUID = "1925783A",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100449/1925783A"
        },
        [10044906] = {
          Content = "艾森巴恩？你怎么又会出现在这里？",
          ContentKR = "아이젠반 역장님? 여긴 왜 오신 거죠?",
          DialogueId = 10044906,
          GUID = "19257864",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100449/19257864"
        },
        [10044907] = {
          Content = "这个问题应该由我来问才是。",
          ContentKR = "그건 내가 물어야 할 질문일 텐데.",
          DialogueId = 10044907,
          GUID = "1925788E",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100449/1925788E"
        },
        [10044908] = {
          Content = "在最初见到你们的时候，我确实小瞧了你们。只以为是现成的可以用来安抚乘客情绪的工具。",
          ContentKR = "너희를 처음 봤을 때, 상당히 과소평가했던 건 사실이야. 그저 승객들의 불안을 잠재워 줄 적당한 도구로만 생각했지.",
          DialogueId = 10044908,
          GUID = "192578B8",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100449/192578B8"
        },
        [10044909] = {
          Content = "但我得承认，你们聪明的程度以及身手，都出乎我的意料。外加那位阁下似乎格外中意你们，乃至于我不得不开始对你们抱有防备之心。",
          ContentKR = "하지만 이젠 인정하겠다. 너희는 내 예상보다 훨씬 똑똑하고, 실력도 좋더군. 게다가 그분께서 너희를 유독 눈여겨보시는 바람에, 나로선 너희를 철저히 경계할 수밖에 없었어.",
          DialogueId = 10044909,
          GUID = "192578E2",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100449/192578E2"
        },
        [10044910] = {
          Content = "即便你们已经证明了自己并非神弃者同盟的人，但我依旧还要防备你们对寒鸦号动什么手脚。",
          ContentKR = "너희가 포세이큰 동맹의 일원이 아니라는 건 증명됐지만, 이 갈까마귀호에 수작을 부리지 않으리란 보장은 없으니까.",
          DialogueId = 10044910,
          GUID = "1925790C",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100449/1925790C"
        },
        [10044911] = {
          Content = "毕竟，我已经为了伺候那位棘手的要人小心翼翼地准备了一个月，终于在明天就能把她送走，处理积压如山的车站其他事务。",
          ContentKR = "나는, 한 달 동안 그 까다로운 귀빈을 의전하며 보조해 왔다. 하지만 내일 그분이 떠나시면, 나는 산더미처럼 쌓인 우리 역의 업무를 해결할 수 있게 돼.",
          DialogueId = 10044911,
          GUID = "19257936",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100449/19257936"
        },
        [10044912] = {
          Content = "所以，今晚容不得半点闪失。",
          ContentKR = "따라서, 오늘 밤은 단 한 치의 오차도 용납할 수 없다.",
          DialogueId = 10044912,
          GUID = "19257960",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100449/19257960"
        },
        [10044913] = {
          Content = "我们来这里只是找监军大人，并没有打算做什么出格的事。",
          ContentKR = "우린 문제를 일으키러 온 게 아니라, 그냥 감찰실장님을 만나러 온 거예요.",
          DialogueId = 10044913,
          GUID = "1925798A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100449/1925798A"
        },
        [10044914] = {
          Content = "什么监军大人？十三军团的高层目前都在帝国的南方处理同盟叛乱的善后事宜。想和我玩诈术？你还不够格。",
          ContentKR = "감찰실장? 제13군단 고위층은 지금 전원 모두 제국 남부에서 동맹 놈들의 반란을 수습하고 있다. 나한테 알량한 속임수를 쓰려 들어? 넌 아직 그 수준이 아니야.",
          DialogueId = 10044914,
          GUID = "192579B4",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100449/192579B4"
        },
        [10045001] = {
          Content = "监军大人！你总算来了，这个艾森巴恩太狡猾了，始终不相信我们！",
          ContentKR = "감찰실장! 드디어 와 줬구나! 이 역장 진짜 너무해! 아까부터 우리 말은 하나도 안 믿어 줘!",
          DialogueId = 10045001,
          GUID = "192587FA",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 101004,
            [3] = 201030,
            [4] = 201031,
            [5] = 403012
          },
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100450/192587FA"
        },
        [10045002] = {
          Content = "原来如此……您并没有告知他们您的真实身份啊。请恕我多嘴一句，身为帝国的公主却谎称军人，这多少会有损您的声名。",
          ContentKR = "과연... 아직 이자들에게 진짜 신분을 밝히지 않으신 모양이군요. 주제넘은 참견이지만, 제국의 공주 전하께서 일개 군인 행세를 하시면, 전하의 명예에 흠이 나게 됩니다.",
          DialogueId = 10045002,
          GUID = "19258824",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100450/19258824"
        },
        [10045003] = {
          Content = "而您的名誉受损，小官作为百花车站的站长，也同样会感到心痛万分，您能理解吗？<H>芙罗蒂娅公主殿下</>。",
          ContentKR = "혹시 이런 일로 명예가 실추되시기라도 한다면, 블룸필드역의 역장인 저는 얼마나 통탄스럽겠습니까? <H>플로렌티아 공주 전하</>.",
          DialogueId = 10045003,
          GUID = "1925884E",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100450/1925884E"
        },
        [10045004] = {
          Content = "您的出走已经在皇都的贵族中如同插着翅膀一样小范围流传开来，小官衷心地恳求您，不要再给皇帝陛下增添烦恼了。",
          ContentKR = "황성의 귀족 중 일부 사이에선 전하께서 황성 밖으로 떠나셨다는 이야기가 퍼져나가고 있습니다. 부디 황제 폐하께 더 이상의 심려를 끼쳐드리지 않으시기를 간청드립니다.",
          DialogueId = 10045004,
          GUID = "19258878",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100450/19258878"
        },
        [10045005] = {
          Content = "你僭越了，会不会给叔父增添烦恼，还轮不到你来揣度。",
          ContentKR = "염려가 과하시군요. 제가 숙부님께 심려를 끼쳐드릴지는 당신이 함부로 왈가왈부할 사안이 아닙니다.",
          DialogueId = 10045005,
          GUID = "192588A2",
          SpeakNpcId = 100404,
          SpeakNpcName = "UI_SpeakName_Fuluodiya",
          VoiceName = "voice/$Locale$/story/1004/100450/192588A2"
        },
        [10045006] = {
          Content = "而他们，则是我在冰湖城这短暂的自由时光认识的朋友。你也许有所耳闻，在冰湖城东区有一支新成立不久的狩月人小队，名为夜航者。",
          ContentKR = "그리고 이분들은, 제가 아이스레이크 시티에서 잠시나마 자유를 누리며 사귄 벗들입니다. 아마, 이 도시 동부에서 얼마 전 새로 결성됐다는 월석 사냥꾼 모임 '녹토 보이저'에 대해 모르진 않으시겠죠.",
          DialogueId = 10045006,
          GUID = "192588CC",
          SpeakNpcId = 100404,
          SpeakNpcName = "UI_SpeakName_Fuluodiya",
          VoiceName = "voice/$Locale$/story/1004/100450/192588CC"
        },
        [10045007] = {
          Content = "他们先是解决了前一阵东区突发的秽蚀者事件，在卡戎狩猎案中，也协助了第十三军团。而我就在这个过程中与他们相识。",
          ContentKR = "얼마 전 동부에서 급작스럽게 발생한 침식자 사건과 카론 사냥을 해결하고, 제13군단에 힘을 보태 준 협력자들이 바로 이분들입니다. 저 역시 그때 이분들과 인연이 생겼죠.",
          DialogueId = 10045007,
          GUID = "192588F6",
          SpeakNpcId = 100404,
          SpeakNpcName = "UI_SpeakName_Fuluodiya",
          VoiceName = "voice/$Locale$/story/1004/100450/192588F6"
        },
        [10045008] = {
          Content = "既然我即将被送回迪斯玛尼亚，那么他们今天来送我一程，也是理所应当。",
          ContentKR = "벗들이 곧 디즈마니아로 돌아가게 될 저를 배웅해 주러 오는 건, 지극히 당연한 일입니다.",
          DialogueId = 10045008,
          GUID = "19258920",
          SpeakNpcId = 100404,
          SpeakNpcName = "UI_SpeakName_Fuluodiya",
          VoiceName = "voice/$Locale$/story/1004/100450/19258920"
        },
        [10045009] = {
          Content = "如你所见，我的车厢外全都是十三军团的士兵，逃不掉。如果你实在不放心，大可以再加派你的下属将寒鸦号围住，待我们告别后再撤走。",
          ContentKR = "보시다시피, 제 객차 밖은 제13군단의 병사들이 경호 중입니다. 도망칠 방법은 없어요. 정 불안하시다면, 저희가 작별 인사를 마칠 때까지, 사람을 더 배치해 갈까마귀호를 포위하시면 됩니다.",
          DialogueId = 10045009,
          GUID = "1925894A",
          SpeakNpcId = 100404,
          SpeakNpcName = "UI_SpeakName_Fuluodiya",
          VoiceName = "voice/$Locale$/story/1004/100450/1925894A"
        },
        [10045010] = {
          Content = "殿下都已经这么说了，我自然是相信的，那么还请各位尽情叙旧。当然，为了殿下的安全，请允许我对他们搜身，确保他们身上没有携带武器。",
          ContentKR = "그런 말씀을 듣고 어찌 감히 전하를 의심하겠습니까? 편히 이야기 나누십시오. 다만 전하의 안전을 위해, 무기를 숨기고 있지는 않은지, 몸수색 정도는 허락해 주셨으면 합니다.",
          DialogueId = 10045010,
          GUID = "19258974",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100450/19258974"
        },
        [10045011] = {
          Content = "……好。搜完就跟我进来吧。",
          ContentKR = "...좋습니다. 수색이 끝나면 같이 안으로 들어가시죠.",
          DialogueId = 10045011,
          GUID = "1925899E",
          SpeakNpcId = 100404,
          SpeakNpcName = "UI_SpeakName_Fuluodiya",
          VoiceName = "voice/$Locale$/story/1004/100450/1925899E"
        },
        [10045101] = {
          Content = "哇……虽然上一次在车厢入口就感觉这里不简单，没想到里面居然豪华到这种地步……就算是嘟嘟皎皎前辈见到了，肯定也会被吓到！",
          ContentKR = "우와... 저번에 열차칸 입구에서부터 뭔가 평범하진 않다고 느꼈는데, 안이 엄청 으리으리하네... 이건 철도원 루나 선배가 봐도, 깜짝 놀라겠어!",
          DialogueId = 10045101,
          GUID = "19259862",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1004/100451/19259862"
        },
        [10045102] = {
          Content = "请用茶，这是来自华胥的饮品，加入了牛奶与糖中和了苦涩的口感，深受芙罗拉小姐喜爱，尤其是我亲手制作的。",
          ContentKR = "차 드세요. 화서에서 들여온 음료인데, 우유와 설탕을 넣어 쓴맛을 잡았죠. 플로라 아가씨께서 무척 좋아하신답니다. 특히 제가 만든 건 더더욱요.",
          DialogueId = 10045102,
          GUID = "1925988C",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100451/1925988C"
        },
        [10045103] = {
          Content = "芙罗拉？",
          ContentKR = "플로라?",
          DialogueId = 10045103,
          GUID = "192598B6",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100451/192598B6"
        },
        [10045104] = {
          Content = "小姐的本名太引人注目，所以还请和我一样，称呼她为芙罗拉小姐。",
          ContentKR = "아가씨의 본명은 밖에서 너무 눈에 띄니까요. 그러니 플로라 씨로 불러 주시면 될 것 같네요.",
          DialogueId = 10045104,
          GUID = "192598E0",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100451/192598E0"
        },
        [10045105] = {
          Content = "茶？我来喝喝看……好喝耶！",
          ContentKR = "차? 나도 마셔 볼래... 엄청 맛있다!",
          DialogueId = 10045105,
          GUID = "1925990A",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100451/1925990A"
        },
        [10045106] = {
          Content = "不过，奥特赛德，{nickname}，你们怎么不喝？难道怕苦？不苦的。",
          ContentKR = "근데 아웃사이더, {nickname}, 너네는 왜 안 마셔? 쓸까 봐 그래? 하나도 안 쓴데.",
          DialogueId = 10045106,
          GUID = "19259934",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100451/19259934"
        },
        [10045107] = {
          Content = "在喝茶之前，我还是想搞清楚究竟是怎么回事。她到底是什么人，为什么会知道我们之前的经历。",
          ContentKR = "차 마시기 전에, 뭐가 어떻게 된 건지부터 제대로 듣고 싶어요. 당신은 대체 누구고, 우리 행적은 어떻게 그렇게 잘 알고 있는 거죠?",
          DialogueId = 10045107,
          GUID = "1925995E",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100451/1925995E"
        },
        [10045108] = {
          Content = "慢慢来，首先，芙罗拉小姐确实是……",
          ContentKR = "천천히 말씀드릴게요. 우선, 플로라 아가씨는...",
          DialogueId = 10045108,
          GUID = "19259988",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100451/19259988"
        },
        [10045109] = {
          Content = "还是我来吧，希尔妲。你去门口，防止有人偷听我们接下来的对话。",
          ContentKR = "내가 설명할게, 힐다. 넌 입구 쪽으로 가서, 누가 우리 이야기를 엿듣지 못하게 지켜 줘.",
          DialogueId = 10045109,
          GUID = "192599B2",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/192599B2"
        },
        [10045110] = {
          Content = "首先，我来回答第一个问题，我是谁。我得向你们说一声抱歉，方才情急之下自称是第十三军团的监军，骗了你们。",
          ContentKR = "우선 첫 번째 질문부터 대답할게요. 제가 누구냐고요. 먼저, 미안해요. 처음엔 너무 다급한 나머지, 제13군단의 감찰실장이라고 둘러댔어요.",
          DialogueId = 10045110,
          GUID = "192599DC",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/192599DC"
        },
        [10045111] = {
          Content = "只是在那时候，我直接表明身份，你们也并不会相信吧。",
          ContentKR = "하지만 그 상황에서 제 진짜 신분을 밝혔더라도, 여러분은 제 말을 믿어 주지 않았을 거예요.",
          DialogueId = 10045111,
          GUID = "19259A06",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259A06"
        },
        [10045112] = {
          Content = "没错，我的身份如同艾森巴恩所说，是帝国的公主，芙罗蒂娅·普洛塞庇娜·盖雷亚。",
          ContentKR = "그래요, 전 아이젠반이 말한 것처럼, 이 제국의 공주 플로렌티아 프로세르피나 갈레아예요.",
          DialogueId = 10045112,
          GUID = "19259A30",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259A30"
        },
        [10045113] = {
          Content = "（帝国的公主……竟然是个卡戎之民？）",
          ContentKR = "(제국의 공주가... 카론이라고?)",
          DialogueId = 10045113,
          DisableMouth = 1,
          GUID = "19259A5A",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100451/19259A5A"
        },
        [10045114] = {
          Content = "公主不是应该一直待在迪斯玛尼亚准备继承皇位吗？为什么会出现在冰湖城这样的边陲城市？",
          ContentKR = "공주님이라면 디즈마니아에 머물면서 다음 황제가 될 준비를 해야 하는 거 아니에요? 왜 아이스레이크 시티 같은 변두리에 계신 거죠?",
          DialogueId = 10045114,
          GUID = "19259A84",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100451/19259A84"
        },
        [10045115] = {
          Content = "如果我的父亲——先代皇帝还没有去世的话，那应该确实如此。只可惜他已经去世很久了。",
          ContentKR = "제 아버님... 그러니까 선대 황제 폐하께서 아직 살아 계셨다면 그랬겠지요. 애석하게도, 아버님은 오래전에 세상을 떠나셨어요.",
          DialogueId = 10045115,
          GUID = "19259AAE",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259AAE"
        },
        [10045116] = {
          Content = "而在那之后没多久，我就被当做一位皇位觊觎者，被新任皇帝软禁起来，失去了自由。",
          ContentKR = "그리고 얼마 지나지 않아, 저는 새 황제에게 황위를 노린다고 오해받아, 자유를 빼앗기고 연금당하는 처지가 됐지요.",
          DialogueId = 10045116,
          GUID = "19259AD8",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259AD8"
        },
        [10045117] = {
          Content = "随后便是俗套的宫廷故事一般，公主厌倦了无法自由行动的生活，想要逃离皇都，于是在我的侍女，希尔妲的帮助下逃到了这里。",
          ContentKR = "그다음은 흔한 이야기예요. 황성이라는 새장을 벗어나고 싶었던 공주가, 자신의 시녀 힐다의 도움을 받아, 이곳까지 도망쳐 왔다는 거죠.",
          DialogueId = 10045117,
          GUID = "19259B02",
          RelatedWikiId = {
            [1] = 201033
          },
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259B02"
        },
        [10045118] = {
          Content = "我来到冰湖城的时候，泪湖那里出现了秽蚀者，本来以为城里会死伤惨重，结果却发现是一个狩月人小队解决了危机。",
          ContentKR = "제가 아이스레이크 시티에 도착했을 때, 눈물의 호수 쪽에 침식자들이 나타났었어요. 사상자가 많이 나올 줄 알았는데, 어느 월석 사냥꾼 팀 덕분에 위기를 넘길 수 있었죠.",
          DialogueId = 10045118,
          GUID = "19259B2C",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259B2C"
        },
        [10045119] = {
          Content = "此后在“卡戎狩猎”事件，同样又是他们，跑遍了冰湖城的各个角落，积极调查凶手。",
          ContentKR = "그 뒤에 벌어진 '카론 사냥' 때도 마찬가지로, 똑같은 월석 사냥꾼 팀이 아이스레이크 시티 곳곳을 발로 뛰며, 적극적으로 범인 조사에 나섰고요.",
          DialogueId = 10045119,
          GUID = "19259B56",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259B56"
        },
        [10045120] = {
          Content = "是的，从那时候开始我就知道你们了，夜航者小队的狩月人们。",
          ContentKR = "그래요, 전 그때부터 여러분을 알고 있었어요. 팀 '녹토 보이저'의 월석 사냥꾼 여러분.",
          DialogueId = 10045120,
          GUID = "19259B80",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259B80"
        },
        [10045121] = {
          Content = "原本我还打算雇佣你们护送我离开冰湖城，可在付诸行动之前，我就被第十三军团的密探找到，还在和他们的打斗中受了些伤。",
          ContentKR = "처음에는 여러분을 호위로 고용해서 아이스레이크 시티를 빠져나갈 계획이었지만, 그러기도 전에 제13군단의 요원들에게 꼬리를 밟혔고, 몸싸움을 벌이다 부상까지 입게 됐어요.",
          DialogueId = 10045121,
          GUID = "19259BAA",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259BAA"
        },
        [10045122] = {
          Content = "原来你从那时候就……难怪你相信我们不是神弃者同盟的成员。",
          ContentKR = "그때부터 우리를... 그래서 우리가 포세이큰 동맹 쪽 사람이 아니라는 걸 믿어 준 거였군요.",
          DialogueId = 10045122,
          GUID = "19259BD4",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100451/19259BD4"
        },
        [10045123] = {
          Content = "那你……芙罗拉小姐，你知不知道寒鸦号原本计划在五天后运送一个囚犯到迪斯玛尼亚？",
          ContentKR = "그러면... 플로라 씨, 아시는지 모르겠지만, 원래 갈까마귀호는 5일 뒤에 죄수 하나를 디즈마니아로 압송하기로 돼 있었어요.",
          DialogueId = 10045123,
          GUID = "19259BFE",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100451/19259BFE"
        },
        [10045124] = {
          Content = "难道那个囚犯其实是——",
          ContentKR = "설마 그 죄수라는 게...",
          DialogueId = 10045124,
          GUID = "19259C28",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100451/19259C28"
        },
        [10045125] = {
          Content = "是我。很遗憾以这种身份与您相识。",
          ContentKR = "저예요. 이런 모습으로 여러분과 만나게 돼서 정말 유감이에요.",
          DialogueId = 10045125,
          GUID = "19259C52",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259C52"
        },
        [10045126] = {
          Content = "寒鸦号最初定的时间的确是五天后发车。但因为冰湖城先后出了卡戎狩猎和盖雷亚剧院之夜两起惨案，又发现了神弃者同盟的活动踪迹——",
          ContentKR = "갈까마귀호는 원래 닷새 뒤에 떠나기로 되어 있었어요. 하지만 이곳에서 카론 사냥과 갈레아 극장의 참변이 연달아 일어났고, 포세이큰 동맹의 움직임까지 포착되는 바람에...",
          DialogueId = 10045126,
          GUID = "19259C7C",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259C7C"
        },
        [10045127] = {
          Content = "所以，第十三军团提前了运送计划，要求当我身体稍作恢复后，便出发前往迪斯玛尼亚。更改后的发车时间就是今天下午。",
          ContentKR = "제13군단에서 저를 이송하는 일정을 앞당겨 버렸죠. 제 몸이 어느 정도만 회복되면, 곧바로 디즈마니아로 하라면서요. 그렇게 변경된 일정이, 바로 오늘 오후였어요.",
          DialogueId = 10045127,
          GUID = "19259CA6",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259CA6"
        },
        [10045128] = {
          Content = "如果不是今天出了爆炸案的意外，恐怕我现在已经在前往迪斯玛尼亚的路上了吧。",
          ContentKR = "오늘 폭발 사건이 일어나지 않았다면, 저는 이미 디즈마니아로 끌려가고 있었겠죠.",
          DialogueId = 10045128,
          GUID = "19259CD0",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259CD0"
        },
        [10045129] = {
          Content = "…………",
          ContentKR = "......",
          DialogueId = 10045129,
          GUID = "19259CFA",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100451/19259CFA"
        },
        [10045130] = {
          Content = "您似乎有些失望。",
          ContentKR = "실망하신 것 같네요.",
          DialogueId = 10045130,
          GUID = "19259D24",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259D24"
        },
        [10045131] = {
          Content = "那让我猜上一猜——您有一位重要之人同我一样落在了第十三军团手里，所以您误把我当作了她。",
          ContentKR = "제 추측이지만, 아주 소중한 누군가가 저처럼 제13군단에 죄수로 잡혀 있고, 저를 그 사람이라고 착각하신 모양이네요.",
          DialogueId = 10045131,
          GUID = "19259D4E",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259D4E"
        },
        [10045132] = {
          Content = "……对。",
          ContentKR = "...네.",
          DialogueId = 10045132,
          GUID = "19259D78",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100451/19259D78"
        },
        [10045133] = {
          Content = "难怪您几次三番试图接近这辆列车。很遗憾，请允许我向您致歉。",
          ContentKR = "어쩐지 몇 번이나 이 열차에 접근하려고 애쓰시는 것 같았어요. 헛된 기대를 품게 만들어서 정말 미안해요.",
          DialogueId = 10045133,
          GUID = "19259DA2",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259DA2"
        },
        [10045134] = {
          Content = "没什么好道歉的，这也不是你的错。",
          ContentKR = "사과할 거 없어요. 플로라 씨 잘못은 아니잖아요.",
          DialogueId = 10045134,
          GUID = "19259DCC",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100451/19259DCC"
        },
        [10045135] = {
          Content = "无关对错，而是我很清楚希望在眼前破灭的感觉。如果是这样的话，那么我也不强求您能帮我了。",
          ContentKR = "누구의 잘못이냐를 떠나서, 저는 눈앞에서 희망이 산산조각 난다는 게 어떤 느낌인지 잘 알아요. 이제 사정을 알았으니, 억지로 도와달라는 부탁은 하지 않을게요.",
          DialogueId = 10045135,
          GUID = "19259DF6",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259DF6"
        },
        [10045136] = {
          Content = "帮你？",
          ContentKR = "도와달라고요?",
          DialogueId = 10045136,
          GUID = "19259E20",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100451/19259E20"
        },
        [10045137] = {
          Content = "是的，我原本希望委托夜航者小队协助我逃离这辆寒鸦号。拦下艾森巴恩，派希尔妲协助调查，都是为此。",
          ContentKR = "네, 원래는 팀 '녹토 보이저' 여러분께 제가 이 갈까마귀호를 빠져나갈 수 있게 해 달라는 의뢰를 맡길 생각이었어요. 아이젠반을 막아 세운 것도, 힐다를 보내 여러분의 조사를 돕게 한 것도 다 그래서였어요.",
          DialogueId = 10045137,
          GUID = "19259E4A",
          RelatedWikiId = {
            [1] = 201031
          },
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259E4A"
        },
        [10045138] = {
          Content = "一旦呼吸过自在的空气，便没有人想要重返黄金囚笼。",
          ContentKR = "한 번이라도 마음껏 숨을 쉬어 본 새라면, 두 번 다시 황금 새장으로 돌아가고 싶지 않은 법이거든요.",
          DialogueId = 10045138,
          GUID = "19259E74",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259E74"
        },
        [10045139] = {
          Content = "我现在依旧希望您接下这个委托。但我同样知道，我没有资格要求您什么，您也需要保留足够的力量去救你真正想救的人。",
          ContentKR = "지금도 여러분이 이 의뢰를 맡아 주시길 바라지만, 제게는 그럴 자격이 없다는 사실도 잘 알아요. 정말 구하고 싶었던 그분을 위해, 힘을 아껴 두셔야 할 테니까요.",
          DialogueId = 10045139,
          GUID = "19259E9E",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259E9E"
        },
        [10045140] = {
          Content = "感谢你的理解……但，这件事太突然了，请让我再想一想。",
          ContentKR = "이해해 줘서 고맙긴 한데... 그래도, 너무 갑작스러운 일이라, 조금만 더 생각할 시간을 주세요.",
          DialogueId = 10045140,
          GUID = "19259EC8",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100451/19259EC8"
        },
        [10045141] = {
          Content = "嗯……我只希望，无论是接受还是不接受这个委托，在明天寒鸦号发车之前，都要托希尔妲给我一个明确的答复。",
          ContentKR = "네.... 다만, 이 의뢰를 수락하시든, 거절하시든, 내일 갈까마귀호가 출발하기 전까지는 꼭 힐다를 통해 확실한 답변을 전해 주셨으면 해요.",
          DialogueId = 10045141,
          GUID = "19259EF2",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100451/19259EF2"
        },
        [10045142] = {
          Content = "好。",
          ContentKR = "알겠어요.",
          DialogueId = 10045142,
          GUID = "19259F1C",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100451/19259F1C"
        },
        [10045201] = {
          Content = "（寒鸦号受到严密的保护，而我们又被艾森巴恩盯上了，在车站里贸然出手一定不会有好结果……）",
          ContentKR = "(갈까마귀호 주변은 경비가 삼엄하고, 아이젠반은 우리를 예의 주시하고 있어. 역 안에서 섣불리 나서서 좋을 일은 없을 거야...)",
          DialogueId = 10045201,
          DisableMouth = 1,
          GUID = "1925A8CA",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100452/1925A8CA"
        },
        [10045202] = {
          Content = "（贝蕾现在又毫无消息……现在唯一能与十三军团产生关系的人，也许正是芙罗拉这个皇室成员……）",
          ContentKR = "(베레 쪽 소식을 전혀 알 수 없는 상황에서... 제13군단과 끈이 닿아 있는 사람은, 황족인 플로라밖에 없을지도...)",
          DialogueId = 10045202,
          DisableMouth = 1,
          GUID = "1925A8F4",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100452/1925A8F4"
        },
        [10045203] = {
          Content = "（可是，虽然她没有任何犹豫地向我发出委托，但我真的能把她救出来吗？）",
          ContentKR = "(문제는, 플로라는 나를 믿고 단호하게 의뢰를 맡겨 줬지만, 내가 정말 그녀를 이 도시에서 탈출시켜 줄 수 있을까?)",
          DialogueId = 10045203,
          DisableMouth = 1,
          GUID = "1925A91E",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100452/1925A91E"
        },
        [10045204] = {
          Content = "殿下……奉站长的命令，您不能离开车厢太远。",
          ContentKR = "공주 전하... 객차에서 너무 멀리 떨어지시지 말라는, 역장님의 지시가 있었습니다.",
          DialogueId = 10045204,
          GUID = "1925A948",
          SpeakNpcId = 100408,
          VoiceName = "voice/$Locale$/story/1004/100452/1925A948"
        },
        [10045205] = {
          Content = "别担心，我只是在月台上走一走，再呼吸一口北境的空气。",
          ContentKR = "걱정하지 마세요. 승강장을 잠시 거닐며, 북쪽의 공기를 조금 더 마셔 두려는 것뿐입니다.",
          DialogueId = 10045205,
          GUID = "1925A972",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100452/1925A972"
        },
        [10045206] = {
          Content = "再去看一眼月亮，毕竟对我来说，这样的夜晚，不会再有第二次了。",
          ContentKR = "저 달도 한 번 더 눈에 새겨 두려고요. 제게 이런 밤은, 이제 두 번 다시 찾아오지 않을 테니까요.",
          DialogueId = 10045206,
          GUID = "1925A99C",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100452/1925A99C"
        },
        [10045301] = {
          Content = "第二天清晨——",
          ContentKR = "이튿날 아침——",
          DialogueId = 10045301,
          GUID = "1925B932",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 403011,
            [3] = 201033,
            [4] = 201031
          },
          VoiceName = "voice/$Locale$/story/1004/100453/1925B932"
        },
        [10045302] = {
          Content = "应该就是这一辆车，能赶在寒鸦号出发之前发车。",
          ContentKR = "아마 이 기차 맞을 거야. 이 열차는 갈까마귀호보다 먼저 출발해.",
          DialogueId = 10045302,
          GUID = "1925B95C",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100453/1925B95C"
        },
        [10045303] = {
          Content = "哇，人好多。",
          ContentKR = "우와, 사람 엄청 많다.",
          DialogueId = 10045303,
          GUID = "1925B986",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100453/1925B986"
        },
        [10045304] = {
          Content = "是啦，每天早上是人最多的时候，我要忙得不可开交。",
          ContentKR = "맞아! 원래 아침에 사람이 제일 몰려서, 나도 눈코 뜰 새 없이 바빠.",
          DialogueId = 10045304,
          GUID = "1925B9B0",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100453/1925B9B0"
        },
        [10045305] = {
          Content = "本来你们昨天来参观车站，还经历了爆炸案，我都担心你们会有心理阴影，以后都不敢坐火车了。",
          ContentKR = "난 너희가 어제 기차역 구경 왔다가, 폭발 사건에 휘말리는 바람에, 앞으로 두 번 다시는 기차에 안 타려고 할 줄 알았어.",
          DialogueId = 10045305,
          GUID = "1925B9DA",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100453/1925B9DA"
        }
      }
    end
  },
  {
    MinKey = 10045306,
    MaxKey = 10046519,
    Loader = function()
      return {
        [10045306] = {
          Content = "没想到今天又来了，并且还这么早，看来已经完全被火车的机械之美征服了。小白呀，我觉得你也很适合叫做嘟嘟皎皎呢。",
          ContentKR = "근데 오늘 또, 그것도 아침 일찍 다시 와 주다니! 너희도 기차의 기계적인 아름다움에 푹 빠져 버린 모양이네. 스노우, 너한테도 철도원이라는 이름이 잘 어울릴 것 같아.",
          DialogueId = 10045306,
          GUID = "1925BA04",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100453/1925BA04"
        },
        [10045307] = {
          Content = "嘿嘿，比起你我还差得远啦。并且，我已经遇到了这么好的狩月人队友，是不会成为其他皎皎啦。",
          ContentKR = "헤헤, 선배에 비하면 난 아직 멀었지! 그리고, 이렇게 좋은 월석 사냥꾼 친구들을 만났으니까, 난 지금 이대로가 좋은 것 같아.",
          DialogueId = 10045307,
          GUID = "1925BA2E",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100453/1925BA2E"
        },
        [10045308] = {
          Content = "对哦，那我就祝你们一路顺风啦，等你们再从迪斯玛尼亚回来的时候，记得告诉我迪斯玛尼亚到底是什么样！",
          ContentKR = "하긴 그러네. 그럼 다들 조심히 잘 다녀와! 나중에 돌아오면, 디즈마니아는 어떤 곳이었는지 꼭 얘기해 줘야 해!",
          DialogueId = 10045308,
          GUID = "1925BA58",
          SpeakNpcId = 100405,
          VoiceName = "voice/$Locale$/story/1004/100453/1925BA58"
        },
        [10045309] = {
          Content = "好！",
          ContentKR = "응!",
          DialogueId = 10045309,
          GUID = "1925BA82",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100453/1925BA82"
        },
        [10045310] = {
          Content = "您好，列车马上就要出发了，请进到车厢内，坐到对应的座位上。",
          ContentKR = "승객 여러분, 열차가 곧 출발합니다. 가지고 계신 승차권을 확인하신 후, 서둘러 승차하시기 바랍니다.",
          DialogueId = 10045310,
          GUID = "1925BAAC",
          SpeakNpcId = 100445,
          VoiceName = "voice/$Locale$/story/1004/100453/1925BAAC"
        },
        [10045311] = {
          Content = "要发车了，走吧。",
          ContentKR = "출발하려나 봐, 얼른 타자.",
          DialogueId = 10045311,
          GUID = "1925BAD6",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100453/1925BAD6"
        },
        [10045312] = {
          Content = "从刚刚开始你就一言不发……身体不要紧吗？毕竟昨晚几乎一夜没睡。",
          ContentKR = "아까부터 조용하네... 컨디션은 좀 어때? 어젯밤에 거의 한숨도 못 잤잖아.",
          DialogueId = 10045312,
          GUID = "1925BB00",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100453/1925BB00"
        },
        [10045313] = {
          Content = "没事，你不也一夜没睡，没什么的。我只是在心里预演着我们的计划，还是有一些担心。",
          ContentKR = "괜찮아. 너도 잠 설친 건 마찬가지잖아. 그냥, 아무래도 마음이 안 놓여서, 머릿속으로 우리 계획을 실행해 보고 있었어.",
          DialogueId = 10045313,
          GUID = "1925BB2A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100453/1925BB2A"
        },
        [10045314] = {
          Content = "我也在担心……不如我们再核对一遍吧，记得越熟悉，心里就越踏实。",
          ContentKR = "마음이 안 놓이긴 하지... 차라리 다시 한번 계획을 맞춰 보자. 완벽하게 기억해 둘수록, 덜 불안할 거 아냐.",
          DialogueId = 10045314,
          GUID = "1925BB54",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100453/1925BB54"
        },
        [10045315] = {
          Content = "我们的目标是把芙罗拉从她的专列寒鸦号上救出。",
          ContentKR = "우리 목표는, 플로라를 갈까마귀호에서 빼내는 거야.",
          DialogueId = 10045315,
          GUID = "1925BB7E",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100453/1925BB7E"
        },
        [10045401] = {
          Content = "我们的目标是把芙罗拉小姐从十三军团专列寒鸦号上救出来，但是想要达成这件事，我们会面临以下几个困难。",
          ContentKR = "우리의 목표는 플로라 아가씨를 제13군단 전용 열차, 갈까마귀호에서 구출하는 겁니다. 그렇지만 당장 몇 가지 걸림돌이 있어요.",
          DialogueId = 10045401,
          GUID = "1925C99A",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 403011,
            [3] = 201033,
            [4] = 201031,
            [5] = 201030
          },
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100454/1925C99A"
        },
        [10045402] = {
          Content = "首先，是如何上车。艾森巴恩对于列车的监视，你们今天已经见识过了。明天他想必不会给你们任何靠近的机会。",
          ContentKR = "첫 번째는 어떻게 타느냐예요. 오늘 보셔서 아시겠지만, 아이젠반이 열차를 삼엄하게 감시하고 있어요. 내일은 여러분이 접근조차 하지 못하게 막아서겠죠.",
          DialogueId = 10045402,
          GUID = "1925C9C4",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100454/1925C9C4"
        },
        [10045403] = {
          Content = "其次是车上的士兵，本来寒鸦号上就已经载满了十三军团的士兵，而因为神弃者同盟的袭击，艾森巴恩还把其他列车的警卫抽调了过去。",
          ContentKR = "두 번째는 열차 내부의 병력이에요. 원래 갈까마귀호에 타고 있던 제13군단의 병사들도 수가 만만치 않지만, 포세이큰 동맹의 습격으로, 아이젠반이 다른 열차의 경비병들까지 차출해 탑승시켰어요.",
          DialogueId = 10045403,
          GUID = "1925C9EE",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100454/1925C9EE"
        },
        [10045404] = {
          Content = "哪怕个人的武力再强大，也难以对付这个数目的敌人。",
          ContentKR = "아무리 실력이 좋아도, 그 많은 병사들을 상대하는 건 힘들다고 봐야 해요.",
          DialogueId = 10045404,
          GUID = "1925CA18",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CA18"
        },
        [10045405] = {
          Content = "最后，则是怎么离开：即便可以混进列车，并且抵达芙罗拉小姐所在的车厢，在离开时也同样需要面对艾森巴恩手下的卫兵们。",
          ContentKR = "마지막은 탈출 방법이에요. 어찌어찌 아가씨께서 계신 칸에 도달한다 쳐도, 탈출할 때는 아이젠반의 부하들을 상대해야 할 테니까요.",
          DialogueId = 10045405,
          GUID = "1925CA42",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CA42"
        },
        [10045406] = {
          Content = "最后一个问题，我倒是有个大胆的想法。",
          ContentKR = "마지막 문제라면, 나한테 화끈한 아이디어가 하나 있어.",
          DialogueId = 10045406,
          GUID = "1925CA6C",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CA6C"
        },
        [10045407] = {
          Content = "之前教你的<H>钩索</>，你应该已经很熟练了吧。刚好，黎瑟之前留给我们一副机动性更强的钩索。",
          ContentKR = "전에 가르쳐 준 적 있으니까, 이젠 <H>갈고리</> 잘 쓰지? 리듬이, 전에 쓰던 갈고리보다 기동성이 훨씬 끝내주는 걸 하나 남겨두고 갔거든.",
          DialogueId = 10045407,
          GUID = "1925CA96",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CA96"
        },
        [10045408] = {
          Content = "你的意思是……你们其中一人，带着芙罗拉小姐直接利用钩索跳车，摆脱追兵？",
          ContentKR = "그러니까... 둘 중 한 분이 아가씨를 모시고, 갈고리를 사용해 열차 밖으로 뛰어내려서, 추격자를 따돌리시겠단 건가요?",
          DialogueId = 10045408,
          GUID = "1925CAC0",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CAC0"
        },
        [10045409] = {
          Content = "没错。迪斯玛尼亚车站守备森严，相比冰湖城恐怕有过之而无不及。所以唯一能逃走的“空隙”，只有列车行驶过程中。",
          ContentKR = "그래. 디즈마니아에 있는 기차역은 여기보다 경비가 훨씬 삼엄할 거 아냐. 결국 우리가 도망칠 수 있는 '빈틈'은, 기차가 달리고 있을 때밖에 없어.",
          DialogueId = 10045409,
          GUID = "1925CAEA",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CAEA"
        },
        [10045410] = {
          Content = "有些冒险。但……的确是唯一的方式了。",
          ContentKR = "무모한 도박이지만... 지금으로선 달리 방법이 없군요.",
          DialogueId = 10045410,
          GUID = "1925CB14",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CB14"
        },
        [10045411] = {
          Content = "但怎么登上一辆无法靠近的车……确实有点头疼。",
          ContentKR = "그런데 근처에도 못 가는 기차에 어떻게 올라타느냐가 문제야... 골치 아프네.",
          DialogueId = 10045411,
          GUID = "1925CB3E",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CB3E"
        },
        [10045412] = {
          Content = "能藏在车底或者车顶吗？等到列车开动后再跳进车厢。",
          ContentKR = "기차 밑이나 지붕에 숨어 있는 건 어떨까? 출발하고 나면 객차 안으로 들어가는 거지.",
          DialogueId = 10045412,
          GUID = "1925CB68",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CB68"
        },
        [10045413] = {
          Content = "恐怕不能。艾森巴恩一定会在发车前做彻底的检查。",
          ContentKR = "그건 불가능할 거예요. 아이젠반이 열차를 출발시키기 전에 샅샅이 수색할 테니까요.",
          DialogueId = 10045413,
          GUID = "1925CB92",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CB92"
        },
        [10045414] = {
          Content = "而且在发车前去靠近寒鸦号几乎是不可能的。",
          ContentKR = "갈까마귀호에 접근하고 싶다면, 열차가 출발하기 전에는 불가능하다고 봐야 해.",
          DialogueId = 10045414,
          GUID = "1925CBBC",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CBBC"
        },
        [10045415] = {
          Content = "那么反过来，也就是说，在离开百花车站后，登上寒鸦号反倒要容易许多。",
          ContentKR = "바꿔 말하면, 일단 기차가 블룸필드역을 빠져나가기만 하면, 갈까마귀호에 올라타기 훨씬 수월하다는 거잖아.",
          DialogueId = 10045415,
          GUID = "1925CBE6",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CBE6"
        },
        [10045416] = {
          Content = "但艾森巴恩有吩咐过，明天寒鸦号前往迪斯玛尼亚将不停靠任何站台，直接抵达。而想要靠近一辆正在运行的火车，也毫无疑问是自杀行为。",
          ContentKR = "그렇지만 아이젠반은 내일 갈까마귀호는 중간 정차 없이 디즈마니아로 직행한다고 못 박아 뒀어요. 달리는 열차에 맨몸으로 뛰어오르겠다는 건, 자살 행위나 다름없어요.",
          DialogueId = 10045416,
          GUID = "1925CC10",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CC10"
        },
        [10045417] = {
          Content = "唔，好苦恼。我说，小仆从，要不今晚我们练一练跑步吧，要是跑得和火车差不多快的话，就能登上寒鸦号了。",
          ContentKR = "으, 머리 아파. 있잖아, 시종, 우리 오늘 밤에 달리기 특훈이라도 하자. 기차만큼 빨리 달릴 수 있게 되면, 갈까마귀호에 올라탈 수 있을 거야.",
          DialogueId = 10045417,
          GUID = "1925CC3A",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CC3A"
        },
        [10045418] = {
          Content = "别说傻话，白。{nickname}确实跳得高跑得快，但比起火车来还是差上不少。这个世界上和火车跑得差不多快的东西除了飞艇以外，就只有火车自己。",
          ContentKR = "무슨 바보 같은 소리를 해, 스노우. {nickname} 얘가 아무리 날고 기어도, 달리는 기차를 어떻게 따라잡겠냐. 이 세상에서 기차만큼 빠른 건, 비행선 아니면 다른 기차밖에 없다고.",
          DialogueId = 10045418,
          GUID = "1925CC64",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CC64"
        },
        [10045419] = {
          Content = "这个世界上和火车跑得差不多快的东西是火车自己……",
          ContentKR = "이 세상에서 기차만큼 빠른 건, 비행선 아니면 다른 기차밖에 없긴 하지...",
          DialogueId = 10045419,
          GUID = "1925CC8E",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CC8E"
        },
        [10045420] = {
          Content = "明天寒鸦号九点发车，有没有比这个时间点早一些的车次？",
          ContentKR = "내일 갈까마귀호는 오전 9시에 출발해. 그거보다 일찍 출발하는 열차는 없어?",
          DialogueId = 10045420,
          GUID = "1925CCB8",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CCB8"
        },
        [10045421] = {
          Content = "似乎有一班，是开去……",
          ContentKR = "한 대 있을 거예요. 아마 목적지가...",
          DialogueId = 10045421,
          GUID = "1925CCE2",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CCE2"
        },
        [10045422] = {
          Content = "八点开往迪斯玛尼亚的普通速度列车，每一站都停，白可是记得一清二楚。",
          ContentKR = "8시에 디즈마니아로 가는 일반 열차야. 역마다 정차해. 스노우가 똑똑히 기억한다고.",
          DialogueId = 10045422,
          GUID = "1925CD0C",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CD0C"
        },
        [10045423] = {
          Content = "好，那就坐这一班了。至于车票——",
          ContentKR = "좋아, 그럼 그거 타자. 표는...",
          DialogueId = 10045423,
          GUID = "1925CD36",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CD36"
        },
        [10045424] = {
          Content = "包在我身上，我会提前准备好。",
          ContentKR = "제가 구해 두죠. 맡겨 주세요.",
          DialogueId = 10045424,
          GUID = "1925CD60",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CD60"
        },
        [10045425] = {
          Content = "好，我去求卡米拉，这几天菲娜就拜托她照顾。",
          ContentKR = "알겠어. 그럼 난 카밀라한테 가서 며칠만 피나 좀 챙겨달라고 부탁하고 올게.",
          DialogueId = 10045425,
          GUID = "1925CD8A",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CD8A"
        },
        [10045426] = {
          Content = "诶？怎么回事？怎么突然就决定了？",
          ContentKR = "어? 뭔데, 뭔데? 갑자기 뭐가 막 진행되는 거야?",
          DialogueId = 10045426,
          GUID = "1925CDB4",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CDB4"
        },
        [10045427] = {
          Content = "既然艾森巴恩说了寒鸦号不会停靠任何站台，全速前进，那么就意味着它会超过比它更慢的普通列车。",
          ContentKR = "아이젠반이 갈까마귀호는 중간 정차 없이 쭉 목적지까지 간다고 했잖아. 그 얘긴 갈까마귀호가 먼저 출발한 일반 열차를 무조건 추월하게 돼 있다는 거지.",
          DialogueId = 10045427,
          GUID = "1925CDDE",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CDDE"
        },
        [10045428] = {
          Content = "而我们只要坐上这列普通列车，等到寒鸦号即将超过它，并排行驶的时候，用黎瑟给的钩索跳到寒鸦号上，就可以尽量避免和军团的士兵战斗。",
          ContentKR = "그러면 우린 그 일반 열차에 타고 있다가, 갈까마귀호랑 나란히 달리는 순간, 리듬한테 받은 갈고리를 써서 그쪽 열차로 건너가면 돼. 그래야 병사들과의 전투를 최대한 피할 수 있어.",
          DialogueId = 10045428,
          GUID = "1925CE08",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CE08"
        },
        [10045429] = {
          Content = "所以，我们的计划应该是……",
          ContentKR = "그러니까, 우리 작전을 정리해 보면...",
          DialogueId = 10045429,
          GUID = "1925CE32",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100454/1925CE32"
        },
        [10045501] = {
          Content = "从普通列车跳上寒鸦号，找到芙罗拉的车厢，然后带着她跳到另一辆列车上，混进人群中，尽快下车。",
          ContentKR = "일반 열차에서 갈까마귀호로 건너간 다음에, 플로라가 타고 있는 열차 칸을 찾고, 거기서 플로라를 데리고 나와서 다른 열차로 건너간 다음에, 인파 속에 섞여서 최대한 빨리 내리는 거야.",
          DialogueId = 10045501,
          GUID = "1925DA02",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100455/1925DA02"
        },
        [10045502] = {
          Content = "步骤没错，接下来，就要看你的身手如何了。",
          ContentKR = "순서는 완벽하네. 그럼, 이제 실력 한번 보여봐!",
          DialogueId = 10045502,
          GUID = "1925DA2C",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100455/1925DA2C"
        },
        [10045503] = {
          Content = "我相信{nickname}，一定没问题的！",
          ContentKR = "난 {nickname} 믿어! 무조건 해낼 거야!",
          DialogueId = 10045503,
          GUID = "1925DA56",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100455/1925DA56"
        },
        [10045504] = {
          Content = "我也没说不相信，今天晚饭吃什么我都想好了，就等着{性别：他|她}回来呢。",
          ContentKR = "누가 못 믿는대? 난 오늘 저녁에 뭐 먹을지도 다 생각해 놨다고. 우리 친구만 무사히 돌아오면 돼.",
          DialogueId = 10045504,
          GUID = "1925DA80",
          SpeakNpcId = 100401,
          VoiceName = "voice/$Locale$/story/1004/100455/1925DA80"
        },
        [10045505] = {
          Content = "嗯，别太担心。",
          ContentKR = "응, 너무 걱정하지 마.",
          DialogueId = 10045505,
          GUID = "1925DAAA",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100455/1925DAAA"
        },
        [10045601] = {
          Content = "总算要离开冰湖城回迪斯玛尼亚了。真冷啊冰湖城，我感觉整个人都冻瘦了一圈，骨头都脆了。",
          ContentKR = "드디어 디즈마니아로 가는군요. 아이스레이크 시티에선 어찌나 춥던지, 뼈마디가 뚝뚝 끊어지는 것 같더군요.",
          DialogueId = 10045601,
          GUID = "1925EA6A",
          SpeakNpcId = 100408,
          VoiceName = "voice/$Locale$/story/1004/100456/1925EA6A"
        },
        [10045602] = {
          Content = "别放松，说了多少次了，我们在执行重要任务，在抵达迪斯玛尼亚之前，不能放松警惕。",
          ContentKR = "긴장 풀지 마라. 몇 번을 말했나. 우리는 지금 중요한 임무 중이다. 디즈마니아에 도착할 때까지, 절대 방심하지 마.",
          DialogueId = 10045602,
          GUID = "1925EA94",
          SpeakNpcId = 100424,
          VoiceName = "voice/$Locale$/story/1004/100456/1925EA94"
        },
        [10045603] = {
          Content = "可是长官，我看她们也很放松，应该不会有什么事了吧。",
          ContentKR = "그렇지만, 저렇게 한가하게 차나 마시고 있는데, 무슨 일이 생기겠습니까?",
          DialogueId = 10045603,
          GUID = "1925EABE",
          SpeakNpcId = 100408,
          VoiceName = "voice/$Locale$/story/1004/100456/1925EABE"
        },
        [10045604] = {
          Content = "这是来自华胥的五窨一提的花茶，之前试过七窨的，你说香味太过。",
          ContentKR = "이건 화서에서 들여온 꽃차예요. 꽃향을 다섯 번 입힌 거죠. 일곱 번 입혔던 건, 향이 너무 진하다고 하셔서요.",
          DialogueId = 10045604,
          GUID = "1925EAE8",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100456/1925EAE8"
        },
        [10045701] = {
          Content = "殿下，我见过好多人喝茶的时候，都恨不得把茶的产地啊价格啊写在脸上。",
          ContentKR = "공주님, 그동안 제가 본 사람들은, 차를 마실 때 원산지나 값을 들먹이며 생색내는 걸 좋아했어요.",
          DialogueId = 10045701,
          GUID = "1925FAD2",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100457/1925FAD2"
        },
        [10045702] = {
          Content = "但你无所谓这些，只是把它们当做普通的物件去对待。",
          ContentKR = "하지만 공주님께선 눈앞의 대상을 있는 그대로 대해 주세요.",
          DialogueId = 10045702,
          GUID = "1925FAFC",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100457/1925FAFC"
        },
        [10045703] = {
          Content = "谢谢你，希尔妲。虽然我知道你是在夸我，但你也知道，我一直在迪斯玛尼亚的宫殿里，并不会去和人比较什么。",
          ContentKR = "고마워, 힐다. 듣기 좋은 말을 해 주려는 건 알겠지만, 알다시피 난 디즈마니아의 황궁에서만 지내서, 남들과 뭔가를 비교할 기회조차 없었을 뿐이야.",
          DialogueId = 10045703,
          GUID = "1925FB26",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100457/1925FB26"
        },
        [10045704] = {
          Content = "到了冰湖城后，我才知道这个世界和书本上读到的有多么不一样，它美丽，却又冰冷。",
          ContentKR = "아이스레이크 시티에 와서야 알았어. 책으로만 보던 세상과 진짜 세상은 너무 다르더라. 아름다우면서도, 시릴 만큼 차가워.",
          DialogueId = 10045704,
          GUID = "1925FB50",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100457/1925FB50"
        },
        [10045705] = {
          Content = "好啦好啦，喝杯茶，吃一块蛋糕，暖暖身子。",
          ContentKR = "네, 알겠어요. 우선 이 차랑 케이크를 좀 드시면서, 몸을 좀 녹이세요.",
          DialogueId = 10045705,
          GUID = "1925FB7A",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100457/1925FB7A"
        },
        [10045706] = {
          Content = "你还是那么喜欢绘画。让我来看看你从刚刚开始都在画些什么……",
          ContentKR = "여전히 그림 그리는 걸 좋아하시네요. 아까부터 뭘 그리고 계셨는지 보여 주세요...",
          DialogueId = 10045706,
          GUID = "1925FBA4",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100457/1925FBA4"
        },
        [10045707] = {
          Content = "是夜空啊。",
          ContentKR = "밤하늘이군요...",
          DialogueId = 10045707,
          GUID = "1925FBCE",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100457/1925FBCE"
        },
        [10045708] = {
          Content = "嗯，夜空，北方的星空，那些在迪斯玛尼亚看到的亮星要更矮一些。",
          ContentKR = "응, 밤하늘이야. 별이 가득한 북쪽의 밤하늘. 디즈마니아에서 보던 별들보다 훨씬 낮게 떠 있지.",
          DialogueId = 10045708,
          GUID = "1925FBF8",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100457/1925FBF8"
        },
        [10045709] = {
          Content = "星星很美，它们每天都俯视着我们，一动也不动。",
          ContentKR = "별들은 참 아름다워. 매일 같은 곳에서, 변함없는 모습으로 우리를 굽어보니까.",
          DialogueId = 10045709,
          GUID = "1925FC22",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100457/1925FC22"
        },
        [10045710] = {
          Content = "那么……接下来，我还要画一轮月亮。",
          ContentKR = "이제... 여기에 달도 하나 그려 넣어야겠어.",
          DialogueId = 10045710,
          GUID = "1925FC4C",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100457/1925FC4C"
        },
        [10045711] = {
          Content = "期待成品，芙罗拉小姐。不过，我还是希望您先把蛋糕吃掉，毕竟，接下来你还有事要做。",
          ContentKR = "어떻게 완성될지 기대되네요, 아가씨. 그래도, 일단 이 케이크부터 다 드세요. 아직 해야 할 일이 있으시니까요.",
          DialogueId = 10045711,
          GUID = "1925FC76",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100457/1925FC76"
        },
        [10045712] = {
          Content = "……该准备应付眼前的事了。",
          ContentKR = "...곧 일어날 일을 맞이하셔야 하고요.",
          DialogueId = 10045712,
          GUID = "1925FCA0",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100457/1925FCA0"
        },
        [10045801] = {
          Content = "车顶什么声音？去确认一下。",
          ContentKR = "지붕 쪽에 무슨 소리지? 가서 확인해 봐.",
          DialogueId = 10045801,
          GUID = "19260B3A",
          SpeakNpcId = 100424,
          VoiceName = "voice/$Locale$/story/1004/100458/19260B3A"
        },
        [10045802] = {
          Content = "有入侵者，在车顶！",
          ContentKR = "침입자입니다! 지붕 위입니다!",
          DialogueId = 10045802,
          GUID = "19260B64",
          SpeakNpcId = 100408,
          VoiceName = "voice/$Locale$/story/1004/100458/19260B64"
        },
        [10045803] = {
          Content = "啊——",
          ContentKR = "으악!",
          DialogueId = 10045803,
          GUID = "19260B8E",
          SpeakNpcId = 100408,
          VoiceName = "voice/$Locale$/story/1004/100458/19260B8E"
        },
        [10045804] = {
          Content = "该死的，是神弃者同盟吗？不长眼的家伙真的到我们十三军团头上撒野了。",
          ContentKR = "젠장, 포세이큰 동맹인가? 우리 제13군단을 노리다니, 겁대가리를 상실했나 보군.",
          DialogueId = 10045804,
          GUID = "19260BB8",
          SpeakNpcId = 100424,
          VoiceName = "voice/$Locale$/story/1004/100458/19260BB8"
        },
        [10045805] = {
          Content = "都跟我来，留一个人通知其他车厢的士兵。",
          ContentKR = "전원 따라와! 한 명은 남아서 다른 객차에 상황을 알려라.",
          DialogueId = 10045805,
          GUID = "19260BE2",
          SpeakNpcId = 100424,
          VoiceName = "voice/$Locale$/story/1004/100458/19260BE2"
        },
        [10045806] = {
          Content = "是，长官。",
          ContentKR = "네! 알겠습니다!",
          DialogueId = 10045806,
          GUID = "19260C0C",
          SpeakNpcId = 100410,
          VoiceName = "voice/$Locale$/story/1004/100458/19260C0C"
        },
        [10045807] = {
          Content = "联系车长，联系车长，有紧急情况。",
          ContentKR = "차장 응답 바람! 차장 응답 바람! 지붕 위에 긴급 상황 발생!",
          DialogueId = 10045807,
          GUID = "19260C36",
          SpeakNpcId = 100410,
          VoiceName = "voice/$Locale$/story/1004/100458/19260C36"
        },
        [10045901] = {
          Content = "什么情况，什么情况，请讲。",
          ContentKR = "입감 완료, 여기는 차장, 상황 설명 바람.",
          DialogueId = 10045901,
          GUID = "19261BA2",
          SpeakNpcId = 100425,
          VoiceName = "voice/$Locale$/story/1004/100459/19261BA2"
        },
        [10045902] = {
          Content = "是这样的，芙罗蒂娅殿下很喜欢外面的风景，能不能，让列车的速度稍微降下来一些。",
          ContentKR = "다름이 아니라, 플로렌티아 전하께서 창밖의 풍경을 무척 마음에 들어 하십니다. 열차 속도를 조금 늦춰 주시길 바랍니다.",
          DialogueId = 10045902,
          GUID = "19261BCC",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100459/19261BCC"
        },
        [10045903] = {
          Content = "啊……这有些难办啊，毕竟我们收到的命令是尽快抵达皇都。",
          ContentKR = "아... 저희는 최대한 빨리 황성으로 진입하라는 명령을 받아서, 그건 곤란합니다.",
          DialogueId = 10045903,
          GUID = "19261BF6",
          SpeakNpcId = 100425,
          VoiceName = "voice/$Locale$/story/1004/100459/19261BF6"
        },
        [10045904] = {
          Content = "那好吧，打扰了。",
          ContentKR = "어쩔 수 없군요, 실례했습니다.",
          DialogueId = 10045904,
          GUID = "19261C20",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100459/19261C20"
        },
        [10045905] = {
          Content = "殿下能理解我们的苦衷就好，我们也是奉命——",
          ContentKR = "공주 전하께서 저희의 고충을 헤아려 주신다니 다행입니다. 저희도 명을 받고...",
          DialogueId = 10045905,
          GUID = "19261C4A",
          SpeakNpcId = 100425,
          VoiceName = "voice/$Locale$/story/1004/100459/19261C4A"
        },
        [10045906] = {
          Content = "呼——这下就不用担心再有更多士兵赶来了。",
          ContentKR = "휴... 이제 다른 객차에서 병사들이 몰려올 걱정은 없겠죠.",
          DialogueId = 10045906,
          GUID = "19261C74",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100459/19261C74"
        },
        [10045907] = {
          Content = "但也已经有一些士兵到车顶了，希尔妲，你去帮一把吧。",
          ContentKR = "하지만 몇 명이 이미 지붕 위로 올라갔어. 힐다, 가서 그분을 지원해 드리도록 해.",
          DialogueId = 10045907,
          GUID = "19261C9E",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100459/19261C9E"
        },
        [10045908] = {
          Content = "不用您特意吩咐，我确实有这个打算。他们一直对您只有口头上的尊重，可能完全没想过有一天，看似屈服于命运的囚徒会想要去击碎牢笼吧。",
          ContentKR = "말씀 안 하셔도 그럴 생각이었답니다. 병사들은 겉으로만 공주 전하를 떠받들었지, 속으론 그저 운명에 순응하는 죄수로 취급했을 거예요. 언젠가 새장을 부수고 날아오를 날이 올 거라곤 상상도 못 했겠죠.",
          DialogueId = 10045908,
          GUID = "19261CC8",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100459/19261CC8"
        },
        [10046001] = {
          Content = "几乎一夜没睡，还能成功跳到寒鸦号，还能打晕这么多士兵。我真庆幸你是来帮助芙罗拉小姐的。",
          ContentKR = "잠도 거의 못 주무셨을 텐데, 무사히 갈까마귀호로 넘어와서 이렇게 많은 병사들까지 처리하셨군요. 플로라 아가씨를 돕겠다고 해 주셔서 정말 다행이에요.",
          DialogueId = 10046001,
          GUID = "19262C0A",
          RelatedWikiId = {
            [1] = 201033,
            [2] = 201031
          },
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100460/19262C0A"
        },
        [10046002] = {
          Content = "谢谢夸奖，多少有点侥幸，刚刚要不是你帮忙，我可能已经没命了。",
          ContentKR = "고마워, 사실 운이 좋았던 거야. 아까 힐다가 도와주지 않았다면, 큰일 날 뻔했거든.",
          DialogueId = 10046002,
          GUID = "19262C34",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100460/19262C34"
        },
        [10046003] = {
          Content = "不用这么谦虚，我确实是非常认真地在夸奖你。",
          ContentKR = "겸손해하지 않으셔도 돼요. 진심으로 드리는 말씀이니까요.",
          DialogueId = 10046003,
          GUID = "19262C5E",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100460/19262C5E"
        },
        [10046004] = {
          Content = "在一开始芙罗拉小姐想要和你们合作的时候，我感觉她像是一个溺水的人，抓住面前的任何事物，哪怕是一束水草。",
          ContentKR = "처음에 아가씨께서 여러분과 손을 잡고 싶다고 하셨을 땐, 지푸라기라도 잡는 심정으로, 아무나 잡고 매달리시는구나 싶었거든요.",
          DialogueId = 10046004,
          GUID = "19262C88",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100460/19262C88"
        },
        [10046005] = {
          Content = "但此时此刻，我必须真诚地感谢你，并且毫无保留地相信你。接下来芙罗拉小姐就要托付给你了，你一定要把她带到安全的地方，重新获得自由。",
          ContentKR = "하지만 이젠 진심으로 감사드려야겠네요. 앞으론 당신을 백 퍼센트 믿을 테니, 지금부터 플로라 아가씨를 잘 부탁드려요. 반드시 안전한 곳까지 모시고 가서, 자유를 되찾아 드리세요.",
          DialogueId = 10046005,
          GUID = "19262CB2",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100460/19262CB2"
        },
        [10046006] = {
          Content = "我从成为芙罗拉小姐的女仆到现在，几乎没有和她分开过，哪怕是被军团的人抓到的时候，也是一样。",
          ContentKR = "전 아가씨를 모시기 시작하고 나서부터 지금까지, 단 한 번도 그분 곁을 떠난 적이 없어요. 아가씨께서 군단 녀석들에게 붙잡혀 계실 때도 그랬죠.",
          DialogueId = 10046006,
          GUID = "19262CDC",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100460/19262CDC"
        },
        [10046007] = {
          Content = "唯独这一次，我希望她能离开我，离开这个车厢，越远越好。",
          ContentKR = "그렇지만 이번만큼은 아가씨께서 저한테서, 그리고 이 열차에서 최대한 멀리 떠나 주셨으면 해요.",
          DialogueId = 10046007,
          GUID = "19262D06",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100460/19262D06"
        },
        [10046008] = {
          Content = "你不一起跟来吗？",
          ContentKR = "힐다는 같이 안 갈 거야?",
          DialogueId = 10046008,
          GUID = "19262D30",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100460/19262D30"
        },
        [10046009] = {
          Content = "车厢里还有被我打晕的帝国士兵，我需要把他藏起来。然后我要易容成芙罗拉小姐的模样，去尽可能让这列寒鸦号上的人晚一点发现芙罗拉小姐已经逃脱。",
          ContentKR = "일단 이 아래 쓰러져 있는 제국 병사들부터 숨긴 다음에, 제가 플로라 아가씨로 변장해서 시간을 벌어 볼게요. 갈까마귀호의 병사들이 아가씨가 탈출하셨다는 사실을 최대한 늦게 알아채도록 해야 해요.",
          DialogueId = 10046009,
          GUID = "19262D5A",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100460/19262D5A"
        },
        [10046010] = {
          Content = "可是这样你该怎么逃出去？",
          ContentKR = "그러면 힐다 넌 어떻게 이 열차에서 탈출해?",
          DialogueId = 10046010,
          GUID = "19262D84",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100460/19262D84"
        },
        [10046011] = {
          Content = "别担心，既然我能成功协助芙罗拉小姐逃离皇宫，那么就也能成功安全离开这辆列车。",
          ContentKR = "걱정 마세요. 플로라 아가씨께서 황궁 밖으로 도망치실 수 있게 도운 건 바로 저니까요. 이런 열차에서 빠져나가는 정도는 아무 문제도 없어요.",
          DialogueId = 10046011,
          GUID = "19262DAE",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100460/19262DAE"
        },
        [10046012] = {
          Content = "好，既然你相信我，那我也同样选择相信你。",
          ContentKR = "알겠어. 힐다가 날 믿고 맡겨 줬으니까, 나도 힐다를 믿을게.",
          DialogueId = 10046012,
          GUID = "19262DD8",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100460/19262DD8"
        },
        [10046013] = {
          Content = "那是自然，毕竟我是无所不能的女仆。",
          ContentKR = "당연히 그러셔야죠. 저는 만능 메이드랍니다.",
          DialogueId = 10046013,
          GUID = "19262E02",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100460/19262E02"
        },
        [10046014] = {
          Content = "芙罗拉小姐，车顶已经安全了，那么接下来，你就和{nickname}一起行动吧。",
          ContentKR = "플로라 아가씨, 지붕 쪽은 이제 안전해요. 지금부터는 {nickname} 씨와 함께 움직이시면 돼요.",
          DialogueId = 10046014,
          GUID = "19262E2C",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100460/19262E2C"
        },
        [10046015] = {
          Content = "我已经和{性别：他|她}吩咐过，让{性别：他|她}一定要带你获得自由，否则我不会轻饶他。",
          ContentKR = "제가 이 {性别:신사|숙녀}분께, 공주님을 자유롭게 해 드리지 못하면, 절대로 가만두지 않겠다고 신신당부해 뒀어요.",
          DialogueId = 10046015,
          GUID = "19262E56",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100460/19262E56"
        },
        [10046016] = {
          Content = "……好，你在下面应付一阵后也不要待太久，一定一定要活下来。",
          ContentKR = "...알겠어. 적당히 수습하고 빠져나오도록 해. 무슨 일이 있어도, 살아 돌아와.",
          DialogueId = 10046016,
          GUID = "19262E80",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100460/19262E80"
        },
        [10046017] = {
          Content = "这既是我作为主人的命令，也是作为朋友的恳求。",
          ContentKR = "이건 주인으로서 내리는 명령이자, 친구로서 하는 부탁이야.",
          DialogueId = 10046017,
          GUID = "19262EAA",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100460/19262EAA"
        },
        [10046018] = {
          Content = "我明白，芙罗拉。",
          ContentKR = "명심할게요, 플로라.",
          DialogueId = 10046018,
          GUID = "19262ED4",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100460/19262ED4"
        },
        [10046019] = {
          Content = "又有一辆普通列车来了，那么煽情就到此为止吧，这里并不是上演分别戏码的列车站台，你们准备走吧。",
          ContentKR = "일반 열차가 한 대 더 오고 있으니, 신파극은 여기서 마무리 짓도록 하죠. 기차역 승강장도 아닌데, 작별 인사는 어울리지 않아요. 자, 이제 준비하세요.",
          DialogueId = 10046019,
          GUID = "19262EFE",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100460/19262EFE"
        },
        [10046020] = {
          Content = "再见，万能女仆。",
          ContentKR = "또 만나, 만능 메이드 씨.",
          DialogueId = 10046020,
          GUID = "19262F28",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100460/19262F28"
        },
        [10046101] = {
          Content = "……",
          ContentKR = "......",
          DialogueId = 10046101,
          GUID = "19263C72",
          RelatedWikiId = {
            [1] = 201033,
            [2] = 201031
          },
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100461/19263C72"
        },
        [10046102] = {
          Content = "芙罗拉，你没事吧。",
          ContentKR = "플로라 씨, 괜찮아요?",
          DialogueId = 10046102,
          GUID = "19263C9C",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100461/19263C9C"
        },
        [10046103] = {
          Content = "我还好，只是……这是什么地方?",
          ContentKR = "괜찮아요. 그렇지만... 여긴 어디죠?",
          DialogueId = 10046103,
          GUID = "19263CC6",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100461/19263CC6"
        },
        [10046104] = {
          Content = "为什么还有老鼠……",
          ContentKR = "쥐가 돌아다니고 있는데...",
          DialogueId = 10046104,
          GUID = "19263CF0",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100461/19263CF0"
        },
        [10046105] = {
          Content = "在这“老鼠罐头”里有老鼠岂不是很正常，大惊小怪。",
          ContentKR = "'생쥐 통조림'에 쥐 새끼 돌아다니는 게 뭔 대수라고 난리들이야.",
          DialogueId = 10046105,
          GUID = "19263D1A",
          SpeakNpcId = 100426,
          VoiceName = "voice/$Locale$/story/1004/100461/19263D1A"
        },
        [10046106] = {
          Content = "“老鼠罐头”？",
          ContentKR = "'생쥐 통조림'이요?",
          DialogueId = 10046106,
          GUID = "19263D44",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100461/19263D44"
        },
        [10046107] = {
          Content = "怎么？这都没听说过？“老鼠罐头”指的就是这列车的最后一节，票价最便宜，但也最为简陋，没有服务，没有桌椅。大家就像是被装进罐头的老鼠。",
          ContentKR = "왜? 처음 들어 봐? '생쥐 통조림'은 이 기차의 꼬리칸 말하는 거야. 푯값이 제일 싼 대신, 의자고 뭐고 없는 깡통이나 다름없지. 여기 승객들은 그 깡통에 처박힌 생쥐 새끼들이고.",
          DialogueId = 10046107,
          GUID = "19263D6E",
          RelatedWikiId = {
            [1] = 405017
          },
          SpeakNpcId = 100426,
          VoiceName = "voice/$Locale$/story/1004/100461/19263D6E"
        },
        [10046108] = {
          Content = "是了，看你们俩就没怎么挨过饿，尤其是这个小妮子，身上的衣服可能比我的命都贵。我刚还以为是哪个不要命的穷鬼，敢扒在车顶上逃票。",
          ContentKR = "모를 만도 하겠네, 너희는 배곯아 본 적도 없는 것 같거든. 게다가 저 아가씨가 입고 있는 옷만 해도 내 목숨값보다 비싸겠어. 난 또 어느 정신 나간 거렁뱅이가, 푯값 안 내겠다고 지붕에 매달려 왔나 했네.",
          DialogueId = 10046108,
          GUID = "19263D98",
          SpeakNpcId = 100426,
          VoiceName = "voice/$Locale$/story/1004/100461/19263D98"
        },
        [10046109] = {
          Content = "现在看来，你们八成是一对从头等车厢的车顶逃过来，打算私奔的苦命鸳鸯。",
          ContentKR = "지금 보니까 그게 아니라, 사랑의 도피를 한답시고 일등석 열차칸에서 몰래 도망쳐 온 한 쌍의 원앙새였던 거야?",
          DialogueId = 10046109,
          GUID = "19263DC2",
          SpeakNpcId = 100426,
          VoiceName = "voice/$Locale$/story/1004/100461/19263DC2"
        },
        [10046110] = {
          Content = "兜里有几个子儿？拿出来一些来。否则的话，我可能就要去找乘务去聊一聊了。",
          ContentKR = "주머니에 든 거 있으면 좀 내놔 보지? 아니면, 난 승무원이랑 얘기하러 가 봐야겠거든.",
          DialogueId = 10046110,
          GUID = "19263DEC",
          SpeakNpcId = 100426,
          VoiceName = "voice/$Locale$/story/1004/100461/19263DEC"
        },
        [10046111] = {
          Content = "没错，我们是从头等车厢过来的乘客，你可以找乘务，看他敢不敢动我们。",
          ContentKR = "그래요, 우린 일등석 승객 맞아요. 승무원 불러 올 거면 마음대로 하세요. 어디 승무원이 뭘 하나 보죠.",
          DialogueId = 10046111,
          GUID = "19263E16",
          ImprPlusId = 1008
        },
        [10046112] = {
          Content = "难道你们就没听说过，关键时刻给人一点恩惠，要比专门去赠送礼物还要有用吗？",
          ContentKR = "곤란한 일을 겪고 있는 사람한테 도움을 주면, 나중에 큰 보답을 받게 된다는 얘기도 못 들어 봤어요?",
          DialogueId = 10046112,
          GUID = "19263E40",
          ImprPlusId = 1006
        },
        [10046113] = {
          Content = "你这是在威胁我们？同样出门在外，还是友善一点吧。",
          ContentKR = "지금 협박하시는 건가요? 집 떠나 온 처지끼리, 서로 돕고 살면 좋잖아요.",
          DialogueId = 10046113,
          GUID = "19263E6A",
          ImprPlusId = 1007
        },
        [10046114] = {
          Content = "有点意思，你们要是不怕的话，我可就真去喊了啊，我倒要看你们嘴硬到什么时候。",
          ContentKR = "재미있네. 겁도 안 내는 것 같은데, 그러면 진짜 가서 승무원을 불러와 줄게. 언제까지 그렇게 뻣뻣하게 나오나 보자고.",
          DialogueId = 10046114,
          GUID = "19263E94",
          SpeakNpcId = 100426,
          VoiceName = "voice/$Locale$/story/1004/100461/19263E94"
        },
        [10046115] = {
          Content = "诶？反倒讲起大道理了。可惜啊，我这个人就是只看眼前的利益，不懂你说的这些。",
          ContentKR = "응? 갑자기 웬 설교야. 아쉽지만, 난 내 코가 석 자라, 지금 당장 눈앞에 떨어지는 콩고물 아니면 관심 없어.",
          DialogueId = 10046115,
          GUID = "19263EBE",
          SpeakNpcId = 100426,
          VoiceName = "voice/$Locale$/story/1004/100461/19263EBE"
        },
        [10046116] = {
          Content = "谁刁难你了？谁刁难了？大家有人看见我刁难他们了吗？没有吧！",
          ContentKR = "누가 널 협박했다는 거야? 누가? 여기서 내가 얘네 협박한 거 본 사람 있어? 아무도 없지?",
          DialogueId = 10046116,
          GUID = "19263EE8",
          SpeakNpcId = 100426,
          VoiceName = "voice/$Locale$/story/1004/100461/19263EE8"
        },
        [10046117] = {
          Content = "你……别挡路！",
          ContentKR = "당장... 비켜요!",
          DialogueId = 10046117,
          GUID = "19263F12",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100461/19263F12"
        },
        [10046118] = {
          Content = "哎哟，还想动手啊。好哇，本来我就活够了，想去皇都随便找个看了不顺眼的贵族家门口吊死，直接给他那大屋变成凶宅。",
          ContentKR = "이야, 이러다 치겠다? 좋아, 어차피 살 만큼 살았겠다, 이참에 황성에 가서 밥맛없는 귀족놈 집 대문 앞에 목매달고, 흉가나 만들어 주려고 했었거든.",
          DialogueId = 10046118,
          GUID = "19263F3C",
          SpeakNpcId = 100426,
          VoiceName = "voice/$Locale$/story/1004/100461/19263F3C"
        },
        [10046119] = {
          Content = "现在倒不用特意去找了，来，你就对着这边下刀，快点。",
          ContentKR = "귀찮게 거기까지 안 가도 되겠네. 자, 찔러, 찔러 보래도!",
          DialogueId = 10046119,
          GUID = "19263F66",
          SpeakNpcId = 100426,
          VoiceName = "voice/$Locale$/story/1004/100461/19263F66"
        },
        [10046120] = {
          Content = "怎么回事？",
          ContentKR = "무슨 일 났어?",
          DialogueId = 10046120,
          GUID = "19263F90",
          SpeakNpcId = 100427,
          VoiceName = "voice/$Locale$/story/1004/100461/19263F90"
        },
        [10046121] = {
          Content = "看起来是要打架，都是坐老鼠罐头的，何必互相刁难呢。",
          ContentKR = "싸움 났나 봐. 다 같이 깡통 속에 처박힌 생쥐 신세들인데 왜들 서로 못 잡아먹어서 안달인 거야.",
          DialogueId = 10046121,
          GUID = "19263FBA",
          SpeakNpcId = 100428,
          VoiceName = "voice/$Locale$/story/1004/100461/19263FBA"
        },
        [10046122] = {
          Content = "要不去找乘务吧……",
          ContentKR = "가서 승무원 불러와야겠는데...",
          DialogueId = 10046122,
          GUID = "19263FE4",
          SpeakNpcId = 100427,
          VoiceName = "voice/$Locale$/story/1004/100461/19263FE4"
        },
        [10046123] = {
          Content = "（糟糕，得尽快解决这件事，不引起人注意才是。）",
          ContentKR = "(큰일이야. 눈에 띄지 않게, 최대한 빨리 상황을 해결해야 해.)",
          DialogueId = 10046123,
          DisableMouth = 1,
          GUID = "1926400E",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100461/1926400E"
        },
        [10046124] = {
          Content = "勒庞大叔，等一等……这两位是我的亲戚，求你别刁难他们。",
          ContentKR = "르펜 아저씨, 잠깐만요... 이 두 사람은 제 친척이에요! 괴롭히지 마세요!",
          DialogueId = 10046124,
          GUID = "19264038",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100461/19264038"
        },
        [10046125] = {
          Content = "哦？小史蒂芬啊，原来你也在这辆车上。怎么，你家那个抠门老头终于攒够了钱，愿意带你去皇都玩上一圈啦？",
          ContentKR = "어? 스테판이냐? 너도 이 기차 탔었어? 뭐야, 너네 집 그 짠돌이가 드디어 돈 좀 모아서 황성 구경 좀 시켜 준대?",
          DialogueId = 10046125,
          GUID = "19264062",
          SpeakNpcId = 100426,
          VoiceName = "voice/$Locale$/story/1004/100461/19264062"
        },
        [10046126] = {
          Content = "我爸……他有事，抽不开身，所以才拜托我的亲戚带我一起出来。",
          ContentKR = "아빠는... 일이 생겨서 못 오셨어요. 그래서 친척들한테 저랑 같이 가 달라고 부탁하신 거예요.",
          DialogueId = 10046126,
          GUID = "1926408C",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100461/1926408C"
        },
        [10046127] = {
          Content = "大表姐，{性别：二表哥|二表姐}，我都和你们说过了，火车是要对号入座的，不能乱走。还是和我回普通车厢吧。",
          ContentKR = "큰 누나, {性别:형|작은누나}, 내가 얘기해 줬었잖아요. 자기 자리 아닌 데 가면 안 된다니까요. 얼른 나랑 일반석 열차칸으로 가요.",
          DialogueId = 10046127,
          GUID = "192640B6",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100461/192640B6"
        },
        [10046128] = {
          Content = "啊？好好好，走走，回去回去，我和你大表姐就是好奇嘛，这下知道错了。",
          ContentKR = "어? 아, 응, 그래, 가야지, 자리로 돌아가야지. 나랑 {性别:큰 누나|큰 언니}는 그냥 궁금해서 와 본 거야. 이젠 안 그럴게.",
          DialogueId = 10046128,
          GUID = "192640E0",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100461/192640E0"
        },
        [10046129] = {
          Content = "…………！大、大表姐……",
          ContentKR = "......! {性别:크, 큰 누나|크, 큰 언니}...?",
          DialogueId = 10046129,
          GUID = "1926410A",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100461/1926410A"
        },
        [10046130] = {
          Content = "嗯……都怪你{性别：二表哥|二表姐}非好奇这最后一节车厢里面是什么模样。既然我们在这里并不受欢迎，那便回去吧。",
          ContentKR = "아, 음... 이게 다 네 {性别:사촌 형이|작은누나가} 꼬리칸을 구경해야겠다고 고집을 부려서 이렇게 된 거야. 여기 분들은 우리를 안 반기시는 것 같으니까, 얼른 돌아가자.",
          DialogueId = 10046130,
          GUID = "19264134",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100461/19264134"
        },
        [10046131] = {
          Content = "哎？等会儿，那他们是为啥从车顶下来的……",
          ContentKR = "응? 잠깐만, 그러면 아까는 왜 열차 지붕에서 내려온 거지...",
          DialogueId = 10046131,
          GUID = "1926415E",
          SpeakNpcId = 100426,
          VoiceName = "voice/$Locale$/story/1004/100461/1926415E"
        },
        [10046132] = {
          Content = "算了，既然小史蒂芬和他们那么亲近，那八成也不是坏人就是了，继续睡觉了。真希望一觉睡醒就能到迪斯玛尼亚……",
          ContentKR = "에이, 뭐, 스테판이랑 친한 걸 보면 나쁜 녀석들은 아니겠지. 에라이, 그냥 잠이나 자자! 눈 딱 뜨면 디즈마니아에 도착해 있었으면 좋겠네...",
          DialogueId = 10046132,
          GUID = "19264188",
          SpeakNpcId = 100426,
          VoiceName = "voice/$Locale$/story/1004/100461/19264188"
        },
        [10046201] = {
          Content = "什么？你是说你跳上了寒鸦号然后又跳了出来……还在军团士兵的眼皮子底下把他们关押的囚犯救走……",
          ContentKR = "네? 다른 열차에서 갈까마귀호로 점프했다가, 다시 이 열차로 건너왔다고요...? 군단 병사들이 감시하고 있는 죄수까지 데리고요...?",
          DialogueId = 10046201,
          GUID = "19264CDA",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100462/19264CDA"
        },
        [10046202] = {
          Content = "能想出这个方法，然后还能做出来的你们真是不折不扣的疯子……如果下次还有这么帅气的计划，能不能也带上我……不，还是算了。",
          ContentKR = "그런 방법을 생각해 낸 것도 대단한데, 실제로 해내다니, 우와, 진짜 제대로 미쳤네요... 다음에 또 그런 끝내주는 작전을 세우면, 나도 같이... 아니, 난 역시 그만둘래요.",
          DialogueId = 10046202,
          GUID = "19264D04",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100462/19264D04"
        },
        [10046203] = {
          Content = "希望没有下次了吧。为什么你也在这辆车上？啊……难道是你父亲给你的票……",
          ContentKR = "다음엔 이런 일이 없길 바라야지. 그런데 넌 왜 이 기차에 타고 있는 거야? 아... 혹시 너희 아빠가 받은 기차표가...",
          DialogueId = 10046203,
          GUID = "19264D2E",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100462/19264D2E"
        },
        [10046204] = {
          Content = "嗯，没错，他帮助神弃者同盟拿到的车票就是极光号的票。我想着不能让他几乎拼了命拿到的车票白白浪费，于是就上了这辆车。",
          ContentKR = "네, 맞아요. 아빠가 포세이큰 동맹을 도와주는 대신 받은 게, 오로라호의 표였어요. 아빠가 목숨 걸고 구한 표를 휴지 조각으로 만들 순 없으니까, 그래서 탄 거예요.",
          DialogueId = 10046204,
          GUID = "19264D58",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100462/19264D58"
        },
        [10046205] = {
          Content = "那么接下来，就跟着我来吧，到普通车厢各处走走。我想亲眼看一看这辆车的各个车厢都是什么样……相信你们也会想看看的。",
          ContentKR = "그럼 이제 저랑 같이 일반석 칸 여기저기를 돌아다녀 봐요. 객차 내부가 어떻게 생겼는지 제 눈으로 직접 보고 싶었거든요... {性别:형|누나}도 그렇죠?",
          DialogueId = 10046205,
          GUID = "19264D82",
          RelatedWikiId = {
            [1] = 405018
          },
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100462/19264D82"
        },
        [10046206] = {
          Content = "好……",
          ContentKR = "그래...",
          DialogueId = 10046206,
          GUID = "19264DAC",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100462/19264DAC"
        },
        [10046301] = {
          Content = "怎么样，热闹吧。我听说平民们的车厢永远都是这样，笑声能盖过汽笛的嘟嘟声。",
          ContentKR = "어때요? 엄청 시끌벅적하죠? 평민들이 타는 열차칸은 늘 이래요. 사람들이 웃고 떠드는 소리가 열차 소리보다 훨씬 커요.",
          DialogueId = 10046301,
          GUID = "19265D42",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100463/19265D42"
        },
        [10046302] = {
          Content = "…………",
          ContentKR = "......",
          DialogueId = 10046302,
          GUID = "19265D6C",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100463/19265D6C"
        },
        [10046303] = {
          Content = "怎么了，是不喜欢吵闹吗？",
          ContentKR = "왜 그래요? 너무 시끄럽나요?",
          DialogueId = 10046303,
          GUID = "19265D96",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100463/19265D96"
        },
        [10046304] = {
          Content = "不，我只是没见过……",
          ContentKR = "아니요, 그냥 이런 분위기는 처음이라...",
          DialogueId = 10046304,
          GUID = "19265DC0",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100463/19265DC0"
        },
        [10046305] = {
          Content = "哟，小史蒂芬回来了？怎么，探险结束了？我早说了，你不该去“老鼠罐头”，那里的人有好有坏。想要去那里，你得更壮实一点，然后喝上三杯啤酒。",
          ContentKR = "어이구, 왔니, 스테판? 그래, 꼬리칸 탐험은 어땠어? 아저씨가 '생쥐 통조림'은 함부로 가는 데가 아니라고 했잖아. 거기 가려면 덩치도 좀 있어야 하고, 맥주도 세 잔은 버틸 줄 알아야 해.",
          DialogueId = 10046305,
          GUID = "19265DEA",
          SpeakNpcId = 100429,
          VoiceName = "voice/$Locale$/story/1004/100463/19265DEA"
        },
        [10046306] = {
          Content = "等等，你怎么还带了人回来？生面孔啊。",
          ContentKR = "잠깐, 그런데 같이 온 그 사람들은 누구야? 처음 보는 얼굴들인데.",
          DialogueId = 10046306,
          GUID = "19265E14",
          SpeakNpcId = 100429,
          VoiceName = "voice/$Locale$/story/1004/100463/19265E14"
        },
        [10046307] = {
          Content = "啊，嗯，我是史蒂芬的{性别：二表哥|二表姐}，这位是他的大表姐。",
          ContentKR = "아, 음, 저는 스테판의 {性别:사촌 형이고|둘째 사촌 누나고}, 이쪽은 {性别:저희 누나|저희 언니}예요.",
          DialogueId = 10046307,
          GUID = "19265E3E",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100463/19265E3E"
        },
        [10046308] = {
          Content = "……你好。",
          ContentKR = "...안녕하세요.",
          DialogueId = 10046308,
          GUID = "19265E68",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100463/19265E68"
        },
        [10046309] = {
          Content = "怎么有点怕生？这可不行，来，喝了这杯酒。咕嘟咕嘟喝完啊，你就会看不清眼前的人长什么样，一点都不害怕了。",
          ContentKR = "낯을 가리나 보네? 그럼 못 써. 자, 한 잔 쭉 들이켜 봐. 벌컥벌컥 마시고 나면, 눈앞이 핑 돌면서 무서울 게 하나도 없어지거든.",
          DialogueId = 10046309,
          GUID = "19265E92",
          SpeakNpcId = 100429,
          VoiceName = "voice/$Locale$/story/1004/100463/19265E92"
        },
        [10046310] = {
          Content = "…………",
          ContentKR = "......",
          DialogueId = 10046310,
          GUID = "19265EBC",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100463/19265EBC"
        },
        [10046311] = {
          Content = "看这赌鬼喝多了酒的样子，人和柱子都分不清，就别赌了，再赌下去就是给人送钱。",
          ContentKR = "도박에 술에 아주 가지가지 하네. 어째 사람이랑 기둥도 구분을 못 해? 도박도 좀 그만해. 남 좋은 일만 시키지 말고.",
          DialogueId = 10046311,
          GUID = "19265EE6",
          SpeakNpcId = 100431,
          VoiceName = "voice/$Locale$/story/1004/100463/19265EE6"
        },
        [10046312] = {
          Content = "来，小姑娘到这来，尝一口。我刚刚想出了一种新的香肠和奶酪的搭配方式，他们几个笨蛋在挑我的刺，这次我不给他们吃了。",
          ContentKR = "자, 얘들아, 여기 와서 이거 한 번 먹어 봐. 아저씨가 소시지에 치즈를 곁들여 먹는 새로운 방법을 개발했거든. 저 멍청한 녀석들은 자꾸 딴죽을 걸어서, 이번에는 안 주려고.",
          DialogueId = 10046312,
          GUID = "19265F10",
          SpeakNpcId = 100431,
          VoiceName = "voice/$Locale$/story/1004/100463/19265F10"
        },
        [10046313] = {
          Content = "用发酵时间短一点的奶酪，中间夹上两片干肠，最中间夹上一块这个味道大一点的。味可能大了点，但是包好吃，不行的话捏着鼻子吃下去。",
          ContentKR = "잘 말린 소시지 사이에, 향이 강한 치즈를 하나 넣고, 소시지 바깥은 발효 시간이 좀 짧은 치즈를 덮는 거야. 향이 조금 강하긴 한데, 맛은 정말 끝내 줘. 뭐하면 코라도 막고 먹어 봐.",
          DialogueId = 10046313,
          GUID = "19265F3A",
          SpeakNpcId = 100431,
          VoiceName = "voice/$Locale$/story/1004/100463/19265F3A"
        },
        [10046314] = {
          Content = "啊唔——",
          ContentKR = "아암——",
          DialogueId = 10046314,
          GUID = "19265F64",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100463/19265F64"
        },
        [10046315] = {
          Content = "啊唔——",
          ContentKR = "아암——",
          DialogueId = 10046315,
          GUID = "19265F8E",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100463/19265F8E"
        },
        [10046316] = {
          Content = "这个……好好吃。",
          ContentKR = "이거... 진짜 맛있네요.",
          DialogueId = 10046316,
          GUID = "19265FB8",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100463/19265FB8"
        },
        [10046317] = {
          Content = "最外面的奶酪香味很足，然后是干肠的肉香。奶酪还有一点水分，让干肠的口感更好。最中间……还有一种浓郁的鲜美味道，我说不上来。",
          ContentKR = "겉을 감싼 치즈 향 사이로, 소시지의 고기 향이 밀려 들어와요. 치즈가 살짝 촉촉해서, 말린 소시지의 식감도 완벽히 잡아 주고요. 그리고 제일 가운데 있는 건... 신선하면서도 맛이 진한데, 뭐라고 설명해야 할지 모르겠어요.",
          DialogueId = 10046317,
          GUID = "19265FE2",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100463/19265FE2"
        },
        [10046318] = {
          Content = "最中间是羊奶酪，因为有股味儿所以算是著名的风味食物吧。怎么，第一次吃？",
          ContentKR = "맨 가운데 있는 건 양젖 치즈야. 냄새 때문에 호불호가 많이 갈리긴 하지만, 상당히 별미거든. 왜? 처음 먹어 봐?",
          DialogueId = 10046318,
          GUID = "1926600C",
          SpeakNpcId = 100431,
          VoiceName = "voice/$Locale$/story/1004/100463/1926600C"
        },
        [10046319] = {
          Content = "啊，是的。家里管得比较严，我没太吃过这种食物。",
          ContentKR = "아, 네. 집이 엄한 편이라, 이렇게 독특한 음식은 거의 접해 본 적이 없어요.",
          DialogueId = 10046319,
          GUID = "19266036",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100463/19266036"
        },
        [10046320] = {
          Content = "哎，这就不对了，我得批评你家里人，人就应该敢于多尝试才是，要有勇气！那些虾呀蟹呀，你说看起来和虫子也差不多，其实好吃得很。",
          ContentKR = "아이고, 그러면 못 쓰지. 내가 한 소리 해야겠네. 사람은 이것저것 먹어 볼 줄도 알아야 하는 거야! 용기가 있어야지! 새우나 게 같은 것도, 벌레 같이 생겼지만, 막상 먹으면 얼마나 맛있는데.",
          DialogueId = 10046320,
          GUID = "19266060",
          SpeakNpcId = 100431,
          VoiceName = "voice/$Locale$/story/1004/100463/19266060"
        },
        [10046321] = {
          Content = "看你也挺喜欢我的这种吃法的，我再卷一点，你兜着，多吃点。我啊，鼻子比一般人灵，喜欢各种吃东西，看别人吃得开心自己也高兴。",
          ContentKR = "입맛에 꽤 맞는 모양이네. 아저씨가 몇 개 더 만들어 줄 테니까, 가지고 가서 많이 먹어. 난 말이야, 다른 사람들보다 후각이 예민해서, 다양한 음식에 도전하는 걸 좋아해. 맛있게 먹어 주는 사람을 보면, 나까지 행복해진다니까.",
          DialogueId = 10046321,
          GUID = "1926608A",
          SpeakNpcId = 100431,
          VoiceName = "voice/$Locale$/story/1004/100463/1926608A"
        },
        [10046322] = {
          Content = "……谢谢。",
          ContentKR = "...감사합니다.",
          DialogueId = 10046322,
          GUID = "192660B4",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100463/192660B4"
        },
        [10046323] = {
          Content = "吃吃吃，整天就知道吃，没点眼力见。你就没看出来人家姑娘这身衣服金贵得很，你直接拿给她，滴上油怎么办。",
          ContentKR = "아주, 입만 열면 음식 얘기지. 어쩜 그렇게 눈치가 없어! 이 아가씨가 입고 있는 옷이 얼마나 비싼 건지 안 보여? 기름이라도 묻으면 어쩌려고 그냥 쥐여 주는 거야.",
          DialogueId = 10046323,
          GUID = "192660DE",
          SpeakNpcId = 100433,
          VoiceName = "voice/$Locale$/story/1004/100463/192660DE"
        },
        [10046324] = {
          Content = "我这边有块布，干净的，来裹上。",
          ContentKR = "여기 깨끗한 천 있으니까, 이걸로 싸서 줘.",
          DialogueId = 10046324,
          GUID = "19266108",
          SpeakNpcId = 100433,
          VoiceName = "voice/$Locale$/story/1004/100463/19266108"
        },
        [10046325] = {
          Content = "哎哟，还是你想的周到。",
          ContentKR = "이야, 역시 나보다 낫네.",
          DialogueId = 10046325,
          GUID = "19266132",
          SpeakNpcId = 100431,
          VoiceName = "voice/$Locale$/story/1004/100463/19266132"
        },
        [10046326] = {
          Content = "我来拿着吧。",
          ContentKR = "내가 들게.",
          DialogueId = 10046326,
          GUID = "1926615C",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100463/1926615C"
        },
        [10046327] = {
          Content = "不错，看看，人家这才叫懂事贴心。",
          ContentKR = "보기 좋네. 이거 봐, 얼마나 의젓하고 다정해.",
          DialogueId = 10046327,
          GUID = "19266186",
          SpeakNpcId = 100433,
          VoiceName = "voice/$Locale$/story/1004/100463/19266186"
        },
        [10046328] = {
          Content = "难怪啊，她打扮的这么好，却还愿意跟着你呢。老实说，你们俩是不是其实并不是什么{性别：姐弟|姐妹}，而是那种关系？",
          ContentKR = "어쩐지, 저렇게 잘 차려입고도 널 졸졸 따라다니는 이유가 있었네. 솔직히 말해 봐. 둘이 {性别:남매|자매}가 아니라, 그렇고 그런 사이지?",
          DialogueId = 10046328,
          GUID = "192661B0",
          SpeakNpcId = 100433,
          VoiceName = "voice/$Locale$/story/1004/100463/192661B0"
        },
        [10046329] = {
          Content = "那种关系？",
          ContentKR = "그렇고 그런 사이요?",
          DialogueId = 10046329,
          GUID = "192661DA",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100463/192661DA"
        },
        [10046330] = {
          Content = "{性别：是啊，我啊，最擅长看人了，但凡映入眼帘的人和事，我可都不会放过。|没事，别害羞，大婶我知道，现在有些女孩子之间也有意思的，很正常。}",
          ContentKR = "{性别:그래, 이 아줌마는 사람 보는 눈 하나는 기가 막히거든. 귀신은 속여도 내 눈은 못 속여.|괜찮아, 쑥스러워할 거 없어. 아줌마도 알아. 요즘은 아가씨들끼리도 알콩달콩한다면서? 하나도 안 이상해.}",
          DialogueId = 10046330,
          GUID = "19266204",
          SpeakNpcId = 100433,
          VoiceName = "voice/$Locale$/story/1004/100463/19266204"
        },
        [10046331] = {
          Content = "我看你们俩贴的挺近的，就算别人和你说话，你也时不时瞟{性别：他|她}两眼。不是没怎么出过门，就是有心思。",
          ContentKR = "아까부터 둘이 딱 붙어서, 네가 다른 사람이랑 얘기라도 하면, 저 {性别:친구|아가씨}가 자꾸 슬쩍슬쩍 쳐다보던걸. 외출을 별로 해 본 적이 없든지, 아니면 너한테 마음이 있어서 저러는 거야.",
          DialogueId = 10046331,
          GUID = "1926622E",
          SpeakNpcId = 100433,
          VoiceName = "voice/$Locale$/story/1004/100463/1926622E"
        },
        [10046332] = {
          Content = "我确实没怎么出过门。",
          ContentKR = "제가 외출을 해 본 적이 거의 없기는 해요.",
          DialogueId = 10046332,
          GUID = "19266258",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100463/19266258"
        },
        [10046333] = {
          Content = "怎么会呢？我要是有个这么好看的女儿啊，恨不得每天带她在冰湖城里走上一圈，让人家看看呢。",
          ContentKR = "왜 그럴까? 나한테 이렇게 예쁜 딸이 있었으면, 매일 같이 데리고 다니면서, 아이스레이크 시티 온 동네에 자랑이랑 자랑은 다 하고 다녔을 텐데.",
          DialogueId = 10046333,
          GUID = "19266282",
          SpeakNpcId = 100433,
          VoiceName = "voice/$Locale$/story/1004/100463/19266282"
        },
        [10046334] = {
          Content = "真不是您想的那样，不信你问史蒂芬。诶？史蒂芬呢？",
          ContentKR = "저희는 정말 그런 사이 아니에요. 정 못 믿으시겠으면 스테판한테 물어보세요. 어? 얘가 어디 갔지?",
          DialogueId = 10046334,
          GUID = "192662AC",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100463/192662AC"
        },
        [10046335] = {
          Content = "跑去那边了，应该在听人弹琴？至于你们俩啊，我也不打算再问了，我懂我懂。你们继续在车厢里四处看看吧，我啊，就不打扰你们啦。",
          ContentKR = "저쪽으로 갔어. 아마 노래 들으러 갔을걸? 아무튼, 이제 그만 캐물을게. 그럼, 그럼. 아줌마는 눈치껏 빠져 줄 테니까, 둘이 오붓하게 기차 구경 마저 해.",
          DialogueId = 10046335,
          GUID = "192662D6",
          SpeakNpcId = 100433,
          VoiceName = "voice/$Locale$/story/1004/100463/192662D6"
        },
        [10046401] = {
          Content = "……那个，平民的话是会这样，比较热情，也喜欢乱说话。如果感到冒犯的话，我们找个安静地方。",
          ContentKR = "...저기, 아까 그 아주머니 말은 너무 마음에 담아두지 마세요. 원래 평민들은 오지랖도 넓고, 말도 툭툭 던지거든요. 너무 무례했으면, 조용한 곳을 알아볼게요.",
          DialogueId = 10046401,
          GUID = "19266DAA",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100464/19266DAA"
        },
        [10046402] = {
          Content = "不，不如说反过来，我还挺喜欢其他人这么对我说话的。",
          ContentKR = "아니에요. 오히려 전 그분들이 절 스스럼없이 대해 주셔서 내심 기뻤는걸요.",
          DialogueId = 10046402,
          GUID = "19266DD4",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100464/19266DD4"
        },
        [10046403] = {
          Content = "对我的称呼不再是殿下，公主，也不会因为我头顶上的冠冕战战兢兢。他们和我说话的时候眼里是我这个人，芙罗拉，而不是某个头衔。",
          ContentKR = "저를 공주 전하라고 부르는 사람도 없었고, 제 지위 때문에 전전긍긍하는 사람도 없었어요. 그분들은 제 신분이 아니라, '플로라'라는 한 사람을 보고 말을 걸어 주신 거예요.",
          DialogueId = 10046403,
          GUID = "19266DFE",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100464/19266DFE"
        },
        [10046404] = {
          Content = "他们称呼我为“你”，而非“您”。我也可以这样称呼他们。哦，他们也不知道我叫做芙罗拉，而我这时的头衔也是大表姐，差点忘了。",
          ContentKR = "저를 '공주님'이 아니라, 그냥 '아가씨'라고 불러 주셨고, 저도 그분들과 편하게 이야기할 수 있었죠. 아, 그러고 보니 저를 스테판의 큰 사촌 누나로 알고 계셔서, 플로라라는 이름은 모르시겠네요.",
          DialogueId = 10046404,
          GUID = "19266E28",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100464/19266E28"
        },
        [10046405] = {
          Content = "不过，这个头衔要有意思多了，哈哈！",
          ContentKR = "근데, 사촌 누나라는 호칭이 훨씬 마음에 들어요, 후훗!",
          DialogueId = 10046405,
          GUID = "19266E52",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100464/19266E52"
        },
        [10046406] = {
          Content = "第一次见到你这么笑。或者说，第一次见到你笑。",
          ContentKR = "그렇게 소리 내서 웃으시는 건 처음이네요. 아니, 웃는 모습 자체를 처음 보는 것 같아요.",
          DialogueId = 10046406,
          GUID = "19266E7C",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100464/19266E7C"
        },
        [10046407] = {
          Content = "我也是才知道，原来笑出声音来是可以不被侍女长训斥的。可惜，现在没有镜子，我也想看自己这么笑起来的样子。",
          ContentKR = "저도 방금 알았어요. 이렇게 소리 내 웃어도, 옆에서 잔소리할 시녀장이 없네요. 제가 지금 어떻게 웃고 있는지 보고 싶은데, 거울이 없다는 게 아쉬운걸요.",
          DialogueId = 10046407,
          GUID = "19266EA6",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100464/19266EA6"
        },
        [10046408] = {
          Content = "唔……我描述一下，就是眼睛和嘴巴都弯弯的，像是月亮。眼睛像是弦月，嘴巴要比弦月宽一点点。",
          ContentKR = "음... 설명해 드릴게요. 눈꼬리랑 입꼬리가 달처럼 휘어져 있어요. 눈은 초승달 같고, 입은 초승달보단 살짝 도톰해요.",
          DialogueId = 10046408,
          GUID = "19266ED0",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100464/19266ED0"
        },
        [10046409] = {
          Content = "用月亮做比喻是很好，但是听起来有点抽象，还是有点难以想象。",
          ContentKR = "달로 비유해 주신 건 좋지만, 너무 추상적이라서, 어떤 모습인지 머릿속에 그려지진 않네요.",
          DialogueId = 10046409,
          GUID = "19266EFA",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100464/19266EFA"
        },
        [10046410] = {
          Content = "不好意思，我读书不算多。",
          ContentKR = "죄송해요. 평소에 책을 많이 읽는 편이 아니라서요.",
          DialogueId = 10046410,
          GUID = "19266F24",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100464/19266F24"
        },
        [10046411] = {
          Content = "不，没事，我已经看到了。",
          ContentKR = "아니요, 괜찮아요. 이제 제 눈에도 보여요.",
          DialogueId = 10046411,
          GUID = "19266F4E",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100464/19266F4E"
        },
        [10046412] = {
          Content = "史蒂芬在那边探头探脑的，好像在找什么东西，去看看怎么回事吧。",
          ContentKR = "스테판이 뭘 찾고 있나 봐요. 계속 저기서 기웃거리고 있는데, 가서 무슨 일인지 확인해 봐야 할 것 같아요.",
          DialogueId = 10046412,
          GUID = "19266F78",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100464/19266F78"
        },
        [10046413] = {
          Content = "我说刚刚怎么都没看见他，走，去问问。",
          ContentKR = "아까부터 안 보이던 이유가 있었네요. 자, 가서 한번 물어보죠.",
          DialogueId = 10046413,
          GUID = "19266FA2",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100464/19266FA2"
        },
        [10046501] = {
          Content = "史蒂芬小表弟，你在这儿做什么呢？不好好听琴，一直望着那边，是想跟着售货员去下一列车厢吗？",
          ContentKR = "우리 사촌 동생, 여기서 뭐 해? 왜 노래 안 듣고 계속 저쪽만 빤히 보고 있는 거야? 판매 승무원 따라 다음 열차칸에 가 보고 싶어?",
          DialogueId = 10046501,
          GUID = "19267E12",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100465/19267E12"
        },
        [10046502] = {
          Content = "啊……嗯。我就是有点好奇。",
          ContentKR = "아... 네. 그냥 조금 궁금해요.",
          DialogueId = 10046502,
          GUID = "19267E3C",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100465/19267E3C"
        },
        [10046503] = {
          Content = "心不在焉的，是有什么心事吗？",
          ContentKR = "마음이 딴 데 가 있네. 무슨 고민이라도 있는 거야?",
          DialogueId = 10046503,
          GUID = "19267E66",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100465/19267E66"
        },
        [10046504] = {
          Content = "嗯……",
          ContentKR = "네...",
          DialogueId = 10046504,
          GUID = "19267E90",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100465/19267E90"
        },
        [10046505] = {
          Content = "怎么回事？是谁欺负你了？",
          ContentKR = "왜 그래? 누가 너 괴롭혔어?",
          DialogueId = 10046505,
          GUID = "19267EBA",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100465/19267EBA"
        },
        [10046506] = {
          Content = "不，没有人欺负我。其实……我只是……想再见一次我爸。",
          ContentKR = "아뇨, 아무도 저 안 괴롭혔어요. 사실... 그냥... 딱 한 번만 더 아빠를 만나고 싶어요.",
          DialogueId = 10046506,
          GUID = "19267EE4",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100465/19267EE4"
        },
        [10046507] = {
          Content = "你爸？",
          ContentKR = "너희 아빠?",
          DialogueId = 10046507,
          GUID = "19267F0E",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100465/19267F0E"
        },
        [10046508] = {
          Content = "报告站长大人，卡诺的笔迹与那封匿名信的笔迹一致。被称为哈洛吉的青年身上也搜出了神弃者同盟的信物，阶级为渡鸦！",
          ContentKR = "역장님! 보고드립니다! 익명 투서의 필적이 카르노의 필적과 정확히 일치합니다. 또한, 하로기라는 남자에게서 포세이큰 동맹의 증표가 발견됐습니다. 계급은 레이븐입니다!",
          DialogueId = 10046508,
          GUID = "19267F38",
          SpeakNpcId = 100420,
          VoiceName = "voice/$Locale$/story/1004/100447/192556EC"
        },
        [10046509] = {
          Content = "知道了，明天把他们送去迪斯玛尼亚进行进一步审讯吧。",
          ContentKR = "알겠다. 두 놈 다 내일 디즈마니아로 압송해서 추가 신문을 진행해.",
          DialogueId = 10046509,
          GUID = "19267F62",
          SpeakNpcId = 100416,
          VoiceName = "voice/$Locale$/story/1004/100447/19255716"
        },
        [10046510] = {
          Content = "这么说来，你上这辆车其实是为了……",
          ContentKR = "설마, 네가 이 열차에 탄 진짜 이유가...",
          DialogueId = 10046510,
          GUID = "19267F8C",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100465/19267F8C"
        },
        [10046511] = {
          Content = "对不起，刚刚没和你们说实话。其实是我听说关押他的车今天早上就出发，正好就是极光号，所以用他给我准备的票上了这辆车。",
          ContentKR = "아까 거짓말해서 정말 죄송해요. 사실 아빠를 태우고 가는 열차가 오늘 아침에 출발한다는 얘기를 들었어요. 그런데 그게 마침 오로라호라서, 아빠한테 받은 표를 내고 열차에 탔어요.",
          DialogueId = 10046511,
          GUID = "19267FB6",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100465/19267FB6"
        },
        [10046512] = {
          Content = "刚刚去“老鼠罐头”，也是在想他会不会被关在那里，结果却在那里碰上了你们。",
          ContentKR = "아까 '생쥐 통조림' 칸도, 아빠가 혹시 거기 갇혀 계실까 봐 가 봤던 건데. 어쩌다 보니까 두 분이랑 마주친 거예요.",
          DialogueId = 10046512,
          GUID = "19267FE0",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100465/19267FE0"
        },
        [10046513] = {
          Content = "而再向前的车厢，分别是守卫车厢、仆从车厢和头等车厢。通过这些过后才是车长室。",
          ContentKR = "여기서 앞으로 더 가면, 경비용 객차, 하인용 객차, 그리고 일등석 객차가 나와요. 거기서 더 앞으로 가면 차장실이에요.",
          DialogueId = 10046513,
          GUID = "1926800A",
          RelatedWikiId = {
            [1] = 405019,
            [2] = 405020,
            [3] = 405021
          },
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100465/1926800A"
        },
        [10046514] = {
          Content = "趁着售货员推开门过去，我看了看守卫车厢，可是也没看到父亲。那这么看来，他肯定是被关在了车长车厢。",
          ContentKR = "아까 판매원이 문 열고 들어갈 때 살짝 봤는데, 아빠는 경비용 객차 안에 없었어요. 그러니까, 차장실에 갇혀 계신 게 분명해요.",
          DialogueId = 10046514,
          GUID = "19268034",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100465/19268034"
        },
        [10046515] = {
          Content = "要到达车长车厢的话，至少需要经过三个车厢……我有点担心，尤其像我这副样子，一进到头等车厢，肯定会被那些厌恶卡戎的家伙赶出来的……",
          ContentKR = "근데 차장실까지 가려면, 적어도 열차칸을 3개나 지나가야 하는데... 저 같은 애가 일등석 객차에 들어가면, 카론을 싫어하는 사람들한테 쫓겨나고 말 거예요...",
          DialogueId = 10046515,
          GUID = "1926805E",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100465/1926805E"
        },
        [10046516] = {
          Content = "……头等车厢里的乘客都是哪些人？",
          ContentKR = "...일등석 승객들은 어떤 사람들이니?",
          DialogueId = 10046516,
          GUID = "19268088",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100465/19268088"
        },
        [10046517] = {
          Content = "能进到头等车厢的，要么是名字比我们长很多的贵族老爷，要么是做生意发了大财的桂冠卡戎，说话的时候都用鼻孔看人。",
          ContentKR = "거기 들어갈 수 있는 건, 우리보다 이름이 훨씬 긴 귀족들이나, 사업으로 돈을 엄청 많이 번 계관카론밖에 없어요. 말이라도 걸면 사람을 벌레 보듯 해요.",
          DialogueId = 10046517,
          GUID = "192680B2",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100465/192680B2"
        },
        [10046518] = {
          Content = "不过地位更高，名字更长的贵族老爷也不会出现在那里，因为他们大多有自己的私人列车和飞艇了……",
          ContentKR = "그보다 더 지위가 높고, 이름도 훨씬 긴 귀족들은 대부분 자기들 전용 열차나 비행선이 있어서 이런 거 안 타겠지만...",
          DialogueId = 10046518,
          GUID = "192680DC",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100465/192680DC"
        },
        [10046519] = {
          Content = "喔……如果是这些人的话，我反而有些兴趣了，我倒要看看他们能凶成什么样。",
          ContentKR = "음... 그런 사람들이라면 오히려 흥미가 생기는걸. 대체 얼마나 무섭게들 구는지 직접 확인해 봐야겠어.",
          DialogueId = 10046519,
          GUID = "19268106",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100465/19268106"
        }
      }
    end
  },
  {
    MinKey = 10046520,
