          DialogueId = 10046605,
          GUID = "19268F22",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100466/19268F22"
        },
        [10046606] = {
          Content = "是的，钢琴家与学生们，我们的老师多年来怀才不遇，一直想要找一个成名的机会，所以换上了最好的衣服……",
          ContentKR = "네, 피아니스트와 학생들이에요. 저희 선생님께선 오랜 세월 동안 재능을 인정받지 못하시다가, 드디어 유명해질 기회를 잡아서, 가장 좋은 옷으로 갈아입고...",
          DialogueId = 10046606,
          GUID = "19268F4C",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100466/19268F4C"
