          GUID = "19274442",
          SpeakNpcId = 100431,
          VoiceName = "voice/$Locale$/story/1004/100477/19274442"
        },
        [10047710] = {
          Content = "我有办法，只是需要各位的帮助。",
          ContentKR = "방법은 있어요. 대신 여러분이 도와주셔야 돼요.",
