        [10049006] = {
          Content = "不会的不会的，小仆从不是一直吹自己从悬崖上摔下去都不会死，命超硬的吗？我们只要像说好的那样，去皇都最大的酒馆等着和{性别：他|她}会合就好啦。",
          ContentKR = "에이, 괜찮을 거야. 시종이 맨날 자기는 절벽에서 떨어져도 안 죽는다고, 목숨이 엄청 질기다고 허풍 떠는 거 몰라? 우린 약속대로 황성의 제일 큰 술집에서 걔랑 합류하기만 하면 돼.",
          DialogueId = 10049006,
          GUID = "1928190C",
          SpeakNpcId = 100402,
          VoiceName = "voice/$Locale$/story/1004/100490/1928190C"
        },
        [10049007] = {
          Content = "紧急新闻。今日，神弃者同盟在科赛托斯省南缘劫持了“极光号”列车，随后利用列车头部装载的列车炮击坠前来救援的帝国飞艇。",
          ContentKR = "긴급 뉴스입니다. 오늘, 포세이큰 동맹이 코퀴투스 성 남쪽 경계에서 열차 '오로라호'를 납치하고, 구조를 위해 출동한 제국 비행선을 열차포로 격추했습니다.",
          DialogueId = 10049007,
          GUID = "19281936",
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_SpeakName_Shouyinji",
          VoiceName = "voice/$Locale$/story/1004/100490/19281936"
        },
        [10049008] = {
          Content = "飞艇在一棵巨大天之树处爆炸，致使天之树燃烧。这是今年发生的第二起点燃天之树事件。第六军团已增派救援，目前极光号乘客全部失联，生死不明。",
          ContentKR = "비행선은 거대한 천국의 나무 근처에서 폭발했고, 이로 인해 천국의 나무에 불이 붙었습니다. 이는 올해 발생한 두 번째 천국의 나무 화재 사건입니다. 제6군단은 추가 구조대를 파견했으며, 현재 오로라호 승객은 전원 연락 두절 상태로, 생존이 확인되지 않은 상황입니다.",
          DialogueId = 10049008,
          GUID = "19281960",
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_SpeakName_Shouyinji",
          VoiceName = "voice/$Locale$/story/1004/100490/19281960"
        },
        [10049009] = {
          Content = "…………",
          ContentKR = "......",
          DialogueId = 10049009,
          GUID = "1928198A",
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1004/100490/1928198A"
        },
        [10049010] = {
          Content = "女士，请问我点的“冰湖往事”快要好了吗？",
          ContentKR = "저기요, 방금 주문한 '아이스레이크의 이야기' 다 됐나요?",
          DialogueId = 10049010,
          GUID = "192819B4",
          SpeakNpcId = 100414,
          VoiceName = "voice/$Locale$/story/1004/100490/192819B4"
        },
        [10049011] = {
          Content = "我和朋友今天出发离开这儿，所以我们想喝杯最有冰湖城特色的饮料作为纪念！",
          ContentKR = "저랑 친구가 오늘 여길 떠나거든요. 그래서 기념으로 아이스레이크 시티에서 가장 특색 있는 음료를 마시고 싶어서요!",
          DialogueId = 10049011,
          GUID = "192819DE",
          SpeakNpcId = 100414,
          VoiceName = "voice/$Locale$/story/1004/100490/192819DE"
        },
        [10049012] = {
          Content = "……店主女士？",
          ContentKR = "...사장님?",
          DialogueId = 10049012,
          GUID = "19281A08",
          SpeakNpcId = 100414,
          VoiceName = "voice/$Locale$/story/1004/100490/19281A08"
        },
        [10049013] = {
          Content = "……别慌，就要好了。",
          ContentKR = "...진정해요. 거의 다 됐으니까.",
          DialogueId = 10049013,
          GUID = "19281A32",
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1004/100490/19281A32"
        },
        [10049014] = {
          Content = "你们一定能活下来的，对吧？毕竟你们说过，更危险的事情，也早就经历过了。",
          ContentKR = "너흰 꼭 살아남을 수 있을 거야, 그렇지? 더 위험한 일도 겪어봤다고 했잖아.",
          DialogueId = 10049014,
          GUID = "19281A5C",
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1004/100490/19281A5C"
        },
        [10049015] = {
          Content = "殿下不是刚刚还好好坐在那儿吗，什么叫突然消失？你们以为这是什么流行侦探小说？",
          ContentKR = "전하께서 방금까지만 해도 멀쩡히 거기 앉아 계셨는데, 갑자기 사라졌다니 그게 무슨 소리야? 너희들 이게 무슨 추리소설인 줄 알아?",
          DialogueId = 10049015,
          GUID = "19281A86",
          SpeakNpcId = 100424,
          VoiceName = "voice/$Locale$/story/1004/100490/19281A86"
        },
        [10049016] = {
          Content = "在流行侦探小说里这种事件叫做“密室失踪案件”，队长。",
          ContentKR = "요즘 유행하는 추리소설에선 이런 경우를 '밀실 실종 사건'이라고 부릅니다, 대장님.",
          DialogueId = 10049016,
          GUID = "19281AB0",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100490/19281AB0"
        },
        [10049017] = {
          Content = "我问你这个了吗？都给我找——就算把寒鸦号拆成零件仓库，也要把芙罗蒂娅殿下找出来！",
          ContentKR = "내가 지금 그걸 물어봤어? 당장 찾아와! 갈까마귀호를 싹 분해해서라도 플로렌티아 전하를 찾아내!",
          DialogueId = 10049017,
          GUID = "19281ADA",
          SpeakNpcId = 100424,
          VoiceName = "voice/$Locale$/story/1004/100490/19281ADA"
        },
        [10049018] = {
          Content = "是，队长。",
          ContentKR = "네, 대장님.",
          DialogueId = 10049018,
          GUID = "19281B04",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100490/19281B04"
        },
        [10049019] = {
          Content = "……过关。",
          ContentKR = "...미션 클리어.",
          DialogueId = 10049019,
          GUID = "19281B2E",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100490/19281B2E"
        },
        [10049020] = {
          Content = "芙罗拉，{nickname}，不知你们那边还顺利吗？",
          ContentKR = "플로라 아가씨, {nickname}, 그쪽은 순조롭게 진행되고 있나요?",
          DialogueId = 10049020,
          GUID = "19281B58",
          SpeakNpcId = 100403,
          VoiceName = "voice/$Locale$/story/1004/100490/19281B58"
        },
        [10049021] = {
          Content = "大表姐，你说你和{性别：二表哥|二表姐}立下了一个契约，可以感知到{性别：他|她}的状况，真有这么神奇的魔法吗？",
          ContentKR = "누나, 누나는 {性别:형|작은누나}하고 계약을 맺어서 지금 상태를 감지할 수 있다고 했죠? 정말 그런 신기한 마법이 있어요?",
          DialogueId = 10049021,
          GUID = "19281B82",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100490/19281B82"
        },
        [10049022] = {
          Content = "是的。",
          ContentKR = "응.",
          DialogueId = 10049022,
          GUID = "19281BAC",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100490/19281BAC"
        },
        [10049023] = {
          Content = "……啊……！",
          ContentKR = "......아아!",
          DialogueId = 10049023,
          GUID = "19281BD6",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100490/19281BD6"
        },
        [10049024] = {
          Content = "这是？！你有{性别：他|她}的消息了？",
          ContentKR = "왜요?! {性别:형|작은누나} 소식을 알아낸 거예요?",
          DialogueId = 10049024,
          GUID = "19281C00",
          SpeakNpcId = 100415,
          VoiceName = "voice/$Locale$/story/1004/100490/19281C00"
        },
        [10049025] = {
          Content = "……有消息了。",
          ContentKR = "...응.",
          DialogueId = 10049025,
          GUID = "19281C2A",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100490/19281C2A"
        },
        [10049026] = {
          Content = "{性别：他|她}死了。",
          ContentKR = "그 사람... 죽었어.",
          DialogueId = 10049026,
          GUID = "19281C54",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100490/19281C54"
        },
        [10049101] = {
          Content = "（我这是在……雾海吗？倒不如说……原来雾海真的存在啊。）",
          ContentKR = "(여긴... 안개의 바다...? 아니, 그것보다... 안개의 바다가 정말로 있었던 거네.)",
          DialogueId = 10049101,
          DisableMouth = 1,
          GUID = "192828A2",
          RelatedWikiId = {
            [1] = 402001
          },
          SnapShot = "HEART",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/192828A2"
        },
        [10049102] = {
          Content = "（看来，我真的死了啊。死亡的感觉倒也不坏，除了身体轻了一点。没有想象中那么疼。）",
          ContentKR = "(아, 나 정말 죽었나 봐. 근데 죽은 느낌도 나쁘진 않네. 몸이 좀 가벼운 것만 빼면, 생각했던 것만큼 아프진 않아.)",
          DialogueId = 10049102,
          DisableMouth = 1,
          GUID = "192828CC",
          SnapShot = "HEART",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/192828CC"
        },
        [10049103] = {
          Content = "（……只是，还留有太多遗憾。）",
          ContentKR = "(...그냥, 아쉬운 게 너무 많아.)",
          DialogueId = 10049103,
          DisableMouth = 1,
          GUID = "192828F6",
          SnapShot = "HEART",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/192828F6"
        },
        [10049104] = {
          Content = "（那么接下来该做什么呢？）",
          ContentKR = "(그럼 이제 뭘 해야 되지?)",
          DialogueId = 10049104,
          DisableMouth = 1,
          GUID = "19282920",
          SnapShot = "HEART",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282920"
        },
        [10049105] = {
          Content = "（一直向前吗？这里看起来也没有边界……还是说要像那种神话故事一样，一直走下去，走向另一个新生的彼岸？）",
          ContentKR = "(계속 쭉 가면 되나? 여긴 끝도 없는 것 같은데... 아니면 신화에 나오는 것처럼, 계속 걸어가다 보면 새로운 삶이 기다리는 저편이 나오는 건가?)",
          DialogueId = 10049105,
          DisableMouth = 1,
          GUID = "1928294A",
          SnapShot = "HEART",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/1928294A"
        },
        [10049106] = {
          Content = "（按照卡戎的传说，雾海里是有神明在等待着的，还有引渡人……可是引渡人不在啊，休假了吗？）",
          ContentKR = "(카론 전설에서, 안개의 바다에는 신이 기다리고 있고, 인도자도 있다고 했는데... 근데 인도자가 안 보이네. 휴가라도 간 건가?)",
          DialogueId = 10049106,
          DisableMouth = 1,
          GUID = "19282974",
          SnapShot = "HEART",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282974"
        },
        [10049107] = {
          Content = "（那还是我自己来吧，只要呼喊神的名字的话，他们总得有点什么回应才是，否则这片雾海也太过质朴了。）",
          ContentKR = "(그럼 내가 직접 해볼까. 신의 이름을 부르면 뭔가 반응이 있지 않겠어? 그렇지 않으면 이 안개의 바다도 너무 허전하잖아.)",
          DialogueId = 10049107,
          DisableMouth = 1,
          GUID = "1928299E",
          SnapShot = "HEART",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/1928299E"
        },
        [10049108] = {
          Content = "（那位创世的母神大人叫什么来着——茵……茵……茵为？不是……茵乐？不是……）",
          ContentKR = "(창세의 어머니신 이름이 뭐였더라... 에...에...에이미? 아니지... 에밀리...?)",
          DialogueId = 10049108,
          DisableMouth = 1,
          GUID = "192829C8",
          SnapShot = "HEART",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/192829C8"
        },
        [10049109] = {
          Content = "（哦！是<H>茵布拉</>。）",
          ContentKR = "(아! <H>엠블라</>였지.)",
          DialogueId = 10049109,
          DisableMouth = 1,
          GUID = "192829F2",
          SnapShot = "HEART",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/192829F2"
        },
        [10049110] = {
          Content = "茵——布——拉——",
          ContentKR = "엠——블——라——",
          DialogueId = 10049110,
          GUID = "19282A1C",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282A1C"
        },
        [10049111] = {
          Content = "不会真的没有人吧……这雾海怎么回事？难道说，死去的人太多，觐见神明得排队？",
          ContentKR = "진짜 정말 아무도 없는 건가... 이 안개의 바다는 대체 뭐지? 혹시 죽은 사람이 너무 많아서 신을 알현하는 데도 줄을 서야 하는 건가?",
          DialogueId = 10049111,
          GUID = "19282A46",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282A46"
        },
        [10049112] = {
          Content = "找到你了，{nickname}。",
          ContentKR = "여기 있었군요, {nickname}.",
          DialogueId = 10049112,
          GUID = "19282A70",
          RelatedWikiId = {
            [1] = 201033
          },
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282A70"
        },
        [10049113] = {
          Content = "谁？",
          ContentKR = "누구...?",
          DialogueId = 10049113,
          GUID = "19282A9A",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282A9A"
        },
        [10049114] = {
          Content = "是我，芙罗蒂娅·普洛塞庇娜·盖雷亚。",
          ContentKR = "저예요, 플로렌티아 프로세르피나 갈레아.",
          DialogueId = 10049114,
          GUID = "19282AC4",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282AC4"
        },
        [10049115] = {
          Content = "……？！芙罗拉？你也死了？",
          ContentKR = "...?! 플로라 씨? 당신도 죽은 건가요?",
          DialogueId = 10049115,
          GUID = "19282AEE",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282AEE"
        },
        [10049116] = {
          Content = "怎么会这样……那史蒂芬呢？还有大家呢？……难道说，我最终还是失败了吗？",
          ContentKR = "어떻게 이런 일이... 그럼 스테판이랑 다른 사람들은요? ...설마, 결국 실패로 돌아간 건가요?",
          DialogueId = 10049116,
          GUID = "19282B18",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282B18"
        },
        [10049117] = {
          Content = "我不知道，这需要你自己去见证。",
          ContentKR = "저도 몰라요, 그건 당신이 직접 확인해야 해요.",
          DialogueId = 10049117,
          GUID = "19282B42",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282B42"
        },
        [10049118] = {
          Content = "什么意思？",
          ContentKR = "그게 무슨 말이에요?",
          DialogueId = 10049118,
          GUID = "19282B6C",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282B6C"
        },
        [10049119] = {
          Content = "字面意思。这里并非你应该来的地方，而我来此，是为了履行契约，接你离开。",
          ContentKR = "말 그대로예요. 여긴 당신이 와야 할 곳이 아니에요. 전 계약을 이행하기 위해, 당신을 데리러 온 거예요.",
          DialogueId = 10049119,
          GUID = "19282B96",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282B96"
        },
        [10049120] = {
          Content = "契约？你是说刚才你和我签订的那个？",
          ContentKR = "계약이요? 아까 우리 둘이 맺었던 그 계약 말이에요?",
          DialogueId = 10049120,
          GUID = "19282BC0",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282BC0"
        },
        [10049121] = {
          Content = "难道说，那个契约并非只是口头上的，而是让你能找到我的航标？",
          ContentKR = "설마 그 계약이 단순히 말로만 한 게 아니라, 절 찾아내는 표식 같은 거였나요?",
          DialogueId = 10049121,
          GUID = "19282BEA",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282BEA"
        },
        [10049122] = {
          Content = "并非如此。也许我得用一个虽然听起来更复杂，但也最简单的说法来向你解释。",
          ContentKR = "그건 아니에요. 조금 복잡하게 들릴 순 있지만, 그래도 최대한 간단하게 설명해 줄게요.",
          DialogueId = 10049122,
          GUID = "19282C14",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282C14"
        },
        [10049123] = {
          Content = "我，把我的灵魂分成了两半，一半自然是留在了自己的身体里，另一半，就在这里，在你的眼前。",
          ContentKR = "제 영혼을 둘로 나눴어요. 절반은 당연히 제 육체에 남겨뒀고, 나머지 절반은 바로 여기, 당신 눈앞에 있어요.",
          DialogueId = 10049123,
          GUID = "19282C3E",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282C3E"
        },
        [10049124] = {
          Content = "你坚持要逞强，而我也没有更好的方式解决那辆过载的火车。所以，我只能用这种办法，用我从母亲血脉中继承的古老仪式，以相连的生命带你离开雾海。",
          ContentKR = "당신은 끝까지 고집을 부렸고, 저도 과부하 상태인 그 열차를 해결할 더 나은 방법이 없었어요. 그래서 이 방법을 쓴 거예요. 어머니의 핏줄에서 물려받은 고대 의식으로 생명을 연결하고, 당신을 안개의 바다에서 데려 나온 거죠.",
          DialogueId = 10049124,
          GUID = "19282C68",
          RelatedWikiId = {
            [1] = 304009
          },
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282C68"
        },
        [10049125] = {
          Content = "很遗憾……一开始我还希望你运气足够好，能省下这份力量，又或者在更久以后才用上。",
          ContentKR = "유감이네요... 당신 운이 좋아서 이 힘을 아껴둘 수 있길 바랐거든요. 아니면 좀 더 나중에 쓸 수 있다면 좋았겠죠.",
          DialogueId = 10049125,
          GUID = "19282C92",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282C92"
        },
        [10049126] = {
          Content = "抱歉……",
          ContentKR = "미안해요...",
          DialogueId = 10049126,
          GUID = "19282CBC",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282CBC"
        },
        [10049127] = {
          Content = "不要道歉。毕竟，最初是因为你接下了我的委托，才会有这些事发生。",
          ContentKR = "사과하지 마세요. 어차피 애초에 당신이 제 의뢰를 받아줬기 때문에 이런 일들이 생긴 거니까요.",
          DialogueId = 10049127,
          GUID = "19282CE6",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282CE6"
        },
        [10049128] = {
          Content = "我一直一直期待着，可以向你说一句“谢谢”。还好现在并不晚。",
          ContentKR = "전 줄곧 당신에게 고맙다고 말할 기회를 기다렸어요. 지금이라도 늦지 않아서 다행이에요.",
          DialogueId = 10049128,
          GUID = "19282D10",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282D10"
        },
        [10049129] = {
          Content = "好了，我想说的差不多也说完了，那么，伸出手来。",
          ContentKR = "자, 하고 싶은 말은 거의 다 했으니까, 이제 손을 내밀어 봐요.",
          DialogueId = 10049129,
          GUID = "19282D3A",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282D3A"
        },
        [10049130] = {
          Content = "干什么？",
          ContentKR = "뭐 하려고요?",
          DialogueId = 10049130,
          GUID = "19282D64",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282D64"
        },
        [10049131] = {
          Content = "当然是把我自己——芙罗拉的一半的力量给你，让你离开这里，去亲眼见证你关心的那些人们到底如何了。",
          ContentKR = "당연히 저 플로라의 힘의 절반을 당신에게 주려는 거죠. 그래야 여기서 나가서, 당신이 걱정하는 사람들이 어떻게 됐는지 직접 확인할 수 있잖아요.",
          DialogueId = 10049131,
          GUID = "19282D8E",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282D8E"
        },
        [10049132] = {
          Content = "好。",
          ContentKR = "알겠어요.",
          DialogueId = 10049132,
          GUID = "19282DB8",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282DB8"
        },
        [10049133] = {
          Content = "不过，总觉得你比现实里的芙罗拉要话多一些？",
          ContentKR = "근데 왠지 현실의 플로라보다 말이 좀 많은 것 같은데요?",
          DialogueId = 10049133,
          GUID = "19282DE2",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282DE2"
        },
        [10049134] = {
          Content = "可能是外面的那个我背负着太多喘不过气的东西，而在这里，我只是一个最普通不过的人。",
          ContentKR = "밖에 있는 플로라는, 아마 숨도 못 쉴 만큼 많은 짐을 짊어지고 있어서 그럴 거예요. 여기 있는 플로라는 그냥 평범한 사람이거든요.",
          DialogueId = 10049134,
          GUID = "19282E0C",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282E0C"
        },
        [10049135] = {
          Content = "你不也同样吗？我听见你像孩子一样大喊大叫。",
          ContentKR = "당신도 마찬가지잖아요? 아까 애들처럼 소리 지르는 거 다 들었어요.",
          DialogueId = 10049135,
          GUID = "19282E36",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282E36"
        },
        [10049136] = {
          Content = "这么一说，我都有点同情你了，醒来之后就得先呛上一大口水，然后去面对那个既美丽又冰冷的世界。",
          ContentKR = "근데 생각해 보니 좀 안쓰럽기도 하네요. 여기서 깨어나면 입안에 물부터 한가득 들이키고, 그 아름답지만 차가운 세계를 다시 마주해야 하잖아요.",
          DialogueId = 10049136,
          GUID = "19282E60",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282E60"
        },
        [10049137] = {
          Content = "美丽又冰冷的世界啊……很精确的形容，但我可能会补充另一个说法：",
          ContentKR = "아름답지만 차가운 세계라... 정확한 묘사네요. 하지만 전 다른 말로 표현하고 싶어요.",
          DialogueId = 10049137,
          GUID = "19282E8A",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282E8A"
        },
        [10049138] = {
          Content = "我需要回到那个尚有许多人在等待着我的世界。",
          ContentKR = "전 '아직 많은 사람들이 절 기다리고 있는 그 세계'로 돌아가야 해요.",
          DialogueId = 10049138,
          GUID = "19282EB4",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282EB4"
        },
        [10049139] = {
          Content = "世界对我来说，并非是几个形容词就能概括的，尽管它可能很残酷，残酷到把我送到了雾海。",
          ContentKR = "저한테 세계란 몇 개의 형용사로 정의할 수 있는 게 아니에요. 어쩌면 잔인할 수도 있겠죠. 절 안개의 바다로 보낼 정도로 말이에요.",
          DialogueId = 10049139,
          GUID = "19282EDE",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282EDE"
        },
        [10049140] = {
          Content = "但是，它也是一个个围绕着我的人们而织就的，为了他们，我也必须回去。",
          ContentKR = "하지만 거긴 절 둘러싼 하나하나의 사람들로 엮인 세계이기도 해요. 그 사람들을 위해서라도 전 반드시 돌아가야 해요.",
          DialogueId = 10049140,
          GUID = "19282F08",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282F08"
        },
        [10049141] = {
          Content = "你要是这么想，我就放心了。",
          ContentKR = "그렇게 생각한다니 안심이 되네요.",
          DialogueId = 10049141,
          GUID = "19282F32",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282F32"
        },
        [10049142] = {
          Content = "那么，芙罗拉有什么打算呢？",
          ContentKR = "그럼, 플로라 씨는 이제 어떻게 할 생각이죠?",
          DialogueId = 10049142,
          GUID = "19282F5C",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19282F5C"
        },
        [10049143] = {
          Content = "我会换上贫民的衣服，在军团的人到来之前，混迹在人群中离开。随后，前往迪斯玛尼亚与希尔妲会面。",
          ContentKR = "전 평민 옷으로 갈아입고, 군단 쪽 사람들이 도착하기 전에 인파에 섞여 빠져나갈 거예요. 그 후에는 디즈마니아로 가서 힐다와 만날 예정이고요.",
          DialogueId = 10049143,
          GUID = "19282F86",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282F86"
        },
        [10049144] = {
          Content = "接下来，我会到南方的<H>伊瑟尔自由邦</>去，去那里解开一个父亲生前留下的谜题。也许，那个谜题可以赋予我无法估算的力量。",
          ContentKR = "그다음에는 남쪽의 <H>이스엘 자유국</>으로 가서, 아버지께서 생전에 남기신 수수께끼를 풀 생각이에요. 어쩌면 그 수수께끼가 제게 가늠할 수 없는 힘을 줄지도 모르니까요.",
          DialogueId = 10049144,
          GUID = "19282FB0",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282FB0"
        },
        [10049145] = {
          Content = "而后，我将借助它完成<H>复仇</>。",
          ContentKR = "그리고 그 힘으로 <H>복수</>를 할 거예요.",
          DialogueId = 10049145,
          GUID = "19282FDA",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19282FDA"
        },
        [10049146] = {
          Content = "复仇？",
          ContentKR = "복수요?",
          DialogueId = 10049146,
          GUID = "19283004",
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/19283004"
        },
        [10049147] = {
          Content = "神弃者同盟有一点说得没错，海伯利亚早就疯了，变成了一头嗜血的巨兽。而造成这一切的人，他们必须付出代价。",
          ContentKR = "포세이큰 동맹의 말이 적어도 하나는 맞았어요. 휘페르보레아는 이미 미쳐버렸고, 피에 굶주린 괴수가 돼버렸죠. 이 모든 걸 초래한 자들, 그들은 반드시 대가를 치러야 해요.",
          DialogueId = 10049147,
          GUID = "1928302E",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/1928302E"
        },
        [10049148] = {
          Content = "无需满面担忧，{nickname}。我所言的复仇，绝非神弃者同盟那样的全然破坏。",
          ContentKR = "걱정하진 마세요, {nickname}. 제가 말하는 복수는 포세이큰 동맹처럼 모든 걸 파괴하는 건 아니에요.",
          DialogueId = 10049148,
          GUID = "19283058",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19283058"
        },
        [10049149] = {
          Content = "——而是，改变我们的国家。我要予贫苦者以生存，予卑下者以尊严，予被战火折磨的人们以和平，予这个国度以失落的正义。",
          ContentKR = "제가 원하는 건, 이 나라를 바꾸는 거예요. 가난한 이들에겐 생존을, 천한 이들에겐 존엄을, 전쟁의 고통에 시달리는 이들에겐 평화를, 그리고 이 나라엔 잃어버린 정의를 되찾아주고 싶어요.",
          DialogueId = 10049149,
          GUID = "19283082",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19283082"
        },
        [10049150] = {
          Content = "那样的未来，我希望和你，和希尔妲，和夜航者小队，和这辆列车上的人们一起见证。",
          ContentKR = "그런 미래를, 전 당신과 힐다, 녹토 보이저 팀, 그리고 이 열차에 탄 모든 사람들과 함께 보고 싶어요.",
          DialogueId = 10049150,
          GUID = "192830AC",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/192830AC"
        },
        [10049151] = {
          Content = "<H>伊瑟尔自由邦</>……如果你也愿意和我一起踏上这条道路，就让我们在那里相会。",
          ContentKR = "<H>이스엘 자유국</>... 만약 당신도 저와 함께 이 길을 걷고 싶다면, 그곳에서 만나요.",
          DialogueId = 10049151,
          GUID = "192830D6",
          RelatedWikiId = {
            [1] = 105001
          },
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/192830D6"
        },
        [10049152] = {
          Content = "当然，在此之前，你要找到那位重要之人。希尔妲是一位出身于军团的、最优秀的密探，她会按照承诺给予你一切协助。",
          ContentKR = "물론, 그 전에 당신은 그 중요한 사람을 찾아야 해요. 힐다는 군단 출신의 최우수 요원이고, 약속대로 당신의 모든 일을 도와줄 거예요.",
          DialogueId = 10049152,
          GUID = "19283100",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19283100"
        },
        [10049153] = {
          Content = "那么，该启程了，{nickname}。",
          ContentKR = "그럼, 이제 떠날 시간이에요, {nickname}.",
          DialogueId = 10049153,
          GUID = "1928312A",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/1928312A"
        },
        [10049154] = {
          Content = "记得醒来后要立刻往上游，毕竟你的身体还在水里。如果获得第二次生命后就立刻被水呛死，那你可就是史上最愚蠢的狩月人了。",
          ContentKR = "깨어나면 바로 수면 위로 올라가는 거 잊지 마세요. 당신 몸은 아직 물속에 있으니까요. 두 번째 생명을 얻자마자 물에 빠져 죽는다면, 당신은 역사상 가장 멍청한 월석 사냥꾼이 될 거예요.",
          DialogueId = 10049154,
          GUID = "19283154",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100491/19283154"
        },
        [10049155] = {
          Content = "你难道忘记了吗？我其实早就是了。",
          ContentKR = "잊은 건가요? 전 원래 그런 사람이었잖아요.",
          DialogueId = 10049155,
          GUID = "1928317E",
          NextDialogue = 100499190,
          SpeakNpcId = 1001,
          VoiceName = "voice/$Locale$/story/1004/100491/1928317E"
        },
        [10049201] = {
          Content = "12小时前，百花车站站台",
          ContentKR = "12시간 전, 블룸필드역 승강장",
          DialogueId = 10049201,
          GUID = "1928390A",
          VoiceName = "voice/$Locale$/story/1004/100492/1928390A"
        },
        [10049202] = {
          Content = "你……怎么回来了？不是说要回去思考一晚上吗？",
          ContentKR = "당신... 왜 돌아온 거죠? 하룻밤 생각해 보고 온다고 하지 않았어요?",
          DialogueId = 10049202,
          GUID = "19283934",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100492/19283934"
        },
        [10049203] = {
          Content = "不用了，我答应你的委托。",
          ContentKR = "그럴 필요 없어요. 의뢰를 받아들일게요.",
          DialogueId = 10049203,
          GUID = "1928395E",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100492/1928395E"
        },
        [10049204] = {
          Content = "你是不是有点太低估这项委托的难度了？",
          ContentKR = "혹시 이 의뢰의 난이도를 너무 과소평가하는 건 아닌가요?",
          DialogueId = 10049204,
          GUID = "19283988",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100492/19283988"
        },
        [10049205] = {
          Content = "没有，甚至我觉得它的困难会超乎我的想象，但是我也意识到，这应该是距离我追求目标的最直接路径。",
          ContentKR = "아뇨, 오히려 제가 상상조차 못 할 만큼 어려울 거라고 생각해요. 하지만 그게 제가 추구하는 목표에 가장 빠르게 다가갈 수 있는 길이란 걸 알았죠.",
          DialogueId = 10049205,
          GUID = "192839B2",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100492/192839B2"
        },
        [10049206] = {
          Content = "所以，我愿意帮助你，芙罗拉。",
          ContentKR = "그래서, 당신을 돕고 싶어요. 플로라 씨.",
          DialogueId = 10049206,
          GUID = "192839DC",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100492/192839DC"
        },
        [10049207] = {
          Content = "真是……把利益看得比自身安危还重的愚蠢狩月人。但……向你发出委托的我也同样愚蠢罢了。",
          ContentKR = "...이익을 자기 안전보다 중요하게 여긴다니... 정말 멍청한 월석 사냥꾼이로군요. 하지만... 당신에게 의뢰를 하는 저 역시 어리석은 건 마찬가지겠죠.",
          DialogueId = 10049207,
          GUID = "19283A06",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100492/19283A06"
        },
        [10049208] = {
          Content = "那么我现在正式向你发出委托：狩月人{nickname}，我希望你能让我获得自由。",
          ContentKR = "그럼 이제 정식으로 의뢰할게요. 월석 사냥꾼 {nickname}, 절 자유롭게 해주세요.",
          DialogueId = 10049208,
          GUID = "19283A30",
          SpeakNpcId = 100404,
          VoiceName = "voice/$Locale$/story/1004/100492/19283A30"
        },
        [10049209] = {
          Content = "我接受这项委托。并承诺，一定帮你实现。",
          ContentKR = "그 의뢰 받아들일게요. 그리고 약속하죠, 반드시 이뤄 줄게요.",
          DialogueId = 10049209,
          GUID = "19283A5A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100492/19283A5A"
        },
        [10049301] = {
          Content = "那位下属本不必死。",
          ContentKR = "그 부하는 죽을 필요가 없었다.",
          DialogueId = 10049301,
          GUID = "19284972",
          RelatedWikiId = {
            [1] = 204002
          },
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100446,
          VoiceName = "voice/$Locale$/story/1004/100493/19284972"
        },
        [10049302] = {
          Content = "你还是喜欢生额外的事端，就像我第一次见到你那样，“牲王”。",
          ContentKR = "넌 여전히 쓸데없는 일을 벌이는 걸 좋아하는군. 처음 널 만났을 때처럼 말이야, '야수왕'.",
          DialogueId = 10049302,
          GUID = "1928499C",
          RelatedWikiId = {
            [1] = 201015,
            [2] = 407016
          },
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100446,
          VoiceName = "voice/$Locale$/story/1004/100493/1928499C"
        },
        [10049303] = {
          Content = "你的废话也像我第一次见你时一样多。你要点燃天之树的目标我达成了，这不就够了。",
          ContentKR = "당신 잔소리도 처음 만났을 때만큼이나 많네요. 천국의 나무를 불태우라는 당신 목표는 달성했잖아요. 그거면 된 거 아니에요?",
          DialogueId = 10049303,
          GUID = "192849C6",
          SpeakNpcId = 100413,
          VoiceName = "voice/$Locale$/story/1004/100493/192849C6"
        },
        [10049304] = {
          Content = "还有，没事别用那个称呼叫我。能进雾影会固然很好，但为什么只有我的职位名那么没品，像只小畜生。",
          ContentKR = "그리고, 웬만하면 그 이름으로 부르지 마세요. 미스트 새도우에 들어온 건 좋은데, 왜 제 호칭만 그렇게 품격이 없는 거죠? 꼭 짐승 취급하는 것 같잖아요.",
          DialogueId = 10049304,
          GUID = "192849F0",
          RelatedWikiId = {
            [1] = 101004
          },
          SpeakNpcId = 100413,
          VoiceName = "voice/$Locale$/story/1004/100493/192849F0"
        },
        [10049305] = {
          Content = "“牲王”的意义，并非汇聚盲从的野兽，让它们如群氓般撕咬，而是教会它们如何潜伏在黑暗中，磨砺自己的爪子和牙齿，找准最合适的时机，一击毙命。",
          ContentKR = "'야수왕'의 의미는 야수떼를 한데 모아 맹목적인 군중처럼 물어뜯게 하는 게 아니다. 그들에게 어둠 속에 잠복하며 발톱과 이빨을 날카롭게 갈고닦아, 가장 적절한 순간을 노려 일격에 목숨을 끊는 법을 알려주는 것이야.",
          DialogueId = 10049305,
          GUID = "19284A1A",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100446,
          VoiceName = "voice/$Locale$/story/1004/100493/19284A1A"
        },
        [10049306] = {
          Content = "愤怒总是驱使你做无意义的事，卡嘉。",
          ContentKR = "넌 늘 분노에 못 이겨 무의미한 짓을 하는군, 카지아.",
          DialogueId = 10049306,
          GUID = "19284A44",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100446,
          VoiceName = "voice/$Locale$/story/1004/100493/19284A44"
        },
        [10049307] = {
          Content = "说到无意义的事，你不也一样么？按照原计划，你不会出现在这里。是为了关注那个半路跑出来的{nickname}，你才来。",
          ContentKR = "무의미한 짓이라면, 당신도 마찬가지 아닌가요? 원래 계획대로라면 당신은 여기 나타나지 않았어야 했죠. 중간에 튀어나온 그 {nickname} 때문에 온 거잖아요.",
          DialogueId = 10049307,
          GUID = "19284A6E",
          SpeakNpcId = 100413,
          VoiceName = "voice/$Locale$/story/1004/100493/19284A6E"
        },
        [10049308] = {
          Content = "我就不明白了，对{性别：他|她}这么感兴趣的话，直接抓来不就好了么，反正你又不是办不到。",
          ContentKR = "이해가 안 돼요. 그 녀석한테 그렇게 관심이 많으면 그냥 잡아 오면 되잖아요. 어차피 당신이라면 못 할 것도 아니면서.",
          DialogueId = 10049308,
          GUID = "19284A98",
          SpeakNpcId = 100413,
          VoiceName = "voice/$Locale$/story/1004/100493/19284A98"
        },
        [10049309] = {
          Content = "…………",
          ContentKR = "......",
          DialogueId = 10049309,
          GUID = "19284AC2",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100446,
          VoiceName = "voice/$Locale$/story/1004/100493/19284AC2"
        },
        [10049310] = {
          Content = "你僭越了，“牲王”。",
          ContentKR = "선을 넘는군, '야수왕'.",
          DialogueId = 10049310,
          GUID = "19284AEC",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100446,
          VoiceName = "voice/$Locale$/story/1004/100493/19284AEC"
        },
        [10049311] = {
          Content = "……是。",
          ContentKR = "...알겠어요.",
          DialogueId = 10049311,
          GUID = "19284B16",
          SpeakNpcId = 100413,
          VoiceName = "voice/$Locale$/story/1004/100493/19284B16"
        },
        [10049312] = {
          Content = "那我走了。去找到哈洛吉的尸体。搭档一场，我得好好送他去雾海。",
          ContentKR = "그럼 전 하로기의 시신을 찾으러 가 볼게요. 그래도 동료였는데, 제대로 안개의 바다로 보내줘야죠.",
          DialogueId = 10049312,
          GUID = "19284B40",
          SpeakNpcId = 100413,
          VoiceName = "voice/$Locale$/story/1004/100493/19284B40"
        },
        [10049313] = {
          Content = "卡嘉。",
          ContentKR = "카지아.",
          DialogueId = 10049313,
          GUID = "19284B6A",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100446,
          VoiceName = "voice/$Locale$/story/1004/100493/19284B6A"
        },
        [10049314] = {
          Content = "他们的死是有意义的。燃烧的天之树已经撕裂了帝国的天空，而燃烧仍将继续。我们已经无需担心那些飞在天空中的巨兽对我们进行单方面屠戮。",
          ContentKR = "그들의 죽음은 의미가 있었다. 불타는 천국의 나무가 이미 제국의 하늘을 갈라놓았고, 그 불길은 계속될 거다. 이제 우린 공중을 날아다니는 괴물들의 일방적인 학살을 걱정할 필요가 없다.",
          DialogueId = 10049314,
          GUID = "19284B94",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100446,
          VoiceName = "voice/$Locale$/story/1004/100493/19284B94"
        },
        [10049315] = {
          Content = "取而代之的，是战争。这一次，我们不会再有犹疑或怜悯。",
          ContentKR = "그 대신, 전쟁이 시작될 거다. 이번만큼은 망설임도, 자비도 없을 거다.",
          DialogueId = 10049315,
          GUID = "19284BBE",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100446,
          VoiceName = "voice/$Locale$/story/1004/100493/19284BBE"
        },
        [10049316] = {
          Content = "是的，战争从未结束。隐忍了这么多年，这个时刻终于来临。而当它结束之时，海伯利亚帝国或是神弃者同盟，终有一方将被烧成灰烬。",
          ContentKR = "그래, 전쟁은 결코 끝나지 않았다. 그토록 오랜 세월을 참고 견뎌, 드디어 그 순간이 온 거다. 그리고 이 전쟁이 끝날 때는, 휘페르보레아 제국이든, 포세이큰 동맹이든, 둘 중 하나는 반드시 재가 되어 사라질 것이다.",
          DialogueId = 10049316,
          GUID = "19284BE8",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100446,
          VoiceName = "voice/$Locale$/story/1004/100493/19284BE8"
        },
        [10049401] = {
          Content = "嘿！那边的年轻人！",
          ContentKR = "저기! 거기 너!",
          DialogueId = 10049401,
          GUID = "192859DA",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 201005,
            [3] = 201009
          },
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/192859DA"
        },
        [10049402] = {
          Content = "没错，就是你！不知你是否愿意帮我一个小忙？我在皇都颇有一些家资，可以付给你公道无欺的报酬！",
          ContentKR = "그래, 너 말이야! 내 부탁 하나만 들어주지 않을래? 우리 집은 황성에서 꽤 알아주는 부자니까, 보수는 섭섭하지 않게 챙겨 줄게!",
          DialogueId = 10049402,
          GUID = "19285A04",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285A04"
        },
        [10049403] = {
          Content = "（似乎是个贵族。）",
          ContentKR = "(귀족인 것 같네.)",
          DialogueId = 10049403,
          DisableMouth = 1,
          GUID = "19285A2E",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100494/19285A2E"
        },
        [10049404] = {
          Content = "我看你刚刚在这边忙来忙去，但我又看你衣服整洁，和人说话神态也毫不畏缩，看起来不像是来讨生活的。",
          ContentKR = "아까부터 계속 이 근처를 왔다갔다 하던데, 멀끔한 옷차림에 당당한 태도를 보면, 하루 벌어 하루 먹고사는 그런 타입은 아닌 것 같단 말이지.",
          DialogueId = 10049404,
          GUID = "19285A58",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285A58"
        },
        [10049405] = {
          Content = "倒是像去调查锻铁厂里面锻铁工生活情况的记者，或者，另有所图！",
          ContentKR = "제철소 안 노동자들의 상황을 취재하러 온 기자거나... 뭔가 다른 꿍꿍이가 있는 거겠지!",
          DialogueId = 10049405,
          GUID = "19285A82",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285A82"
        },
        [10049406] = {
          Content = "？！",
          ContentKR = "?!",
          DialogueId = 10049406,
          GUID = "19285AAC",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100494/19285AAC"
        },
        [10049407] = {
          Content = "别慌别慌，我和你实际上也差不多！我呢，其实是刚入职《海伯利亚早报》的记者，迪斯玛尼亚过来的！",
          ContentKR = "당황하지 마, 사실 나도 너랑 사정이 비슷하거든! 사실 난 디즈마니아에서 온 〈휘페르보레아 제국 조간신문〉의 신입 기자야!",
          DialogueId = 10049407,
          GUID = "19285AD6",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285AD6"
        },
        [10049408] = {
          Content = "我听小道消息说，冰湖城这边的第六军团，别看嘴上说着忠诚，私下里坏得冒烟，不知道干过多少欺负平民的勾当。",
          ContentKR = "여기 아이스레이크 시티의 제6군단이 겉으로만 충성하네 어쩌네 하고, 뒤로는 온갖 못된 짓들을 하면서 평민들을 괴롭히고 다닌다는 얘길 들었거든.",
          DialogueId = 10049408,
          GUID = "19285B00",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285B00"
        },
        [10049409] = {
          Content = "别说，刚来到车站这个地方，我就觉得很不舒服了。我昨天才打听了一下午，就感觉走哪儿都有卫兵的视线盯着，他们一定在提防我……",
          ContentKR = "아니나 다를까, 어제 딱 이 기차역에 도착했는데, 분위기가 영 마음에 안 들더라고. 어제 오후에 정보 좀 캐고 다녔다고, 가는 곳마다 경비병들이 빤히 쳐다보더라니까. 날 감시하는 게 분명해...",
          DialogueId = 10049409,
          GUID = "19285B2A",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285B2A"
        },
        [10049410] = {
          Content = "真是罪恶的城市！不过一个小小的车站，就埋藏着这么多不可告人的秘密。",
          ContentKR = "이 조그만 기차역에 그렇게나 많은 추악한 비밀이 숨겨져 있다니. 여긴 죄악의 도시가 틀림없어!",
          DialogueId = 10049410,
          GUID = "19285B54",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285B54"
        },
        [10049411] = {
          Content = "你都打听了些什么？",
          ContentKR = "뭘 알아보고 다니셨는데요?",
          DialogueId = 10049411,
          GUID = "19285B7E",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100494/19285B7E"
        },
        [10049412] = {
          Content = "“我听说第六军团有很多不可告人的勾当，把你了解的都告诉我吧！让我们一起揭露这片土地上的邪恶。”",
          ContentKR = "\"제6군단에선 차마 말 못 할 짓들을 수도 없이 저지른다던데, 아는 대로 다 털어놔 보세요! 함께 이 도시의 추악한 실상을 세상에 알리는 거예요\"라고 했지.",
          DialogueId = 10049412,
          GUID = "19285BA8",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285BA8"
        },
        [10049413] = {
          Content = "这样明着打听，别人知道也不会告诉你的。",
          ContentKR = "그렇게 대놓고 캐물으면, 누가 정보를 제공하겠어요.",
          DialogueId = 10049413,
          GUID = "19285BD2",
          ImprPlusId = 1008
        },
        [10049414] = {
          Content = "说得好，军团太坏了，就该这么骂！",
          ContentKR = "옳으신 말씀이에요! 군단은 못된 놈들이라, 욕을 바가지로 먹어도 싸요!",
          DialogueId = 10049414,
          GUID = "19285BFC",
          ImprPlusId = 1010
        },
        [10049415] = {
          Content = "这都没把你当危险分子抓走，站长脾气还怪好的。",
          ContentKR = "그 난리를 치고도 위험인물로 안 끌려간 걸 보면, 여기 역장은 성격이 엄청 좋은가 보네요.",
          DialogueId = 10049415,
          GUID = "19285C26",
          ImprPlusId = 1006
        },
        [10049416] = {
          Content = "奇怪了，动物挨打会出声，人不也应该差不多啊。还是说这边的情况已经糟糕到没有卡戎相信索拉了？",
          ContentKR = "참 이상해. 지렁이도 밟으면 꿈틀하는 게 정상 아니야? 아니면 여기 상황이 정말 최악이라, 카론이 솔라를 전혀 못 믿는 지경이 된 건가?",
          DialogueId = 10049416,
          GUID = "19285C50",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285C50"
        },
        [10049417] = {
          Content = "可是真毫不犹豫赞同我的也只有你一个，大家好像都多少有所猜忌防备。",
          ContentKR = "하지만 이렇게 내 편을 들어주는 건 너밖에 없어. 다른 사람들은 몸 사리느라 바쁘더라고.",
          DialogueId = 10049417,
          GUID = "19285C7A",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285C7A"
        },
        [10049418] = {
          Content = "我？危险分子？我要是危险分子他就是危险国王！我确实听说他把这车站当做自己的私有物一样，也打算调查调查他。",
          ContentKR = "내가? 위험인물이라고? 내가 위험인물이면, 여기 역장은 위험 대마왕이야! 안 그래도 그 역장이 이 역을 자기 집 안방처럼 주무른다는 소문이 파다해서, 뒤를 좀 캐보려던 참이었어.",
          DialogueId = 10049418,
          GUID = "19285CA4",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285CA4"
        },
        [10049419] = {
          Content = "……总之，为了让埋在冰湖城的邪恶秘密公之于众，我需要一个人帮忙。我在这儿观察了一阵子，发现你就是最好的人选。",
          ContentKR = "...어쨌든, 아이스레이크 시티에 숨겨진 추악한 진실을 낱낱이 밝히려면 도와줄 사람이 하나 필요해. 아까부터 쭉 지켜봤는데, 네가 가장 적임자야.",
          DialogueId = 10049419,
          GUID = "19285CCE",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285CCE"
        },
        [10049420] = {
          Content = "首先，我刚刚已经说了，你应该也有自己的目的，想要调查些什么。",
          ContentKR = "첫 번째 이유는, 아까도 말했지만, 너도 나름의 목적을 가지고 뭔가를 조사 중이란 점이야.",
          DialogueId = 10049420,
          GUID = "19285CF8",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285CF8"
        },
        [10049421] = {
          Content = "其次，整个大厅当中你是跑得最快的那个，身手绝非常人，所以我觉得你可以信赖。",
          ContentKR = "두 번째 이유는, 네가 이 대합실에 있는 사람 중에서 발이 제일 빠르더라고. 몸놀림도 뭔가 예사롭지 않은 게, 믿고 맡겨도 될 것 같아.",
          DialogueId = 10049421,
          GUID = "19285D22",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285D22"
        },
        [10049422] = {
          Content = "非要再说些什么的话，直觉告诉我……你不是坏人。",
          ContentKR = "굳이 이유를 하나 더 보태자면, 직감이야... 넌 나쁜 사람이 아닐 거란 느낌이 들거든.",
          DialogueId = 10049422,
          GUID = "19285D4C",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285D4C"
        },
        [10049423] = {
          Content = "但我也只是平民，在这里同样行动不便。",
          ContentKR = "그런데 전 평민이라, 여길 마음대로 돌아다닐 수 없는 건 마찬가지예요.",
          DialogueId = 10049423,
          GUID = "19285D76",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100494/19285D76"
        },
        [10049424] = {
          Content = "这很简单！我爸说过，“冰湖城那种乡下，没有一枚金币搞不定的事。如果有，那就再加一枚。”",
          ContentKR = "그건 걱정 마! 우리 아빠가 \"아이스레이크 시티 같은 촌구석에선 골드 한 닢이면 안 되는 일이 없다. 만일 정말 안 된다면, 한 닢 더 얹어주면 그만이야.\"라고 했거든.",
          DialogueId = 10049424,
          GUID = "19285DA0",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285DA0"
        },
        [10049425] = {
          Content = "这一沓都是我的支票，每张价值5金币。如果遇到有人找你麻烦，直接塞给他就好了——我爸说的。",
          ContentKR = "이건 내 수표 뭉치인데, 한 장당 골드 다섯 닢짜리야. 누가 트집 잡고 귀찮게 굴면, 그냥 이걸 쥐여줘. 그럼 해결된다고, 우리 아빠가 그랬어.",
          DialogueId = 10049425,
          GUID = "19285DCA",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285DCA"
        },
        [10049426] = {
          Content = "…………",
          ContentKR = "......",
          DialogueId = 10049426,
          GUID = "19285DF4",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100494/19285DF4"
        },
        [10049427] = {
          Content = "等调查出来真相，我也给你十张作为报酬，如何！",
          ContentKR = "진실을 밝혀내 주면, 보수로 이 수표 10장 줄게! 어때?",
          DialogueId = 10049427,
          GUID = "19285E1E",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285E1E"
        },
        [10049428] = {
          Content = "……也不是不行。",
          ContentKR = "...안 될 건 없죠.",
          DialogueId = 10049428,
          GUID = "19285E48",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100494/19285E48"
        },
        [10049429] = {
          Content = "好，那么为了确保你确实能打探到消息，我需要你先去试一试。来，拿上这叠支票，凑到锻铁厂入口的那个监工附近，去和他套套近乎。",
          ContentKR = "좋아, 그럼 네 정보 수집력을 확인할 겸 일단 테스트부터 해 보자. 자, 이 수표 뭉치를 가지고, 제철소 입구에 있는 현장 감독한테 가서 슬쩍 꼬드겨 봐.",
          DialogueId = 10049429,
          GUID = "19285E72",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285E72"
        },
        [10049430] = {
          Content = "你是不是只是单纯想使唤人？",
          ContentKR = "그냥 저 부려 먹고 싶어서 이러는 거 아니에요?",
          DialogueId = 10049430,
          GUID = "19285E9C",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100494/19285E9C"
        },
        [10049431] = {
          Content = "也不是啦，毕竟我家的钱也不是大风刮来的，总得要确认一下才是。",
          ContentKR = "아니야. 우리 집 돈도 땅 파서 나오는 게 아니니까, 실력은 확인해 봐야지.",
          DialogueId = 10049431,
          GUID = "19285EC6",
          SpeakNpcId = 100411,
          SpeakNpcName = "UI_SpeakName_Guizuqingnian",
          VoiceName = "voice/$Locale$/story/1004/100494/19285EC6"
        },
        [10049432] = {
          Content = "行，行，我去试一试。",
          ContentKR = "그래요, 알겠어요. 한번 해 볼게요.",
          DialogueId = 10049432,
          GUID = "19285EF0",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100494/19285EF0"
        },
        [10049501] = {
          Content = "你好……",
          ContentKR = "안녕하세요...",
          DialogueId = 10049501,
          GUID = "19286A42",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100495/19286A42"
        },
        [10049502] = {
          Content = "什么人？这里正在施工，并且也是锻铁厂入口附近，不是你该来的地方。",
          ContentKR = "넌 뭐냐니까? 여긴 공사 현장이고 제철소로 들어가는 입구야, 네가 올 곳이 아니라고.",
          DialogueId = 10049502,
          GUID = "19286A6C",
          SpeakNpcId = 100449,
          VoiceName = "voice/$Locale$/story/1004/100495/19286A6C"
        },
        [10049503] = {
          Content = "啊，是这样的，我是经常搭乘火车的乘客，看你们在这边辛苦整修车站，想着你们也不容易，于是想要资助一下。",
          ContentKR = "아, 그게요. 저는 기차를 자주 타는 승객인데, 여러분이 보수 공사를 하시느라 고생이 너무 많으시길래, 후원을 조금 하고 싶어서요.",
          DialogueId = 10049503,
          GUID = "19286A96",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100495/19286A96"
        },
        [10049504] = {
          Content = "叽里咕噜说这么一大堆，我以为是要干什么。说吧，资助什么？提前说啊，什么旧衣服破鞋子之类的，这边可不要。",
          ContentKR = "중얼중얼 무슨 중요한 얘기라도 하나 했네. 그래서, 뭘 후원하겠다는 건데? 미리 말해 두는데, 헌 옷이나 낡아빠진 신발 쪼가리 같은 건 안 받아.",
          DialogueId = 10049504,
          GUID = "19286AC0",
          SpeakNpcId = 100449,
          VoiceName = "voice/$Locale$/story/1004/100495/19286AC0"
        },
        [10049505] = {
          Content = "是这个，你看看呢。",
          ContentKR = "이거예요. 한번 보세요.",
          DialogueId = 10049505,
          GUID = "19286AEA",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100495/19286AEA"
        },
        [10049506] = {
          Content = "一张纸？我看看……嗯？支票？",
          ContentKR = "종이 쪼가리잖아? 어디 보자... 어? 수표네?",
          DialogueId = 10049506,
          GUID = "19286B14",
          SpeakNpcId = 100449,
          VoiceName = "voice/$Locale$/story/1004/100495/19286B14"
        },
        [10049507] = {
          Content = "哎呀哎呀，你早说嘛。实际上我看您也面熟，一早就知道你是对铁道建设极为热心之人。说吧，有什么我可以帮您的？",
          ContentKR = "아이고, 진작 말씀을 하시지. 그렇지 않아도 어디서 많이 뵀다 싶었더니, 역시나 철도 사업에 관심이 많은 분이셨군요. 자, 제가 뭘 도와드리면 될까요?",
          DialogueId = 10049507,
          GUID = "19286B3E",
          SpeakNpcId = 100449,
          VoiceName = "voice/$Locale$/story/1004/100495/19286B3E"
        },
        [10049508] = {
          Content = "实际上，我想了解看看锻铁厂是什么样的，但一直被拦着……",
          ContentKR = "사실, 제철소 안이 어떻게 생겼는지 조금 둘러보고 싶은데, 계속 저는 출입이 안 된다고...",
          DialogueId = 10049508,
          GUID = "19286B68",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100495/19286B68"
        },
        [10049509] = {
          Content = "哎呀，就这点事，我当是什么呢。小事小事，报我名字就行了。你想待多久待多久！",
          ContentKR = "아이고, 그런 거라면 진작 말씀하시지! 별거 아니니까, 제 이름을 대고 들어가시면 됩니다. 원하시는 만큼 편히 계세요!",
          DialogueId = 10049509,
          GUID = "19286B92",
          SpeakNpcId = 100449,
          VoiceName = "voice/$Locale$/story/1004/100495/19286B92"
        },
        [10049601] = {
          Content = "你们到底是怎么搞的，就这么个调试流程，乱七八糟。啊，前天是液压阀压力不够，昨天是月髓液喷料。",
          ContentKR = "대체 일을 어떻게들 하길래, 시운전 절차가 이렇게 엉망진창이야! 엊그제는 유압 밸브 압력이 떨어지더니, 어제는 액체 폭시코르가 뿜어져 나왔잖아!",
          DialogueId = 10049601,
          GUID = "19287AAA",
          RelatedWikiId = {
            [1] = 408022,
            [2] = 406007
          },
          SpeakNpcId = 100407,
          SpeakNpcName = "UI_SpeakName_WeiyanGongren",
          VoiceName = "voice/$Locale$/story/1004/100496/19287AAA"
        },
        [10049602] = {
          Content = "今天倒好咯，测试一开始，列车头撞出去十几米，我看你们不是在测试火车，是在测试飞艇哦。",
          ContentKR = "오늘은 한술 더 떠서 테스트 시작하자마자, 열차가 10m도 넘게 앞으로 치고 나갔다고! 이게 열차 테스트야? 비행선 테스트지!",
          DialogueId = 10049602,
          GUID = "19287AD4",
          SpeakNpcId = 100407,
          SpeakNpcName = "UI_SpeakName_WeiyanGongren",
          VoiceName = "voice/$Locale$/story/1004/100496/19287AD4"
        },
        [10049603] = {
          Content = "要不是我眼疾手快躲到边上，就和这几个铸件一样，被压成铁饼了。卡诺，你来说一下这次的问题出在哪里。",
          ContentKR = "재빨리 옆으로 피해서 다행이지, 아니었으면 나도 저 쇳덩이들처럼 찌그러질 뻔했어! 카르노, 이번엔 대체 어디서 문제가 터진 건지 말해 봐.",
          DialogueId = 10049603,
          GUID = "19287AFE",
          SpeakNpcId = 100407,
          SpeakNpcName = "UI_SpeakName_WeiyanGongren",
          VoiceName = "voice/$Locale$/story/1004/100496/19287AFE"
        },
        [10049604] = {
          Content = "啊……嗯……应该是设置处在过载模式下的引擎太多了，超过了限制……",
          ContentKR = "아... 음... 과부하 모드로 설정된 엔진이, 설정 가능 상한을 초과해서 문제가 발생한 것 같습니다...",
          DialogueId = 10049604,
          GUID = "19287B28",
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100496/19287B28"
        },
        [10049605] = {
          Content = "没错，这就是老师傅的实力，说什么都是一句话到点上。你们也都学着点，要是人人都像卡诺一样可靠，我也不用这样每天提心吊胆上工。",
          ContentKR = "그래, 이게 바로 베테랑이라는 거야. 딱 한 마디로 핵심을 짚어내잖아. 너희도 좀 보고 배워. 다들 카르노처럼만 일해 주면, 내가 지금처럼 매일 불안에 떨면서 출근할 일도 없을 거 아니야.",
          DialogueId = 10049605,
          GUID = "19287B52",
          SpeakNpcId = 100407,
          SpeakNpcName = "UI_SpeakName_WeiyanGongren",
          VoiceName = "voice/$Locale$/story/1004/100496/19287B52"
        },
        [10049606] = {
          Content = "都给我检查一下问题，问题不清零，决不重新开始调试！",
          ContentKR = "문제점들 싹 다 다시 점검해! 결함을 전부 잡아내기 전까지, 시운전은 절대 없을 줄 알아!",
          DialogueId = 10049606,
          GUID = "19287B7C",
          SpeakNpcId = 100407,
          SpeakNpcName = "UI_SpeakName_WeiyanGongren",
          VoiceName = "voice/$Locale$/story/1004/100496/19287B7C"
        },
        [10049607] = {
          Content = "好——",
          ContentKR = "네!",
          DialogueId = 10049607,
          GUID = "19287BA6",
          SpeakNpcName = "UI_CMNpc_Chezhan_Name_Workers",
          VoiceName = "voice/$Locale$/story/1004/100496/19287BA6"
        },
        [10049608] = {
          Content = "那个……不好意思，我想过一下。",
          ContentKR = "저기... 실례합니다, 좀 지나갈게요.",
          DialogueId = 10049608,
          GUID = "19287BD0",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100496/19287BD0"
        },
        [10049609] = {
          Content = "不行，你也留下来，和他们一起检修。",
          ContentKR = "안 돼, 너희도 남아. 저 녀석들이랑 같이 점검해.",
          DialogueId = 10049609,
          GUID = "19287BFA",
          SpeakNpcId = 100407,
          SpeakNpcName = "UI_SpeakName_WeiyanGongren",
          VoiceName = "voice/$Locale$/story/1004/100496/19287BFA"
        },
        [10049610] = {
          Content = "啊？我们只是路过的烟囱工而已。",
          ContentKR = "네? 저희는 그냥 지나가던 굴뚝 청소부일 뿐인데요.",
          DialogueId = 10049610,
          GUID = "19287C24",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100496/19287C24"
        },
        [10049611] = {
          Content = "我管你是什么工人，想必刚刚你也听到了吧，我们这边在进行新型列车的实验，而实验的时候出现了大事故，导致火车头意外向前开动了。",
          ContentKR = "청소부고 나발이고 알 게 뭐야. 너희도 방금 들었지? 우리가 여기서 신형 열차 테스트를 하다가 대형 사고가 터져서, 열차가 갑자기 앞으로 돌진해 버렸다고.",
          DialogueId = 10049611,
          GUID = "19287C4E",
          SpeakNpcId = 100407,
          SpeakNpcName = "UI_SpeakName_WeiyanGongren",
          VoiceName = "voice/$Locale$/story/1004/100496/19287C4E"
        },
        [10049612] = {
          Content = "所以我宣布，在我的视线范围内所有人，都应该来排除其他的风险，否则火车头一爆炸，大家都得死！",
          ContentKR = "그러니까, 내 눈에 띄는 놈들은 모조리 일손을 보태야 해. 아니면 열차가 터져서 다 같이 골로 갈 판이니까!",
          DialogueId = 10049612,
          GUID = "19287C78",
          SpeakNpcId = 100407,
          SpeakNpcName = "UI_SpeakName_WeiyanGongren",
          VoiceName = "voice/$Locale$/story/1004/100496/19287C78"
        },
        [10049613] = {
          Content = "我也会死吗？",
          ContentKR = "저도 같이 죽나요?",
          DialogueId = 10049613,
          GUID = "19287CA2",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100496/19287CA2"
        },
        [10049614] = {
          Content = "对，所以不想死的话！快动起来，安全问题大过天！",
          ContentKR = "그래, 그러니까 죽기 싫으면 빨리빨리 움직여! 첫째도 안전, 둘째도 안전이야!",
          DialogueId = 10049614,
          GUID = "19287CCC",
          SpeakNpcId = 100407,
          SpeakNpcName = "UI_SpeakName_WeiyanGongren",
          VoiceName = "voice/$Locale$/story/1004/100496/19287CCC"
        },
        [10049615] = {
          Content = "就算他这么说……可是检修的话，该从哪里干起呢……",
          ContentKR = "하지만... 점검을 해 보려고 해도, 어디서부터 손을 대야 하는지 모르는데...",
          DialogueId = 10049615,
          GUID = "19287CF6",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100496/19287CF6"
        },
        [10049701] = {
          Content = "好，谢谢工段长。",
          ContentKR = "네. 수고하셨습니다, 반장님.",
          DialogueId = 10049701,
          GUID = "19288B12",
          SpeakNpcId = 100418,
          VoiceName = "voice/$Locale$/story/1004/100497/19288B12"
        },
        [10049702] = {
          Content = "我看你们几个干活挺麻利的，要不趁着肺还没被灰尘填满，别做烟囱工了，到我们车间来上工吧。",
          ContentKR = "너희 말이야, 일머리가 꽤 좋던데, 폐에 시커먼 먼지 들어차기 전에, 굴뚝 청소부는 때려치우고, 여기 와서 일하는 건 어때?",
          DialogueId = 10049702,
          GUID = "19288B3C",
          SpeakNpcId = 100407,
          SpeakNpcName = "UI_SpeakName_WeiyanGongren",
          VoiceName = "voice/$Locale$/story/1004/100497/19288B3C"
        },
        [10049703] = {
          Content = "不用了，谢谢你，我们还忙着有事。",
          ContentKR = "괜찮아요. 제안은 감사한데, 저희가 좀 바빠서요.",
          DialogueId = 10049703,
          GUID = "19288B66",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1004/100497/19288B66"
        },
        [10049704] = {
