        [10100813] = {
          Camera = "-495.370117,-373.561523,136.682617,0.001181,-3.199342,37.251434,50.0,754.408386,false,Manual,4.0,16:9 Digital Film",
          Content = "真是稀奇。不知哪儿冒出来的大慈善家花一笔巨款雇人救一个陌生人，却不愿露面，也没有说救了你之后要做什么。",
          ContentKR = "정말 이상하네. 갑자기 나타난 자선가께서 거액을 주고 사람을 고용해 생면부지 사람을 구해 놓고, 얼굴도 비추지 않는다니. 널 구한 후에 어떻게 하라는 말도 없었어.",
          DialogueId = 10100813,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "-487.870117,-383.416016,136.682617,0.001181,-3.199342,37.251339,50.0,793.406921,false,DoNotOverride,4.0,16:9 Digital Film",
