        [10100817] = {
          Camera = "-2534.498047,882.487305,128.315918,0.001157,0.000109,-69.548653,30.0,1183.44812,false,Manual,2.8,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "就算你宁愿一路乞讨穿越海伯利亚大平原，也要想方设法应付沿途各城镇的盘查。下一次，可就不一定这么好运——",
          ContentKR = "구걸로 휘페르보레아 제국 대평원을 통과한다고 해도, 그 많은 도시들의 검문은 또 어떻게 할 건데? 다음에도 이번처럼 운이 좋다는 보장은 없어.",
          DialogueId = 10100817,
          FinalCamera = "-2516.917969,889.322266,133.45166,0.001157,0.400112,-68.748718,30.0,1183.44812,false,Manual,2.8,16:9 Digital Film",
          GUID = "19494D4A",
          NextDialogue = 10100818,
          SpeakNpcId = 200003,
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101008/19494D4A"
        },
        [10100818] = {
          Camera = "-196.237305,-18.549316,146.658691,0.001187,-2.999962,0.843019,35.000008,264.133331,false,Manual,6.0,16:9 Digital Film",
          Content = "说不定，你就要在不知道哪个城市的牢狱里度过一大把好时光了。",
          ContentKR = "잘못하면 어느 도시의 감옥 안에서 허송세월하게 될지도 몰라.",
          DialogueId = 10100818,
          GUID = "19494D74",
          NextDialogue = 10100819,
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1002/101008/19494D74"
        },
        [10100819] = {
          Camera = "-3.067383,-50.891113,144.484375,0.00118,-1.90149,144.27504,35.000008,98.568146,false,Manual,2.8,16:9 Digital Film",
          Content = "（嗯……果然，回去并不是件容易事。要先想办法准备一笔钱，以及，刚才那位士兵提到的“通行证”。）",
          ContentKR = "(음... 역시 돌아가는 게 쉽지 않겠어. 돈을 마련할 방법을 찾아야 해. 아까 그 병사가 얘기한 '통행증'도 필요하고.)",
          DialogueId = 10100819,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "19494D9E",
          NextDialogue = 101008062,
          Scripts = "PlayAnimation{_delay{1.5},ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{1}}",
