        [10100820] = {
          Camera = "-196.237305,-18.549316,146.658691,0.001187,-2.999962,0.843019,35.000008,264.133331,false,Manual,6.0,16:9 Digital Film",
          Content = "十三军团直属于皇帝陛下，每个行省都有他们的踪迹。西比尔可能在海伯利亚任何一座要塞现身。",
          ContentKR = "모든 주가 황제 폐하 직속 군단인 제13군단 영향 하에 있어. 즉, 시빌라는 휘페르보레아 제국의 모든 요새에서 나타날 수 있다는 거야.",
          DialogueId = 10100820,
          GUID = "19494DC8",
          NextDialogue = 10100821,
          RelatedWikiId = {
            [1] = 101005
          },
          Scripts = [[
SEQ{
