}]],
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1002/101008/19494DC8"
        },
        [10100821] = {
          Camera = "-389.902344,-245.504395,22.587891,0.001195,10.30069,31.257433,35.000015,178.504257,false,DoNotOverride,4.0,16:9 Digital Film",
          Content = "而其中可能性最大的是，皇都迪斯玛尼亚那座巨大钢铁堡垒。全帝国最训练有素的士兵、一切你想象得到和想象不到的武器，都汇聚在那里。",
          ContentKR = "그중 가장 가능성이 큰 건 황성 디즈마니아의 거대한 강철 요새야. 제국에서 가장 잘 훈련된 병사들과 온갖 무기들이 전부 그곳에 모여 있거든.",
          DialogueId = 10100821,
          FinalCamera = "-373.101562,-274.45459,22.588379,0.001195,10.30069,35.05777,35.000015,178.504257,false,DoNotOverride,4.0,16:9 Digital Film",
          GUID = "19494DF2",
          NextDialogue = 10100822,
          RelatedWikiId = {
            [1] = 408004
          },
          Scripts = "PlayAnimation{_delay{2.2},ActorId{200003},AnimationId{\"Think_Start\"},Duration{1}}",
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "100001:Sigh_End",
            [2] = "200003:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101008/19494DF2"
        },
        [10100822] = {
          Camera = "-2070.686523,-3294.441406,2337.578125,0.001209,26.398127,22.05953,11.0,10000.0,false,Manual,1.2,16:9 Digital Film",
          CameraBlendCurve = "easeInQuad",
          Content = "海伯利亚是一座轰鸣的战车，那里就是它的引擎，它的炉芯——如果你想去试试，那就尽管去吧。我见过很多疯子，你不是第一个，也不是最后一个。",
          ContentKR = "휘페르보레아 제국이 힘차게 전진하는 전차라면, 그곳은 전차의 엔진이자 중심이지. 몸소 겪어보고 싶으면 마음대로 해. 정신 나간 것들이 어디 너 하나뿐이었겠어?",
          DialogueId = 10100822,
          FinalCamera = "-1849.558594,-2787.050781,2533.88208,0.001209,26.398127,22.05953,12.0,10000.0,false,Manual,1.2,16:9 Digital Film",
          GUID = "19494E1C",
          NextDialogue = 10100823,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/talk_engine_roaring\"},EventKey{\"talk_engine_roaring\"},PlayAs2D{false}}",
