          VoiceName = "voice/$Locale$/story/1002/101024/194A52A4"
        },
        [10102412] = {
          Camera = "-55.461655,-337.166504,128.610107,0.00026,-2.599427,85.993988,35.000011,438.68515,false,Manual,4.0,16:9 Digital Film",
          Content = "但是，我们在这里不受欢迎也是事实。你与索拉人打交道的时候，务必小心。",
          ContentKR = "근데, 우리가 여기서 환영받지 못한다는 것도 사실이야. 솔라랑 얘기할 땐 꼭 조심해야 해.",
          DialogueId = 10102412,
          FacialId = {
            [1] = "200006:None"
          },
          GUID = "194A52CE",
          LookAt = {
