          VoiceName = "voice/$Locale$/story/1002/101024/194A52CE"
        },
        [10102413] = {
          Camera = "58.191639,-99.209473,136.023438,0.000193,-2.407013,118.074898,35.000011,200.943283,false,Manual,16.789953,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "刚才那个士兵……即使那么残忍，他需要付出的代价，也不过是“失手”带来的降职而已。",
          ContentKR = "방금 그 병사도... 그렇게 잔인한 짓을 저질렀지만, 겨우 '실수'로 인한 좌천일 뿐이지.",
          DialogueId = 10102413,
          FacialId = {
            [1] = "200006:Unhappy01"
          },
          FinalCamera = "42.692451,-70.151367,134.639648,0.000193,-2.407013,118.074898,35.000011,167.002686,false,Manual,16.789953,16:9 Digital Film",
          GUID = "194A52F8",
          NextDialogue = 10102414,
          RelatedWikiId = {
