        [10102415] = {
          Camera = "-1800.157715,2413.916504,273.974609,0.000225,0.78582,15.127397,34.946079,2906.058594,false,Manual,1.2,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "就像卡戎之民不能进入冰湖城的内城，也不得离开帝国一样平常，就像花会凋谢，湖会冻结，雪落在炉火里会融化一样平常。",
          ContentKR = "꽃이 시들고 호수가 얼어붙고, 눈이 난로에 떨어지면 녹는 것과 같이 카론은 아이스레이크 시티의 내성에 들어갈 수 없고, 제국을 떠날 수도 없는 게 당연한 일인 것처럼 말이야.",
          DialogueId = 10102415,
          FinalCamera = "-1800.157715,2413.916504,273.974609,0.000221,16.385637,17.728439,34.946079,2906.058594,false,Manual,1.2,16:9 Digital Film",
          GUID = "194A534C",
