        },
        [10102418] = {
          Camera = "66.620682,-134.877441,134.162109,0.000286,-1.6084,122.284637,35.0,237.803711,false,Manual,10.0,16:9 Digital Film",
          Content = "海伯利亚的索拉人认为，会“魔法”的卡戎之民是邪恶的施术者，是人类安宁最大的威胁。",
          ContentKR = "휘페르보레아의 솔라들은 '마법'을 다루는 카론을 사악한 주술사이자 인간의 평화를 위협하는 가장 큰 존재로 여겨.",
          DialogueId = 10102418,
          FacialId = {
            [1] = "200006:Unhappy01"
          },
          FinalCamera = "70.857864,-124.749756,132.748047,0.000286,-1.6084,122.28463,35.0,260.709564,false,Manual,20.0,16:9 Digital Film",
          GUID = "194A53CA",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextDialogue = 10102419,
          SpeakNpcId = 200006,
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101024/194A53CA"
        },
        [10102419] = {
          Camera = "122.866249,218.987305,211.869629,0.000266,-23.201653,-126.796036,30.0,100000.0,false,DoNotOverride,2.8,16:9 Digital Film",
          Content = "那你们也不能总是默默忍受一切呀！为什么不用你们的魔法“轰”地一下，打得他们哇哇叫！……真是的，气死我了。",
          ContentKR = "그럼 너희도 계속 그렇게 참고 있어서는 안되잖아! 왜 너희 마법을 이용해서 '쾅'하고 날려버리지 않는 거야! ...정말이지 열받아 죽겠어.",
          DialogueId = 10102419,
          FacialId = {
            [1] = "200002:Unacceptable01"
          },
          GUID = "194A53F4",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextOptions = {
            [1] = 101024191,
