}]],
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101024/194A53F4"
        },
        [10102420] = {
          Camera = "64.667946,-80.196289,127.522705,0.000266,0.40182,121.194527,35.0,193.268097,false,Manual,8.0,16:9 Digital Film",
          Content = "十八九年前，帝国的卡戎之民曾发起过一场战争，那时我还没出生。我了解得不多，大家也不敢谈这些，只知道那场战争最后以卡戎之民的惨败告终。",
          ContentKR = "18, 19년 전, 제국의 카론이 전쟁을 일으켰던 적이 있었대. 그땐 나도 아직 태어나기 전이고 누구도 자세히 말하려 하지 않아서 자세히는 잘 몰라. 그저 그 전쟁은 카론의 참패로 끝났다는 것만 알고 있었어.",
          DialogueId = 10102420,
          FacialId = {
            [1] = "200006:Sad02"
          },
          GUID = "194A53F5",
          LookAt = {
            [1] = "200002:n(200006)",
            [2] = "100001:n(200006)"
          },
          NextDialogue = 10102421,
          Scripts = "PlayFacial{_delay{3},ActorId{200006},FacialId{\"None\"}}",
          SpeakNpcId = 200006,
          TalkActionId = {
            [1] = "200002:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101024/194A53F5"
        },
        [10102421] = {
          Camera = "339.758728,-353.583008,127.41748,0.000174,-1.999777,136.198685,51.477085,612.078247,false,Manual,4.0,16:9 Digital Film",
          Content = "虽然今天依旧有很多像你们一样的人愿意反抗，比如那些自称“神弃者”的卡戎之民……",
          ContentKR = "비록 요즘도 너희처럼 저항하려는 사람들이 있긴 하지만, 예를 들어 스스로를 '포세이큰 동맹'이라고 부르는 카론들…",
          DialogueId = 10102421,
          FacialId = {
            [1] = "200006:Sad01"
          },
          GUID = "194A53F6",
          NextDialogue = 10102422,
          SpeakNpcId = 200006,
          TalkActionId = {
            [1] = "200006:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101024/194A53F6"
        },
        [10102422] = {
          Camera = "-3715.893799,4608.366699,265.344238,0.000265,-8.60015,-142.191864,21.341076,438.68515,false,DoNotOverride,4.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "但精通魔法的人终究只是少数。更多卡戎之民只是耕种的农夫，劳作的工人，吆喝的小贩——再普通、再普通不过的人们。",
          ContentKR = "마법에 능통한 자는 결국 소수야. 대부분의 카론은 그저 농사를 짓는 농부나, 일하는 노동자, 그리고 큰 소리로 물건 파는 상인 같은... 평범한 사람들이야.",
          DialogueId = 10102422,
          FacialId = {
            [1] = "200006:Unhappy01"
          },
          FinalCamera = "-3813.631592,4532.532227,246.634521,0.000265,-8.60015,-142.191864,21.341076,438.68515,false,DoNotOverride,4.0,16:9 Digital Film",
          GUID = "194A53F7",
          NextDialogue = 10102423,
          Scripts = [[
