          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/101024/194A53F7"
        },
        [10102423] = {
          Camera = "539.756348,2904.77124,127.158203,-3.000001,0.0,90.0,25.0,126.264847,false,Manual,2.157469,16:9 Digital Film",
          Content = "对大多数人来说，反抗的代价太奢侈了，能让自己，让自己身边的人活下去，就已经需要拼尽全力了。",
          ContentKR = "그 사람들에게 저항하는 건 너무 큰 대가를 치러야 해. 그냥 살아가는 것만으로도 이미 온 힘을 다해야 하는 거야.",
          DialogueId = 10102423,
          FinalCamera = "509.710114,2888.154785,128.653564,-3.000001,0.0,84.999977,25.0,768.651489,false,Manual,1.2,16:9 Digital Film",
          GUID = "194A53F8",
