        },
        [10102424] = {
          Camera = "504.833527,-760.180176,666.255859,0.000036,-30.599928,125.39814,40.000011,330.001251,false,DoNotOverride,2.3,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "抱歉，刚刚拉走了你们，我只是……只是不想让刚认识的朋友面临危险。",
          ContentKR = "미안, 방금 너희를 끌고 온 건... 그냥 막 알게 된 친구가 위험에 빠지는 걸 보고 싶지 않았을 뿐이야.",
          DialogueId = 10102424,
          FinalCamera = "504.833527,-760.180176,617.54541,0.000036,-30.599928,125.39814,40.000011,330.001251,false,DoNotOverride,2.3,16:9 Digital Film",
