        [10102614] = {
          Camera = "73.365112,16.138672,155.199219,0.001344,-8.499999,-165.541534,35.0,266.048492,false,Manual,5.0,16:9 Digital Film",
          Content = "诶，白刚才听着好像是，这位大姐姐的钱包被抢走了？",
          ContentKR = "앗, 스노우가 방금 들어보니... 여기 언니가 지갑을 빼앗겼나 봐?",
          DialogueId = 10102614,
          FacialId = {
