          VoiceName = "voice/$Locale$/story/1002/101026/194A741C"
        },
        [10102701] = {
          Content = "那位小姐这么着急，我也一起去帮忙吧。",
          ContentKR = "급한 일인 것 같은데, 나도 도울게.",
          DialogueId = 10102701,
          GUID = "194A8262",
          NextDialogue = 10102702,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101027/194A8262"
        },
        [10102702] = {
          Content = "不要插手，这是对我们未来狩月人的简单考验。要是没有吃这碗饭的实力，做狩月人只会害了自己。",
          ContentKR = "끼어들지 마. 이건 월석 사냥꾼이 될 수 있는지 테스트하려는 거니까. 이런 것도 스스로 못한다면 월석 사냥꾼이 되어 봤자 자기 목숨도 부지하기 힘들 테니까.",
          DialogueId = 10102702,
          GUID = "194A828C",
          NextDialogue = 10102703,
          SpeakNpcId = 200003,
          TurnTo = {
            [1] = "2000061:n(200003)"
          },
          VoiceName = "voice/$Locale$/story/1002/101027/194A828C"
        },
        [10102703] = {
          Content = "好吧……",
          ContentKR = "알겠어요...",
          DialogueId = 10102703,
          GUID = "194A82B6",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101027/194A82B6"
        },
        [10102801] = {
          Content = "你、你真的愿意帮我吗！呜……谢谢你，陌生人！",
          ContentKR = "저, 정말 절 도와주신다고요? 흑... 고마워요, 정말!",
          DialogueId = 10102801,
          GUID = "194A92CA",
          NextDialogue = 10102802,
          SpeakNpcId = 2000111,
          TurnTo = {
            [1] = "2000111:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1002/101028/194A92CA"
        },
        [10102802] = {
          Content = "小贼刚才是往西边去了。但是冰湖城嘛，四通八达，谁知道他到底会窜到哪儿去。等下咱俩先找找线索！",
          ContentKR = "그 도둑은 서쪽으로 도망갔어요. 하지만 아이스레이크 시티는 길이 사방으로 뻗어 있어서 어디로 갔는지는 아무도 모를 거예요. 우선 단서부터 찾아보죠!",
          DialogueId = 10102802,
          GUID = "194A92F4",
          SpeakNpcId = 2000111,
          VoiceName = "voice/$Locale$/story/1002/101028/194A92F4"
        },
        [10103001] = {
          Content = "原来井盖下面这么大、这么宽敞呀！还比上面暖和好多！就像一个秘密的小王国一样。",
          ContentKR = "와, 맨홀 아래 공간이 이렇게 크고 넓을 줄이야! 게다가 밖보다 더 따뜻하잖아... 마치 비밀 왕국 같아요.",
          DialogueId = 10103001,
          GUID = "194A92F5",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10103002,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101030/194A92F5"
        },
        [10103002] = {
          Content = "把这些小动物请走，再把异味儿清理干净，搬个帐篷就能住人啦！",
          ContentKR = "이런 작은 동물들이랑 냄새만 해결하면, 텐트 하나만 있어도 살 수 있겠어요!",
          DialogueId = 10103002,
          GUID = "194A92F6",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10103003,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101030/194A92F6"
        },
        [10103003] = {
          Content = "对啊对啊！而且，诶{nickname}你看，住在这儿还不用付房租！",
          ContentKR = "맞아, 맞아! 그리고 {nickname}, 여기서 살면 집세도 안 내도 될 것 같은데?",
          DialogueId = 10103003,
          ExStoryInfo = "Player",
          GUID = "194A92F7",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10103004,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101030/194A92F7"
        },
        [10103004] = {
          Content = "让我们一起来打跑这些家伙，抢走他们的国土，我做魔王，册封你为……",
          ContentKR = "같이 여기 녀석들을 쫓아내고 영토를 빼앗는 거야. 난 마왕이 돼서 널...",
          DialogueId = 10103004,
          GUID = "194AB3EE",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10103005,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101030/194AB3EE"
        },
        [10103005] = {
          Content = "“骁勇的独目勇者，冷酷的冰湖之主，第一代下水道公爵”！",
          ContentKR = "'용맹한 외눈박이 용사, 냉혹한 아이스레이크의 주인, 초대 하수도 공작'으로 임명하겠어!",
          DialogueId = 10103005,
          GUID = "194AB418",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10103006,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101030/194AB418"
        },
        [10103006] = {
          Content = "（好像称呼有点太长了，缩短一些比较好……）",
          ContentKR = "(호칭이 좀 기네. 짧은 게 더 좋을 것 같은데.)",
          DialogueId = 10103006,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "194AB419",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10103007,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101030/194AB419"
        },
        [10103007] = {
          Content = "（等等，怎么我真的在一本正经思考了。）",
          ContentKR = "(잠깐, 내가 왜 이걸 그리 진지하게 생각하는 거지.)",
          DialogueId = 10103007,
