        },
        [10104020] = {
          Camera = "259.278076,116.387695,137.603516,0.001216,-0.898272,38.841999,25.0,100000.0,false,DoNotOverride,2.8,16:9 Digital Film",
          Content = "这是刚才追回钱包的报酬，拿好了。还有，带上这个。",
          ContentKR = "그리고 이건 방금 찾은 지갑에 대한 보수야. 잘 챙겨. 아, 이것도 가져가.",
          DialogueId = 10104020,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194B5AC8",
          NextDialogue = 10104021,
          Scripts = "PlayAnimation{_delay{5},ActorId{200003},AnimationId{\"Talk02_Start\"},Duration{1}}",
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Give"
          },
          VoiceName = "voice/$Locale$/story/1002/101040/194B5AC8"
        },
        [10104021] = {
          Camera = "-501.142578,-406.078125,344.859375,0.001474,-14.701865,36.043182,35.0,100000.0,false,DoNotOverride,2.8,16:9 Digital Film",
          Content = "活着回来。",
          ContentKR = "죽지 말라고.",
          DialogueId = 10104021,
          FinalCamera = "-751.681763,-588.393555,426.658203,0.001474,-14.701865,36.043182,35.0,100000.0,false,DoNotOverride,2.8,16:9 Digital Film",
          GUID = "194B5AF2",
          Scripts = [[
