        [10104402] = {
          Camera = "214.22168,-132.881836,141.021973,0.000037,-1.199094,134.199219,35.0,230.308487,false,Manual,4.0,16:9 Digital Film",
          Content = "赛琪？你怎么跟上来了？",
          ContentKR = "프시케? 왜 따라온 거야?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104402,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Happy01"
          },
          GUID = "194B9974",
