        },
        [10104403] = {
          Camera = "-188.268555,-20.25293,121.632812,0.000053,0.600934,2.599361,30.000002,316.328461,false,Manual,2.5,16:9 Digital Film",
          Content = "我来帮你们带路吧。我指的是……去格雷姆废矿的路。",
          ContentKR = "내가 길을 알려줄게. 그러니까... 글로스터 광갱으로 가는 길 말이야.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104403,
          FacialId = {
