          SpeakNpcId = 200006,
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101044/194B999E"
        },
        [10104404] = {
          Camera = "-271.905273,-43.04541,1110.167236,0.000141,-2.599092,-179.809708,25.0,813.98584,false,DoNotOverride,1.2,16:9 Digital Film",
          Content = "白认识路！不过……嗯，如果有人一起的话更好了，毕竟这可是出城。",
          ContentKR = "스노우도 길은 알아! 하지만... 그래, 누구든 같이 있으면 더 좋지. 어쨌든 이건 도시 밖으로 나가는 거니까.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104404,
