          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200006:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101044/194B99C8"
        },
        [10104405] = {
          Camera = "-80.464844,-28.455566,146.255371,0.000019,-2.199915,8.608652,35.000008,213.527512,false,Manual,4.0,16:9 Digital Film",
          Content = "是啊，外乡人在城外很容易迷路的。我看到你接了恩里克叔叔……我们的委托，所以我想我还是帮下忙为好。",
          ContentKR = "그래, 외지인은 도시 밖에서 길을 잃을 수 있어. 헨릭 아저씨의... 우리 의뢰를 받는 걸 봤어. 그래서 나도 좀 도와주고 싶어서.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104405,
          FacialId = {
            [1] = "200006:Smile02"
          },
          GUID = "194B99F2",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextOptions = {
            [1] = 101044051,
            [2] = 101044052
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200006},AnimationId{"AgreeHead"},Duration{2}},
PlayAnimation{ActorId{200006},AnimationId{"SpecialThink_Start"},Duration{2}}
}]],
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101044/194B99F2"
        },
        [10104406] = {
          Camera = "618.545898,-425.736328,165.672852,0.000053,-5.400419,148.00415,25.0,705.171997,false,DoNotOverride,5.0,16:9 Digital Film",
          CameraBlendCurve = "easeInQuad",
          Content = "刚好，我也想出来走走。我们出发吧？",
          ContentKR = "마침 좀 걷고 싶기도 했고. 그럼 출발할까?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104406,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "608.34375,-442.196289,165.672852,0.000051,-5.400419,149.999954,25.000002,715.606018,false,DoNotOverride,5.0,16:9 Digital Film",
          GUID = "194B9A1C",
          SpeakNpcId = 200006,
          TalkActionId = {
            [1] = "200006:SpecialThink_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101044/194B9A1C"
        },
        [10104501] = {
          Content = "呼……好久没来城外了。",
          ContentKR = "휴... 도시 밖은 오랜만이야.",
          DialogueId = 10104501,
          Duration = 3,
          GUID = "194BA9B2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104502,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101045/194BA9B2"
        },
        [10104502] = {
          Content = "落满雪的针叶林，望不到边的冰湖……高个子山峰被天空按住了脑袋……很喜欢。",
          ContentKR = "눈이 가득 쌓인 침엽수림, 끝없이 펼쳐진 아이스레이크... 하늘 높이 솟은 산봉우리... 나는 정말 이 풍경을 좋아하거든.",
          DialogueId = 10104502,
          Duration = 3,
          GUID = "194BA9DC",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104503,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101045/194BA9DC"
        },
        [10104503] = {
          Content = "白还是更喜欢城里面！如果郊外没有那些到处巡逻的秽兽就好啦。",
          ContentKR = "스노우는 도시가 더 좋아! 교외에 돌아다니는 그 필토이드들만 없었어도 더 좋았을 텐데.",
          DialogueId = 10104503,
          Duration = 3,
          GUID = "194BAA06",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10104504,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA06"
        },
        [10104504] = {
          Content = "里面更安全些。但是，我喜欢这里的……空气。",
          ContentKR = "시티 안이 더 안전하긴 하지. 하지만 난 이곳 공기가... 좋아.",
          DialogueId = 10104504,
          Duration = 3,
          GUID = "194BAA30",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104505,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA30"
        },
        [10104505] = {
          Content = "有区别吗？我闻起来都差不多耶……",
          ContentKR = "차이가 있어? 난 잘 모르겠는데...",
          DialogueId = 10104505,
          Duration = 3,
          GUID = "194BAA5A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10104506,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA5A"
        },
        [10104506] = {
          Content = "嗯……冰湖城的空气总是带着腥味，带着哭声。",
          ContentKR = "응... 아이스레이크 시티의 공기에는 항상 비릿한 냄새와 울음소리가 섞여 있거든.",
          DialogueId = 10104506,
          Duration = 3,
          GUID = "194BAA84",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104507,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101045/194BAA84"
        },
        [10104507] = {
          Content = "而这里是森林的味道，浮冰的味道，还有驶向远方的汽笛。这里偶尔能看到雪白的鹿从林间窜出——",
          ContentKR = "하지만 여긴 숲 냄새, 얼음 냄새가 느껴져. 그리고 먼 곳으로 향하는 기차 소리가 들려. 또 가끔은 하얀 사슴이 숲에서 튀어나오는 것도 볼 수 있어.",
          DialogueId = 10104507,
          Duration = 3,
          GUID = "194BAAAE",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104508,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101045/194BAAAE"
        },
        [10104508] = {
          Content = "而冰湖城街道的角落窜出来的，是小偷、强盗……或者呜咽的乞丐。",
          ContentKR = "하지만 아이스레이크 시티 길거리 구석에서 튀어나오는 건 도둑, 강도... 아니면 흐느끼는 거지들이잖아.",
          DialogueId = 10104508,
          Duration = 3,
          GUID = "194BAAD8",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104509,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101045/194BAAD8"
        },
        [10104509] = {
          Content = "{nickname}，你呢？讲讲你的故乡吧！那座海岛是怎样的？",
          ContentKR = "{nickname}, 넌 어때? 네 고향 얘기 좀 해줘! 그 섬은 어때?",
          DialogueId = 10104509,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BAB02",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104510,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB02"
        },
        [10104510] = {
          Content = "那里的“空气”是金色的砂砾，海岸的迷迭香……",
          ContentKR = "그곳의 '공기'에는 황금빛 모래알, 해안의 로즈마리 향기가 나...",
          DialogueId = 10104510,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BAB2C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104511,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB2C"
        },
        [10104511] = {
          Content = "是深夜朦胧的海雾，是我和贝……和家人每天眺望的巨大天之树。",
          ContentKR = "깊은 밤에는 어슴푸레한 바다 안개가 끼고, 나는 베... 가족과 매일 멀리서 거대한 천국의 나무를 바라봤어.",
          DialogueId = 10104511,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194BAB56",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10104512,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB56"
        },
        [10104512] = {
          Content = "嗯……那如果你什么时候回去故乡，请代我向它们问候~",
          ContentKR = "음... 그럼 고향에 가게 된다면 나 대신 가족에게 안부 전해줘~",
          DialogueId = 10104512,
          Duration = 3,
          GUID = "194BAB80",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10104513,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101045/194BAB80"
        },
        [10104513] = {
          Content = "……唔唔，你们两个的话好难懂哦……",
          ContentKR = "...흠흠, 둘이서 대체 무슨 말을 하는 건지...",
          DialogueId = 10104513,
          Duration = 3,
          GUID = "194BABAA",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10104514,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101045/194BABAA"
        },
        [10104514] = {
          Content = "等你再长大一些就明白啦。",
          ContentKR = "너도 좀 더 자라면 알게 될 거야.",
          DialogueId = 10104514,
          Duration = 3,
          GUID = "194BABD4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10104515,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101045/194BABD4"
        },
        [10104515] = {
          Content = "……不过，皎皎之民似乎是长不大的？",
          ContentKR = "...아, 루나는 자라지 않던가?",
          DialogueId = 10104515,
          Duration = 3,
          GUID = "194BABFE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101045/194BABFE"
        },
