          VoiceName = "voice/$Locale$/story/1002/101054/194C4414"
        },
        [10105501] = {
          Content = "那边好像有条路！我们快上去，这里站久了老觉得阴森森的……",
          ContentKR = "아무래도 길이 있는 것 같아! 어서 가보자. 여기 한참 있었더니 뭔가 으스스하단 말이야...",
          DialogueId = 10105501,
          GUID = "194C4DC1",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105502,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101055/194C4DC1"
        },
        [10105502] = {
          Content = "……等等，刚才他那句“无关的家伙”，说的不会是我吧？",
          ContentKR = "...잠깐, 설마 내가 그 '상관없는 녀석'은 아니지?",
          DialogueId = 10105502,
          GUID = "194C4DC2",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101055/194C4DC2"
        },
        [10105601] = {
          Content = "这条小路和之前的矿道好像不太一样，像是什么人自己挖出来的。",
          ContentKR = "이 오솔길은 아까 갱도와는 다른 것 같아. 꼭 누군가 직접 파낸 것처럼...",
          DialogueId = 10105601,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5E2A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105602,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E2A"
        },
        [10105602] = {
          Content = "还真是耶，这里还有好几把镐子……看来早有冒险家来过这儿了！",
          ContentKR = "정말 그렇네. 여기 삽도 있어... 다른 모험가가 여기 왔었나 봐!",
          DialogueId = 10105602,
          Duration = 3,
          GUID = "194C5E54",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105603,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E54"
        },
        [10105603] = {
          Content = "诶，赛琪你怎么脸色那么差？从刚才开始就没见你说话了。",
          ContentKR = "어라, 프시케, 안색이 왜 그래? 아까부터 말도 없고.",
          DialogueId = 10105603,
          Duration = 3,
          GUID = "194C5E7E",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105604,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E7E"
        },
        [10105604] = {
          Content = "啊，我、我有吗？",
          ContentKR = "아, 내, 내가 그랬어?",
          DialogueId = 10105604,
          Duration = 3,
          GUID = "194C5EA8",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10105605,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101056/194C5EA8"
        },
        [10105605] = {
          Content = "可能是想到刚才那只怪物，还有些后怕吧。那只怪物会不会曾经也……",
          ContentKR = "아마... 아까 그 몬스터가 생각나서, 무서워서 그래. 그 몬스터, 설마 예전에...",
          DialogueId = 10105605,
          Duration = 3,
          GUID = "194C5ED2",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105606,
          SpeakNpcId = 200006,
