        [10106203] = {
          Camera = "275.194794,306.837891,122.601562,0.000144,-0.389526,-86.22683,50.0,393.914001,false,Manual,3.873447,16:9 Digital Film",
          Content = "没什么。只是味道很甜，让我想起了一个人……我的家人。她总是会在饭菜里放很多很多糖。",
          ContentKR = "아무것도 아니야. 그냥 달콤한 맛에 한 사람이 생각 나서... 내 가족인데 항상 음식에 설탕을 엄청 넣었거든.",
          DialogueId = 10106203,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile02"
          },
          FinalCamera = "273.907379,326.357422,122.730469,0.000156,-0.389526,-86.226807,50.000008,393.914001,false,Manual,3.873447,16:9 Digital Film",
          GUID = "194CC0EE",
          NextDialogue = 10106204,
          Scripts = [[
SEQ{
