        [10106206] = {
          Camera = "-36.164703,179.021484,97.113281,0.000154,3.212634,-35.412941,35.000008,159.590256,false,DoNotOverride,19.0,16:9 Digital Film",
          Content = "有一次，那个渔夫不知从哪儿搞来了一些帝国物资，其中就有两罐糖，她便用半个月的工钱换了那么一小罐。",
          ContentKR = "어느 날은 어부가 어디선가 제국 물건을 구해왔는데 거기에 설탕도 두 캔 있었거든. 그런데 그 친구는 보름 품삯으로 그 작은 캔을 바꿔온 거야.",
          DialogueId = 10106206,
