        [10106207] = {
          Camera = "275.194794,306.837891,122.601562,0.000144,-0.389526,-86.22683,50.0,393.914001,false,Manual,3.873447,16:9 Digital Film",
          Content = "那是她第一次拿到糖，她自己也不知道要怎么用，只知道那是很好很好的东西。所以，她就在炖鱼的时候，一股脑地全都倒了进去。",
          ContentKR = "그게 그 친구가 처음으로 구한 설탕이었어. 하지만 그래서인지 설탕이 맛있다는 것만 알지 어떻게 쓰는 줄 몰라서 생선 조릴 때 몽땅 쏟아부어버렸다니까.",
          DialogueId = 10106207,
