        [10106209] = {
          Camera = "96.518188,-136.830078,134.59375,0.000123,1.799413,15.609182,35.000008,213.622009,false,Manual,7.38829,16:9 Digital Film",
          Content = "天呐，我感觉我已经闻到了那股腥甜的味儿，太可怕了。她应该向你道歉，或者至少向糖和鱼道歉。",
          ContentKR = "맙소사, 이야기만 들어도 달큰한 비린내가 느껴지는 것 같아. 끔찍한데. 그 정도면 그 친구는 너, 아니면 설탕과 생선한테 미안하다고 해야 할 지경인데.",
          DialogueId = 10106209,
