        [10106301] = {
          Camera = "-6.289551,163.633789,182.636719,0.000162,-9.200067,-82.733803,30.0,315.887299,false,Manual,2.2,16:9 Digital Film",
          CameraBlendCurve = "easeOutQuad",
          Content = "该谈谈正事了。我是说，今天在废矿带走群星绮晶的事。",
          ContentKR = "이제 본론으로 들어가자. 오늘 폐광에서 반짝이는 수정을 가지고 간 일 말이야.",
