        [10106304] = {
          Camera = "-62.165771,-132.756836,145.641602,0.000175,5.599655,57.998493,35.0,179.039703,false,Manual,7.148376,16:9 Digital Film",
          Content = "不关她事。小矮子虽然大话张口就来，但人还算有分寸，听到什么也不大要紧。我担心的是旁边那个绿衣服小姑娘。",
          ContentKR = "스노우 때문에 그런 건 아냐. 그 꼬맹이는 입만 산 것처럼 보여도 사리 분별할 줄은 알거든. 뭘 들어도 큰일 날 건 없어. 내가 걱정되는 건 그때 초록옷 입은 여자애야.",
          DialogueId = 10106304,
          FacialId = {
            [1] = "200021:Smile01",
            [2] = "100001:None"
          },
          GUID = "194CD104",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10106306,
          Scripts = [[
SEQ{
