}]],
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD104"
        },
        [10106305] = {
          Camera = "-62.165771,-132.756836,145.641602,0.000175,5.599655,57.998493,35.0,179.039703,false,Manual,7.148376,16:9 Digital Film",
          Content = "如果你指的是绿衣服小姑娘，那没错。",
          ContentKR = "초록옷 입은 애를 말하는 거라면 맞아.",
          DialogueId = 10106305,
          FacialId = {
            [1] = "200021:Doubt01",
            [2] = "100001:None"
          },
          GUID = "194CD105",
          NextDialogue = 10106306,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD105"
        },
        [10106306] = {
          Content = "我见过她出入“修普诺斯之家”。我不知道她到底只是个普通住客，还是恩里克·埃塞尔莱德的帮手。",
          ContentKR = "나도 그 애가 '히프노스의 집'을 드나드는 걸 본 적이 있어. 그냥 평범한 투숙객인지, 아니면 헨릭 애설레드의 조력자인지는 잘 모르겠지만.",
          DialogueId = 10106306,
          GUID = "194CD106",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10106306.T_Story_Recall_10106306'",
          NextDialogue = 10106307,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Think_Start",
            [2] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD106"
        },
        [10106307] = {
          Camera = "-134.704102,-202.952148,138.852539,0.000154,3.5,48.999954,35.0,313.47171,false,Manual,2.264544,16:9 Digital Film",
          CameraBlendCurve = "easeInQuad",
          Content = "我不绕圈子直说了：恩里克这人有问题，我怀疑他在做一些见不得人的勾当。",
          ContentKR = "솔직히 말할게. 헨릭이란 자는 수상해. 뭔가 떳떳하지 못한 짓거리를 하고 있을 거야.",
          DialogueId = 10106307,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "-108.404053,-223.467773,138.852539,0.000162,3.899915,58.900612,35.000011,319.900421,false,Manual,2.264544,16:9 Digital Film",
          GUID = "194CD12C",
          NextDialogue = 10106308,
          SpeakNpcId = 200021,
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD12C"
        },
        [10106308] = {
          Camera = "15.576416,24.124023,175.081543,-0.0,-10.199944,-103.000977,35.000008,120.127426,false,Manual,3.0,16:9 Digital Film",
          Content = "见不得人的……勾当？",
          ContentKR = "수상하다고? 떳떳하지 못한 짓거리라니?",
          DialogueId = 10106308,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "194CD12D",
          NextDialogue = 10106309,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200021:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD12D"
        },
        [10106309] = {
          Camera = "-129.019531,-207.28418,135.132324,0.000153,4.599757,50.60236,35.0,316.170074,false,Manual,2.264544,16:9 Digital Film",
          Content = "你知道他找的这个群星绮晶是什么吗？这种矿石，一度因为漂亮很受欢迎——但这只是表象。在一些国家，它的用途是……医药。",
          ContentKR = "그 반짝이는 수정이 뭔지는 알고 있어? 예쁜 광물이라 한때 아주 인기가 많았지. 근데 그게 다가 아냐. 어떤 나라에선 그걸... 약으로 쓰기도 해.",
          DialogueId = 10106309,
          FacialId = {
            [1] = "200021:Angry01"
          },
          GUID = "194CD1AA",
          NextDialogue = 10106310,
          Scripts = [[
