PlayAnimation{_delay{2},ActorId{200021},AnimationId{"Talk02_Start"},Duration{2}}
}]],
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD1D4"
        },
        [10106311] = {
          Content = "他违背了禁令。这件事我听说了。",
          ContentKR = "헨릭이 반짝이는 수정을 구하려고 하는 게 금지령을 어기는 거라는 건 나도 알고 있어.",
          DialogueId = 10106311,
          GUID = "10106311",
          NextDialogue = 10106312
        },
        [10106312] = {
          Camera = "0.102539,187.96582,195.69873,0.00013,-12.400058,-82.534454,30.000008,282.315033,false,Manual,2.2,16:9 Digital Film",
          Content = "只是这样也就罢了。冰湖城大街上站着的，有几个人手里真的干干净净？关键在于，另一些关于“修普诺斯之家”的流言。",
          ContentKR = "그것뿐이라면 뭐... 아이스레이크 시티 거리를 다니는 사람 중 몇 명이나 깨끗하겠어? 내가 말하려는 핵심은 '히프노스의 집'에 대한 다른 소문이야.",
          DialogueId = 10106312,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "-0.895264,195.582031,197.388184,0.00013,-12.400058,-82.534454,30.000008,282.315033,false,Manual,2.2,16:9 Digital Film",
          GUID = "194CD1FE",
          NextDialogue = 10106313,
          Scripts = [[
SEQ{
