PlayAnimation{ActorId{200021},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{3},ActorId{200021},AnimationId{"Explain01_Start"},Duration{1}}
}]],
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD1FE"
        },
        [10106313] = {
          Camera = "-2526.490234,772.758789,582.1875,0.000011,-9.199978,-15.202279,45.000023,2420.254639,false,Manual,1.2,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "附近的人说，恩里克和那里的住客行事怪异，他们向来不与外人交往。虽然打着旅店的名义，但是它所有的住客都是由恩里克<H>挑选</>。",
          ContentKR = "인근 사람들 말로는 헨릭과 거기 투숙객들 거동이 수상하대. 외부인과 지금까지 일절 왕래도 하지 않고 있어. 여관이라고 하지만 투숙객은 전부 헨릭이 <H>고른</> 사람들이었고.",
          DialogueId = 10106313,
          FinalCamera = "-2536.047363,737.591797,582.1875,0.000011,-9.199978,-15.202335,45.000023,2420.254639,false,Manual,1.2,16:9 Digital Film",
          GUID = "194CD228",
          NextDialogue = 10106314,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Think_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD228"
        },
        [10106314] = {
          Camera = "-118.642822,-24.229492,136.930176,0.000165,10.799492,27.794773,35.0,170.938126,false,Manual,1.623207,16:9 Digital Film",
          Content = "有人偷瞧过几眼，里面都是些不到二十岁的年轻人。更奇怪的是，那里的住客向来只见进去，不见出来。没人知道那些住客最后去了哪里。",
          ContentKR = "엿본 적이 있다는 사람들 말로는 거기 사는 사람들은 전부 스무 살도 안 된 젊은 사람들이었대. 더 이상한 건 들어가는 사람은 있어도 나오는 사람은 본 적이 없다는 거야. 결국 그 사람들이 어디로 갔는지 아무도 모르지.",
          DialogueId = 10106314,
          FinalCamera = "-87.214844,-7.525391,144.353027,0.000166,11.999521,27.99498,35.0,150.986908,false,Manual,1.623207,16:9 Digital Film",
          GUID = "194CD252",
