          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101063/194CD252"
        },
        [10106315] = {
          Camera = "1.409424,177.989258,193.487305,0.000134,-12.400058,-82.534454,30.000002,263.612305,false,Manual,2.2,16:9 Digital Film",
          Content = "我也听说过一些“鬼宅”之类的传言，这么一说就更……",
          ContentKR = "나도 '귀신의 집'에 대한 소문 같은 건 들어봤어. 그렇게 말하니 더... 그렇긴 한데...",
          DialogueId = 10106315,
          ExStoryInfo = "Player",
          FacialId = {
