            [2] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD27C"
        },
        [10106316] = {
          Content = "说起来，你为什么会调查到这个？",
          ContentKR = "어째서 그런 걸 조사하고 있었어?",
          DialogueId = 10106316,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194CD27D",
