        [10106318] = {
          Camera = "-599.96167,1241.567383,973.956787,0.000164,-31.200064,-54.605648,35.0,179.039703,false,DoNotOverride,7.148376,16:9 Digital Film",
          Content = "前几天我去了那个旅馆，和恩里克大吵了一架。结果呢，匕首都架在那家伙脖子上了，他还是不肯说出亨特的下落。",
          ContentKR = "그래서 며칠 전에 그 여관에 가서 헨릭과 크게 싸웠지. 단검을 그 녀석 목에다 들이대는데도 헌트의 행방을 말하지 않더라고.",
          DialogueId = 10106318,
