        [10106319] = {
          Camera = "-62.165771,-132.756836,145.641602,0.000175,5.599655,57.998493,35.0,179.039703,false,Manual,7.148376,16:9 Digital Film",
          Content = "他只是在那儿冷笑，“卡戎之民谋害索拉人是什么下场，你比我更懂。我知道你有个妹妹。为了她，少管闲事。”",
          ContentKR = "헨릭은 그저 차갑게 웃으면서 \"카론이 솔라를 해치면 어떤 결과가 있을지 나보다 더 잘 알 텐데. 여동생이 있다고 들었는데 동생을 위해서라도 쓸데없는 일에 작작 끼어들어.\"라고 말하더라니까.",
          DialogueId = 10106319,
          FinalCamera = "-57.103516,-124.65625,146.576172,0.000175,5.599648,57.998432,35.0,179.039703,false,Manual,7.148376,16:9 Digital Film",
