        [10106320] = {
          Camera = "3519.108887,1585.492188,-165.398438,0.0,0.0,-94.298676,15.0,506.047913,false,DoNotOverride,1.2,16:9 Digital Film",
          Content = "他*的！真想把他扔进泪湖喂鱼。总之，我必须查清楚亨特的下落，还有恩里克的底细。",
          ContentKR = "젠장할! 당장 눈물의 호수에 처넣어 버리고 싶었다고. 아무튼 헌트가 어떻게 됐는지, 헨릭이 어떤 놈인지 꼭 알아내고 말 거야.",
          DialogueId = 10106320,
          FacialId = {
            [1] = "200021:Angry01"
          },
          GUID = "194CD324",
          NextOptions = {
