          VoiceName = "voice/$Locale$/story/1002/101063/194CD324"
        },
        [10106321] = {
          Content = "你对朋友还挺仗义的。",
          ContentKR = "친구에 대한 생각이 정말 대단한걸.",
          DialogueId = 10106321,
          GUID = "10106321",
          NextDialogue = 10106322
        },
        [10106322] = {
