        [10106323] = {
          Camera = "31.643555,152.46875,202.856445,0.000216,-11.998804,-94.401909,55.0,248.159653,false,Manual,7.148376,16:9 Digital Film",
          Content = "这么说来，我也有个担心的人……你提到的绿衣服女孩，赛琪。",
          ContentKR = "그러고 보니 나도 걱정되는 사람이 있어... 네가 말한 그 초록옷 입은 여자애, 프시케 말이야.",
          DialogueId = 10106323,
          ExStoryInfo = "Player",
          FacialId = {
