        [10106328] = {
          Camera = "15.664551,9.075195,174.650879,0.000171,-3.399993,66.602043,25.000002,54.401806,false,Manual,3.0,16:9 Digital Film",
          Content = "我可以弄到一个你心心念念的东西——",
          ContentKR = "우선 나는 네가 간절히 원하는 걸 구해줄 수 있어.",
          DialogueId = 10106328,
          FacialId = {
            [1] = "200021:Smile01"
          },
          GUID = "194CD44A",
          NextDialogue = 10106329,
          SpeakNpcId = 200021,
          TalkActionId = {
