        [10106335] = {
          Camera = "1.812988,-141.155273,152.519043,0.000166,0.799924,88.794739,25.0,179.039703,false,Manual,4.301303,16:9 Digital Film",
          Content = "你要怎么搞到呢，你和冰湖城的卫兵很熟？",
          ContentKR = "어떻게 할 건데? 아이스레이크 시티 근위병과 친해?",
