        [10106337] = {
          Content = "哦，我知道了。办张假的对吧。",
          ContentKR = "아, 알겠어. 가짜를 만드는 거구나.",
          DialogueId = 10106337,
          GUID = "10106337",
          NextDialogue = 10106339
        },
        [10106338] = {
          Content = "那我自己去找人办一份不就行了？",
          ContentKR = "그럼 내가 직접 사람을 찾아서 만들어도 되는 것 아냐?",
