        [10108018] = {
          Camera = "-432.941406,1929.711914,30.550781,0.000332,-3.300006,-73.81044,30.0,174.408691,false,DoNotOverride,3.236185,16:9 Digital Film",
          Content = "村民们告诉我，净界岛的秽兽此前一直住在山里，并没有表现出强烈的攻击性；但在我们抵达的<H>两天前</>，却突然发疯般地攻击村民。",
          ContentKR = "마을 사람들이 연옥도의 필토이드는 이전까지 줄곧 산에 살았고, 그동안은 강한 공격성을 보이지 않았다고 했습니다. 하지만 저희가 도착하기 <H>이틀 전</>, 갑자기 폭주라도 한 듯 마을 사람들을 공격했다고 하더군요.",
          DialogueId = 10108018,
          FinalCamera = "-432.941406,1929.711914,67.210938,0.000332,-3.300019,-73.810356,30.0,174.408691,false,DoNotOverride,3.236185,16:9 Digital Film",
          GUID = "194DEAB4",
          NextDialogue = 10108019,
          SpeakNpcId = 100006,
          TalkActionId = {
            [1] = "100006:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101080/194DEAB4"
        },
        [10108019] = {
          Camera = "-44.418457,-154.999023,169.058594,0.000032,-19.399868,-78.186974,30.000002,78.537529,false,Manual,4.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "“两天前”……",
          ContentKR = "'이틀 전'이라...",
          DialogueId = 10108019,
          FinalCamera = "-40.415039,-174.143066,162.169922,0.00003,-19.399921,-78.187599,30.000002,58.681007,false,Manual,4.0,16:9 Digital Film",
          GUID = "194DEADE",
          NextDialogue = 10108020,
          SpeakNpcId = 100005,
          TalkActionId = {
            [1] = "100005:Think_Start"
          },
          ToFinalCameraBlendTime = 1.5,
          VoiceName = "voice/$Locale$/story/1002/101080/194DEADE"
        },
        [10108020] = {
          Camera = "-65.008301,620.166992,-9.789062,0.00008,-5.799861,76.39901,50.000011,165.188309,false,Manual,2.775071,16:9 Digital Film",
          Content = "……看来您已经猜到了。这太巧合了，不是吗？因为计划临时有变，我们刚好比原定的登岛时期迟了两天。",
          ContentKR = "...벌써 짐작하셨나 보군요. 공교롭지 않습니까? 계획이 갑자기 바뀌어서 저희가 원래 계획보다 이틀 늦게 섬에 도착했으니까요.",
          DialogueId = 10108020,
          GUID = "194DEB08",
          NextDialogue = 10108021,
          SpeakNpcId = 100006,
          TalkActionId = {
            [1] = "100005:Think_End",
            [2] = "100006:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101080/194DEB08"
        },
        [10108021] = {
          Content = "而有能力操纵秽兽行刺的，只有<W>神弃者同盟</>。",
          ContentKR = "필토이드를 조종해 암살할 능력을 갖춘 건 <W>포세이큰 동맹</>뿐입니다.",
          DialogueId = 10108021,
          GUID = "194DEB32",
          NextDialogue = 10108022,
          RelatedWikiId = {
            [1] = 101004
          },
          Scripts = "PlayAnimation{delay{4},ActorId{100006},AnimationId{\"Think_End\"},Duration{1}}",
          SpeakNpcId = 100006,
          VoiceName = "voice/$Locale$/story/1002/101080/194DEB32"
        },
        [10108022] = {
          Camera = "-94.642578,-318.927246,96.927734,8.007288,17.396826,65.810257,20.000008,110.446434,false,Manual,6.0,16:9 Digital Film",
          Content = "……无论是不是同盟，十三军团都混进了不该有的东西。",
          ContentKR = "...포세이큰 동맹의 소행이든 아니든, 제13군단에 쥐새끼가 들어온 것 같은데.",
          DialogueId = 10108022,
          FinalCamera = "-100.751465,-332.528809,92.259766,8.007426,17.396826,65.810616,20.000008,110.446434,false,Manual,6.0,16:9 Digital Film",
          GUID = "194DEB5C",
          NextDialogue = 10108023,
          Scripts = "TurnTo{_delay{1},TurnToDescription{\"100005:p(-180)\"}}",
          SpeakNpcId = 100005,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101080/194DEB5C"
        },
        [10108023] = {
          Content = "这么多年过去，虫子们又开始不安分起来……",
          ContentKR = "몇 년 되었더니 또다시 벌레 같은 것들이 꿈틀대기 시작하는군...",
          DialogueId = 10108023,
          GUID = "194DEB86",
          LookAt = {
            [1] = "100005:n(100005)"
          },
          NextDialogue = 10108024,
          SpeakNpcId = 100005,
          TalkActionId = {
            [1] = "100005:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101080/194DEB86"
        },
        [10108024] = {
          Camera = "-267.375,-231.39209,11.626953,3.599992,2.500006,0.199989,35.000008,198.622971,false,Manual,3.0,16:9 Digital Film",
          Content = "该彻底踩碎了。",
          ContentKR = "확실히 밟아줘야겠어.",
          DialogueId = 10108024,
          FinalCamera = "-324.33252,-231.588867,9.132812,3.599993,2.500006,0.199989,35.000008,198.622971,false,Manual,3.0,16:9 Digital Film",
          GUID = "194DEBB0",
          Scripts = "MoveTo{_delay{3},ActorId{100005},TargetPoint{\"P101080Xibi1\"},MoveSpeed{80},Visibility{\"Show\"}}",
          SpeakNpcId = 100005,
          TalkActionId = {
