        [10108303] = {
          Camera = "3226.708984,-329.703857,-858.430176,-0.0,2.99999,145.59549,15.0,100000.0,false,Disable,2.8,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "比如那些大型的野兽啊秽兽啊，跑得快但体格笨重。你就可以找墙壁、树干什么的，站在前面挑衅，它冲过来就马上闪开，让它自己一头撞晕。",
          ContentKR = "예를 들면 이런 큰 필토이드는 달리기는 빨라도 몸집이 육중하잖아. 그러니 벽이나 나무줄기 앞에 서서 녀석들을 도발하는 거야. 그 놈들이 돌진해서 너에게 다가왔을 때쯤 네가 옆으로 살짝 비켜서서 자기 혼자 머리를 부딪혀 정신을 못 차리게 하는 거지.",
          DialogueId = 10108303,
          FinalCamera = "3120.359375,-484.996094,-858.430176,-0.0,2.99999,145.59549,15.0,100000.0,false,Disable,2.8,16:9 Digital Film",
          GUID = "194E19A0",
