          VoiceName = "voice/$Locale$/story/1002/101083/194E19A0",
          bForbidSkipOptions = true
        },
        [10108304] = {
          Content = "嗯，很不错的手段。",
          ContentKR = "음, 괜찮은 방법인걸.",
          DialogueId = 10108304,
          GUID = "10108304",
          ImprPlusId = 1006,
          NextDialogue = 10108306
        },
        [10108305] = {
          Content = "呃……好卑鄙的手段。",
          ContentKR = "윽... 비겁한 수단이잖아. ",
          DialogueId = 10108305,
          GUID = "10108305",
          ImprPlusId = 1007,
