        },
        [10108306] = {
          Camera = "352.355469,-143.926758,113.639648,0.000176,0.800027,154.399246,50.000008,466.962006,false,Manual,8.0,16:9 Digital Film",
          CameraBlendCurve = "easeOutQuad",
          Content = "哈，那当然。这可是我从小到大摸爬滚打锻炼出的妙招。而对付敌人也是类似的道理，暴怒的人，和野兽没多大区别。",
          ContentKR = "하, 그거야 당연하지. 이건 내가 어릴 때부터 고생하며 익힌 묘수라고. 적을 상대하는 것도 비슷한 원리야. 화가 난 인간은 야수와 별반 다를 것 없어.",
          DialogueId = 10108306,
          FacialId = {
            [1] = "200021:Smile02"
          },
          FinalCamera = "354.804688,-138.704834,113.639648,0.000176,0.80002,155.399689,50.000008,466.962006,false,Manual,8.0,16:9 Digital Film",
          GUID = "194E19CA",
          NextDialogue = 10108307,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1002/101083/194E19CA"
        },
        [10108307] = {
