        [10108323] = {
          Camera = "-122.808594,351.115967,244.380371,0.000146,-18.200684,-67.394974,50.0,100000.0,false,Disable,2.8,16:9 Digital Film",
          Content = "听过一些坊间传闻而已，海伯利亚十几年前就出过一个拥有“和鸣之力”的家伙。你的力量……虽然细微，但和传说中的和鸣之力很像。",
          ContentKR = "그냥 소문으로 들은 거야. 휘페르보레아에서 십 몇 년 전에 '레조넌스'를 가진 자가 있었대. 네 힘은... 약하긴 해도 전설 속 레조넌스와 꽤 비슷해.",
          DialogueId = 10108323,
          FacialId = {
