        },
        [10108330] = {
          Camera = "162.910156,-71.224854,104.924805,0.000222,9.998556,149.005325,35.0,100.0,false,Manual,11.0,16:9 Digital Film",
          Content = "嗯。所以我说尽量少在人前显露，以免惹上不必要的麻烦。",
          ContentKR = "맞아. 그래서 되도록 다른 사람 앞에서 드러내지 말라고 한 거야. 귀찮은 일이 생길 수 있으니까.",
          DialogueId = 10108330,
          GUID = "194E1B9F",
