          VoiceName = "voice/$Locale$/story/1002/101083/194E1B9F"
        },
        [10108331] = {
          Camera = "528.824219,335.385986,-75.997559,0.000308,13.795157,-147.790375,35.0,264.565613,false,Manual,5.0,16:9 Digital Film",
          Content = "毕竟……上个拥有这种力量的家伙，可是把整个帝国搅得血雨腥风的，下场也凄惨得很，被吊死在迪斯玛尼亚的广场上。",
          ContentKR = "결국... 이전에 그 힘을 가졌던 자는 제국 전체를 피바다로 만들어 놨고, 그 최후는 참혹했지. 디즈마니아 광장에서 교수형을 당했다고.",
          DialogueId = 10108331,
          FinalCamera = "528.824219,335.385986,-26.985352,0.000309,9.999997,-147.789948,35.0,264.565613,false,Manual,5.0,16:9 Digital Film",
          GUID = "194E1C13",
          NextOptions = {
