        [10108336] = {
          Camera = "662.0625,-196.700195,127.136719,0.000301,-2.808314,161.416794,35.0,1282.889648,false,Manual,11.157635,16:9 Digital Film",
          Content = "好了，太阳也快下山了。回去吧，待会儿还有场“硬仗”要打。",
          ContentKR = "좋아, 해도 거의 저물었네. 돌아가자. '힘든 싸움'이 기다리고 있으니까.",
          DialogueId = 10108336,
          FinalCamera = "734.255859,-220.97583,130.874023,0.000301,-2.808314,161.416794,35.0,1282.889648,false,Manual,11.157635,16:9 Digital Film",
          GUID = "194E1C16",
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C16"
        },
        [10108337] = {
          Camera = "-158.597656,636.088623,270.316406,0.000033,-15.400197,-73.59948,50.0,340.220642,false,DoNotOverride,2.0,16:9 Digital Film",
          Content = "不错嘛，体术比我想象中精进得更快。这么快就已经是独当一面的狩月人了，唉，还是年轻人有本事。",
          ContentKR = "괜찮네, 싸움이 생각보다 빨리 늘었구나. 이제는 독립적인 월석 사냥꾼이 되었군. 젊은이는 역시 능력이 있구만.",
          DialogueId = 10108337,
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "-173.53125,686.955078,284.919434,0.000033,-15.40019,-73.599449,50.0,340.220642,false,DoNotOverride,2.0,16:9 Digital Film",
          GUID = "194E1C17",
          NextDialogue = 10108338,
          Scripts = "PlayAnimation{_delay{6.2},ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{1}}\n",
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "100001:Confident_Start"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C17"
        },
        [10108338] = {
          Camera = "-5360.410156,-7622.796875,10140.634766,0.000062,-10.601491,16.198198,15.000005,340.220642,false,DoNotOverride,2.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "走吧，太阳快下山了，该回城和小矮子会合了，不知道她那边盯梢顺不顺利。",
          ContentKR = "가자, 해가 곧 지겠어. 도시로 돌아가서 꼬맹이랑 합류할 때가 됐어. 그쪽에서 미행이 잘 되고 있을지 모르겠네.",
          DialogueId = 10108338,
          FacialId = {
            [1] = "200021:Confident01"
          },
          FinalCamera = "-5071.761719,-7538.956055,10084.37793,0.000067,-10.601498,16.198914,15.000005,340.220642,false,DoNotOverride,2.0,16:9 Digital Film",
          GUID = "194E1C18",
          SpeakNpcId = 200021,
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C18"
        },
        [10108401] = {
          Content = "说起来，你的父母是什么人？",
          ContentKR = "그러고 보니 네 부모님은 뭐 하는 분들이야?",
          DialogueId = 10108401,
          Duration = 4,
          GUID = "194E298A",
          NextDialogue = 10108402,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1002/101084/194E298A"
        },
        [10108402] = {
          Content = "怎么突然问这个？",
          ContentKR = "왜 갑자기 그런 걸 물어?",
          DialogueId = 10108402,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194E29B4",
          NextDialogue = 10108403,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101084/194E29B4"
        },
        [10108403] = {
          Content = "当然是因为和鸣之力很特别啊。卡戎之民的魔法，大多与血脉有关。没准你就大有来头。",
          ContentKR = "당연히 특별한 레조넌스 때문이지. 카론의 마법은 대게 혈통과 관계가 있거든. 어쩌면 넌 사실 엄청난 배경을 가졌을 수도 있어.",
          DialogueId = 10108403,
          Duration = 4,
          GUID = "194E29DE",
          NextDialogue = 10108404,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1002/101084/194E29DE"
        },
        [10108404] = {
          Content = "其实我也不知道……我从记事起就和贝蕾相依为命。其他的，就不太清楚了。",
          ContentKR = "실은 나도 잘 몰라... 베레와 함께 산 기억 밖에 없거든. 다른 건 딱히 기억이 없어.",
          DialogueId = 10108404,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194E2A08",
          NextDialogue = 10108405,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101084/194E2A08"
        },
        [10108405] = {
          Content = "这样啊……",
          ContentKR = "그렇구나...",
          DialogueId = 10108405,
          Duration = 4,
          GUID = "194E2A32",
          NextDialogue = 10108406,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1002/101084/194E2A32"
        },
        [10108406] = {
          Content = "哎，我说，那如果以后你发现自己其实是什么亲王啊公爵啊流落在外的私生子，可别把我这个贫贱之交忘了哦。",
          ContentKR = "아, 혹시라도 네가 사실 무슨 왕이나 공작의 버려진 사생아였다는 게 밝혀지더라도, 이 가난한 친구를 잊으면 안 돼.",
          DialogueId = 10108406,
          Duration = 4,
          GUID = "194E2A5C",
          NextDialogue = 10108407,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1002/101084/194E2A5C"
        },
        [10108407] = {
          Content = "哈，最好真的像你说的那样。",
          ContentKR = "하, 정말 반이라도 진짜였으면 좋겠다.",
          DialogueId = 10108407,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194E2A86",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101084/194E2A86"
        },
