        [10109010] = {
          Camera = "-218.000488,-102.597656,160.563965,0.000186,-4.601375,10.503407,45.0,275.06012,false,Manual,8.0,16:9 Digital Film",
          Content = "……你怎么知道……",
          ContentKR = "...그걸 어떻게...",
          DialogueId = 10109010,
