        [10109705] = {
          Camera = "330.355469,-963.607422,7.018555,-5.000005,1.19807,109.312668,50.0,1184.560059,false,Manual,3.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "它叫“照相机”，是很了不起的宝物。",
          ContentKR = "'사진기'라고 하는 거야. 엄청나게 귀한 물건이지.",
          DialogueId = 10109705,
          FacialId = {
            [1] = "200006:Smile02",
