}]],
          SpeakNpcId = 200006,
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1002/101097/194EFFA4"
        },
        [10109708] = {
          Camera = "17.835938,30.003906,75.855469,0.000003,5.999706,139.000046,50.0,172.869095,false,Manual,5.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "所以我悄悄把它“种”在了这里。……那个时候的我，真是傻乎乎的。",
          ContentKR = "그래서 그걸 몰래 여기다 '심어 놓은' 거야. ...그때의 나는 참 바보 같았어.",
          DialogueId = 10109708,
