        [10109709] = {
          Camera = "-167.960938,132.5625,94.099609,0.000283,-8.400545,-7.686968,50.0,217.697235,false,Manual,8.0,16:9 Digital Film",
          Content = "不过爸爸妈妈后来并没有责怪我，而是对我说，“那就等你成年那天再把它挖出来吧，就当是给未来自己的礼物。”",
          ContentKR = "하지만 아빠, 엄마는 혼내지 않고 나한테 이렇게 말했지. \"그럼 미래의 자신에게 줄 선물이라고 여기고 네가 성년이 되는 날 다시 꺼내렴.\"",
          DialogueId = 10109709,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "-167.53125,135.693359,94.099609,0.000283,-8.400545,-8.887018,50.0,217.697235,false,Manual,8.0,16:9 Digital Film",
          GUID = "194EFFF8",
          LookAt = {
