            [2] = 10109711
          },
          SpeakNpcId = 200006,
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101097/194EFFF8"
        },
        [10109710] = {
          Content = "是很可爱的想法。",
          ContentKR = "귀여운 생각이네.",
          DialogueId = 10109710,
          GUID = "10109710",
          NextDialogue = 10109712
        },
        [10109711] = {
          Content = "大家小时候都做过傻事。",
          ContentKR = "모두 어릴 때는 바보 같은 짓을 하잖아.",
          DialogueId = 10109711,
          GUID = "10109711",
          NextDialogue = 10109712
        },
        [10109712] = {
          Camera = "95.253906,26.408203,53.023438,-1.0,8.100427,144.515015,40.000011,249.648575,false,Manual,8.0,16:9 Digital Film",
          Content = "{nickname}，谢谢你这些天陪我，但我没有什么值钱的东西。这个相机，就当做送给你的礼物吧。",
          ContentKR = "{nickname}, 요즘 나와 같이 있어 줘서 고마워. 그런데 나한테 값비싼 물건이 없어서, 이 사진기를 선물로 줄게.",
          DialogueId = 10109712,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "93.351562,23.771484,53.079102,-0.999999,8.100427,144.115082,40.000011,249.648575,false,Manual,8.0,16:9 Digital Film",
          GUID = "194F0022",
          NextOptions = {
            [1] = 10109713,
            [2] = 10109714
          },
          SpeakNpcId = 200006,
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101097/194F0022"
        },
        [10109713] = {
          Content = "这不是你的宝物吗？太贵重了。",
          ContentKR = "이건 네 보물이잖아. 너무 귀한 거야.",
          DialogueId = 10109713,
          GUID = "10109713",
          NextDialogue = 10109715
        },
        [10109714] = {
          Content = "你给过我礼物了——那朵花。它是无价之宝。",
          ContentKR = "나한테 선물은 이미 줬어. 그때 그 꽃, 그건 값을 매길 수 없는 보물이나 마찬가지야.",
          DialogueId = 10109714,
          GUID = "10109714",
          NextDialogue = 10109715
        },
        [10109715] = {
          Camera = "15.8125,94.824219,78.226562,0.000262,7.799119,158.600952,50.0,140.419205,false,Manual,8.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "我的眼睛已经不再需要它，但你的旅途还很漫长。",
          ContentKR = "내 눈은 이제 사진기가 필요하지 않아. 하지만 네 여정은 아직 길잖아.",
          DialogueId = 10109715,
          FacialId = {
            [1] = "200006:Happy02"
          },
          FinalCamera = "15.8125,94.824219,78.226562,0.000262,7.799119,159.000992,52.0,140.419205,false,Manual,8.0,16:9 Digital Film",
          GUID = "194F004C",
          NextDialogue = 10109716,
          SpeakNpcId = 200006,
          TalkActionId = {
            [1] = "200006:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101097/194F004C"
        },
        [10109716] = {
          Camera = "-73.710938,92.207031,66.693359,0.000262,3.399228,-0.487854,50.0,93.129883,false,Manual,5.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "用你的眼睛，替我继续看看这个世界吧。",
          ContentKR = "네 눈으로 나 대신 이 세계를 계속 봐줘.",
          DialogueId = 10109716,
          FinalCamera = "-73.710938,92.207031,66.693359,0.000262,3.399228,-0.487854,52.0,93.129883,false,Manual,5.0,16:9 Digital Film",
          GUID = "194F0076",
