        },
        [10109717] = {
          Camera = "-380.574219,-471.193359,463.862305,-5.000005,-33.000675,60.310459,50.0,928.722656,false,DoNotOverride,3.0,16:9 Digital Film",
          Content = "…………",
          ContentKR = "......",
          DialogueId = 10109717,
