          VoiceName = "voice/$Locale$/story/1002/101097/194F00A0"
        },
        [10109718] = {
          Camera = "198.785156,-175.792969,10.463867,-3.000001,7.397299,129.297333,35.0,447.397217,false,Manual,3.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "难得出来一趟，我们就在湖上随便走走吧？",
          ContentKR = "모처럼 나왔는데 우리 호숫가를 좀 걸을까?",
          DialogueId = 10109718,
          FinalCamera = "207.707031,-186.716797,8.631836,-3.000001,7.397299,129.297287,35.0,479.576324,false,Manual,3.0,16:9 Digital Film",
          GUID = "194F00CA",
          SpeakNpcId = 200006,
          TalkActionId = {
            [1] = "200006:Talk02_Start"
          },
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1002/101097/194F00CA"
        },
        [10109801] = {
          Content = "在我很小的时候，爸爸偶尔会带我来湖边散步。",
          ContentKR = "어릴 때 종종 아빠와 함께 호숫가를 산책하고는 했어.",
          DialogueId = 10109801,
          GUID = "194F0F3A",
          NextDialogue = 10109802,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101098/194F0F3A"
        },
        [10109802] = {
          Content = "虽然时不时要和秽兽捉迷藏，但我总是很期待来这里。",
          ContentKR = "가끔은 필토이드와 숨바꼭질을 해야 했지만, 그래도 항상 여기 오길 바랐어.",
          DialogueId = 10109802,
          GUID = "194F0F64",
          NextDialogue = 10109803,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101098/194F0F64"
        },
        [10109803] = {
          Content = "因为我喜欢这里的浮冰和山峰，更因为，我喜欢看列车呼啸而过。",
          ContentKR = "이곳의 빙하와 산봉우리를 좋아하거든, 거기에 열차가 씽씽 달리며 지나가는 걸 보는 것도 좋았어.",
          DialogueId = 10109803,
          GUID = "194F0F8E",
          NextDialogue = 10109804,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101098/194F0F8E"
        },
        [10109804] = {
          Content = "你喜欢列车？",
          ContentKR = "열차를 좋아해?",
          DialogueId = 10109804,
          ExStoryInfo = "Player",
          GUID = "194F0FB8",
          NextDialogue = 10109805,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101098/194F0FB8"
        },
        [10109805] = {
          Content = "嗯。我喜欢它开去的地方……“南方”。",
          ContentKR = "응, 열차가 떠나는 곳이 좋거든... '남쪽' 말이야.",
          DialogueId = 10109805,
          GUID = "194F0FE2",
          NextDialogue = 10109806,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101098/194F0FE2"
        },
        [10109806] = {
          Content = "书上写，南方和冰湖城不一样。",
          ContentKR = "책에는 남쪽이 아이스레이크 시티와 다르다고 적혀 있었어.",
          DialogueId = 10109806,
          GUID = "194F100C",
          NextDialogue = 10109807,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101098/194F100C"
        },
        [10109807] = {
          Content = "那里的太阳更加温暖，那里有四季变换。",
          ContentKR = "그곳의 태양은 훨씬 따뜻하고, 사계절의 변화도 있대.",
          DialogueId = 10109807,
          GUID = "194F1036",
          NextDialogue = 10109808,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101098/194F1036"
        },
        [10109808] = {
          Content = "当春天来临，冰雪就会融去，即使在旷野，也会有大片繁花盛开。",
          ContentKR = "봄이 오면 얼음과 눈이 녹고, 광야에는 꽃이 가득 핀다더라.",
          DialogueId = 10109808,
          GUID = "194F1060",
          NextDialogue = 10109809,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101098/194F1060"
        },
        [10109809] = {
          Content = "当时我就想，如果我也能乘上列车，就可以抵达那里了。",
          ContentKR = "그때의 난 열차만 탈 수 있다면 그곳에 갈 수 있을 거라 생각했어.",
          DialogueId = 10109809,
          GUID = "194F108A",
          NextDialogue = 10109810,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101098/194F108A"
        },
        [10109810] = {
          Content = "但是爸爸告诉我，这个心愿太奢侈了。",
          ContentKR = "하지만 아빠는 그 소원이 너무 허황되다고 했지.",
          DialogueId = 10109810,
          GUID = "194F10B4",
          NextDialogue = 10109811,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101098/194F10B4"
        },
        [10109811] = {
          Content = "因为……卡戎之民的缘故？",
          ContentKR = "...카론이라서?",
          DialogueId = 10109811,
          ExStoryInfo = "Player",
          GUID = "194F10DE",
          NextDialogue = 10109812,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101098/194F10DE"
        },
        [10109812] = {
          Content = "是的。而且爸爸和妈妈只是最普通的花匠，我们很清贫，没有乘上那辆列车的资格。",
          ContentKR = "맞아. 게다가 아빠와 엄마는 그저 꽃을 기르는 일을 해서 가난했어. 그런 기차를 탈 자격이 없었지.",
          DialogueId = 10109812,
          GUID = "194F1108",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101098/194F1108"
        },
        [10109901] = {
          Camera = "43.035156,-369.824219,5.117188,0.00037,9.794949,103.195534,15.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "所以，你敲开“修普诺斯之家”大门的那一天，我是那么惊喜……因为我几乎从未和冰湖城之外的人打过交道。",
          ContentKR = "그래서 네가 '히프노스의 집' 문을 두드리던 날, 난 정말 기뻤어... 아이스레이크 시티 바깥 사람과 교류한 적이 없었거든.",
          DialogueId = 10109901,
          FacialId = {
            [1] = "200027:Smile02"
          },
          FinalCamera = "50.992188,-403.761719,-0.895508,0.00037,9.794949,103.195534,15.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
