        [10110206] = {
          Camera = "74.595703,85.75,141.061523,0.000114,1.99839,-111.626167,35.0,100000.0,false,Disable,2.8,16:9 Digital Film",
          Content = "停手停手，钱袋还你！我也是好几天没吃顿饱饭了，一时糊涂才……唉，我错了我错了！",
          ContentKR = "잠깐만, 잠깐만! 지갑 돌려줄게! 나도 며칠째 굶어서 정신이 나가서 그랬던 거야... 아, 내가 잘못했어!",
          DialogueId = 10110206,
          GUID = "194F51AC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110206.T_Story_Recall_10110206'",
          NextDialogue = 10110207,
          SnapShot = "MEMORY",
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101032/194AD496"
        },
        [10110207] = {
          Camera = "49.960938,32.921875,126.546875,0.000111,8.397717,119.570648,35.0,362.075562,false,Manual,22.0,16:9 Digital Film",
          Content = "你处决了他？他……还罪不至死吧。",
          ContentKR = "그 사람을 죽였다고요? 죄를 짓기는 했지만... 죽을 정도는 아니었지 않나요?",
          DialogueId = 10110207,
          ExStoryInfo = "Player",
          FacialId = {
