          },
          NextDialogue = 10110208,
          Scripts = "CameraMoveTo{_delay{1.5},TargetPosition{\"53.412109,-207.308594,178.919922,0.000045,-11.599839,106.600044,35.000008,338.707367,false,Manual,4.0,16:9 Digital Film\"},duration{0}},",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F51D6"
        },
        [10110208] = {
          Camera = "2442.902344,1375.00293,-15.568359,0.000018,1.799891,-157.005646,50.0,546.458801,false,Manual,1.2,16:9 Digital Film",
          Content = "你小点声！都说了不是我干的，我只是把他的遗体悄悄运出来而已。",
          ContentKR = "조용히 해! 내가 한 게 아니라니까, 난 그냥 시신을 몰래 옮기는 것뿐이야.",
          DialogueId = 10110208,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "2446.085938,1367.493164,-15.568359,0.000015,1.799891,-157.005661,50.0,2902.307617,false,Manual,4.0,16:9 Digital Film",
          GUID = "194F5200",
          NextDialogue = 10110209,
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          TalkActionId = {
            [1] = "200004:Talk01_Start",
            [2] = "100001:Angry01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5200"
        },
        [10110209] = {
          Content = "我叫凯文，你见过的，是冰湖城外围卫戍部队的……这个倒霉蛋是哈尔，我以前的邻居，我们打小就认识了。",
          ContentKR = "난 케빈이라고 해. 전에 본 적 있지? 아이스레이크 시티 외곽 방위대... 이 재수 없는 놈은 하알인데 내 이웃이었어. 어릴 때부터 알던 사이지.",
          DialogueId = 10110209,
          GUID = "194F522A",
          NextDialogue = 10110210,
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F522A"
        },
        [10110210] = {
          Camera = "155.150391,89.697266,40.088867,0.000099,0.594261,-127.181572,25.0,379.426514,false,Manual,22.0,16:9 Digital Film",
          CameraBlendCurve = "easeInQuad",
          Content = "这家伙母亲去得早，打过的架不比吃过的饭少。虽然家人禁止我和卡戎来往，但我想着好歹也是一起玩到大的，所以偶尔会帮他点忙……",
          ContentKR = "이 녀석은 어머니가 일찍 돌아가셨어. 어려서부터 밥 먹듯이 싸우고 자랐어. 가족들은 내가 카론과 어울리지 못하게 했지만 그래도 같이 놀고 자라서 종종 도와주던 사이야...",
          DialogueId = 10110210,
          FinalCamera = "155.150391,89.697266,40.088867,0.000105,18.793825,-127.379799,25.0,379.426514,false,Manual,22.0,16:9 Digital Film",
          GUID = "194F5254",
          NextDialogue = 10110211,
          Scripts = [[
