}]],
          SpeakNpcId = 200004,
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5254"
        },
        [10110211] = {
          Camera = "189.996094,-133.302734,149.913086,0.000003,1.39997,178.999893,35.0,180.0,false,Manual,4.146463,16:9 Digital Film",
          CameraBlendCurve = "easeInQuad",
          Content = "后来有一天他鬼鬼祟祟地来找我。我以为他又欠了一屁股债，或者又被酒鬼老爹打了，来找我诉苦。但我没想到他告诉我，他出现了“<W>秽蚀</>”的征兆……",
          ContentKR = "그런데 어느 날 녀석이 몰래 날 찾아왔어. 난 또 녀석이 빚을 졌거나 술주정뱅이 아버지한테 얻어맞아서 하소연하러 온 줄 알았지. 그런데 나한테 그러더군, 자신한테 '<W>침식</>' 징조가 나타났다고...",
          DialogueId = 10110211,
          FinalCamera = "190.324219,-114.291016,149.913086,0.000003,1.39997,178.999893,35.0,180.0,false,Manual,4.146463,16:9 Digital Film",
