        [10110213] = {
          Camera = "65.837891,244.282227,142.673828,0.000048,-1.002317,-107.633041,35.000015,374.558105,false,Manual,4.0,16:9 Digital Film",
          Content = "身为卡戎，不知道“秽蚀”是什么？你到底是不是帝国人啊？",
          ContentKR = "카론이 '침식'을 모른다고? 너 제국인이 맞긴 해?",
          DialogueId = 10110213,
          GUID = "194F52D2",
          NextOptions = {
            [1] = 10110214,
            [2] = 10110216
          },
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F52D2"
        },
        [10110214] = {
          Content = "我是偏远村子来的，消息闭塞…… ",
          ContentKR = "전 외딴 시골에서 와서 세상물정을 잘 몰라서요...",
          DialogueId = 10110214,
          GUID = "10110214",
          ImprPlusId = 1007,
          NextDialogue = 10110215
        },
        [10110215] = {
          Camera = "65.837891,244.282227,142.673828,0.000048,-1.002317,-107.633041,35.000015,374.558105,false,Manual,4.0,16:9 Digital Film",
          Content = "哦对，卡米拉提到过，那也难怪吧。",
          ContentKR = "아참, 카밀라가 그랬었지. 그래, 어쩐지.",
          DialogueId = 10110215,
          GUID = "194F52FC",
          NextDialogue = 10110218,
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F52FC"
        },
        [10110216] = {
          Content = "再多问，小心我把今天的事…… ",
          ContentKR = "계속 물으면 오늘 일을...",
          DialogueId = 10110216,
          GUID = "10110216",
          ImprPlusId = 1010,
          NextDialogue = 10110217
        },
        [10110217] = {
          Camera = "65.837891,244.282227,142.673828,0.000048,-1.002317,-107.633041,35.000015,374.558105,false,Manual,4.0,16:9 Digital Film",
          Content = "啊啊不问了不问了，你千万别说出去啊！",
          ContentKR = "아, 알았어. 안 물어볼게. 절대 말하지 마!",
          DialogueId = 10110217,
          FacialId = {
            [1] = "200004:Sad01"
          },
          GUID = "194F5326",
          NextDialogue = 10110218,
          SpeakNpcId = 200004,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5326"
        },
        [10110218] = {
          Camera = "774.716797,904.916992,888.727539,0.000136,-34.801495,-130.630646,35.0,100000.0,false,Disable,2.8,16:9 Digital Film",
          Content = "<W>秽蚀</>是一种只在卡戎身上出现的特殊疾病，摊上就无药可救。",
          ContentKR = "<W>침식</>은 카론 몸에만 나타나는 특수한 질병이야. 고칠 방법도 없어.",
          DialogueId = 10110218,
          FinalCamera = "819.070312,866.855469,888.727539,0.000136,-34.801495,-130.630646,35.0,100000.0,false,Disable,2.8,16:9 Digital Film",
          GUID = "194F5350",
          NextDialogue = 10110219,
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5350"
        },
        [10110219] = {
          Camera = "59.294922,60.157227,158.963867,0.000116,1.398187,-107.029724,35.0,201.991119,false,Manual,6.0,16:9 Digital Film",
          Content = "你们这群人，差不多十几岁的时候吧，都会觉醒个什么力量，但也不是每个人都那么顺利。",
          ContentKR = "너처럼 20살이 되기 몇 년 전, 어떤 힘을 각성하게 되지만, 모두 순조롭게 각성하는 건 아니야.",
          DialogueId = 10110219,
          FinalCamera = "54.453125,61.650391,158.963867,0.000116,1.398222,-105.829933,35.0,197.159012,false,Manual,6.0,16:9 Digital Film",
          GUID = "194F537A",
          NextDialogue = 10110220,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.1},TargetPosition{"14.539062,-57.106445,149.019531,0.000111,-4.801684,98.370796,35.0,159.591751,false,Manual,6.0,16:9 Digital Film"},duration{0}},
CameraMoveTo{_delay{4.2},TargetPosition{"24.572266,-55.670898,149.019531,0.000112,-5.201646,97.571365,35.000008,165.538956,false,Manual,6.0,16:9 Digital Film"},duration{4}}
}]],
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101102/194F537A"
        },
        [10110220] = {
          Content = "总有几个倒霉蛋不知道哪根筋搭错了，变成<W>秽兽</>——但要说威力啊，外面的普通秽兽连它们一根指头都不如，卫戍部队一整支小队都未必能搞定。",
          ContentKR = "운이 더럽게 나쁜 녀석들은 항상 있으니까, 그런 녀석들은 <W>필토이드</>로 변하기도 해. 하지만 그 위력은 엄청나서 일반 필토이드와는 비교도 안 될 정도야. 방위대 한 소대가 나서도 제압에 성공할지 미지수거든.",
          DialogueId = 10110220,
          GUID = "194F53A4",
          NextDialogue = 10110221,
          RelatedWikiId = {
            [1] = 303003
          },
          SpeakNpcId = 200004,
          VoiceName = "voice/$Locale$/story/1002/101102/194F53A4"
        },
        [10110221] = {
          Camera = "582.199219,778.926758,7556.786133,0.000033,22.586451,-62.627708,15.000007,179.344406,false,DoNotOverride,22.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "要是秽蚀者出现在城里，那附近一大片人都要自求多福喽。",
          ContentKR = "시티 내에 침식자가 나타나면, 그 주변 사람들은 알아서 살길을 도모해야 할 거야.",
          DialogueId = 10110221,
          FinalCamera = "731.279297,485.125,7697.886719,0.000031,23.186407,-63.027958,15.000007,179.344406,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "194F53CE",
          NextDialogue = 10110222,
          SpeakNpcId = 200004,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F53CE"
        },
        [10110222] = {
          Camera = "3.785156,91.553711,146.086914,0.000141,3.197669,-91.427162,35.000011,214.337555,false,Manual,6.0,16:9 Digital Film",
          Content = "所以你明白为什么那么多索拉人恨卡戎了吧？大家都说是因为卡戎的血管里流淌着邪恶的魔力，所以才会招惹来这种祸端。而秽蚀者，就是所有卡戎中最邪恶的。",
          ContentKR = "이제 왜 그렇게 많은 솔라들이 카론을 미워하는지 알겠지? 모두 카론의 몸에 흐르는 사악한 마력이 이런 재앙을 불러온다고 믿거든. 그리고 침식자란, 카론 중에서도 가장 사악한 존재야.",
          DialogueId = 10110222,
          FacialId = {
            [1] = "200004:None"
          },
          GUID = "194F53F8",
          NextDialogue = 10110223,
          Scripts = "PlayAnimation{_delay{1},ActorId{200004},AnimationId{\"Talk01_Start\"},Duration{1}}",
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F53F8"
        },
        [10110223] = {
          Camera = "3.785156,91.553711,146.086914,0.000141,3.197669,-91.427162,35.000011,214.337555,false,Manual,6.0,16:9 Digital Film",
          Content = "这话吧，说实话我也不是那么信，但是……唉！总之，这么稀罕的事，怎么就摊在哈尔头上了呢。",
          ContentKR = "솔직히 말하자면 나도 다 믿는 건 아니야... 아! 어쨌든 이런 일이 왜 하알한테 일어난 건지.",
          DialogueId = 10110223,
          GUID = "194F5422",
          NextDialogue = 10110224,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"200004:p(P101102Bag)"}},
