}]],
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5422"
        },
        [10110224] = {
          Camera = "59.203125,-199.486328,172.362305,0.000048,-11.20041,106.99884,35.000008,100000.0,false,Disable,4.0,16:9 Digital Film",
          Content = "半月前那家伙慌慌张张来找我，但我哪敢收留他！包庇秽蚀者跟包庇神奇同盟一样是重罪，一不留神小命就丢了。我只能给点吃的，让他自己想办法去。",
          ContentKR = "보름 전쯤, 녀석이 급하게 날 찾아왔는데 내가 뭘 어떻게 하겠어! 침식자를 비호하는 건 포세이큰 동맹을 비호하는 것과 같은 중죄야. 까딱하면 목숨을 잃는다고. 내가 할 수 있는 건 먹을 걸 좀 주고 혼자 방법을 생각하도록 하는 게 다였어.",
          DialogueId = 10110224,
          GUID = "194F544C",
          NextDialogue = 10110225,
          Scripts = "CameraMoveTo{_delay{11},TargetPosition{\"74.595703,85.75,141.061523,0.000111,4.598363,-113.225594,35.0,100000.0,false,Disable,2.8,16:9 Digital Film\"},duration{0}}",
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F544C"
        },
        [10110225] = {
          Camera = "81.287109,-34.47168,231.873047,0.000089,-31.399204,-132.789673,35.000008,100000.0,false,Disable,4.0,16:9 Digital Film",
          Content = "后来听说他偷人家东西被人抓了现行，又被发现是秽蚀者，直接送治安署去了。",
          ContentKR = "나중에 녀석이 남의 돈을 훔치다가 현행범으로 잡혔다는 말을 들었어. 게다가 침식자인 걸 걸려서 그대로 치안서로 보내졌다고 하더군.",
          DialogueId = 10110225,
          GUID = "194F5476",
          NextOptions = {
            [1] = 10110226
          },
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5476"
        },
        [10110226] = {
          Content = "送去治安署会发生什么？",
          ContentKR = "치안서로 보내진 후 무슨 일이 있었나요?",
          DialogueId = 10110226,
          GUID = "194F5477",
          NextDialogue = 10110227
        },
        [10110227] = {
          Camera = "777.373047,-100.292969,25.057617,0.000009,4.599859,172.998215,40.000011,332.596619,false,Manual,22.0,16:9 Digital Film",
          Content = "都说了秽蚀者是无药可救的，还能发生什么？自然是移交给我们卫戍部队，然后……唉。",
          ContentKR = "침식자는 약도 없다고 하는데 또 무슨 일이 있겠어? 당연히 우리 방위대에 넘어왔고, 그 후에는... 하아.",
          DialogueId = 10110227,
          GUID = "194F54A0",
          NextDialogue = 10110228,
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Disagree"
