          VoiceName = "voice/$Locale$/story/1002/101102/194F54A0"
        },
        [10110228] = {
          Camera = "-30.980469,-249.970703,249.849609,0.000058,-40.098839,61.201523,20.000011,207.029022,false,Manual,3.5,16:9 Digital Film",
          Content = "虽然这家伙也算自作自受……但好歹也当过几年朋友，我不忍心让他躺在冰冷的殓房，就把他偷……带了出来，打算把他葬在泪湖边上，埋他母亲的地方。",
          ContentKR = "자업자득이긴 하지만... 그래도 친구로 지낸 세월이 얼만데, 차마 차가운 시체를 안치소에다 둘 순 없어서 몰래... 데리고 나와서 녀석 어머니가 묻힌 눈물의 호수 쪽에 묻어주려던 거야.",
          DialogueId = 10110228,
          FinalCamera = "-23.003906,-235.451172,235.890625,0.000058,-40.098839,61.201523,20.000011,207.029022,false,Manual,3.5,16:9 Digital Film",
