        [10110229] = {
          Camera = "49.005859,-190.758789,170.493164,0.000064,-9.500171,103.609756,40.000023,322.94809,false,Manual,3.0,16:9 Digital Film",
          Content = "等等，我想知道……从秽蚀出现征兆，到秽蚀发生……这期间会有什么症状？",
          ContentKR = "잠깐만요, 궁금한 게 있어요... 침식 징후가 나타나고 침식이 발병할 때까지... 그사이에 어떤 증상이 있나요?",
          DialogueId = 10110229,
