        [10110230] = {
          Camera = "29.394531,154.411133,135.935547,0.000082,4.298655,-102.209503,40.000011,300.548492,false,Manual,4.0,16:9 Digital Film",
          Content = "我哪知道啊？哦，之前好像听说过有些家伙会变得特别狂躁，也有一些可怜家伙会逐渐失去正常的感知，比如瞎了聋了之类的？",
          ContentKR = "내가 어떻게 알아? 아, 광적으로 초조하게 변한다든가, 정상적인 감각을 잃는다고 들었어. 눈이 멀거나 귀가 안 들리는 거지.",
          DialogueId = 10110230,
          FacialId = {
            [1] = "200004:Sad01"
