        [10110239] = {
          Camera = "62.695312,-35.460938,197.44043,0.000168,-15.401721,-165.42247,35.000008,239.561539,false,Manual,22.0,16:9 Digital Film",
          Content = "天呐，饶了我吧，你就算想打听什么军团机密，也犯不着找我这样的大头兵啊——我就一看门的！",
          ContentKR = "맙소사, 좀 봐줘. 네가 무슨 군단 기밀을 묻는다 해도 나 같은 병사는 몰라. 난 그냥 문지기라고!",
          DialogueId = 10110239,
          FacialId = {
            [1] = "200004:Sad01"
          },
          FinalCamera = "78.841797,-97.880859,197.44043,0.000168,-18.601685,-166.822098,35.000011,239.561539,false,Manual,22.0,16:9 Digital Film",
          GUID = "194F5698",
          NextDialogue = 10110240,
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5698"
        },
        [10110240] = {
          Camera = "24.123047,-69.332031,126.121094,0.000172,2.398667,98.17495,35.000011,177.910553,false,Manual,4.0,16:9 Digital Film",
          Content = "城北“修普诺斯之家”的店主恩里克·埃塞尔莱德，您知道他些什么？有一件算一件，希望您如实告诉我。",
          ContentKR = "시티 북쪽의 '히프노스의 집' 주인 헨릭 애설레드가 뭘 하는지 아세요? 저한테 전부 사실대로 알려주세요.",
          DialogueId = 10110240,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194F56C2",
          NextDialogue = 10110241,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F56C2"
        },
        [10110241] = {
          Camera = "121.794922,416.958008,140.132812,0.000136,-2.801443,-106.219742,35.000008,100000.0,false,Disable,2.8,16:9 Digital Film",
          Content = "恩里克·埃塞尔莱德……不就是个开旅馆的吗？我想想，我长官倒是跟他有些交情。这人……虽说有过案底，但这些年也算老老实实的，没犯过什么事儿。",
          ContentKR = "헨릭 애설레드라... 여관 주인 아니야? 아, 생각해 보니 내 상관 중에도 친하신 분이 계셔. 그 사람... 전과가 있긴 해도 최근 몇 년간 성실하게 지냈어. 아무 일도 없었지.",
          DialogueId = 10110241,
          FacialId = {
            [1] = "200004:None"
          },
          FinalCamera = "182.132812,391.785156,140.132812,0.00013,-3.201432,-116.019501,35.000008,100000.0,false,Disable,2.8,16:9 Digital Film",
          GUID = "194F56EC",
          NextDialogue = 10110242,
          Scripts = "PlayAnimation{_delay{1},ActorId{200004},AnimationId{\"Think_Start\"},Duration{2}}\n",
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F56EC"
        },
        [10110242] = {
          Camera = "182.132812,391.785156,140.132812,0.00013,-3.201432,-116.019501,35.000008,100000.0,false,Disable,2.8,16:9 Digital Film",
          Content = "哦，那家伙脾气挺臭的，不止一次把去投宿的外乡人赶跑。不过这个嘛，据说之前他干老本行的时候，脾气也不怎么样，不过那时候至少还有家里人管着。",
          ContentKR = "아, 그 녀석 성질이 더러워서 투숙하러 온 외지인을 쫓아낸 적이 한두 번이 아니야. 하지만 그 전에 본업을 할 때는 성질은 고약해도, 그래도 식구들은 잘 돌봤다고 들었어.",
          DialogueId = 10110242,
          GUID = "194F5716",
          NextDialogue = 10110261,
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5716"
        },
        [10110243] = {
          Content = "请详细说一下“案底”。",
          ContentKR = "'전과'라고요?",
          DialogueId = 10110243,
          GUID = "10110243",
          NextDialogue = 10110246
        },
        [10110244] = {
          Content = "请详细说一下“他的老本行”。",
          ContentKR = "'본업'이요?",
          DialogueId = 10110244,
          GUID = "10110244",
          NextDialogue = 10110251
        },
        [10110245] = {
          Content = "请详细说一下“他的家人”。",
          ContentKR = "'그의 가족'은요?",
          DialogueId = 10110245,
          GUID = "10110245",
          NextDialogue = 10110254
        },
        [10110246] = {
          Camera = "182.132812,391.785156,140.132812,0.00013,-3.201432,-116.019501,35.000008,100000.0,false,Disable,2.8,16:9 Digital Film",
          Content = "这个啊……我想想，十几年前来着？大概十四、五年前吧，恩里克·埃塞尔莱德在弗莱格桑省的<H>丹流城</>犯下了一起谋杀案。",
          ContentKR = "그게... 어디 보자, 한 10년 전이었나? 대략 15년쯤 전에 헨릭 애설레드가 플래그슨 주에 있는 <H>스칼렛</>에서 살인을 저질렀어.",
          DialogueId = 10110246,
          GUID = "194F5740",
          NextDialogue = 10110247,
          RelatedWikiId = {
            [1] = 408006
          },
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}}",
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5740"
        },
        [10110247] = {
          Camera = "48.828125,-238.466797,197.088867,0.000132,-14.601796,105.386505,35.000008,394.862823,false,Manual,4.0,16:9 Digital Film",
          Content = "被害者是个卡戎，哦对，还是个出现了征兆的<W>秽蚀者</>——就咱们刚才说到的。这不算什么重罪，所以他只坐了几个月牢就放出来了。",
          ContentKR = "피해자는 카론이었어. 아, 그래, <W>침식자</> 징후가 나타난 카론이었지. 우리가 방금 말한 것처럼 말이야. 그런데 그건 무슨 중죄가 아니어서, 몇 개월 감옥살이하고 풀려났어.",
          DialogueId = 10110247,
          GUID = "194F576A",
          NextDialogue = 10110248,
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F576A"
        },
        [10110248] = {
          Camera = "11.783203,35.181641,158.039062,0.000169,-12.8009,95.373573,35.000008,83.272263,false,Manual,5.0,16:9 Digital Film",
          Content = "他为什么要这么做？",
          ContentKR = "왜 그런 거죠?",
          DialogueId = 10110248,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Angry01"
          },
          GUID = "194F5794",
          NextDialogue = 10110249,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5794"
        },
        [10110249] = {
          Camera = "781.091797,122.442383,14.25293,0.00013,1.998233,-169.017654,25.0,182.242599,false,Manual,22,16:9 Digital Film",
          Content = "……不知道。不过，是个人类就会害怕、憎恶秽蚀者，这也没什么奇怪的吧？",
          ContentKR = "...모르지, 하지만 인간이라면 침식자를 두려워하고 증오하는 게 이상할 건 없잖아?",
          DialogueId = 10110249,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "781.091797,122.442383,33.219727,0.00013,0.0,-169.01709,25.0,182.242599,false,Manual,22,16:9 Digital Film",
          GUID = "194F57BE",
          NextDialogue = 10110250,
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Disagree",
            [2] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F57BE"
        },
        [10110250] = {
          Camera = "31.501953,148.584961,134.270508,0.000126,2.597808,-102.621628,35.000008,314.487457,false,Manual,4.0,16:9 Digital Film",
          Content = "这件事我也是听长官说起的，毕竟过去那么多年了，又不是发生在本地，所以冰湖城也没几个人知道，要是说错了你不要怪我啊！",
          ContentKR = "이 일은 나도 상사한테 들은 거야. 어쨌든 이미 몇 년이나 지난 일인데, 여기서 일어난 일도 아니라서 아이스레이크 시티에는 아는 사람이 몇 없어. 내가 잘못 말했다고 해도 내 탓은 하지 마!",
          DialogueId = 10110250,
          GUID = "194F57E8",
          NextDialogue = 10110261,
          Scripts = "PlayAnimation{_delay{4},ActorId{200004},AnimationId{\"Talk01_End\"},Duration{1}}",
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F57E8"
        },
        [10110251] = {
          Camera = "31.501953,148.584961,134.270508,0.000126,2.597808,-102.621628,35.000008,314.487457,false,Manual,4.0,16:9 Digital Film",
          Content = "冰湖城上了岁数的人都知道，恩里克曾经是冰湖城远近闻名的<H>医生</>。他医术挺高明的，是连内城的贵族老爷都会找他看病的那种。",
          ContentKR = "아이스레이크 시티에서 나이 좀 먹은 사람들은 헨릭이 예전에 이곳에서 유명한 <H>의사</>였다는 걸 다 알아. 아주 뛰어나서 대단하다는 귀족 나리들도 진료받으러 왔거든.",
          DialogueId = 10110251,
          GUID = "194F5812",
          NextDialogue = 10110252,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}}",
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5812"
        },
        [10110252] = {
          Camera = "327.693359,662.063477,356.859375,0.000096,-19.999989,-112.616272,35.0,100000.0,false,Disable,2.8,16:9 Digital Film",
          Content = "但后来不知发生了什么事，他在声名最显赫的时候关了医馆，又过了两年，医馆再次开张，但招牌却变成了“旅馆”。",
          ContentKR = "하지만 그 후 무슨 일인지 가장 명성이 자자할 때 병원 문을 닫았어. 2년이 지나 병원 문을 다시 열긴 했지만 간판이\n'여관'으로 바뀌어 있었지.",
          DialogueId = 10110252,
          FinalCamera = "350.828125,717.59375,368.043945,0.000096,-19.999989,-112.616272,35.0,100000.0,false,Disable,2.8,16:9 Digital Film",
          GUID = "194F583C",
          NextDialogue = 10110253,
          Scripts = "PlayAnimation{_delay{1},ActorId{200004},AnimationId{\"Think_Start\"},Duration{1}}",
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101102/194F583C"
        },
        [10110253] = {
          Camera = "62.0,13.855469,151.842773,0.000098,1.998315,-117.01268,35.000008,143.588394,false,Manual,5.149117,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "哦，仔细想想，好像刚好就是他在丹流城犯事前后那两年……",
          ContentKR = "아, 그러고 보니 마침 헨릭이 스칼렛에서 일을 저지른 것도 그때쯤이었어.",
          DialogueId = 10110253,
          FinalCamera = "100.847656,-14.870117,151.862305,0.000107,6.598201,-135.012131,35.000011,143.588394,false,Manual,5.149117,16:9 Digital Film",
          GUID = "194F5866",
          NextDialogue = 10110261,
          SpeakNpcId = 200004,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101102/194F5866"
        },
        [10110254] = {
          Camera = "37.912109,160.816406,132.972656,0.000113,2.998043,-103.822327,35.000008,305.385315,false,Manual,2.8,16:9 Digital Film",
          Content = "一个妻子，一个女儿，普普通通的三口之家。他妻子很早就过世了，是他自己把女儿拉扯大的。",
          ContentKR = "아내와 딸이 하나 있었어. 그냥 평범한 세 식구였지. 그의 아내는 아주 일찍 세상을 떠서 혼자 딸을 키웠어.",
          DialogueId = 10110254,
          GUID = "194F5890",
          NextDialogue = 10110255,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}}",
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5890"
        },
        [10110255] = {
          Camera = "67.521484,-246.492188,192.460938,0.000153,-11.802217,107.784149,35.000011,445.644928,false,Manual,4.0,16:9 Digital Film",
          Content = "至于他女儿……叫什么来着？海蒂？海莉？记不清了——总之那姑娘当年和恩里克一起去了丹流城旅行，但并没有跟他一起回来。",
          ContentKR = "헨릭의 딸... 이름이 뭐였더라? 하이디? 헤일리? 기억이 잘 안 나네. 어쨌든 그 아가씨는 헨릭과 같이 스칼렛에 여행 갔다가 돌아오지 않았어.",
          DialogueId = 10110255,
          GUID = "194F58BA",
          NextDialogue = 10110256,
          RelatedWikiId = {
            [1] = 201006
          },
          SpeakNpcId = 200004,
          TalkActionId = {
            [1] = "200004:Think_Start"
          },
