        [10110504] = {
          Camera = "597.891357,-27.287598,177.053955,0.000212,-9.60052,80.358948,40.0,340.8461,false,Manual,5.0,16:9 Digital Film",
          Content = "你还挺神通广大。",
          ContentKR = "좋은 생각이네.",
