          Content = "我大概……猜到了原因。",
          ContentKR = "난... 이유를 알 것 같아.",
          DialogueId = 10110511,
          ExStoryInfo = "Player",
          FinalCamera = "617.869507,29.944824,148.867676,0.000067,-6.800539,83.778389,30.000008,242.72731,false,Manual,3.0,16:9 Digital Film",
