        },
        [10110512] = {
          Content = "（说出在凯文处打听到的情报。）",
          ContentKR = "(케빈에게서 캐낸 정보를 말한다.)",
          DialogueId = 10110512,
          GUID = "10110512",
          NextDialogue = 10110513
        },
        [10110513] = {
          Camera = "960.668701,-341.848633,606.558594,0.000024,-38.601192,121.190224,30.000002,362.012939,false,Manual,22.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "……恩里克曾是一名医生，但出于某种原因关闭了医馆；恩里克有一个女儿，但她在丹流城下落不明；恩里克在丹流城谋害了一名秽蚀者……",
          ContentKR = "...헨릭은 예전에 의사였지만 어떤 이유로 병원 문을 닫았어. 헨릭에게는 딸이 하나 있었는데, 스칼렛에서 행방이 묘연해졌고. 헨릭은 스칼렛에서 침식자를 한 명 죽였다고...",
          DialogueId = 10110513,
          FacialId = {
            [1] = "200021:Think01"
          },
          FinalCamera = "896.82605,-237.447266,505.624023,0.000011,-40.001194,121.590363,30.000002,362.012939,false,Manual,22.0,16:9 Digital Film",
          GUID = "194F83B6",
          NextDialogue = 10110514,
          SpeakNpcId = 200021,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101105/194F83B6"
        },
        [10110514] = {
          Camera = "673.087097,200.460449,158.318604,0.00003,-18.200924,80.989754,30.000013,71.430817,false,Manual,22.0,16:9 Digital Film",
          Content = "嗯。更重要的是，这三件事是在同一年发生的，所以它们不会没有关联。",
          ContentKR = "응. 더 중요한 건 이 세 사건이 같은 해에 일어났어. 분명 연관이 있을 거야.",
          DialogueId = 10110514,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200021:Doubt01"
          },
          GUID = "194F83E0",
          NextDialogue = 10110515,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F83E0"
        },
        [10110515] = {
          Camera = "801.704407,333.576172,133.333984,0.000171,-0.800471,-142.436356,30.000002,310.031403,false,Manual,3.5,16:9 Digital Film",
          Content = "……考虑到修普诺斯之家的住客很有可能都是秽蚀者……嗯，我懂你的意思了。",
          ContentKR = "...히프노스의 집 투숙객들은 아마 전부 침식자일 거라고... 음, 무슨 말을 하려는 지 알겠어.",
          DialogueId = 10110515,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          GUID = "194F840A",
          NextDialogue = 10110516,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F840A"
        },
        [10110516] = {
          Camera = "684.15155,260.363281,147.201416,0.000142,-1.401261,-120.639412,30.000002,200.0,false,Manual,3.0,16:9 Digital Film",
          Content = "恩里克的女儿大概率在丹流城遭遇了不测，这件事很可能同秽蚀者有关，从而激起了恩里克对秽蚀者的仇恨，即使多年后仍然无法消解……",
          ContentKR = "헨릭의 딸은 아마 스칼렛에서 불의의 사고를 당했을 거야. 아마 그 일이 침식자와 관련이 있겠지. 그래서 헨릭은 침식자에게 원한이 생겼고, 지금까지 여러 해가 지나도록 사라지지 않은 거야...",
          DialogueId = 10110516,
          GUID = "194F8434",
          NextDialogue = 10110517,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101105/194F8434"
        },
        [10110517] = {
          Content = "所以他不知道用了什么方式将一些秽蚀者控制起来，并动用私刑——你是这么想的吧？",
          ContentKR = "그래서 모종의 방식으로 몇몇 침식자를 통제하고, 손을 쓰는 거라고 생각하는 거지?",
          DialogueId = 10110517,
          GUID = "194F845E",
