        [10111502] = {
          Content = "谁让你和她玩的？说过多少次，少碰那些不干不净的，你想被邪恶的魔法害死吗？",
          ContentKR = "걔랑 놀지 말라고 했지? 몇 번이나 말했잖니, 그런 존재는 가까이하면 안 돼. 사악한 마법 때문에 큰일이라도 나면 어쩌려고 그래!",
          DialogueId = 10111502,
          GUID = "191BB9FC",
          NextDialogue = 10111503,
          SpeakNpcId = 200041,
          VoiceName = "voice/$Locale$/story/1002/101115/191BB9FC"
        },
        [10111503] = {
          Content = "哎呀，好好的积木都弄脏了，快扔掉！",
          ContentKR = "휴, 멀쩡한 블록만 더러워졌네. 얼른 갖다 버려!",
          DialogueId = 10111503,
          GUID = "191BBA26",
          SpeakNpcId = 200041,
          VoiceName = "voice/$Locale$/story/1002/101115/191BBA26"
        },
        [10111601] = {
          Content = "那天，怀着委屈与不解，我花了一整晚时间洗澡，直到皮肤流出鲜血。",
          ContentKR = "그날 나는 억울함과 의아함을 안고 피가 날 때까지 밤새워 목욕했다.",
          DialogueId = 10111601,
          GUID = "191BBA50",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101116/191BBA50"
        },
        [10111701] = {
          Content = "不是的长官，我的女儿一向懂事，她绝不会偷窃顾客的项链，更没有藏在花盆里！",
          ContentKR = "아닙니다, 병사님. 제 딸은 착해서 절대 손님의 목걸이를 훔치지도, 화분에 숨기지도 않는다고요!",
          DialogueId = 10111701,
          GUID = "191BCA3A",
          NextDialogue = 10111702,
          SpeakNpcId = 200039,
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA3A"
        },
        [10111702] = {
          Content = "狡辩什么，卡戎崽子有几个手脚干净的？",
          ContentKR = "변명은 집어치워, 카론 놈들 중에 깨끗한 놈이 얼마나 된다고!",
          DialogueId = 10111702,
          GUID = "191BCA64",
          NextDialogue = 10111703,
          SpeakNpcId = 200043,
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA64"
        },
        [10111703] = {
          Content = "这样吧，不是说没偷没藏吗，那就让她自己把店里那些花一盆盆砸了，证明清白。",
          ContentKR = "그래, 훔치지 않았다면서? 그럼 직접 가게의 모든 화분을 깨부숴서 결백을 증명해봐.",
          DialogueId = 10111703,
          GUID = "191BCA8E",
          NextDialogue = 10111704,
          SpeakNpcId = 200044,
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA8E"
        },
        [10111704] = {
          Content = "……因为，我们生而是“恶魔的孩子”。",
          ContentKR = "...왜냐하면 우리는 '악마의 아이'니까요.",
          DialogueId = 10111704,
          GUID = "191BDAA2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101117/191BDAA2"
        },
        [10111801] = {
          Content = "啊啊……为什么……",
          ContentKR = "아아... 어째서...",
          DialogueId = 10111801,
          GUID = "191BDACC",
          NextDialogue = 10111802,
          SpeakNpcId = 200039,
          VoiceName = "voice/$Locale$/story/1002/101118/191BDACC"
        },
        [10111802] = {
          Content = "她那么善良，我们一家也本本分分，没做过任何坏事……为什么这种事会落在我们头上？",
          ContentKR = "이렇게 착한 아이에게... 우리 가족 모두 나쁜 짓 한 번 한 적이 없는데... 왜 이런 일이 우리한테 벌어지는 거죠?",
          DialogueId = 10111802,
          GUID = "191BDAF6",
          NextDialogue = 10111803,
          SpeakNpcId = 200039,
          VoiceName = "voice/$Locale$/story/1002/101118/191BDAF6"
        },
        [10111803] = {
          Content = "……事到如今，只能去请求恩里克·埃塞尔莱德医生了。这是我们最后能为她做的。",
          ContentKR = "...이렇게 된 이상 헨릭 애설레드 선생님께 부탁할 수밖에 없어. 이게 우리가 마지막으로 프시케를 위해 할 수 있는 거야.",
          DialogueId = 10111803,
          GUID = "191BDB20",
          NextDialogue = 10111804,
          SpeakNpcId = 200038,
          VoiceName = "voice/$Locale$/story/1002/101118/191BDB20"
        },
        [10111804] = {
          Content = "爸爸，妈妈，对不起……",
          ContentKR = "엄마, 아빠, 미안해요...",
          DialogueId = 10111804,
          GUID = "191BDB4A",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101118/191BDB4A"
        },
        [10111901] = {
          Content = "……没有任何意义。",
          ContentKR = "...다 부질없어.",
          DialogueId = 10111901,
          GUID = "191BEB0A",
          NextDialogue = 10111902,
          SpeakNpcId = 200045,
          VoiceName = "voice/$Locale$/story/1002/101119/191BEB0A"
        },
        [10111902] = {
          Content = "你每天送这种东西给我，又能改变什么呢。",
          ContentKR = "매일 이런 걸 준다고 뭐가 달라지겠어.",
          DialogueId = 10111902,
          GUID = "191BEB34",
          NextDialogue = 10111903,
          SpeakNpcId = 200045,
          VoiceName = "voice/$Locale$/story/1002/101119/191BEB34"
        },
        [10111903] = {
          Content = "赛琪。你应该知道，来到“修普诺斯之家”意味着什么。",
          ContentKR = "프시케, '히프노스의 집'에 온 게 어떤 의미인지 잘 알고 있지?",
          DialogueId = 10111903,
          GUID = "191BEB5E",
          NextDialogue = 10111904,
          SpeakNpcId = 200046,
          VoiceName = "voice/$Locale$/story/1002/101119/191BEB5E"
        },
        [10111904] = {
          Content = "嗯，我都明白。",
          ContentKR = "네, 알아요.",
          DialogueId = 10111904,
          GUID = "191BEB88",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10111905,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101119/191BEB88"
        },
        [10111905] = {
          Content = "……但我们是为了什么“意义”才活着吗？",
          ContentKR = "...그런데 우리는 무슨 '의미'를 위해 살아가는 거죠?",
          DialogueId = 10111905,
          GUID = "191BEBB2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101119/191BEBB2"
        },
        [10112001] = {
          Content = "……赛琪……",
          ContentKR = "...프시케...",
          DialogueId = 10112001,
          ExStoryInfo = "Player",
          GUID = "191B9902",
          NextDialogue = 10112002,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101120/191B9902"
        },
        [10112002] = {
          Content = "……能听见我的声音吗……",
          ContentKR = "...내 목소리 들려?",
          DialogueId = 10112002,
          ExStoryInfo = "Player",
          GUID = "191B992C",
          NextDialogue = 10112003,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101120/191B992C"
        },
        [10112003] = {
          Content = "……回答我……",
          ContentKR = "...대답해줘...",
          DialogueId = 10112003,
          ExStoryInfo = "Player",
          GUID = "191B9956",
          NextDialogue = 10112004,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101120/191B9956"
        },
        [10112004] = {
          Content = "有什么人在呼唤我吗……",
          ContentKR = "누가 날 부르고 있어...",
          DialogueId = 10112004,
          GUID = "191B9980",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10112005,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101120/191B9980"
        },
        [10112005] = {
          Content = "是在告诉我，不要就这样睡着吗……",
          ContentKR = "이대로 잠들지 말라고 알려주는 걸까...",
          DialogueId = 10112005,
          GUID = "191B99AA",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101120/191B99AA"
        },
        [10112100] = {
          Content = "赛琪……醒醒……",
          ContentKR = "프시케... 일어나...",
          DialogueId = 10112100,
          GUID = "19508891",
          VoiceName = "voice/$Locale$/story/1002/101121/19508891"
        },
        [10112101] = {
