        [10112104] = {
          Camera = "-749.858276,899.738281,124.033691,0.00006,3.599072,-132.19986,80.0,607.756409,false,Manual,4.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "你在想什么？你在愤怒什么？——我知道了，你渴望战胜我，杀掉我。你以为只要我不在了，你的生活就能回到正轨，回到那些平静的时日……",
          ContentKR = "뭘 생각하고 있어? 뭘 화내고 있는 거야? 알겠어, 넌 나를 이기고, 나를 죽이고 싶어. 내가 사라지기만 하면 네 삶이 다시 평범한 날들로 돌아갈 거 같아?…",
          DialogueId = 10112104,
          FinalCamera = "-829.983887,811.878906,132.056641,0.000061,3.999062,-132.799957,80.0,450.437531,false,Manual,4.0,16:9 Digital Film",
