          },
          VoiceName = "voice/$Locale$/story/1002/101173/1953DEAE"
        },
        [10117401] = {
          Content = "雾区堆放垃圾的地方……",
          ContentKR = "안개 구역 쓰레기 더미 쪽이라...",
          DialogueId = 10117401,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1953EE1A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10117402,
          SpeakNpcId = 100001
        },
        [10117402] = {
          Content = "他说的是3号大垃圾箱！跟我来！",
          ContentKR = "3번 대형 쓰레기통이에요! 여기예요!",
          DialogueId = 10117402,
          Duration = 3,
          GUID = "1953EE44",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101174/1953EE44"
        },
        [10117501] = {
          Content = "去吧去吧……老话怎么说的来着？“早起的鸟儿有垃圾捡！”",
          ContentKR = "어서 가 보렴... 옛말에 뭐라 그랬더라? \"일찍 일어난 새가 쓰레기를 줍는다!\"였나?",
          DialogueId = 10117501,
          GUID = "1953FE82",
          SpeakNpcId = 200054,
          VoiceName = "voice/$Locale$/story/1002/101175/1953FE82"
        },
        [10117601] = {
          Content = "这一带没有人。",
          ContentKR = "이 근처엔 아무도 없네.",
          DialogueId = 10117601,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19540EEA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10117602,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101176/19540EEA"
        },
        [10117602] = {
          Content = "……没关系！灵敏的“侦探”嗅觉告诉我，这附近一定能找到线索！",
          ContentKR = "...괜찮아요! 명탐정의 예리한 감각이 이 근처에 분명 단서가 있다고 말해주고 있어요!",
          DialogueId = 10117602,
          Duration = 3,
          GUID = "19540F14",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101176/19540F14"
        },
        [10117701] = {
          Camera = "-410.567871,424.552368,74.604492,0.000115,4.799778,-44.802727,25.000002,100000.0,false,Disable,2.8,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "涂鸦墙边的箱子叠了两层……底层箱子被斜过来了，表面还有凌乱的成年男性脚印——哼哼，被我看穿了！",
          ContentKR = "벽화 옆에 상자가 두 겹으로 쌓여 있네요... 아래쪽 상자가 비스듬히 놓여 있고, 표면에 어른 남자의 어지러운 발자국도 있고요. 흠흠, 제가 모두 간파했답니다!",
          DialogueId = 10117701,
          FinalCamera = "-410.567871,424.552368,74.604492,0.000105,8.599781,-41.002731,25.000002,100000.0,false,Disable,2.8,16:9 Digital Film",
          GUID = "19541F52",
