          VoiceName = "voice/$Locale$/story/1002/101182/1954715A"
        },
        [10118202] = {
          Camera = "-476.057983,-45.540398,533.046387,0.000058,-4.400117,156.809341,35.000008,241.278336,false,Manual,4.2,16:9 Digital Film",
          Content = "你、你……至于追到这种地方来吗？你说你那钱本来就是拿来分给别人的，那分老子一点怎么了？",
          ContentKR = "뭐, 뭐야... 굳이 여기까지 쫓아와야 했던 거야? 그 돈은 사람들한테 나눠주는 거라며, 그럼 나한테 조금 나눠준 셈 치면 되는 거잖아?",
          DialogueId = 10118202,
