          GUID = "195481EC",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10118303,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101183/195481EC"
        },
        [10118303] = {
          Content = "以我的推测，他一定钻进了下水道！",
          ContentKR = "제 추리에 의하면 틀림없이 하수도로 들어갔을 거예요!",
          DialogueId = 10118303,
          Duration = 3,
          GUID = "19548216",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101183/19548216"
        },
        [10118401] = {
          Content = "这么深的水……根本就过不去吧！他怎么做到的？",
          ContentKR = "물이 이렇게 깊으면... 도저히 건널 수가 없잖아! 그 녀석은 어떻게 한 거지?",
          DialogueId = 10118401,
          Duration = 3,
          GUID = "1954922A",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10118402,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101184/1954922A"
        },
        [10118402] = {
          Content = "别急，这种时候就该动用本“缄默侦探”的情报网了！",
          ContentKR = "조급해하지 마세요, 이럴 때야말로 '침묵의 탐정'의 정보망을 동원할 때예요!",
          DialogueId = 10118402,
          Duration = 3,
          GUID = "19549254",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10118403,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101184/19549254"
        },
        [10118403] = {
          Content = "根据8号小桶产出的《下水道维修手册》，这里的水位是可以人为控制的！机关一定就在附近。",
          ContentKR = "8번 작은 통에서 나온 <하수도 수리 매뉴얼>에 따르면, 이곳의 수위는 인위적으로 조절할 수 있대요! 기계장치가 분명 근처에 있을 거예요.",
          DialogueId = 10118403,
          Duration = 3,
          GUID = "1954927E",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101184/1954927E"
        },
        [10118501] = {
          Content = "哇——真的有排水机关。垃圾桶公主☆缄默侦探，你好有本领！",
          ContentKR = "와~ 정말 배수 장치가 있네. 쓰레기통 공주☆침묵의 탐정, 정말 대단하잖아!",
          DialogueId = 10118501,
          Duration = 3,
          GUID = "1954A292",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10118502,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101185/1954A292"
        },
        [10118502] = {
          Content = "去掉前面那半，拜托了……呜呜。",
          ContentKR = "앞부분은 빼주면 안 될까요... 으으.",
          DialogueId = 10118502,
          Duration = 3,
          GUID = "1954A2BC",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10118503,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101185/1954A2BC"
        },
        [10118503] = {
          Content = "水位下降了一部分，找找还有没有类似的开关吧。",
          ContentKR = "수위가 조금 내려갔어. 비슷한 스위치가 더 있나 찾아보자.",
          DialogueId = 10118503,
          Duration = 3,
          ExStoryInfo = "Player",
