          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101185/1954A2E6"
        },
        [10118601] = {
          Content = "快看，下边真有路哎！",
          ContentKR = "봐, 아래에 정말 길이 있어!",
          DialogueId = 10118601,
          Duration = 3,
          GUID = "1954B2FA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101186/1954B2FA"
        },
        [10118602] = {
          Content = "对了，《下水道维修手册》里写过，下水道偶尔会招来一些喜欢温暖湿润的秽兽栖身。",
          ContentKR = "맞아요, 《하수도 수리 매뉴얼》에 따르면, 하수도에 가끔 따뜻하고 습한 걸 좋아하는 필토이드가 살기도 한대요.",
          DialogueId = 10118602,
          Duration = 3,
          GUID = "1954B324",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101186/1954B324"
        },
        [10118603] = {
          Content = "虽然这些秽兽是体格最弱小的那种，快跟猫猫狗狗差不多了，但如果成群结队行动，还是会有点危险……",
          ContentKR = "혹시 마주친다고 해도 개나 고양이 정도 크기로 엄청 크진 않지만 무리 지어 다니면 좀 위험할 수도 있어요...",
          DialogueId = 10118603,
          Duration = 3,
          GUID = "1954B34E",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10118604,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101186/1954B34E"
        },
        [10118604] = {
          Content = "我们准备好再前进吧！",
          ContentKR = "준비 단단히 하고 가도록 하죠!",
          DialogueId = 10118604,
          Duration = 3,
          GUID = "1954B378",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101186/1954B378"
        },
        [10118701] = {
          Content = "乖乖站住！不许跑！",
          ContentKR = "거기 서! 도망가지 마!",
          DialogueId = 10118701,
          Duration = 3,
          GUID = "1954C362",
