          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101189/1954E432"
        },
        [10119001] = {
          Content = "刚才有什么飞过来了……",
          ContentKR = "방금 뭔가 날아왔는데...",
          DialogueId = 10119001,
          Duration = 3,
          GUID = "1954F49A",
