          HeadIconType = "Npc",
          NextDialogue = 10119603,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101196/19555734"
        },
        [10119603] = {
          Content = "……也许是为了防止有人误入此地，被秽兽伤到？",
          ContentKR = "...어쩌면 사람들이 실수로 들어와 필토이드에게 공격당하는 걸 막으려는 건지도 몰라.",
          DialogueId = 10119603,
          Duration = 3,
          GUID = "1955575E",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10119604,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101196/1955575E"
        },
        [10119604] = {
          Content = "让我们碰碰运气吧！看看这附近能不能找到钥匙一类的东西。",
          ContentKR = "혹시 근처에 열쇠가 있는지 찾아보자. 운이 좋으면 찾을 수 있을지도 몰라.",
          DialogueId = 10119604,
          Duration = 3,
          GUID = "19555788",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101196/19555788"
        },
        [10119701] = {
          Content = "哇……原来矿坑里还有这种好东西？要是让玛尔洁知道了，她还不得乐开花！",
          ContentKR = "와... 광갱에 이런 좋은 물건이 있었다고? 마르제가 알면 좋아하겠는걸!",
          DialogueId = 10119701,
          Duration = 3,
          GUID = "19556772",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10119702,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101197/19556772"
        },
        [10119702] = {
          Content = "但是这矿石很硬吧，玛尔洁小姐的铲子说不定会被磕坏的。",
          ContentKR = "하지만 이 광석은 너무 단단해 보이는데, 마르제 씨의 삽이 망가질지도 몰라.",
          DialogueId = 10119702,
          Duration = 3,
          GUID = "1955679C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101197/1955679C"
        },
        [10119801] = {
          Content = "{nickname}，我也来帮忙吧！",
          ContentKR = "나도 도와줄게!",
          DialogueId = 10119801,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "195577DA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10119802,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101198/195577DA"
        },
        [10119802] = {
          Content = "不用。赛琪，趁“魔王大人”没看着……我们平分了怎么样？",
          ContentKR = "괜찮아. 프시케, '마왕님'이 보고 있지 않을 때... 우리끼리 나눠 가지는 건 어때?",
          DialogueId = 10119802,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19557804",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10119803,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101198/19557804"
        },
        [10119803] = {
          Content = "你拿着就好！可以给自己买点漂亮衣服什么的，我……没什么需要用钱的地方。",
          ContentKR = "그냥 네가 다 가져가. 예쁜 옷도 사고 그래. 난... 돈 쓸 데가 별로 없어서.",
          DialogueId = 10119803,
          Duration = 3,
          GUID = "1955782E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101198/1955782E"
        },
        [10119901] = {
          Content = "这是什么？",
          ContentKR = "이게 뭐지?",
          DialogueId = 10119901,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19558842",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101199/19558842"
        },
        [10120001] = {
          Content = "唔……是开门的机关！藏得好严实。",
          ContentKR = "음... 문을 여는 장치였네! 정말 잘 숨겨놨는걸.",
          DialogueId = 10120001,
          Duration = 3,
          GUID = "195598AA",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101200/195598AA"
        },
        [10120101] = {
          Content = "怎么这么多……呃……呃呃……",
          ContentKR = "뭐가 이렇게 많아... 으... 으으...",
          DialogueId = 10120101,
          Duration = 3,
          GUID = "1955A912",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10120102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A912"
        },
        [10120102] = {
          Content = "从我大腿上下来，白。你这样我动不了了……你先回冰湖城吧，我不会笑话你的。",
          ContentKR = "일단 내 다리에서 내려와, 스노우. 네가 그러고 있으면 내가 못 움직이잖아... 먼저 아이스레이크 시티로 돌아가. 놀리지 않을 테니까.",
          DialogueId = 10120102,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A93C",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10120103,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A93C"
        },
        [10120103] = {
          Content = "不不不不回去，没没没没有经历过冒冒冒险的人生一定是不不不不不完整的！",
          ContentKR = "아, 안 안 돌아갈 거야, 모모모험을 경험해보지 못한 인생은 부부분명 완벽하지 않으니까!",
          DialogueId = 10120103,
          Duration = 3,
          GUID = "1955A966",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10120104,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A966"
        },
        [10120104] = {
          Content = "好呀，那我就陪着{nickname}和魔王大人一起，把人生变“完整”一点吧。",
          ContentKR = "좋아, 그럼 나도 {nickname}(이)랑 마왕님과 함께 인생을 좀 더 '완전하게' 만들어볼게.",
          DialogueId = 10120104,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A990",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10120105,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A990"
        },
        [10120105] = {
          Content = "刚刚我应该没有拖后腿……所以接下来，我想也不会有问题的！",
          ContentKR = "지금까지 내가 발목 붙잡은 일은 없었던 것 같은데... 그러니까 앞으로도 걱정하지 않아도 괜찮아!",
          DialogueId = 10120105,
          Duration = 3,
          GUID = "1955A9BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10120106,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A9BA"
        },
        [10120106] = {
          Content = "嗯，我们继续往前走吧。",
          ContentKR = "응, 그러면 계속 앞으로 가보자.",
          DialogueId = 10120106,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A9E4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10120107,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A9E4"
        },
        [10120107] = {
          Content = "（只是一些寻常的秽兽，远不如净界岛那一次来得凶险……）",
          ContentKR = "(그저 평범한 필토이드일 뿐이야. 연옥도에서 마주쳤던 것만큼 위험하진 않아...)",
          DialogueId = 10120107,
          DisableMouth = 1,
