        [10120401] = {
          Content = "那边是泪湖诶，我们不是说好要进城吗？",
          ContentKR = "거긴 눈물의 호수잖아, 아까 시티로 가기로 한 거 까먹었어?",
          DialogueId = 10120401,
          GUID = "1955DA4A",
          NextDialogue = 10120402,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101204/1955DA4A"
        },
        [10120402] = {
          Content = "一个人乱转很危险的！快回来，白在这儿等你！",
          ContentKR = "혼자 그렇게 돌아다니면 위험해! 얼른 돌아와, 스노우 여기서 기다리고 있을게!",
          DialogueId = 10120402,
          GUID = "1955DA74",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101204/1955DA74"
        },
        [10120501] = {
          Content = "你要去哪儿呀，我们不是说好要进城吗？",
          ContentKR = "어디 가는 거야, 아까 시티로 가기로 한 거 까먹었어?",
          DialogueId = 10120501,
          GUID = "1955EAB2",
          NextDialogue = 10120502,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101205/1955EAB2"
        },
        [10120502] = {
          Content = "那边有好多好多秽兽，你会被吃掉的！快到白这边来！",
          ContentKR = "거긴 필토이드로 득실거리는 곳이야, 잡아먹힐 수도 있다고! 얼른 스노우 쪽으로 와!",
          DialogueId = 10120502,
          GUID = "1955EADC",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101205/1955EADC"
        },
        [10120601] = {
          Content = "（这就是“城市”吗，还是第一次见到……）",
          ContentKR = "(이게 바로 '도시'인가? 처음 보는 광경이네...)",
          DialogueId = 10120601,
          DisableMouth = 1,
          GUID = "1955FB1A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10120602,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101206/1955FB1A"
        },
        [10120602] = {
          Content = "（可接下来去哪儿，完全没有头绪……还是先找到白和那位卡米拉女士吧。）",
          ContentKR = "(이제 어디로 가야 하는 걸까, 전혀 모르겠다... 아무래도 스노우와 그 카밀라 씨를 찾아가야겠어.)",
          DialogueId = 10120602,
          DisableMouth = 1,
          GUID = "1955FB44",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101206/1955FB44"
        },
        [10120701] = {
          Content = "呜哇哇，过不去了！怎么回事，连下水道也在和我们作对……",
          ContentKR = "우와아, 못 지나가겠어! 대체 뭐야, 하수도까지 우리를 방해하잖아...",
          DialogueId = 10120701,
          GUID = "19560B82",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10120702,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101207/19560B82"
        },
        [10120702] = {
          Content = "让“缄默侦探”看看——这里有个水阀！他一定对水阀做了手脚！",
          ContentKR = "이 ‘침묵의 탐정’이 한번 볼게요. 여기 밸브가 있어요! 이 자식은 분명 밸브를 조작했을 거예요!",
          DialogueId = 10120702,
          GUID = "19560BAC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10120703,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101207/19560BAC"
        },
        [10120703] = {
          Content = "也就是说，这里的水位是<H>水阀</>控制的……",
          ContentKR = "그러니까 이곳의 수위는 <H>밸브</>로 제어된다는 건가...",
          DialogueId = 10120703,
          GUID = "19560BD6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101207/19560BD6"
        },
        [10120801] = {
          Content = "前面还有个水阀！",
          ContentKR = "앞에 밸브가 하나 더 있어요!",
          DialogueId = 10120801,
          GUID = "19561BEA",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101208/19561BEA"
        },
        [10120901] = {
          Content = "那个坏蛋刚刚就是钻到这个洞里去了，我们也跟上！",
          ContentKR = "그 나쁜 놈이 방금 이 구멍으로 들어갔어, 우리도 따라가자!",
          DialogueId = 10120901,
          GUID = "19562C52",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10120902,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101209/19562C52"
        },
        [10120902] = {
          Content = "对了，8号小桶产出的《下水道维修手册》里写过，下水道偶尔会招来一些喜欢温暖潮湿的秽兽。",
          ContentKR = "참, 8번 작은 통에서 나온 〈하수도 유지보수 매뉴얼〉에 나와 있었어요. 하수도에는 가끔 따뜻하고 습한 곳을 좋아하는 필토이드들이 나타난다고요.",
          DialogueId = 10120902,
          GUID = "19562C7C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
