          Camera = "-1100.842773,2782.422852,166.54071,0.000083,-2.001068,-70.194328,50.0,1557.85144,false,Manual,1.2,16:9 Digital Film",
          Content = "我想想……嗯，《下水道维修手册》还写过，下水道的每扇门都配有备用钥匙，平时就放在门附近。我们可以在周围找找。",
          ContentKR = "어디 보자... 음, <하수도 유지보수 매뉴얼>에 따르면, 하수도의 모든 문에는 예비 열쇠가 배치되어 있고, 평소에는 문 근처에 보관된다고 했어요. 우리 주변을 한번 찾아봐요.",
          DialogueId = 10121605,
          FinalCamera = "-1100.842773,2782.422852,251.706909,0.000086,-4.000004,-70.194374,50.0,1557.85144,false,Manual,1.2,16:9 Digital Film",
          GUID = "19569FD2",
          SpeakNpcId = 200011,
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101216/19569FD2"
        },
        [10121701] = {
          Content = "小仆从小仆从，你竖起耳朵仔细听，这里的水流好像有回声耶！",
          ContentKR = "시종, 시종, 귀를 쫑긋 세우고 잘 들어봐, 여기 물소리가 메아리치는 것 같아!",
          DialogueId = 10121701,
          GUID = "1956AF92",
          NextDialogue = 10121702,
          SpeakNpcId = 200002,
          TurnTo = {
            [1] = "200002:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1002/101217/1956AF92"
        },
        [10121702] = {
          Content = "好像有一点……",
          ContentKR = "그런 거 같긴 하네...",
          DialogueId = 10121702,
          GUID = "1956AFBC",
          NextDialogue = 10121703,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101217/1956AFBC"
        },
        [10121703] = {
          Content = "你说，水流后面会不会还有个小房间呢？你要不要去看看？",
          ContentKR = "물줄기 뒤에 작은 방이 있을 수도 있지 않을까? 한번 가서 볼래?",
          DialogueId = 10121703,
          GUID = "1956AFE6",
          NextDialogue = 10121704,
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:SpecialConfident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101217/1956AFE6"
        },
        [10121704] = {
          Content = "你怎么不自己去？",
          ContentKR = "왜 너는 안 가?",
          DialogueId = 10121704,
          GUID = "1956B010",
          NextDialogue = 10121705,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101217/1956B010"
        },
        [10121705] = {
          Content = "这么惊险刺激的冒险机会，当然要留给勇敢的小仆从你啦，嘿嘿……",
          ContentKR = "이렇게 아슬아슬하고 짜릿한 모험 기회는 당연히 용감한 시종 너한테 양보해야지, 헤헤…",
          DialogueId = 10121705,
          GUID = "1956B03A",
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:SpecialConfident_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101217/1956B03A"
        },
        [10121801] = {
          Content = "我们头顶的那根水管上放了一个木箱子，备用钥匙会不会就在那里呀？可是，要怎么爬上去呢……",
          ContentKR = "머리 위에 있는 저 파이프 위에 나무 상자가 하나 놓여 있는데, 예비 열쇠가 거기 있는 거 아닐까요? 그런데 어떻게 올라가야 하지…",
          DialogueId = 10121801,
          GUID = "1956BFFA",
          SpeakNpcId = 200011,
          TalkActionId = {
            [1] = "200011:Think_Start"
          },
          TurnTo = {
            [1] = "200011:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1002/101218/1956BFFA"
        },
        [10121901] = {
          Content = "（备用钥匙应该就是这一把了。回去开门试试看吧。）",
          ContentKR = "(예비 열쇠는 아마 이 열쇠일 거야. 돌아가서 문을 열어보자.)",
          DialogueId = 10121901,
          DisableMouth = 1,
          GUID = "1956D062",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101219/1956D062"
        },
        [10122001] = {
          Content = "他或许被这些秽兽袭击了……我们也不能大意。",
          ContentKR = "필토이드들에게 습격당했을지도 몰라… 우리도 방심하면 안 돼.",
          DialogueId = 10122001,
          GUID = "1956E0CA",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101220/1956E0CA"
        },
        [10122101] = {
          Content = "{nickname}，小心那些秽兽！我先按住他！",
          ContentKR = "필토이드들을 조심해요! 제가 먼저 이 사람을 잡고 있을게요!",
          DialogueId = 10122101,
          GUID = "1956F132",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101221/1956F132"
        },
        [10122201] = {
          Content = "那块亮亮的石头是……？好像还有一本书诶！",
          ContentKR = "저 반짝이는 돌은... 뭐지? 책도 한 권 있는 것 같은데!",
          DialogueId = 10122201,
          GUID = "1957019A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101222/1957019A"
        },
        [10122300] = {
          DialogueId = 10122300,
          DialoguePanelType = "{type:showtext;topic:Reading_Title_101223;content:Reading_Content_101223}",
          GUID = "19571201",
          NextDialogue = 10122301
        },
        [10122301] = {
          Camera = "213.39209,214.109375,166.472168,0.00012,-5.40091,-127.799797,25.000002,464.479523,false,DoNotOverride,2.8,16:9 Digital Film",
