        [10122302] = {
          Camera = "1613.404053,381.626953,486.294678,0.000123,-12.201046,-168.596786,35.0,464.479523,false,DoNotOverride,2.8,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "原来这里探险的狩月人是用<H>引路灯</>和<H>指示牌</>为后面的人指引安全的道路吗……",
          ContentKR = "이 월석 사냥꾼은 <H>안내등</>과 <H>표지판</>으로 뒤따라오는 사람들에게 안전한 길을 안내한 걸까…?",
          DialogueId = 10122302,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "1761.427734,411.505371,518.932861,0.000123,-12.201046,-168.596741,35.000008,464.479523,false,DoNotOverride,2.8,16:9 Digital Film",
          GUID = "1957122C",
          NextDialogue = 10122303,
          SpeakNpcId = 200006,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101223/1957122C"
        },
        [10122303] = {
          Camera = "23.476318,138.433594,140.942383,0.000156,-2.000911,-106.794113,35.0,275.996185,false,Manual,2.8,16:9 Digital Film",
          Content = "有余力的话，我们也帮忙维护一下这些引路灯吧！",
          ContentKR = "시간이 된다면 우리도 이 안내등들을 좀 관리해 주자!",
