          Scripts = "SetLocation{ActorId{100001},TargetPoint{\"P_101259Nvzhu2\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          VoiceName = "voice/$Locale$/story/1002/101259/1959621C"
        },
        [10125911] = {
          Camera = "95.520508,198.755859,124.03125,5.001531,-13.799672,57.99501,20.000008,46.651825,false,Manual,4.0,16:9 Digital Film",
          Content = "……她是我的朋友。",
          ContentKR = "...제 친구예요.",
          DialogueId = 10125911,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "19596246",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10125912,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101259/19596246"
        },
        [10125912] = {
          Content = "我……没能保护好她。她或许是……对我感到失望。",
          ContentKR = "제가... 지켜주지 못했어요. 저한테... 실망했을 거예요.",
          DialogueId = 10125912,
          GUID = "19596270",
          NextDialogue = 10125913,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101259/19596270"
        },
        [10125913] = {
          Camera = "96.016602,285.619141,103.054688,0.000066,7.001299,-64.589752,25.0,76.61264,false,Manual,22.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "不，恰恰相反。我曾见过许多怀抱着强烈的遗憾与怨恨归去的灵魂，他们的恸哭悲号，如浓雾一般溢满河岸。",
          ContentKR = "아니란다, 오히려 그 반대였지. 난 후회와 원망으로 가득 찬 수많은 영혼을 보아왔단다. 그들의 통곡 소리는 강변의 안개처럼 짙었지.",
          DialogueId = 10125913,
          FinalCamera = "150.009766,289.806641,103.926758,0.000063,7.80125,-105.588699,25.0,76.61264,false,Manual,22.0,16:9 Digital Film",
          GUID = "1959629A",
          LookAt = {
            [1] = "100001:n(200076)"
          },
          NextDialogue = 10125914,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101259/1959629A"
        },
        [10125914] = {
          Camera = "1647.097656,1629.320312,80.411133,0.000092,-1.000056,-134.800735,50.000011,655.091675,false,Manual,22.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "但是，那个灵魂的声音非常温柔。没有哀叹，也没有愤怒与不甘，而是在诉说感谢以及……祝福。",
          ContentKR = "하지만 그 아이가 가진 영혼의 목소리는 정말 따뜻했어. 한탄도, 분노도, 미련도 없이, 오히려 고마워하며... 축복을 빌더구나.",
          DialogueId = 10125914,
          FinalCamera = "1720.431641,1626.798828,101.317383,0.000085,-1.000022,-137.800919,50.000008,655.091675,false,Manual,22.0,16:9 Digital Film",
          GUID = "195962C4",
          LookAt = {
            [1] = "200076:p(P_101259Nifu3)"
          },
          NextDialogue = 10125915,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101259/195962C4"
        },
        [10125915] = {
          Camera = "1720.431641,1626.798828,101.317383,0.000085,-1.000022,-137.800919,50.000008,655.091675,false,Manual,22.0,16:9 Digital Film",
          Content = "或许，那便是她所为你留下的。",
          ContentKR = "아마 널 향한 축복이었을 거야.",
          DialogueId = 10125915,
          GUID = "195962EE",
          NextDialogue = 10125916,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          VoiceName = "voice/$Locale$/story/1002/101259/195962EE"
        },
        [10125916] = {
          Camera = "219.347656,76.939453,145.862305,0.000099,-11.600249,129.794128,35.000008,102.30249,false,Manual,22.0,16:9 Digital Film",
          Content = "可是……",
          ContentKR = "하지만...",
          DialogueId = 10125916,
          FacialId = {
            [1] = "100001:Unacceptable01"
          },
          GUID = "19596318",
          LookAt = {
            [1] = "100001:n(200076)"
          },
          NextOptions = {
            [1] = 101259161,
            [2] = 101259162
          },
          Scripts = "SetRotation{SetRotationDescription{\"200076:p(35)\"}}",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101259/19596318"
        },
        [10125917] = {
          Camera = "686.332031,-345.896484,298.178711,0.000049,-16.400145,137.192245,15.000005,102.302483,false,DoNotOverride,6.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "孩子，我已经在这世上活了很久、很久，送别了无数的亡魂，也曾无数次听过这样的话语。",
          ContentKR = "아이야, 난 이 세상에서 아주아주 오래 살면서 무수한 영혼을 떠나보냈고 그런 말을 무수히 들었단다.",
          DialogueId = 10125917,
          FacialId = {
            [1] = "200076:None"
          },
          FinalCamera = "791.003906,-442.84375,340.171875,0.000049,-16.400145,137.192215,15.000005,102.302483,false,DoNotOverride,6.0,16:9 Digital Film",
          GUID = "19596342",
          LookAt = {
            [1] = "200076:n(200076)"
          },
          NextDialogue = 10125918,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "200076:p(180)"
          },
          VoiceName = "voice/$Locale$/story/1002/101259/19596342"
        },
        [10125918] = {
          Camera = "180.162109,98.261719,148.519531,0.000071,-14.39885,123.596199,30.0,102.302483,false,DoNotOverride,6.0,16:9 Digital Film",
          Content = "草木会因一场山火而化作焦土，虫豸会因一阵狂风而溺于深水……无常本就是生命的一部分。或早或晚，死亡终将来临。",
          ContentKR = "초목은 산불에 잿더미가 되고, 작은 곤충은 광풍에 깊은 물속으로 스러지지... 죽음은 본디 생명의 일부란다. 이르든 늦든 찾아오기 마련이지.",
          DialogueId = 10125918,
          FacialId = {
            [1] = "200076:Unhappy01"
          },
          FinalCamera = "189.610352,84.568359,152.894531,0.000069,-14.998897,125.396011,30.0,102.302483,false,DoNotOverride,6.0,16:9 Digital Film",
          GUID = "1959636C",
          NextDialogue = 10125919,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101259/1959636C"
        },
        [10125919] = {
          Camera = "165.951172,300.587891,72.796875,-5.000034,16.399078,-113.601227,25.000002,192.424774,false,Manual,4.0,16:9 Digital Film",
          Content = "除了诅咒命运的冷漠与残酷，或是哀叹自我的无力与渺小，我们还可以选择……珍惜切实存在过的记忆。",
          ContentKR = "운명의 차가움과 잔혹함을 저주하거나 자신의 나약함을 한탄할 수도 있겠지만, 우린... 추억을 소중히 여기는 길을 선택할 수도 있어.",
          DialogueId = 10125919,
          GUID = "19596396",
          LookAt = {
            [1] = "200076:n(100001)"
          },
          NextDialogue = 10125920,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          VoiceName = "voice/$Locale$/story/1002/101259/19596396"
        },
        [10125920] = {
          Camera = "195.244141,88.742188,144.28125,-5.000003,-9.599489,131.589844,25.0,72.421944,false,Manual,3.0,16:9 Digital Film",
          Content = "毕竟，如果说死亡是“必然”，那么活着的每一日，不正是与它擦肩而过的“奇迹”吗？",
          ContentKR = "죽음이 필연적인 거라면, 살아가는 매 순간은 죽음을 비켜간 '기적'이 아니겠니?",
          DialogueId = 10125920,
          GUID = "195963C0",
          LookAt = {
            [1] = "200076:n(200076)"
          },
          NextDialogue = 10125921,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          VoiceName = "voice/$Locale$/story/1002/101259/195963C0"
        },
        [10125921] = {
          Camera = "195.244141,88.742188,144.28125,-5.000003,-9.599489,131.589844,25.0,72.421944,false,Manual,3.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "我想，去往了雾海的那个灵魂，也一定会希望……当你回忆起与她共同经历的时日，你是面带笑意的，而非哀怜和悲泣。",
          ContentKR = "안개의 바다로 떠난 그 영혼도... 네가 눈물이 아닌 미소를 띠며 함께했던 날들을 기억하길 바랄 거란다.",
          DialogueId = 10125921,
          FacialId = {
            [1] = "200076:None"
          },
          FinalCamera = "177.079102,120.476562,136.115234,-5.000005,-11.999385,119.18969,25.0,160.052902,false,Manual,3.0,16:9 Digital Film",
          GUID = "195963EA",
          NextOptions = {
            [1] = 101259211
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{5.0},TargetPosition{"164.480469,147.314453,126.589844,-5.000003,-5.199488,116.586655,35.0,79.720764,false,Manual,4.0,16:9 Digital Film"},duration{0}},
CameraMoveTo{_delay{5.1},TargetPosition{"153.261719,169.722656,124.316406,-5.000003,-5.199488,116.586655,35.0,79.720764,false,Manual,4.0,16:9 Digital Film"},blend{"easeOutQuad"},duration{2.5}}
}]],
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101259/195963EA"
        },
        [10125922] = {
          Camera = "284.724609,1376.494141,-241.195312,-2.5,6.600879,85.189873,9.202867,72.421944,false,DoNotOverride,3.0,16:9 Digital Film",
          Content = "雾海……是卡戎之民的生命之源，亦是安眠之地。亡者的灵魂回归雾海，生者的灵魂从中诞生。生命如此循环流转，生生不息。",
          ContentKR = "안개의 바다는... 카론의 생명이 시작되는 곳이자 안식의 땅이란다. 떠난 이의 영혼은 그곳으로 돌아가고 새 생명의 영혼은 그곳에서 태어나지. 생명은 그렇게 끊없이 이어진단다.",
          DialogueId = 10125922,
          FacialId = {
            [1] = "200076:Smile01"
          },
          FinalCamera = "284.724609,1376.494141,-128.970703,-2.499999,6.600879,89.999962,9.202867,72.421944,false,DoNotOverride,3.0,16:9 Digital Film",
          GUID = "19596414",
          NextDialogue = 10125923,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101259/19596414"
        },
        [10125923] = {
          Camera = "145.720703,154.630859,133.727539,-2.499969,-10.399044,108.20134,30.0,99.420395,false,Manual,4.0,16:9 Digital Film",
          Content = "如果是那样……",
          ContentKR = "그렇다면...",
          DialogueId = 10125923,
          FacialId = {
            [1] = "100001:Shock02"
          },
          GUID = "1959643E",
          NextOptions = {
            [1] = 101259231,
            [2] = 101259232
          },
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101259/1959643E"
        },
        [10125924] = {
          Camera = "550.920898,582.548828,29.561523,-5.000001,-21.600601,-133.792847,10.000003,698.191711,false,Manual,11.0,16:9 Digital Film",
          Content = "如果向我提问的是别人，我应当会如此回答：生与死的循环是不容违背的世界法则，凭人类的力量绝对无法与之抗衡。",
          ContentKR = "다른 이가 그런 질문을 한다면, 난 이렇게 답할 거란다. 삶과 죽음의 순환은 거스를 수 없는 세상의 이치라 인간의 힘으로는 결코 맞설 수 없다고.",
          DialogueId = 10125924,
          FacialId = {
            [1] = "200076:None"
          },
          FinalCamera = "550.920898,582.548828,29.561523,-5.000004,-1.800445,-136.792801,10.000003,698.191711,false,Manual,11.0,16:9 Digital Film",
          GUID = "19596468",
          NextDialogue = 10125925,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101259/19596468"
        },
        [10125925] = {
          Camera = "550.920898,582.548828,29.561523,-5.000004,-1.800445,-136.792801,10.000003,698.191711,false,Manual,11.0,16:9 Digital Film",
          Content = "不过，孩子，我能感受得到……你背负着不同寻常的命运。",
          ContentKR = "하지만 느껴져... 넌 특별한 운명을 짊어지고 있구나.",
          DialogueId = 10125925,
          FacialId = {
            [1] = "200076:Smile01"
          },
          GUID = "19596492",
