        [10125926] = {
          Camera = "708.042969,-427.089844,232.430664,-5.000006,-12.598386,132.779541,18.000004,1651574.625,false,DoNotOverride,22.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "有朝一日，当你获得了足够强大的力量——当你能够直面世界的真相，甚至打破构筑它的法则本身……",
          ContentKR = "언젠가 네가 충분한 힘을 얻어 세상의 진실을 마주하고, 나아가 그 법칙마저 바꿀 수 있게 된다면...",
          DialogueId = 10125926,
          FinalCamera = "708.042969,-427.089844,232.430664,-5.000006,-7.998356,118.776794,18.000004,1651574.625,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "195964BC",
          NextDialogue = 10125927,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1002/101259/195964BC"
        },
        [10125927] = {
          Content = "或许你便能踏入那生命的河流，在它的尽头——雾海，与往昔的灵魂再度相见。",
          ContentKR = "어쩌면 네가 그 생명의 강을 건너, 그 끝인 안개의 바다에서, 떠난 영혼들과 다시 만날 수 있을지도 몰라.",
          DialogueId = 10125927,
          GUID = "195964E6",
          NextOptions = {
            [1] = 101259271
          },
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          VoiceName = "voice/$Locale$/story/1002/101259/195964E6"
        },
        [10125928] = {
          Camera = "604.604492,4438.609375,-186.418945,0.000086,-1.000513,-99.205025,24.0,79896.75,false,Manual,22.0,16:9 Digital Film",
          Content = "呵呵……我不过是驻于河畔的一介旁观者。这个问题的答案，只能由你自己寻得。",
          ContentKR = "후훗... 난 강가에 머무는 한낱 방관자에 불과하단다. 그 질문의 답은 네가 직접 찾아야만 하지.",
          DialogueId = 10125928,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "19596510",
          NextDialogue = 10125929,
          Scripts = "CameraMoveTo{_delay{3.0},TargetPosition{\"154.625,310.175781,110.634766,0.000082,4.398683,-105.211761,25.0,196.124695,false,Manual,4.0,16:9 Digital Film\"},duration{0}}",
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          VoiceName = "voice/$Locale$/story/1002/101259/19596510"
        },
        [10125929] = {
          Camera = "131.395508,182.603516,129.605469,0.000109,-12.600892,102.794952,25.0,56.213341,false,Manual,22.0,16:9 Digital Film",
          Content = "如果你真的心怀渴望，那么，就请继续前进吧。纵是前路无常，也请你坚定地走下去。",
          ContentKR = "마음 속에 갈망을 품고 있다면 계속 앞으로 나아가 보렴.",
          DialogueId = 10125929,
          FacialId = {
            [1] = "100001:Shock02"
          },
          FinalCamera = "134.668945,169.046875,132.874023,0.000097,-13.400926,103.79464,25.0,83.006569,false,Manual,22.0,16:9 Digital Film",
          GUID = "1959653A",
