        },
        [10125930] = {
          Camera = "677.972656,898.259766,768.71582,0.000071,-39.198925,-126.606758,18.0,56.213341,false,Manual,22.0,16:9 Digital Film",
          Content = "一路顺风，亲爱的孩子。",
          ContentKR = "행운이 너와 함께하길 빈단다, 아이야.",
          DialogueId = 10125930,
          FinalCamera = "765.867188,1016.578125,888.923828,0.000071,-39.198925,-126.606758,18.0,56.213341,false,Manual,22.0,16:9 Digital Film",
