        [10129701] = {
          Camera = "98.882812,336.099609,13.861816,0.00006,13.998199,-124.392242,15.0,100000.0,false,Disable,2.8,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          DialogueId = 10129701,
          FinalCamera = "176.5,102.359375,-7.201416,0.000064,19.197878,-143.98999,15.0,100000.0,false,Disable,2.8,16:9 Digital Film",
          GUID = "195BD012",
          ToFinalCameraBlendTime = 3
        },
        [10129801] = {
          Content = "小贼在前面！糟了……他好像和秽兽打起来了！",
          ContentKR = "도둑이에요! 이런... 아무래도 필토이드와 싸우고 있는 것 같아요!",
          DialogueId = 10129801,
          GUID = "195BD013",
          NextDialogue = 10129802,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101298/195BD013"
        },
        [10129802] = {
          Content = "赶跑秽兽，然后制服他吧。",
          ContentKR = "필토이드부터 처리하고, 저 사람을 제압하자.",
          DialogueId = 10129802,
          GUID = "195BD014",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101298/195BD014"
        },
        [10129901] = {
          Content = "那栋宅子常常在深夜传来哭声，偶尔还会飘出奇怪的味道。",
          ContentKR = "그 저택에서 밤마다 우는소리가 들린대. 가끔 이상한 냄새가 풍기기도 하고.",
          DialogueId = 10129901,
          GUID = "195BD015",
          VoiceName = "voice/$Locale$/story/1002/101299/195BD015"
        },
        [10130001] = {
          Content = "恩里克的事与我无关。但如果他真的有什么问题……我担心赛琪的安全。",
          ContentKR = "난 헨릭한테 관심 없어. 그런데 그 사람한테 진짜 뭔가 문제가 있다면... 프시케의 안전이 걱정돼.",
          DialogueId = 10130001,
          GUID = "195BD016",
          NextDialogue = 10106325,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101300/195BD016"
        },
        [10130101] = {
          Camera = "17.943359,4617.524414,902.814453,0.000375,15.299773,-91.196564,30.0,5448.511719,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "如果真的得到了{性别：他|她}——也就是和鸣之力的持有者，您打算如何处置？",
          ContentKR = "레조넌스를 가진 그 {性别:소년을|소녀를} 정말로 손에 넣는다면... 어떻게 하실 겁니까?",
          DialogueId = 10130101,
          Duration = 8,
          FinalCamera = "37.016602,4939.133301,642.138672,0.000375,15.299773,-91.196564,30.0,5448.511719,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "195BD017",
          NextDialogue = 10130102,
          SpeakNpcId = 100006,
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101301/195BD017"
        },
        [10130102] = {
          Content = "完全觉醒的和鸣之力可以对一切“骸”施加干预……但这种力量完全依赖于持有者本人的意志。",
          ContentKR = "완전히 각성한 레조넌스라면, 모든 '다이몬'을 휘두를 수 있지만... 그 힘은 오롯이 소유자의 의지에 달려 있습니다.",
          DialogueId = 10130102,
          Duration = 8,
          GUID = "195BD018",
          NextDialogue = 10130103,
          SpeakNpcId = 100006,
          VoiceName = "voice/$Locale$/story/1002/101301/195BD018"
        },
        [10130103] = {
          Camera = "-1576.924561,1990.549316,316.099609,0.000029,-7.400209,-45.991081,35.000008,2186.29834,false,Manual,1.2,16:9 Digital Film",
          Content = "也就是说，除非{性别：他|她}本人自愿协助，否则得到{性别：他|她}对帝国来说并无意义，甚至可能成为祸端。就像当年……",
          ContentKR = "다시 말해, 그 {性别:소년이|소녀가} 자발적으로 협력하지 않는 한, 그 {性别:소년은|소녀는} 제국에 아무 의미도 없을뿐더러, 오히려 화근이 될 수도 있단 겁니다. 그때처럼 말이죠...",
          DialogueId = 10130103,
          Duration = 8,
          FinalCamera = "-1587.533691,2001.532227,318.089844,0.000029,-7.400209,-45.991081,35.000008,2186.29834,false,Manual,1.2,16:9 Digital Film",
          GUID = "195BD019",
          NextDialogue = 10130104,
          SpeakNpcId = 100006,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101301/195BD019"
        },
        [10130104] = {
          Camera = "-40.981445,48.569336,104.802734,0.000054,3.698834,-87.387604,35.0,198.622971,false,DoNotOverride,3.0,16:9 Digital Film",
          Content = "那就和当年一样抹除掉。无论如何，这份力量不能落入帝国之外，尤其是艾利西安。好了，另一个坏消息呢？",
          ContentKR = "그렇다면 그때처럼 처리하면 된다. 무슨 일이 있어도 그 힘이 제국 밖, 특히 엘리시안의 손에 넘어가게 둘 순 없어. 자, 나쁜 소식은?",
          DialogueId = 10130104,
          Duration = 10,
          FinalCamera = "-42.826172,89.025879,102.189453,0.000054,3.698834,-87.387604,35.0,198.622971,false,DoNotOverride,3.0,16:9 Digital Film",
          GUID = "195BD020",
          NextDialogue = 10108013,
          SpeakNpcId = 100005,
          TalkActionId = {
            [1] = "100005:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101301/195BD020"
        },
        [10130201] = {
          Content = "“牵念之花”……是花店！诶？！难道他准备去约会？",
          ContentKR = "'그리움의 꽃'... 꽃집이잖아! 어?! 설마 데이트라도 하나?",
          DialogueId = 10130201,
          GUID = "195BD021",
          NextDialogue = 10130202,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101302/195BD021"
        },
        [10130202] = {
          Content = "我们坐对面等一会儿吧！",
          ContentKR = "우리, 맞은편에 앉아서 잠깐 기다리자!",
          DialogueId = 10130202,
          GUID = "195BD022",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101302/195BD022"
        },
        [10130301] = {
          Camera = "216.478516,-137.633301,117.546875,0.000164,-6.198915,127.211983,35.0,407.218628,false,DoNotOverride,4.0,16:9 Digital Film",
          Content = "他出来了！",
          ContentKR = "나왔다!",
          DialogueId = 10130301,
          GUID = "195BD023",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "100001:p(LC_EnterFlow)"
          },
          NextDialogue = 10130302,
          Scripts = "MoveTo{ActorId{200002},MoveSpeed{220},TargetPoint{\"P1190930Bai1\"}}",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101303/195BD023"
        },
        [10130302] = {
          Camera = "-353.71582,-276.680176,199.59375,0.000172,-9.398859,23.610058,20.0,407.218628,false,DoNotOverride,4.0,16:9 Digital Film",
          Content = "二位要喝点什么吗？",
          ContentKR = "음료 주문하시겠어요?",
          DialogueId = 10130302,
          GUID = "195BD024",
          NextDialogue = 10130303,
          Scripts = "MoveTo{ActorId{200097},MoveSpeed{80},TargetPoint{\"P1190930Boy1\"}}",
          SpeakNpcId = 200097,
          VoiceName = "voice/$Locale$/story/1002/101303/195BD024"
        },
        [10130303] = {
          Camera = "105.118164,-51.828613,93.718262,0.0,-2.999962,129.999985,30.0,118.813644,false,Manual,4.0,16:9 Digital Film",
          Content = "不喝不喝，我们就坐一会儿，看看风景！你看今晚太阳多好啊，嘿嘿……",
          ContentKR = "아냐, 필요 없어! 우린 그냥 잠깐 앉아서 풍경 좀 보려는 거야! 석양이 참 예쁘네, 헤헤...",
          DialogueId = 10130303,
          GUID = "195BD025",
          NextDialogue = 10130304,
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1002/101303/195BD025"
        },
        [10130304] = {
          Camera = "-353.71582,-276.680176,199.59375,0.000172,-9.398859,23.610058,20.0,407.218628,false,DoNotOverride,4.0,16:9 Digital Film",
          Content = "看风景才要喝点什么！我们店有各式咖啡，还有冰湖城特产北风莓果汁！对了，最新的鲱鱼罐头味浓汤不来品尝一下吗！",
          ContentKR = "그러면 더더욱 뭘 좀 드셔야죠! 저희 가게엔 다양한 커피는 물론, 아이스레이크 시티 특산품인 아이스베리 주스도 있답니다! 아, 새로 나온 청어 통조림 수프는 어떠세요!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10130304,
          GUID = "195BD026",
          NextDialogue = 10130305,
          SpeakNpcId = 200097,
          TalkActionId = {
            [1] = "200097:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101303/195BD026"
        },
        [10130305] = {
          Camera = "126.273438,-640.34082,115.856201,0.000007,0.0,89.999985,20.0,118.813644,false,Manual,4.0,16:9 Digital Film",
          Content = "不了，我们还有事——等下，恩里克呢？",
          ContentKR = "아뇨, 괜찮아요. 저희는 아직 볼일이... 잠깐, 헨릭은?",
          DialogueId = 10130305,
          GUID = "195BD027",
          NextDialogue = 10130306,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101303/195BD027"
        },
        [10130306] = {
          Camera = "48.96875,256.841797,105.016113,-1.5,-4.999971,-84.999916,30.0,169.724716,false,Manual,4.0,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "呜呜，好像跟丢了……",
          ContentKR = "으앙, 놓쳤나 봐...",
          DialogueId = 10130306,
          FinalCamera = "48.96875,256.841797,105.016113,-1.5,-4.999971,-84.999916,30.0,680.897827,false,Manual,1.2,16:9 Digital Film",
          GUID = "195BD028",
          LookAt = {
