            [2] = "100001:p(LC_EnterFlow)"
          },
          NextDialogue = 10130307,
          SpeakNpcId = 200002,
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101303/195BD028"
        },
        [10130307] = {
          Camera = "-31.876953,-170.957031,169.342773,0.0,-14.000125,51.202343,30.0,155.608383,false,Manual,3.0,16:9 Digital Film",
          Content = "……和花店老板打听一下，碰碰运气吧。",
          ContentKR = "...혹시 모르니까 꽃집 사장님한테 물어보자.",
          DialogueId = 10130307,
          GUID = "195BD029",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101303/195BD029"
        },
        [10130401] = {
          Camera = "-137.371094,-123.811035,229.291016,0.000012,-12.600093,90.599869,16.000004,100000.0,false,DoNotOverride,2.8,16:9 Digital Film",
          Content = "（火炉的炉体高大，火焰早已熄灭，但里面的炉灰似乎证明了它近期被使用过。）",
          ContentKR = "(거대한 난로다. 불은 꺼져 있지만, 난로 안에 재를 봐선 최근까지도 사용한 것 같다.)",
          DialogueId = 10130401,
          DisableMouth = 1,
          FinalCamera = "-132.40625,-283.590576,87.898438,0.000034,13.599972,91.399513,16.000004,100000.0,false,DoNotOverride,2.8,16:9 Digital Film",
          GUID = "195BD030",
          LookAt = {
