        [11010103] = {
          Camera = "138.929688,18.707031,107.624329,0.000043,-26.202394,152.990067,28.0,179.473755,false,Manual,10.963819,16:9 Digital Film",
          Content = "<W>你的血肉之躯因窒息而悸动，疼痛叩击着你深处最隐秘的渴望。</>",
          ContentKR = "<W>너의 그 몸뚱이는 질식으로 부들부들 떨리고, 고통이 너의 가장 깊숙한 곳에 숨겨진 욕망을 두드리고 있지.</>",
          DialogueId = 11010103,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "138.929688,18.707031,131.753906,0.000043,-26.202394,152.990067,28.0,179.473755,false,Manual,10.963819,16:9 Digital Film",
