        [11010209] = {
          Content = "（给我闭嘴！我没有！）",
          ContentKR = "(닥쳐! 그렇지 않아!)",
          DialogueId = 11010209,
          GUID = "1B901A6A",
          NextDialogue = 11010210
        },
        [11010210] = {
          Camera = "-299.773438,-22.185547,-5.160034,-18.018326,38.192356,-12.391366,30.0,100.319092,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "<W>不要抗拒。因为我是真正的你，是你的死之本能。终有一日你会遵从我的指引，遵从亘古的意志……</>",
          ContentKR = "<W>저항할 필요 없어. 나야말로 진정한 너이자, 네가 가진 죽음의 본능이니. 언젠가 넌 나의 인도와 태초의 의지를 따르게 될 테니까...</>",
          DialogueId = 11010210,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-298.789062,-47.498047,-11.343872,-18.018387,40.392326,-2.390289,30.000002,100.319092,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1B901A94",
          NextOptions = {
