          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110111/1B90AEBA"
        },
        [11011114] = {
          Camera = "54.410156,219.574219,135.06189,0.000141,-1.200686,-103.445839,35.0,209.628448,false,Manual,22.0,16:9 Digital Film",
          Content = "“雪狼”分队的情况和你们差不多。情况你们自己知道，先别讲给伤员。",
          ContentKR = "'스노우 울프'의 상황도 크게 다르지 않다. 이건 너희들만 알고 있어라. 부상자들에겐 말하지 마라.",
          DialogueId = 11011114,
          FacialId = {
            [1] = "110005:Iyada01"
          },
          FinalCamera = "81.892578,211.804688,135.06189,0.000141,-1.00067,-109.046188,35.0,209.628448,false,Manual,22.0,16:9 Digital Film",
          GUID = "1B90AEE4",
          NextDialogue = 11011115,
          SpeakNpcId = 110010,
          TalkActionId = {
            [1] = "110010:Think_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110111/1B90AEE4"
        },
        [11011115] = {
          Content = "嗯……现在整个“狮鹫”分队能行动的，只剩下你们俩了吗……",
          ContentKR = "흠... 그렇다면 지금 '그리핀'에 작전을 수행할 수 있는 건 자네 둘 뿐이라는 건데...",
          DialogueId = 11011115,
          GUID = "1B90AF0E",
          LookAt = {
            [1] = "110010:n(110005)",
            [2] = "110005:n(110010)"
          },
          NextDialogue = 11011116,
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110111/1B90AF0E"
        },
        [11011116] = {
          Content = "达芙涅，刚才我们打通了仓储区和加工区的通路，中间有片区域还算安全。我给出了信号，待会儿会有人护送你们过去休整。",
          ContentKR = "다프네, 아까 창고 구역과 공장 구역 사이의 통로를 뚫어서 이제 중간 구역은 그나마 괜찮을 거다. 내가 신호를 보내놨으니, 나중에 사람이 오면 함께 그곳으로 이동해 정비할 수 있도록.",
          DialogueId = 11011116,
          GUID = "1B90AF38",
          LookAt = {
            [1] = "110010:n(110005)"
          },
          NextDialogue = 11011117,
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110111/1B90AF38"
        },
        [11011117] = {
          Camera = "-163.324219,118.648438,119.937622,0.000208,2.601052,-56.642597,35.000008,209.628448,false,Manual,22.0,16:9 Digital Film",
          Content = "{nickname2}，你跟我走，继续行动。",
          ContentKR = "{nickname2}, 자넨 나와 함께 움직이지.",
          DialogueId = 11011117,
          ExStoryInfo = "EXPlayer",
