        [11011132] = {
          Content = "是。",
          ContentKR = "예. 알겠습니다.",
          DialogueId = 11011132,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90B1D8",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110111/1B90B1D8"
        },
        [11011133] = {
          Content = "你也受伤了，什么时候的事？",
          ContentKR = "언제... 다치신 겁니까?",
          DialogueId = 11011133,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90B202",
          NextDialogue = 11011134,
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110111/1B90B202"
        },
        [11011134] = {
          Content = "我们几个被那只巨型秽兽袭击的时候。我不是有意向您隐瞒，只是……",
          ContentKR = "거대한 필토이드에게 습격당했을 때요. 일부러 숨기려고 한 건 아니에요. 그저...",
          DialogueId = 11011134,
          Duration = 3,
          GUID = "1B90B22C",
          NextDialogue = 11011135,
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110111/1B90B22C"
        },
        [11011135] = {
          Content = "……好好休息。听老师的话，去休整点吧。",
          ContentKR = "...푹 쉬십시오. 교관님 말씀대로 정비 구역으로 가는 게 좋겠습니다.",
          DialogueId = 11011135,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90B256",
          NextDialogue = 11011136,
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110111/1B90B256"
        },
        [11011136] = {
          Content = "等回皇都，我会去看你。",
          ContentKR = "황성으로 복귀하면 연락드리죠.",
          DialogueId = 11011136,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90B280",
          NextDialogue = 11011137,
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110111/1B90B280"
        },
        [11011137] = {
          Content = "嗯。长官都那么说了，我也没有别的选择。但是，我总担心……",
          ContentKR = "네. 중령님이 저렇게까지 말씀하시니 저도 어쩔 수 없네요. 하지만 걱정되는 건...",
          DialogueId = 11011137,
          Duration = 3,
          GUID = "1B90B2AA",
          NextDialogue = 11011138,
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110111/1B90B2AA"
        },
        [11011138] = {
          Content = "算了，没关系，有他在，应该不会有问题的。",
          ContentKR = "아니에요, 중령님이 계시니 괜찮을 거예요.",
          DialogueId = 11011138,
          Duration = 3,
          GUID = "1B90B2D4",
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110111/1B90B2D4"
        },
        [11011201] = {
          Content = "他们改装了所有机关……同盟中也有了不得的工程师吗？",
          ContentKR = "모든 장치를 개조했다는 건... 포세이큰 동맹에도 뛰어난 엔지니어가 있다고 봐야 하겠습니까?",
          DialogueId = 11011201,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90BD2A",
          NextDialogue = 11011202,
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110112/1B90BD2A"
        },
        [11011202] = {
          Content = "当然。早就和上头的老顽固说过，别把神弃者同盟当“野蛮人”。",
          ContentKR = "물론이지. 그래서 상부에도 포세이큰 동맹을 단순히 '야만인'으로 취급해서는 안 된다고 진작에 말했는데.",
          DialogueId = 11011202,
          Duration = 3,
          GUID = "1B90BD54",
          NextDialogue = 11011203,
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110112/1B90BD54"
        },
        [11011203] = {
          Content = "要是同盟是野蛮人，那帝国让人家占了大半年要塞，岂不是还不如野蛮人？",
          ContentKR = "포세이큰 동맹이 야만인이라면... 그 야만인이 반년 넘게 요새를 차지하고 있도록 그냥 둔 제국은 야만인만도 못하다는 얘기 아닌가?",
          DialogueId = 11011203,
          Duration = 3,
          GUID = "1B90BD7E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 11011204,
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110112/1B90BD7E"
        },
        [11011204] = {
          Content = "嗯……高层太轻敌了。",
          ContentKR = "으음... 상부에서 적을 너무 얕잡아 본 것 같습니다.",
          DialogueId = 11011204,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90BDA8",
          NextDialogue = 11011205,
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110112/1B90BDA8"
        },
        [11011205] = {
          Content = "论“指挥的艺术”，没人比富尔维斯在行。",
          ContentKR = "'지휘의 예술'을 논하자면, 풀비스만 한 사람이 없지.",
          DialogueId = 11011205,
          Duration = 3,
          GUID = "1B90BDD2",
          NextDialogue = 11011206,
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110112/1B90BDD2"
        },
        [11011206] = {
          Content = "让大艺术家自己去军团长办公室解释吧！看他那副伶牙俐齿还能不能哄得西比尔赦免他。",
          ContentKR = "나중에 그 위대한 예술가가 직접 군단장 사무실에 가서 해명하는 날이 왔을 때, 과연 그 신이 내린 혀로 시빌라 군단장님한테서 사면까지 얻어낼 수 있을지 궁금하긴 하군.",
          DialogueId = 11011206,
          Duration = 3,
          GUID = "1B90BDFC",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110112/1B90BDFC"
        },
        [11011301] = {
          Content = "先停下来整理一下现在的情况吧。",
          ContentKR = "잠깐 여기서 현재 상황을 정리해 보지.",
          DialogueId = 11011301,
          Duration = 3,
          GUID = "1B90CD92",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110113/1B90CD92"
        },
        [11011302] = {
          Camera = "160.882812,-192.464844,147.48793,0.000308,-0.601746,106.216949,35.0,178.050125,false,Manual,22.0,16:9 Digital Film",
          Content = "作战计划书上写的是，本次行动总指挥官富尔维斯上校率领人数较多的“一角鲸”部队，在通向龙莎要塞的大桥发起佯攻，以吸引神弃者同盟的关注。",
          ContentKR = "작전 계획서에 따르면, 이번 작전의 총지휘관인 풀비스 대령이 인원이 비교적 많은 '나르왈' 부대를 이끌고, 론샤 요새로 향하는 다리에서 위장 공격을 통해 포세이큰 동맹의 주의를 끌기로 되어 있었지.",
          DialogueId = 11011302,
          FinalCamera = "145.044922,-197.085938,147.48793,0.000309,-0.601746,103.817375,35.0,178.050125,false,Manual,22.0,16:9 Digital Film",
          GUID = "1B90CDBC",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11011303,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 408007,
            [5] = 101004
          },
          SpeakNpcId = 110010,
          TalkActionId = {
            [1] = "110010:Think_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110113/1B90CDBC"
        },
        [11011303] = {
          Camera = "-1571.30957,-661.851562,-349.887054,0.000318,-1.801114,178.220932,35.0,183.307098,false,Manual,22.0,16:9 Digital Film",
          Content = "而我们“雪狼”、“狮鹫”两支小队则从要塞上方空降，兵分两路潜入，分别沿动力室一线和武器库一线快速突袭，直接拿下要塞中枢——中央控制室。",
          ContentKR = "그리고 우리 '스노우 울프'와 '그리핀', 두 소대가 요새 위에서 내려온 다음 둘로 나뉘어 동력실과 무기고로 잠입해 빠르게 기습해서 요새의 핵심인 중앙 관제실을 직접 점령하기로 했었고.",
          DialogueId = 11011303,
