        [11011519] = {
          Camera = "-270.909668,32.457031,122.689575,0.000147,-2.000118,-13.794167,19.449591,100000.0,false,DoNotOverride,2.8,16:9 Digital Film",
          Content = "你们的任务是迅速突击，不许擅自中止行动。",
          ContentKR = "자네들의 임무는 신속하게 돌격하는 거다. 무단으로 작전을 중단해선 안 돼.",
          DialogueId = 11011519,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          FinalCamera = "-269.342773,38.851562,122.689575,0.000147,-2.000118,-13.794167,19.449591,100000.0,false,DoNotOverride,2.8,16:9 Digital Film",
