        },
        [11011826] = {
          Camera = "-203.332031,-139.333984,134.157104,0.00013,-4.800441,125.003876,35.000008,391.636871,false,Manual,2.8,16:9 Digital Film",
          Content = "…………",
          ContentKR = "......",
          DialogueId = 11011826,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9123B4",
