        },
        [11011839] = {
          Camera = "-331.882812,3.074219,121.966187,0.000118,-1.199463,-90.33371,35.000019,244.838531,false,Manual,2.8,16:9 Digital Film",
          Content = "老人家，既然你对水道熟悉，那来带路吧。",
          ContentKR = "노인장, 하수도 길에 익숙하시다고 하니 안내를 부탁하죠.",
          DialogueId = 11011839,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9125D6",
          LookAt = {
            [1] = "110017:n(110022)"
          },
          NextDialogue = 11011840,
          Scripts = "PlayAnimation{_delay{6},ActorId{110017},AnimationId{\"Agree\"},Duration{2}}",
          SpeakNpcId = 110022,
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B9125D6"
        },
        [11011840] = {
          Camera = "410.171875,-492.808594,467.956604,0.000058,-23.799349,145.841736,35.000011,100000.0,false,DoNotOverride,2.8,16:9 Digital Film",
          Content = "你们几个盯紧他们，别让他们有小动作。发现任何异样，立即后撤。",
          ContentKR = "너희는 다른 포로들이 허튼수작 못 부리게 잘 지키고 있어. 근처에 수상한 움직임이 있으면 바로 철수하고.",
          DialogueId = 11011840,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "644.256836,-651.65625,592.720764,0.000058,-23.799349,145.841736,35.000011,100000.0,false,DoNotOverride,2.8,16:9 Digital Film",
          GUID = "1B912600",
          SpeakNpcId = 110022,
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110118/1B912600"
        },
        [11011841] = {
          Content = "老实点！队长说过，不许动！",
          ContentKR = "가만히 있어! 움직이지 말라는 말 못 들었어?",
          DialogueId = 11011841,
          Duration = 3,
          GUID = "1B91262A",
          NextDialogue = 11011842,
          SpeakNpcId = 110015
        },
        [11011842] = {
          Content = "可是，不动的话……就没法为您指路了……",
          ContentKR = "하지만 움직이지 않으면... 길을 안내할 수 없는걸요...",
          DialogueId = 11011842,
          Duration = 3,
          GUID = "1B912654",
          NextDialogue = 11011843,
          SpeakNpcId = 110034
        },
        [11011843] = {
          Content = "对哦，也是。",
          ContentKR = "아, 그렇네.",
          DialogueId = 11011843,
          Duration = 3,
          GUID = "1B91267E",
          NextDialogue = 11011844,
          SpeakNpcId = 110015
        },
        [11011844] = {
          Content = "您无需这样戒备，普通的卡戎之民也是人，大家和您一样，都有妈妈，都想回去和她团聚。",
          ContentKR = "그렇게 경계하지 않아도 돼요. 평범한 카론도 사람이에요. 여러분처럼 저희도 모두 엄마가 있고 또 어서 돌아가 엄마를 만나고 싶은 마음 뿐이에요.",
          DialogueId = 11011844,
          Duration = 3,
          GUID = "1B9126A8",
          NextDialogue = 11011845,
          SpeakNpcId = 110034
        },
        [11011845] = {
          Content = "……唉，卡嘉……",
          ContentKR = "...아아, 카지아...",
          DialogueId = 11011845,
          GUID = "1B9126D2",
          NextDialogue = 11011846,
          SpeakNpcId = 110017
        },
        [11011846] = {
          Content = "……队长，为什么要阻止我？！",
          ContentKR = "...대장님, 왜 저를 막으신 겁니까?!",
          DialogueId = 11011846,
          GUID = "1B9126FC",
          NextDialogue = 11011847,
          SpeakNpcId = 110016
        },
        [11011847] = {
          Content = "不一定所有卡戎之民都是同盟那些反抗者——比如阿瓦尔长官也是卡戎之民。就算这几个人真的是同盟成员，活着的他们也比死了的他们更有价值。",
          ContentKR = "모든 카론이 포세이큰 같이 적인 건 아니야. 아바르 중령님도 카론이잖아. 이 중 몇 명이 정말로 포세이큰 동맹 소속이라 해도 죽이는 것보단 살려 두는 게 더 쓸모 있을 거야.",
          DialogueId = 11011847,
          ExStoryInfo = "EXPlayer",
          GUID = "1B912726",
          NextDialogue = 11011848,
          SpeakNpcId = 110022
        },
        [11011848] = {
          Content = "……无论心里有什么声音在回响，都不要屈从它们。马尔科，不要让冲动凌驾在理智之上。",
          ContentKR = "...마음속에서 어떤 소리가 들리더라도 그것에 굴복하지 마라, 마르코. 충동에 사로잡히면 안돼.",
          DialogueId = 11011848,
          ExStoryInfo = "EXPlayer",
          GUID = "1B912750",
          SpeakNpcId = 110022
        },
        [11011849] = {
          Camera = "-206.832031,-274.033203,151.986694,0.000304,-7.786074,84.022697,30.000002,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "谢谢您……",
          ContentKR = "고마워요...",
          DialogueId = 11011849,
          Duration = 1,
          GUID = "1B91277A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          LookAt = {
            [1] = "110034:n(110022)"
          },
          NextDialogue = 11011850,
          SpeakNpcId = 110034,
          VoiceName = "voice/$Locale$/story/1002/110118/1B91277A"
        },
        [11011850] = {
          Camera = "316.260742,671.15625,590.656799,0.000295,-32.38599,-125.777397,30.000002,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "你在和我说话？",
          ContentKR = "나한테 말한 건가?",
          DialogueId = 11011850,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "248.001953,576.443359,518.394348,0.000295,-32.38599,-125.777397,30.000002,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1B9127A4",
          NextDialogue = 11011851,
          SpeakNpcId = 110022,
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "110022:p(-150)"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B9127A4"
        },
        [11011851] = {
          Camera = "-178.519531,165.578125,130.494019,0.000272,-1.986786,-88.369873,35.000011,223.924484,false,Manual,4.0,16:9 Digital Film",
          Content = "是的。您刚才没有当众搜我身。我很感激，身为帝国人的您，愿意留给一个陌生的卡戎女人一丝尊严。",
          ContentKR = "아까 몸수색을 하지 않으셨죠. 제국인이시면서도 카론 여자인 저의 존엄성을 지켜주신 것에 감사드리고 싶었어요.",
          DialogueId = 11011851,
          GUID = "1B9127CE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11011852,
          SpeakNpcId = 110034,
          VoiceName = "voice/$Locale$/story/1002/110118/1B9127CE"
