          HeadIconType = "Npc",
          NextDialogue = 11011933,
          SpeakNpcId = 110034,
          VoiceName = "voice/$Locale$/story/1002/110119/1B9134C6"
        },
        [11011933] = {
          Content = "也许吧，但愿如此。",
          ContentKR = "그러길 바라야지.",
          DialogueId = 11011933,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9134C7",
          NextDialogue = 11011934,
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110119/1B9134C7"
        },
        [11011934] = {
          Content = "如果能活着回去，我想去服装店，买好多好多以前不舍得买的衣服。",
          ContentKR = "살아서 돌아가면, 예전엔 살 엄두를 못 냈던 옷을 맘껏 사고 싶어요.",
