        [11012466] = {
          Camera = "-270.096924,-220.964355,332.621887,0.000151,-35.795891,35.78912,15.610332,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "我说了，悄悄话只有一句。呵呵……一路顺风，我的长官。",
          ContentKR = "딱 한 마디만 한다고 했잖아. 후훗... 행운을 빌게, 우리 대장 나리.",
