        [11012717] = {
          Camera = "57.001575,280.910156,125.013489,0.000079,-7.598968,-87.998039,40.0,847.801208,false,DoNotOverride,2.8,16:9 Digital Film",
          Content = "长官，我总受你照顾，刚刚你还救了我一命。就算我妈妈在这里，她也会说，“跟上你的长官，不要惧怕死亡。你是海伯利亚的战士，当以生命守卫帝国的一切。”",
          ContentKR = "중령님은 늘 저를 보살펴 주셨고 방금도 제 목숨을 구해 주셨습니다. 어머니가 여기 계셨어도 죽음을 두려워 말고 중령님을 따라 휘페르보레아 제국의 전사답게 목숨을 걸고 제국을 지키라고 말씀하셨을 겁니다.",
          DialogueId = 11012717,
          Duration = 3,
          GUID = "1B91B5E2",
          NextDialogue = 11012718,
          Scripts = "CameraMoveTo{_delay{7},TargetPosition{\"77.976013,62.661133,89.001038,0.000089,1.400619,-94.583221,70.0,559.908325,false,DoNotOverride,12.0,16:9 Digital Film\"},duration{0}}",
          SpeakNpcId = 110020,
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B5E2"
        },
        [11012718] = {
          Camera = "93.908615,56.692871,81.890564,0.0,10.799786,107.816833,70.000015,559.908325,false,DoNotOverride,12.0,16:9 Digital Film",
          Content = "没有人怕死，我怕的是——毫无意义的死。",
          ContentKR = "죽음을 두려워하는 게 아니다. 그저 무의미하게 죽을까봐, 그것이 두려운 거지.",
          DialogueId = 11012718,
          Duration = 3,
          GUID = "1B91B60C",
          NextDialogue = 11012719,
          SpeakNpcId = 110010,
          TalkActionId = {
            [1] = "110022:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B60C"
        },
        [11012719] = {
          Camera = "313.871033,357.636719,159.137878,0.000087,-8.999512,-150.398483,70.000015,501.809082,false,DoNotOverride,5.0,16:9 Digital Film",
          Content = "不会毫无意义的。只要我们前进一步，战线就向前推进了一步。",
          ContentKR = "무의미하지 않을 겁니다. 우리가 한 발 전진하면 전선도 한 발 전진하니 말입니다.",
          DialogueId = 11012719,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
