        [11012817] = {
          Camera = "-280.927521,1211.751587,190.038452,0.000039,-7.600156,-85.574547,45.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "不过这件事你别说出去啊，我们就是为了不让人知道达芙涅是我女儿，才离婚的。",
          ContentKR = "이건 비밀로 해 줘. 다프네가 내 딸인 걸 감추기 위해 이혼한 거거든.",
          DialogueId = 11012817,
          Duration = 3,
          FinalCamera = "-270.015259,1212.595337,190.038452,0.000039,-7.600156,-85.574547,45.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1B91C64A",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11012818,
          Scripts = "PlayAnimation{_delay{4},ActorId{110010},AnimationId{\"Talk02_End\"},Duration{0}}",
          SpeakNpcId = 110010,
          TalkActionId = {
            [1] = "110010:Talk02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C64A"
        },
        [11012818] = {
          Camera = "-331.020386,571.073792,139.486084,0.000067,0.800628,61.435661,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "当年首席炼金术师很喜欢达芙涅，说她会成为未来帝国最优秀的炼金术师。那时她早已宣布不再招收学生，却为这孩子破例了。",
          ContentKR = "예전의 수석 연금술사는 다프네를 무척 아꼈어. 그 아이가 제국 역사상 최고의 연금술사가 될 거라고 말했지. 이미 더는 제자를 받지 않겠다고 선언한 뒤였지만, 다프네만큼은 예외였어.",
          DialogueId = 11012818,
          Duration = 3,
          FinalCamera = "-324.280945,583.456116,139.682922,0.000067,0.800628,61.435661,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1B91C674",
          NextDialogue = 11012819,
          SpeakNpcId = 110010,
          TalkActionId = {
            [1] = "110022:Talk03_End",
            [2] = "110010:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C674"
        },
        [11012819] = {
          Camera = "-256.828491,929.640686,152.787537,-0.0,-5.799807,-88.576996,40.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "因为达芙涅是个天才？",
          ContentKR = "다프네가 천재라서 말입니까?",
          DialogueId = 11012819,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C69E",
          NextDialogue = 11012820,
          SpeakNpcId = 110022,
          TalkActionId = {
            [1] = "110022:Talk02_Start",
            [2] = "110010:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C69E"
        },
        [11012820] = {
          Camera = "-350.142548,666.156311,140.458618,0.000062,2.999812,49.027782,45.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "她确实在炼金术上很有天赋，但佩剑炼金院那种地方，最不缺的就是天才。首席炼金术师说，达芙涅是特别的，因为她拥有一些其他炼金术师没有的东西。",
          ContentKR = "그 아이가 연금술에 재능이 있는 건 사실이지만, 소드 연금원에 넘쳐 나는 게 천재이지 않은가. 수석 연금술사 말로는 다프네에게 다른 이들에겐 없는 특별한 무언가가 있다고 하더군.",
          DialogueId = 11012820,
          Duration = 3,
          FinalCamera = "-340.031555,677.799377,141.266479,0.000062,2.999812,49.027782,45.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1B91C6C8",
          NextDialogue = 11012821,
          Scripts = [[
