            [1] = "110022:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C6F2"
        },
        [11012822] = {
          Camera = "-616.148438,313.40152,101.787903,0.000002,0.999468,49.427162,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "达芙涅知道吗？",
          ContentKR = "다프네도 알고 있습니까?",
          DialogueId = 11012822,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-576.944153,359.186676,102.839539,0.000002,0.999468,49.42717,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1B91C71C",
          NextDialogue = 11012823,
          SpeakNpcId = 110022,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C71C"
        },
        [11012823] = {
          Camera = "-319.142975,642.300842,140.458618,0.00007,3.399658,61.429241,45.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "不知道。她打小心思就单纯，也很黏我，怎么能告诉她这个。",
          ContentKR = "모르지. 어릴 때부터 나를 많이 따랐는데, 어떻게 그런 말을 할 수 있겠어.",
          DialogueId = 11012823,
          Duration = 3,
          FinalCamera = "-305.392487,667.551331,142.16687,0.00007,3.399658,61.429241,45.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1B91C746",
          NextDialogue = 11012824,
          SpeakNpcId = 110010,
          TalkActionId = {
            [1] = "110010:DisagreeHead"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C746"
        },
        [11012824] = {
          Content = "所以我就装作是一个抛妻弃女的坏父亲，她走在路上叫我爸爸，我就会跟她说，“闭嘴，叫什么爸爸、套什么近乎呢，叫长官。”",
          ContentKR = "그래서 내가 아내와 자식을 버린 나쁜 아빠인 척했지. 다프네가 길에서 날 아빠라고 부를 때면 \"조용히 해. 어디서 아빠라고 부르며 친한 척이야. 중령님이라고 불러\"라고 꾸짖곤 했지.",
          DialogueId = 11012824,
          Duration = 3,
          GUID = "1B91C770",
          NextDialogue = 11012825,
          Scripts = [[
PARA{
PlayAnimation{_delay{15},ActorId{110022},AnimationId{"Talk03_End"},Duration{0}},
SEQ{
CameraMoveTo{_delay{6},TargetPosition{"-256.828491,929.640686,152.787537,-0.0,-5.799807,-88.576996,40.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film"},duration{0}},
CameraMoveTo{TargetPosition{"-256.535095,917.831116,151.587341,-0.0,-5.799807,-88.576996,40.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film"},duration{8}}
}}]],
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C770"
        },
        [11012825] = {
          Camera = "-288.338318,672.926819,122.673157,0.000056,11.399967,65.427414,45.000023,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "可她还是太懂事了，连骂我的话都骂不出口，只能和自己闹别扭。",
          ContentKR = "하지만 너무 철이 일찍 들어서 그런지, 나한테 아쉬운 소리 한번 못하고 혼자 힘들어하더군.",
          DialogueId = 11012825,
          Duration = 3,
          GUID = "1B91C79A",
          LookAt = {
            [1] = "110010:n(110010)"
          },
          NextOptions = {
            [1] = 11012826,
            [2] = 11012829
          },
          SpeakNpcId = 110010,
          TalkActionId = {
            [1] = "110010:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C79A"
        },
        [11012826] = {
          Content = "她其实并不喜欢炼金院。您和夫人应该考虑一下她的想法。",
          ContentKR = "사실 다프네는 연금원을 좋아하지 않습니다. 다프네 생각도 물어보셨어야 합니다.",
          DialogueId = 11012826,
          GUID = "1B91C7C4",
          NextDialogue = 11012827
        },
        [11012827] = {
          Camera = "-604.107727,306.536285,101.833496,0.000002,0.999468,49.42717,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "我已经知道了。这次她非要转到龙莎特别行动队来，还瞒过她母亲和我直接向富尔维斯递交申请，可见她是真的不想待在炼金院了。",
          ContentKR = "나도 알고 있어. 다프네가 제 엄마랑 나까지 속이고, 풀비스에게 신청서를 제출하면서까지 이 론샤 특별 행동대로 왔다는 건, 그만큼 연금원에 있기 싫었다는 거겠지.",
          DialogueId = 11012827,
          Duration = 3,
          FinalCamera = "-622.919128,319.203278,101.787903,0.000002,0.999468,49.42717,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1B91C7EE",
          NextDialogue = 11012828,
          SpeakNpcId = 110010,
          TalkActionId = {
            [1] = "110010:AgreeHead",
            [2] = "110010:Sigh_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C7EE"
        },
        [11012828] = {
          Camera = "-264.298615,914.238342,151.455444,0.000002,-5.799711,-85.974731,35.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "……等回去，我和她母亲好好谈谈吧。",
          ContentKR = "...돌아가면, 아이 엄마와 잘 얘기해 봐야지.",
          DialogueId = 11012828,
          Duration = 3,
          GUID = "1B91C818",
          NextDialogue = 11012830,
          SpeakNpcId = 110010,
          TalkActionId = {
            [1] = "110010:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C818"
        },
        [11012829] = {
          Content = "您也牺牲了很多……辛苦了。",
          ContentKR = "너무 많은 걸 희생하신 것 같습니다... 정말 고생 많으셨겠습니다.",
          DialogueId = 11012829,
          GUID = "1B91C842",
          NextDialogue = 11012830
        },
        [11012830] = {
          Camera = "-288.338318,672.926819,122.673157,0.000055,11.399967,65.427475,45.000023,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "……我倒是希望她再多记恨我一些，至少这样，她自己会好过点。",
          ContentKR = "...나는 오히려 다프네가 나를 더 미워했으면 좋겠는데 말이지. 적어도 그렇게 하면 그 아이 마음은 좀 더 편해질 수 있을 테니까.",
          DialogueId = 11012830,
          Duration = 3,
          GUID = "1B91C86C",
          NextDialogue = 11012831,
          SpeakNpcId = 110010,
          TalkActionId = {
            [1] = "110010:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C86C"
        },
        [11012831] = {
          Camera = "-604.107727,306.536285,101.833496,0.000002,0.999468,49.42717,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "唉，要是能回去的话，就请她去看戏吧。我是个大头兵出身，以前从没陪她进过歌剧院，就当把小时候的份也一起补上吧。",
          ContentKR = "휴, 무사히 복귀할 수 있다면 함께 공연이라도 보러 가야겠군. 난 병사 출신이라 젊을 땐 말단 병사 주머니로는 오페라 하우스 한 번 못 데려갔거든. 그때 못해준 걸 다 해주고 싶은데 말이지.",
          DialogueId = 11012831,
          Duration = 3,
          FinalCamera = "-622.919128,319.203278,101.787903,0.000002,0.999468,49.42717,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1B91C896",
          NextDialogue = 11012832,
          Scripts = "PlayAnimation{_delay{7},ActorId{110010},AnimationId{\"Confident_End\"},Duration{0}}",
          SpeakNpcId = 110010,
          TalkActionId = {
            [1] = "110010:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C896"
        },
        [11012832] = {
          Camera = "-324.594086,581.971741,140.384827,0.000062,1.799953,62.62788,45.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "听说迪斯玛尼亚最近新上了一出戏，从北边科赛托斯那边传来的，叫雪国什么什么……到时候我多买一张票，你也一起吧。",
          ContentKR = "디즈마니아에 북쪽 코퀴투스에서 왔다는 새로운 공연이 열린다던데, 설국 뭐라더라... 나중에 표 한 장 더 살 테니 같이 보러 가자.",
          DialogueId = 11012832,
          Duration = 3,
          FinalCamera = "-320.052155,590.743225,140.695251,0.000062,1.799953,62.62788,45.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1B91C8C0",
          NextDialogue = 11012833,
          SpeakNpcId = 110010,
          TalkActionId = {
            [1] = "110022:Talk03_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C8C0"
        },
        [11012833] = {
          Camera = "-258.992004,740.77594,158.750488,1.000006,-7.603387,-103.364433,45.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "好。",
          ContentKR = "좋습니다.",
          DialogueId = 11012833,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C8EA",
          SpeakNpcId = 110022,
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C8EA"
        },
        [11012834] = {
          Content = "可老师是<H>桂冠卡戎</>——和其他卡戎之民不一样。",
          ContentKR = "하지만 교관님은 다른 카론과 다른... <H>계관카론</>이십니다.",
          DialogueId = 11012834,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C6F3",
          NextDialogue = 11012835,
          RelatedWikiId = {
            [1] = 407003
          },
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C6F3"
        },
        [11012835] = {
          Content = "也没什么不一样的。时代变了，现在从元老院和军团内部，到处都有人质疑桂冠卡戎的忠诚。",
          ContentKR = "별반 다르지 않아. 시대가 변했거든. 지금은 원로원부터 군단 내부까지, 계관카론의 충성심을 의심하는 놈들이 사방에 널렸어.",
          DialogueId = 11012835,
          Duration = 3,
          GUID = "1B91C6F4",
          NextDialogue = 11012836,
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C6F4"
        },
        [11012836] = {
          Content = "指不定哪天一纸敕令下来，我们这些人就要回老家喽。如果真有这么一天，达芙涅的前程也可能受牵连……她母亲是这么想的。",
          ContentKR = "칙령 하나면 우린 언제든지 자리가 날아갈 수 있어. 만약 정말 그런 날이 온다면, 다프네의 앞길에 불똥이 튈 수도 있지... 애 엄마는 그걸 걱정한 거야.",
          DialogueId = 11012836,
          Duration = 3,
          GUID = "1B91C6F5",
          NextDialogue = 11012822,
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C6F5"
        },
        [11012901] = {
          Content = "是强敌，留意！",
          ContentKR = "보통 놈들이 아니다, 조심해!",
          DialogueId = 11012901,
          Duration = 3,
          GUID = "1B91D412",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D412"
        },
        [11012902] = {
          Camera = "355.686127,-321.117188,61.902191,0.000327,6.602033,105.412376,28.000011,288.624115,false,Manual,6.072517,16:9 Digital Film",
          Content = "有埋伏！仔细防御！",
          ContentKR = "매복이다! 방어 태세!",
          DialogueId = 11012902,
          FacialId = {
            [1] = "110010:Unhappy01"
          },
