        [11012903] = {
          Camera = "-1147.589233,1035.804688,431.601532,0.000327,-8.59737,-43.590466,28.000006,667.895142,false,DoNotOverride,6.072517,16:9 Digital Film",
          Content = "等等——机关，没有启动？",
          ContentKR = "잠깐, 장치가 가동을 안 하잖아?",
          DialogueId = 11012903,
          FinalCamera = "-1147.589233,1035.804688,431.601532,0.000338,-9.796847,-36.989296,28.000006,667.895142,false,DoNotOverride,6.072517,16:9 Digital Film",
