          VoiceName = "voice/$Locale$/story/1002/110129/1B91D466"
        },
        [11012904] = {
          Camera = "-1936.596191,338.285156,1372.406128,0.000417,-36.596905,43.408157,14.543221,667.895142,false,DoNotOverride,6.072517,16:9 Digital Film",
          Content = "中央控制室空无一人……同盟的“信使”已经撤离了？",
          ContentKR = "중앙 관제실에 아무도 없는데... 포세이큰의 '연락책'은 벌써 철수한 건가?",
          DialogueId = 11012904,
          FinalCamera = "-1936.596191,338.285156,1245.097656,0.000417,-36.596905,43.408157,14.543221,667.895142,false,DoNotOverride,6.072517,16:9 Digital Film",
          GUID = "1B91D490",
          LookAt = {
