        [11013610] = {
          Camera = "-89.605194,-418.919922,28.023407,-10.014737,8.201615,53.252785,35.0,271.651154,false,DoNotOverride,20.0,16:9 Digital Film",
          Content = "就是因为上面有很多聪明人，他们才一定会装傻。阿瓦尔，动动你的脑子。既然我敢把事做绝，自然有想要我做绝的人。",
          ContentKR = "오히려 똑똑한 사람이 많으니까 전부 바보인 척하겠지. 아바르, 머리 좀 굴려봐. 설마 내가 혼자서 이런 일을 꾸몄을 거라 생각하는 건 아니겠지?",
          DialogueId = 11013610,
          Duration = 3,
          GUID = "1B924864",
          NextDialogue = 11013611,
