        [11013612] = {
          Camera = "34.140366,-340.748047,894.160034,-0.001587,-12.995759,88.221321,43.321198,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "陛下即位之初——也就是塞维乌斯公爵担任摄政的那段时间里——他们偏离了海伯利亚长久以来的规则，为帝国这棵大树嫁接了太多无用的枝叶。",
          ContentKR = "폐하께서 막 즉위하셨을 때... 그러니까 세르비우스 공작이 섭정하는 동안 두 분은 휘페르보레아의 오랜 규칙에서 벗어나 제국이란 큰 나무에 쓸모없는 가지를 너무 많이 붙이셨지.",
          DialogueId = 11013612,
          Duration = 3,
          FinalCamera = "195.783936,-345.769531,815.577393,-0.001587,-12.995759,88.221321,43.321198,100000.0,false,Manual,22.0,16:9 Digital Film",
