        [11013614] = {
          Camera = "-129.604523,471.810547,-28.501526,0.000752,21.988857,-30.575706,23.640343,100000.0,false,DoNotOverride,2.654159,16:9 Digital Film",
          Content = "尽管如今陛下已经迷途知返，但这些糜烂的枝叶依旧存在。而我要做的，则是帮陛下一把，将这些糜烂彻底剪除。",
          ContentKR = "지금은 폐하께서 일들을 바로잡으셨지만, 썩은 가지들은 여전하니 말이야. 폐하를 대신해 썩은 가지를 쳐 내는 게 내가 할 일이고.",
          DialogueId = 11013614,
          Duration = 3,
          FinalCamera = "-40.557144,495.207031,55.238251,-10.00088,13.201608,-42.578636,30.0,229.467407,false,DoNotOverride,22.0,16:9 Digital Film",
