          Content = "……闹了半天，你是看不惯我是个卡戎之民啊。",
          ContentKR = "...결국 내가 카론인 게 마음에 안 들었다는 건가?",
          DialogueId = 11013615,
          Duration = 3,
          FinalCamera = "60.468475,373.251953,96.8255,0.0,-0.198417,-44.378376,30.000019,229.46875,false,Manual,22.0,16:9 Digital Film",
          GUID = "1B924936",
          NextDialogue = 11013616,
          SpeakNpcId = 110010,
          ToFinalCameraBlendTime = 5,
