          VoiceName = "voice/$Locale$/story/1002/110151/1B933D2C"
        },
        [11015103] = {
          Camera = "184.916016,-61.012665,145.951035,0.000085,-1.799372,155.628265,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "他们肯定在那里设了埋伏。",
          ContentKR = "놈들이 매복해 있을 겁니다.",
          DialogueId = 11015103,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "207.275391,-71.141312,146.722122,0.000085,-1.799372,155.428955,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B933D56",
          NextDialogue = 11015104,
          SpeakNpcId = 110022,
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933D56"
        },
        [11015104] = {
          Camera = "50.191406,-61.684036,121.714935,0.000108,8.400572,23.04035,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "您伤得很重，我们……会有胜算吗……而且，就算跑出要塞，军团也不会放过我们……等待我们的，会是无休止的追捕和刺杀……",
          ContentKR = "상처가 이렇게 깊은데, 우리에게... 승산이 있을까요... 그리고 요새에서 탈출한다고 해도, 군단이 우릴 가만두지 않을 텐데... 추적과 암살 시도가 계속될 거예요...",
          DialogueId = 11015104,
          Duration = 3,
          FinalCamera = "32.810547,-69.076233,118.901154,0.000109,7.400571,23.039328,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B933D80",
          NextOptions = {
