            [2] = 11015107,
            [3] = 11015110
          },
          Scripts = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{\"Explain02_End\"},Duration{2}}",
          SpeakNpcId = 110005,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933D80"
        },
        [11015105] = {
          Content = "看来只能一辈子住下水道里了。",
          ContentKR = "그럼 하수도에서 평생 사는 수밖에 없겠군요.",
          DialogueId = 11015105,
          GUID = "1B933DAA",
          ImprPlusId = 1010,
          NextDialogue = 11015106
        },
        [11015106] = {
          Camera = "39.349609,-74.855362,160.701706,0.000115,-7.799802,25.839321,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "但这里食物和衣物都不够——不对，请您和我一起好好想办法！",
          ContentKR = "하지만 여긴 음식과 옷이 없는... 아니지, 같이 제대로 된 방법을 생각해 보자니까요!",
          DialogueId = 11015106,
          Duration = 3,
          FinalCamera = "23.103516,-82.726669,163.175507,0.000116,-8.599856,25.63818,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B933DD4",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11015111,
          SpeakNpcId = 110005,
          TalkActionId = {
            [1] = "110005:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933DD4"
        },
        [11015107] = {
          Content = "直接出去和他们决一死战。",
          ContentKR = "나가서 놈들과 목숨 걸고 싸우는 겁니다.",
          DialogueId = 11015107,
          GUID = "1B933DFE",
          ImprPlusId = 1007,
          NextDialogue = 11015108
        },
        [11015108] = {
          Camera = "39.349609,-74.855362,160.701706,0.000115,-7.799802,25.839321,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "不行……虽然有您在，但以您的伤势，我们没有胜算……",
          ContentKR = "안 돼요... 당신이 있다고 해도, 부상이 심해서 힘들 거예요...",
          DialogueId = 11015108,
          Duration = 3,
          FinalCamera = "23.103516,-82.726669,163.175507,0.000116,-8.599856,25.63818,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
