        },
        [11015109] = {
          Content = "……还有别的办法吗……",
          ContentKR = "...다른 방법은 없을까요...",
          DialogueId = 11015109,
          Duration = 3,
          GUID = "1B933E52",
          NextDialogue = 11015111,
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933E52"
        },
        [11015110] = {
          Content = "……冷静下来，一定会有办法的。",
          ContentKR = "...진정해요. 반드시 방법이 있을 겁니다.",
          DialogueId = 11015110,
