        [11015113] = {
          Camera = "-17.943359,-63.457489,146.000702,0.000093,-3.202395,18.475502,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "什么？",
          ContentKR = "네?",
          DialogueId = 11015113,
          Duration = 3,
          FinalCamera = "-0.720703,-57.570724,144.94313,0.000094,-3.00238,17.275826,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
