          TalkActionId = {
            [1] = "110005:Shock04_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933EFA"
        },
        [11015114] = {
          Camera = "489.007812,-334.206299,292.918701,0.000068,-19.202305,139.670319,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "脱掉外衣，和我交换。",
          ContentKR = "저와 옷을 바꿔 입자고요.",
          DialogueId = 11015114,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "445.892578,-297.610748,273.224854,0.000065,-19.402313,139.27037,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B933F24",
          NextDialogue = 11015115,
          SpeakNpcId = 110022,
          TalkActionId = {
            [1] = "110022:Talk02_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933F24"
        },
        [11015115] = {
          Content = "他们以为我死在了中央控制室，不知道现在和你在一起的人是谁，所以他们能确认的目标只有你。",
          ContentKR = "놈들은 제가 중앙 관제실에서 죽은 줄 압니다. 지금 당신과 함께 있는 사람이 누군지 몰라요. 저쪽에서 확인할 수 있는 타깃은 당신뿐이죠.",
          DialogueId = 11015115,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B933F4E",
          NextDialogue = 11015116,
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933F4E"
        },
        [11015116] = {
          Content = "我扮成你的样子往外冲，医务员的制服很醒目，应该可以引开他们。你就想办法趁乱逃掉。",
          ContentKR = "제가 당신인 척하고 밖으로 나가겠습니다. 의무관 제복은 눈에 잘 띄니까 놈들을 유인할 수 있을 테니 그때 어떻게든 빠져나가세요.",
          DialogueId = 11015116,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B933F78",
          NextDialogue = 11015117,
          Scripts = "PlayAnimation{_delay{3},ActorId{110022},AnimationId{\"Talk02_End\"},Duration{2}}",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933F78"
        },
        [11015117] = {
          Camera = "30.167969,-51.420792,112.9972,0.000112,8.79729,16.678789,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "您……是在开玩笑吗？我们的身形根本不一样，他们很快就会察觉的！",
          ContentKR = "지금... 농담하는 거죠? 체형이 달라서 금방 발각될 거라고요!",
          DialogueId = 11015117,
          Duration = 3,
          FinalCamera = "49.683594,-45.570618,123.095779,0.000108,7.997291,16.280628,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B933FA2",
          NextDialogue = 11015118,
          Scripts = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{\"Shock04_End\"},Duration{2}}",
          SpeakNpcId = 110005,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933FA2"
        },
        [11015118] = {
          Camera = "174.623047,-31.802631,151.059662,0.000112,-2.002987,168.472702,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "能让他们多慌乱一秒，你就多一秒能逃走的机会。就这样吧，达芙涅。不要违背老师的遗愿。",
          ContentKR = "저들에게 혼란을 주면 당신이 도망갈 시간을 1초라도 더 벌 수 있을 겁니다. 다프네, 교관님 유언을 따르셔야 합니다.",
          DialogueId = 11015118,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "182.253906,-34.744297,148.60463,0.000112,-1.403016,167.073715,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B933FCC",
          SpeakNpcId = 110022,
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933FCC"
        },
        [11015119] = {
          Content = "别犹豫了，快。",
          ContentKR = "망설일 시간 없습니다. 어서요.",
          DialogueId = 11015119,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B933FF6",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933FF6"
        },
        [11015120] = {
          Content = "……不。",
          ContentKR = "...안 돼요.",
          DialogueId = 11015120,
          Duration = 2,
          GUID = "1B934020",
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934020"
        },
        [11015121] = {
          Content = "谢谢您能记住父亲的愿望。",
          ContentKR = "아버지의 바람을 기억해 줘서 고마워요.",
          DialogueId = 11015121,
          Duration = 3,
          GUID = "1B93404A",
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93404A"
        },
        [11015122] = {
          Content = "但能请您听一听，<H>我的愿望</>吗？",
          ContentKR = "혹시 <Highlight>제 바람</>도 들어 주실 수 있나요?",
          DialogueId = 11015122,
          Duration = 3,
          GUID = "1B934074",
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934074"
        },
        [11015123] = {
          Content = "迪斯玛尼亚常常会下雨。在我很小的时候，我的玩伴们都很讨厌下雨，因为雨会打湿漂亮的头发，弄脏干净的新裙子。",
          ContentKR = "디즈마니아엔 비가 자주 내려요. 제가 아주 어렸을 때, 제 친구들은 비 때문에 예쁘게 빗은 머리카락이 젖고 깨끗한 새 치마가 더러워진다며, 모두 비를 싫어했죠.",
          DialogueId = 11015123,
          Duration = 3,
          FacialId = {
            [1] = "110005:Sad01"
          },
          GUID = "1B93409E",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11015124,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 201016,
            [6] = 408007,
            [7] = 101004
          },
          SpeakNpcId = 110005,
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B93409E"
        },
        [11015124] = {
          Content = "但我不讨厌。因为雨从来不会落到我的肩头。我看到的雨，只是靴子下一圈圈的小水花，伞尖坠落的一串串露滴。",
          ContentKR = "하지만 전 아니었어요. 제 어깨에는 빗방울이 닿지 않았거든요.\n제가 보는 비는 장화 아래에서 튀고, 우산 끝에서 떨어지는 물방울이 전부였어요.",
          DialogueId = 11015124,
          Duration = 3,
          GUID = "1B9340C8",
          NextDialogue = 11015125,
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9340C8"
        },
        [11015125] = {
          Content = "但是长大一点之后，我知道了，我并没有那么喜欢下雨。只是因为当时爸爸在，所以所有的雨，都落在了他的那一边。",
          ContentKR = "좀 크고 난 후에야 제가 비를 좋아하는 게 아니었다는 걸 깨달았어요. 어릴 땐 아빠가 곁에서 대신 비를 맞아 주신 거였죠.",
          DialogueId = 11015125,
          Duration = 3,
          GUID = "1B9340F2",
          NextDialogue = 11015126,
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9340F2"
        },
        [11015126] = {
          Content = "爸爸啊，是一个很好很好的人，也是一个很犟很犟的人。他永远都在为了别人不顾自己，永远都是。",
          ContentKR = "아빠는 무뚝뚝하셨지만 정말 좋은 분이셨어요. 하지만 평생 남을 챙기느라 자신은 돌보지 않으셨죠, 평생을요.",
          DialogueId = 11015126,
          Duration = 3,
          GUID = "1B93411C",
          NextDialogue = 11015128,
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93411C"
        },
        [11015127] = {
          Content = "…………",
          ContentKR = "......",
          DialogueId = 11015127,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934146",
          NextDialogue = 11015128,
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934146"
        },
        [11015128] = {
          Content = "我出生前，他为了能够“配得上”妈妈而加入军团，出生入死；我长大后，他又为了“不耽误我的前程”而离开我和妈妈。",
          ContentKR = "아빠는 제가 태어나기 전에 엄마에게 '어울리는 사람'이 되기 위해 군단에 들어가 생사를 넘나들며 싸우셨고, 제가 크고 나선 '제 앞길에 방해가 되지 않기' 위해 저와 엄마 곁을 떠나셨죠.",
          DialogueId = 11015128,
          Duration = 3,
          GUID = "1B934170",
          NextDialogue = 11015129,
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934170"
        },
        [11015129] = {
          Content = "……在大街上，他板着脸叫我不要喊他爸爸。在深夜的酒馆里，他喊着我和妈妈的名字，一边喝得酩酊大醉，一边流泪——多么伟大的父亲，总是一个人抗下一切……",
          ContentKR = "...길에서 마주치면 냉정한 얼굴로 아빠라고도 못 부르게 하고선, 깊은 밤 술집에서 저와 엄마 이름을 부르며 술에 취해 울던 분이셨어요.\n얼마나 위대한 아버지인가요, 늘 혼자서 모든 걸 짊어지시다니...",
          DialogueId = 11015129,
          Duration = 3,
          GUID = "1B93419A",
          NextDialogue = 11015130,
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93419A"
        },
        [11015130] = {
          Content = "可是，他从来都没有问过我，这一切到底是不是我想要的……就像此刻的您，也从来没有问过我，我是否想要踏着您的生命活下去！",
          ContentKR = "하지만, 아빠는 그 모든 걸 제가 원하는지 묻지 않으셨어요... 지금 당신처럼요. 당신도 제가 당신 목숨을 밟고 살아남길 원하는지 물어보지 않았다고요!",
          DialogueId = 11015130,
          Duration = 3,
          GUID = "1B9341C4",
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9341C4"
        },
        [11015131] = {
          Camera = "74.1875,-11.549334,140.752075,0.000139,2.317531,0.270602,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "您与他都不知道……我想要的，从来都不是一个用自己的身躯为我遮风挡雨的人。我真正的愿望是……",
          ContentKR = "당신이나 아빠는 몰라요... 저는 한 번도 비바람을 대신 막아 줄 사람을 원한 적 없어요. 내가 정말 원하는 건...",
          DialogueId = 11015131,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unhappy01"
          },
          GUID = "1B9341EE",
          NextDialogue = 11015132,
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9341EE"
        },
        [11015132] = {
          Camera = "74.1875,-11.549334,140.752075,0.000139,2.317531,0.270602,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "如果遮风挡雨的伞小到只能庇护一人，请让我和你们一起走进雨里。",
          ContentKR = "비바람을 막아 줄 우산이, 오직 한 사람만 지킬 수 있다면, 전 모두와 함께 빗속으로 들어가겠어요.",
          DialogueId = 11015132,
          Duration = 3,
          FinalCamera = "54.34375,-11.712122,143.421494,0.000139,-0.282503,0.470605,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B934218",
          NextDialogue = 11015133,
          SpeakNpcId = 110005,
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934218"
        },
        [11015133] = {
          Content = "我，想要的是，<H>和您一起</>活下去。",
          ContentKR = "제가 바라는 건, <Highlight>당신과 함께</> 살아남는 거예요.",
          DialogueId = 11015133,
          Duration = 3,
          FacialId = {
            [1] = "110005:Smile01"
          },
          GUID = "1B934242",
          NextDialogue = 11015134,
