        [11015136] = {
          Camera = "-35.435547,164.474655,360.730713,0.000111,20.917017,-153.732254,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "现在的情况是，富尔维斯要灭我们的口，他的手段是给我们扣上间谍的帽子，借军团同僚的手诛杀我们……",
          ContentKR = "현재 상황을 정리해 보죠. 풀비스는 우리 입을 막는 게 목적이에요. 그래서 우리한테 스파이라는 누명을 씌워서 군단이 우릴 쫓고 있고, 결국 우릴 죽이려고 하고 있죠...",
          DialogueId = 11015136,
          Duration = 3,
          FinalCamera = "-35.435547,164.474655,327.571594,0.000111,20.717014,-153.73233,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B9342C0",
          NextDialogue = 11015137,
          SpeakNpcId = 110005,
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9342C0"
        },
        [11015137] = {
          Content = "“狮鹫”、“雪狼”两支先遣小队仅剩我们二人，整座要塞的士兵全受富尔维斯和他的副官法露茜调遣……整座要塞的士兵……",
          ContentKR = "'그리핀'과 '스노우 울프' 두 선발대에 우리 둘만 남았고, 요새에 있는 병사는 전부 풀비스와 그의 부관인 펄시의 지시를 따르죠... 요새에 있는 병사...",
          DialogueId = 11015137,
          Duration = 3,
          GUID = "1B9342EA",
          NextDialogue = 11015138,
          Scripts = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{\"Think_End\"},Duration{2}}",
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9342EA"
        },
        [11015138] = {
          Camera = "43.673828,56.272556,139.847488,0.000149,0.117582,-27.726179,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "等等，我想到了……！父亲和我讲过，“以退为进，险中求胜”……",
          ContentKR = "잠깐, 생각났어요...! 아버지가 말씀하신 게 있거든요. \"이 보 전진을 위해 일 보 후퇴를 하고, 위험 속에서 기회를\n찾아라\"라고요...",
          DialogueId = 11015138,
          Duration = 3,
          FacialId = {
            [1] = "110005:Confident01"
          },
          FinalCamera = "58.037109,42.618416,142.168106,0.000149,1.317605,-24.925119,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B934314",
          NextDialogue = 11015139,
          SpeakNpcId = 110005,
          TalkActionId = {
            [1] = "110005:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934314"
        },
        [11015139] = {
          Camera = "7.253906,20.019621,143.611893,0.00015,-1.08212,-15.727008,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "我们还有一个选择……“自投罗网”。",
          ContentKR = "다른 선택지도 있는데... 호랑이 굴에 스스로 들어가는 거죠.",
          DialogueId = 11015139,
          Duration = 3,
          GUID = "1B93433E",
          NextOptions = {
            [1] = 11015140,
            [2] = 11015142
          },
          Scripts = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{\"Explain01_End\"},Duration{2}}",
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93433E"
        },
        [11015140] = {
          Content = "你要去找富尔维斯？",
          ContentKR = "풀비스를 찾아가겠다는 겁니까?",
          DialogueId = 11015140,
          GUID = "1B934368",
          NextDialogue = 11015141
        },
        [11015141] = {
          Camera = "52.292969,25.010664,127.544891,0.000135,6.718037,-16.930437,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "不，不是富尔维斯，而是<H>另一个人</>……",
          ContentKR = "아니요, 풀비스 말고 <Highlight>다른 사람</>요...",
          DialogueId = 11015141,
          Duration = 3,
          GUID = "1B934392",
          NextDialogue = 11015145,
          SpeakNpcId = 110005,
          TalkActionId = {
            [1] = "110005:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B934392"
        },
        [11015142] = {
          Content = "你要去找……另一个人？",
          ContentKR = "다른 사람...이라고요?",
          DialogueId = 11015142,
          GUID = "1B9343BC",
          NextDialogue = 11015143
        },
        [11015143] = {
          Camera = "52.292969,25.010664,127.544891,0.000135,6.718037,-16.930437,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "对！",
          ContentKR = "네!",
          DialogueId = 11015143,
          Duration = 3,
          GUID = "1B9343E6",
          NextDialogue = 11015145,
          SpeakNpcId = 110005,
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B9343E6"
        },
        [11015145] = {
          Camera = "52.292969,25.010664,127.544891,0.000135,6.718037,-16.930437,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "你还记不记得，法露茜说过这样的话？",
          ContentKR = "펄시가 한 말 기억해요?",
          DialogueId = 11015145,
          Duration = 3,
          FinalCamera = "48.234375,29.943214,125.579117,0.000142,6.717955,-19.329165,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B93443A",
          NextDialogue = 11015146,
          SpeakNpcId = 110005,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93443A"
        },
        [11015146] = {
          Content = "封锁所有地下出口，等叛徒出来，即刻处决。",
          ContentKR = "모든 지하 출구를 봉쇄하고, 반역자들이 나오면 즉시 처형해.",
          DialogueId = 11015146,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B934464",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014415.T_Story_Recall_11014415'",
          NextDialogue = 11015147,
          SpeakNpcId = 110012,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934464"
        },
        [11015147] = {
          Content = "快点，留给我们的时间不多了！",
          ContentKR = "시간이 얼마 없으니 서둘러!",
          DialogueId = 11015147,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B93448E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014413.T_Story_Recall_11014413'",
          NextDialogue = 11015148,
          SpeakNpcId = 110012,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93448E"
        },
        [11015148] = {
          Camera = "-171.576172,354.275269,321.845215,0.000118,-24.091339,-52.323902,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "现在龙莎要塞完全在富尔维斯的手里，抓到我们是迟早的事，法露茜究竟在为什么而慌张？",
          ContentKR = "지금 풀비스가 론샤 요새를 장악하고 있으니, 우릴 잡는 건 시간문제인데 펄시는 왜 서둘렀을까요?",
          DialogueId = 11015148,
          Duration = 3,
          FinalCamera = "-196.277344,386.265381,339.917847,0.000119,-24.091339,-52.323936,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B9344B8",
          NextDialogue = 11015149,
          SpeakNpcId = 110005,
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9344B8"
        },
        [11015149] = {
          Content = "而在那之前，您还记不记得我提到过，我偷听到一位士兵说——",
          ContentKR = "아까 제가 어떤 병사가 하는 말을 몰래 들었다고 했잖아요.",
          DialogueId = 11015149,
          Duration = 3,
          GUID = "1B9344E2",
          NextDialogue = 11015150,
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9344E2"
        },
        [11015150] = {
          Content = "因为战局不顺，西比尔军团长也在赶来龙莎要塞的路上。",
          ContentKR = "게다가 전황이 좋지 않아 시빌라 군단장님도 론샤 요새로 오고 계십니다.",
          DialogueId = 11015150,
          Duration = 3,
          FacialId = {
            [1] = "110005:None"
          },
          GUID = "1B93450C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014415.T_Story_Recall_11014415'",
          NextDialogue = 11015151,
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_Npc_EnemySoldier",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93450C"
        },
        [11015151] = {
          Camera = "154.445312,44.61274,163.534317,0.000121,-6.890936,-151.527649,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "……你的意思是，你想找到西比尔，请求她的庇护。",
          ContentKR = "...그러니까, 시빌라 군단장을 만나 보호를 요청하겠단 말입니까?",
          DialogueId = 11015151,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "177.171875,56.903561,166.748993,0.000123,-8.491031,-151.927643,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B934536",
          NextDialogue = 11015152,
          SpeakNpcId = 110022,
          TalkActionId = {
            [1] = "110022:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934536"
        },
        [11015152] = {
          Camera = "31.996094,51.468288,139.671326,0.000175,-0.491391,-24.739786,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "是的。",
          ContentKR = "맞아요.",
          DialogueId = 11015152,
          Duration = 3,
          GUID = "1B934560",
          NextDialogue = 11015153,
          SpeakNpcId = 110005,
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B934560"
        },
        [11015153] = {
          Camera = "179.789062,39.516891,181.891464,0.000178,-14.491817,-158.539825,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "但是富尔维斯已经给我们安排了罪名，甚至准备好了伪证……等一下，我明白你的“自投罗网”了。",
          ContentKR = "하지만 풀비스가 거짓 증거까지 준비해서 죄명을 마련해 뒀... 잠깐, 방금 얘기한 '호랑이 굴'에 들어가는 작전이 그 뜻이었군요.",
          DialogueId = 11015153,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B93458A",
          NextDialogue = 11015154,
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93458A"
        },
        [11015154] = {
          Camera = "42.076172,35.060333,133.820343,0.000195,2.508544,-21.337816,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "嗯！西比尔军团长也是炼金院出身，以我对她的了解，她不会容忍任何叛徒——即使是最亲近的人。",
          ContentKR = "네! 시빌라 군단장도 연금원 출신이에요. 제가 아는 그분이라면 어떠한 배반도 용납하지 않을 거예요. 설령 그게 가장 가까운 사람이더라도요.",
          DialogueId = 11015154,
          Duration = 3,
          FacialId = {
            [1] = "110005:Confident01"
          },
          FinalCamera = "28.144531,40.503914,129.73497,0.000195,2.508482,-21.537373,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B9345B4",
          NextDialogue = 11015155,
          SpeakNpcId = 110005,
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9345B4"
        },
        [11015155] = {
          Camera = "-191.923828,110.773376,292.437317,0.000252,-26.092831,-22.740551,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "……但也因此，她一定会慎重审问，不会让嫌犯轻易没命，以至断掉线索。",
          ContentKR = "...하지만 그렇기 때문에 신중히 심문할 거예요. 용의자를 함부로 죽여서 단서가 끊어지게 두지 않을 거란 말이죠.",
          DialogueId = 11015155,
          Duration = 3,
          FinalCamera = "-139.972656,126.843193,222.647064,0.000272,-16.892361,-30.148384,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B9345DE",
          NextDialogue = 11015156,
          SpeakNpcId = 110005,
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9345DE"
        },
        [11015156] = {
          Content = "如果我们能见到她，最大的可能，我们会被投入军事监狱。听闻那里壁垒森严，连一只鸟儿都飞不出来；但也因此，一切想要对我们灭口的危险，也都进不去。",
          ContentKR = "시빌라 군단장을 만나면, 우린 군교도소에 갇힐 가능성이 커요. 듣기로는 경계가 아주 삼엄해서 새 한 마리도 빠져나갈 수 없대요. 하지만 오히려 그렇기 때문에 우리를 해치려는 모든 위험도 들어올 수 없겠죠.",
          DialogueId = 11015156,
          Duration = 3,
          GUID = "1B934608",
          NextDialogue = 11015157,
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934608"
        },
        [11015157] = {
          Content = "那里反而变成了最安全的地方。而在审问中证明自己无罪，是我们唯一活下去的机会。",
          ContentKR = "오히려 그곳이 가장 안전한 장소가 될 거예요. 그리고 심문 과정에서 우리의 무죄를 증명하는 게, 우리가 살아남을 유일한 기회예요.",
          DialogueId = 11015157,
          Duration = 3,
          GUID = "1B934632",
          NextDialogue = 11015158,
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934632"
        },
        [11015158] = {
          Camera = "47.939453,49.246361,119.444901,0.000288,8.907598,-26.339521,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "只是要委屈一下您，因间谍罪接受审查，必然会有损您的名誉……但是，只要我们挺过审讯，就能还自己清白，让真正的罪人伏诛。",
          ContentKR = "문제는 스파이 혐의로 심문을 받으면 당신 명예에 큰 오점이 남는다는 거죠... 하지만 심문만 잘 견디면, 우리의 결백을 증명하고 진범을 처벌할 수 있을 거예요.",
          DialogueId = 11015158,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unacceptable01"
          },
          FinalCamera = "27.193359,59.519375,115.815987,0.000286,7.707581,-26.338728,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B93465C",
          NextDialogue = 11015159,
          SpeakNpcId = 110005,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93465C"
        },
        [11015159] = {
          Camera = "243.919922,32.791145,139.274689,0.00031,-0.492122,-160.143555,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "……因间谍罪接受审查……这件事有没有可能传到军团外面去，比如皇室？",
          ContentKR = "...스파이 혐의로 심문을 받으면... 그 사실이 군단 밖으로, 예를 들면... 황실에 전해질 수도 있겠습니까?",
          DialogueId = 11015159,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "259.697266,38.494522,139.446808,0.000309,-1.092161,-160.143555,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B934686",
          NextDialogue = 11015160,
          SpeakNpcId = 110022,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934686"
        },
        [11015160] = {
          Camera = "49.503906,51.240067,154.416092,0.000309,-5.89185,-28.343378,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "尤里乌斯陛下一向极为重视军事，十三军团又是他亲自建立的，我想会的……",
          ContentKR = "율리우스 폐하는 늘 군사를 중시하시고, 제13군단을 직접 창설하셨으니까... 그럴 수 있겠죠.",
          DialogueId = 11015160,
          Duration = 3,
          FacialId = {
            [1] = "110005:None"
          },
          FinalCamera = "49.503906,51.240067,138.708191,0.000309,0.108293,-28.74304,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B9346B0",
          NextDialogue = 11015161,
          RelatedWikiId = {
            [1] = 201018
          },
          SpeakNpcId = 110005,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9346B0"
        },
        [11015161] = {
          Camera = "132.001953,71.535721,136.665466,0.000171,6.118688,-133.138336,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          Content = "……这么说来，或许<H>那个人</>也能帮上忙。",
          ContentKR = "...그렇다면, <Highlight>그 사람</>이 도움이 될 수도 있겠군요.",
          DialogueId = 11015161,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "143.138672,83.421745,135.787506,0.000172,4.518669,-132.938339,35.0,100000.0,false,Disable,22.0,16:9 Digital Film",
          GUID = "1B9346DA",
          NextDialogue = 11015162,
          Scripts = "PlayAnimation{_delay{2},ActorId{110022},AnimationId{\"Think_End\"},Duration{2}}",
          SpeakNpcId = 110022,
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9346DA"
        },
        [11015162] = {
          Content = "好，按你说的办吧。我们去找西比尔。",
          ContentKR = "좋아요, 당신 말대로 하죠. 시빌라를 찾아갑시다.",
          DialogueId = 11015162,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934704",
          SpeakNpcId = 110022,
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B934704"
        },
        [11015163] = {
          Content = "没时间犹豫了，走吧！",
          ContentKR = "망설일 시간 없어요. 어서 가요!",
          DialogueId = 11015163,
          Duration = 3,
          GUID = "1B93472E",
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93472E"
        },
        [11015201] = {
          Content = "于是，我牵起了她的手，朝着透过门缝的那一隙阳光走去。",
          ContentKR = "그래서 전 다프네의 손을 잡고 문틈 사이로 비치는 빛을 향해 걸어갔습니다.",
          DialogueId = 11015201,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934D6A",
          NextDialogue = 11015202,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110152/1B934D6A"
        },
        [11015202] = {
          Content = "就像是，正踏入一座光辉璀璨的坟墓——",
          ContentKR = "마치 찬란하게 빛나는 무덤으로 발을 내딛는 기분이었죠.",
          DialogueId = 11015202,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934D94",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110152/1B934D94"
        },
        [11015203] = {
          Content = "我们用尽最后的力气甩开追兵，一路找到刚抵达要塞的西比尔军团长。",
          ContentKR = "우린 마지막 힘을 다해 추격자를 따돌리고, 막 요새에 도착한 시빌라 군단장을 찾아갔습니다.",
          DialogueId = 11015203,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934DBE",
          NextDialogue = 11015204,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110152/1B934DBE"
        },
        [11015204] = {
          Content = "再后来，正如达芙涅猜测的那样，我们被押送到了这里。",
          ContentKR = "그리고 다프네가 예상한 대로, 이곳에 압송된 겁니다.",
          DialogueId = 11015204,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934DE8",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110152/1B934DE8"
        },
        [11015301] = {
          Camera = "89.232414,-2.948067,11.488281,0.999996,-1.199982,-0.798315,45.0,100000.0,false,DoNotOverride,2.8,16:9 Digital Film",
          Content = "精彩的故事，和现场“一角鲸”士兵的证词完全相反。既然你主张你和阿瓦尔·赫德兰无罪，那么——",
          ContentKR = "이야기는 흥미로웠다만 현장에 있던 '나르왈' 병사의 증언과는 완전 딴판이군. 넌 너와 아바르 헤데란이 무죄라고 주장하고 있지...",
