        [11016805] = {
          Content = "……怎么直接当面说出来了……",
          ContentKR = "...그렇게 직접적으로 말하면 어떡해요...",
          DialogueId = 11016805,
          GUID = "1B945492",
          LookAt = {
            [1] = "110040:n(110041)"
          },
          NextDialogue = 11016806,
          SpeakNpcId = 110041,
          VoiceName = "voice/$Locale$/story/1002/110168/1B945492"
        },
        [11016806] = {
          Content = "那、那个，我也不知道为什么，从今天下午开始，审问官突然变温和了许多，甚至还主动问我有什么特别想实现的心愿。",
          ContentKR = "그, 그러니까... 저도 이유는 모르겠는데 오늘 오후부터 심문관들 태도가 갑자기 부드러워졌어요. 특별히 바라는 게 있냐고까지 물어보는 거 있죠.",
          DialogueId = 11016806,
          GUID = "1B9454BC",
          LookAt = {
            [1] = "110041:n(110040)"
          },
          NextDialogue = 11016807,
          SpeakNpcId = 110041,
          TalkActionId = {
            [1] = "110041:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110168/1B9454BC"
        },
        [11016807] = {
          Content = "但我的供词一直都是那些……是您说了什么，打动了典狱长吗？",
          ContentKR = "하지만 제 증언 내용은 전과 달라진 게 없는데... 당신이 한 얘기가 교도소장 마음을 움직인 걸까요?",
          DialogueId = 11016807,
          FacialId = {
            [1] = "110041:Smile01"
          },
          GUID = "1B9454E6",
          NextDialogue = 11016808,
          Scripts = "CameraMoveTo{_delay{4},TargetPosition{\"97.759766,656.613281,129.179688,0.000218,-0.592225,-99.797882,40.0,150.488785,false,DoNotOverride,22.0,16:9 Digital Film\"},duration{0}}",
          SpeakNpcId = 110041,
          VoiceName = "voice/$Locale$/story/1002/110168/1B9454E6"
        },
        [11016808] = {
          Camera = "208.457031,192.4375,122.078125,0.00018,1.007186,-146.99411,35.0,150.488785,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "……还是说——难道，这是死刑之前最后的怜悯？！",
          ContentKR = "...아니면 설마, 사형 전 마지막으로 베푸는 자비일까요?!",
          DialogueId = 11016808,
          FacialId = {
            [1] = "110041:Iyada01"
          },
          FinalCamera = "175.138672,170.794922,122.734375,0.00018,1.007186,-146.99411,35.0,150.488785,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1B945510",
          NextOptions = {
