          VoiceName = "voice/$Locale$/story/1002/110170/1B94760A"
        },
        [11017010] = {
          Content = "……总算走了。",
          ContentKR = "...드디어 다 나갔군.",
          DialogueId = 11017010,
          Duration = 3,
          GUID = "1B947634",
          SpeakNpcId = 110018,
          VoiceName = "voice/$Locale$/story/1002/110170/1B947634"
        },
        [11017101] = {
          Camera = "266.088867,42.083984,149.292969,0.000127,-0.000061,19.197737,45.000023,400.044037,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "还好、还好。要是再来晚一点，恐怕和你这次会面就是在墓园了。",
          ContentKR = "아슬아슬했어, 정말. 조금만 더 늦었다면 자네와의 만남은 묘지에서 이뤄졌을 지도 모르겠네.",
          DialogueId = 11017101,
          FinalCamera = "261.737305,56.924805,149.292969,0.000127,0.399955,13.99701,45.000023,400.044037,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1B948522",
          LookAt = {
            [1] = "110018:n(110018)",
            [2] = "110022:n(110018)"
          },
          NextDialogue = 11017102,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 201019,
            [6] = 201020
          },
          Scripts = [[
SEQ{PlayAnimation{ActorId{110018},AnimationId{"DisagreeHead"},Duration{3}},
TurnTo{_delay{0.5},TurnToDescription{"110018:n(110022)"}},
