        [11017102] = {
          Camera = "38.443359,-115.731445,90.113281,0.000127,6.999892,36.203079,35.0,400.044037,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "我说朋友，你这次是真的闯了大祸了。你知道见皇兄一面有多难，而我又极少染指政客们的事。不过你还算走运，今早皇兄为别的事情召见我，我才求来这一纸特赦令。",
          ContentKR = "이번엔 정말 큰 사고를 쳤군, 자네. 형님, 그러니까 폐하를 알현하는 게 얼마나 어려운 줄 알잖나? 그리고 나는 정치에 거의 관여하지 않기도 하고. 그래도 운이 좋았던 건지 오늘 아침 형님이 다른 일로 날 부르셔서 간신히 이 특별 사면령을 얻어낼 수 있었지만 말야.",
          DialogueId = 11017102,
          FinalCamera = "33.347656,-115.939453,81.179688,0.000127,6.999892,36.203079,35.0,400.044037,false,DoNotOverride,22.0,16:9 Digital Film",
          GUID = "1B94854C",
          LookAt = {
            [1] = "110018:n(110022)",
            [2] = "110022:n(110018)"
          },
          NextDialogue = 11017103,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.5},ActorId{110018},AnimationId{"Talk02_End"},Duration{5}},
SEQ{
CameraMoveTo{_delay{7.5},TargetPosition{"509.366211,-103.800781,280.621094,0.000228,-31.400387,130.990356,18.000004,254.013382,false,DoNotOverride,7.801928,16:9 Digital Film"},duration{0}},
CameraMoveTo{TargetPosition{"499.982422,-111.956055,283.566406,0.000228,-31.400387,130.990356,18.000004,254.013382,false,DoNotOverride,7.801928,16:9 Digital Film"},duration{15}}
