        [11017104] = {
          Camera = "541.608398,60.505859,169.71875,0.000138,-8.399841,172.791351,35.0,282.239868,false,Manual,5.900274,16:9 Digital Film",
          Content = "……谢谢……不过，先不用了。",
          ContentKR = "...감사한 말씀입니다만, 지금은 괜찮습니다.",
          DialogueId = 11017104,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9485A0",
