        [11017105] = {
          Camera = "261.737305,56.924805,149.292969,0.000127,0.399955,13.99701,45.000023,400.044037,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "……你……脸色好差。看来他们没少折磨你。等下随我去我的居所吧，我安排我的医生为你诊治。",
          ContentKR = "...음... 안색이 너무 좋지 않은 것 같은데, 갇혀 있는 동안 꽤나 시달렸나 보군. 이따 함께 내 거처로 가지. 주치의한테 치료받을 수 있게 준비해 둘 테니.",
          DialogueId = 11017105,
          Duration = 1,
          GUID = "1B9485CA",
          NextDialogue = 11017106,
          Scripts = [[
