          SpeakNpcId = 110022,
          TalkActionId = {
            [1] = "110022:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94861E"
        },
        [11017108] = {
          Camera = "169.751953,12.941406,146.257812,0.000181,-0.200685,23.989719,45.0,254.013382,false,Manual,7.801928,16:9 Digital Film",
          Content = "放心。我听闻你一直在护着她，这份特赦令自然也会庇护她。",
          ContentKR = "안심해. 자네가 그 여자를 계속 보호하려고 했다는 사실도 알고 있으니까. 이 특별 사면령이라면 충분할 거야.",
          DialogueId = 11017108,
          FinalCamera = "159.480469,8.374023,146.257812,0.000181,-0.200685,23.989157,45.0,254.013382,false,Manual,7.801928,16:9 Digital Film",
          GUID = "1B948648",
