        [11017112] = {
          Camera = "34.15918,-378.791016,351.042969,0.000214,-23.400875,60.993435,35.0,254.013382,false,DoNotOverride,7.801928,16:9 Digital Film",
          Content = "还有一件事……",
          ContentKR = "네, 드릴 말씀이 하나 더 있습니다...",
          DialogueId = 11017112,
          ExStoryInfo = "EXPlayer",
