        [11017113] = {
          Camera = "3.826172,76.46582,165.292969,0.000128,-0.600066,-114.184586,31.194523,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "你短期可能回不了军团了。你的嫌疑并未真的洗清，现在回军团只怕身份会尴尬。",
          ContentKR = "어차피 당분간은 군단으로 돌아가기 힘들 거야. 아직 모든 혐의가 깔끔하게 해결된 건 아니라 지금 복귀하면 입지가 곤란할 수 있거든.",
          DialogueId = 11017113,
          Duration = 3,
          GUID = "1B94871A",
          NextDialogue = 11019115,
          Scripts = [[
PARA{
