        [11017115] = {
          Camera = "315.612305,27.775391,111.347656,0.000177,18.198792,35.193779,45.000011,254.013382,false,DoNotOverride,7.801928,16:9 Digital Film",
          Content = "富尔维斯失踪的副官……？好，我记下了。",
          ContentKR = "풀비스의 부관이 사라졌다...? 좋아, 기억해 두지.",
          DialogueId = 11017115,
          GUID = "1B94871D",
          NextDialogue = 11017109,
          SpeakNpcId = 110018,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94871D"
        },
        [11017116] = {
          Camera = "211.03125,373.930664,131.835938,0.000081,2.000002,-130.801483,31.194527,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "嗯。想想那份文件上的一串签名吧——迪斯玛尼亚不知道有多少人在看不见的暗角窥视着你。你的武器可以杀死秽兽，却挡不住来自背后的子弹。",
          ContentKR = "그래. 그 문서에 서명한 사람들을 생각해 봐. 디즈마니아에 있으면 보이지 않는 곳에서 자네를 노리는 사람들이 얼마나 많을지 알 수 없어. 자네의 무기로는 필토이드는 죽일 수 있겠지만, 등 뒤에서 날아오는 총알은 막을 수 없을 테니까.",
          DialogueId = 11017116,
          Duration = 3,
          FinalCamera = "215.617188,369.973633,131.835938,0.000081,1.999995,-130.801483,31.194527,100000.0,false,Manual,22.0,16:9 Digital Film",
          GUID = "1B948798",
          NextDialogue = 11017117,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"118.792969,12.256836,231.714844,0.000107,-21.599482,-163.622894,45.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film"},duration{0}},
CameraMoveTo{TargetPosition{"130.400391,15.670898,236.511719,0.000107,-21.599482,-163.622894,45.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film"},duration{8}}
