        [11017117] = {
          Camera = "-38.605469,-123.583984,167.742188,0.000094,-5.999843,78.991455,31.194527,446.287842,false,Manual,11.834087,16:9 Digital Film",
          Content = "我知道你在担心什么。西比尔·梅森和达芙涅有些故交，且在这起事件中，她明显更相信你们无辜，所以她至少会保证达芙涅的安全。",
          ContentKR = "자네가 무엇을 걱정하는지 알아. 시빌라 메이슨은 다프네와 오랜 친분이 있고, 이번 사건에서도 자네들이 무고하다는 걸 의심치 않고 있으니 적어도 다프네의 안전은 걱정할 필요 없을 거야.",
          DialogueId = 11017117,
          Duration = 3,
          FinalCamera = "-45.6875,-122.178711,167.742188,0.000092,-6.199858,78.391617,31.194527,446.287842,false,Manual,11.834087,16:9 Digital Film",
          GUID = "1B9487C2",
          NextDialogue = 11019119,
          SpeakNpcId = 110018,
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110171/1B9487C2"
        },
        [11017119] = {
          Camera = "653.830078,-1243.886719,875.824219,0.000136,-26.201082,109.391876,31.194523,1682.25708,false,Manual,1.2,16:9 Digital Film",
          Content = "……哈，你知道我最厌恶那些老家伙的繁文缛节。不过，你总算有心情开玩笑了，这很好。",
          ContentKR = "...하하, 내가 꼰대들이나 하는 허례허식을 제일 싫어하는 걸 알 텐데. 그래도 농담할 정신이 있는 것 같으니 다행이군.",
          DialogueId = 11017119,
