          GUID = "1B94B65A",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B65A"
        },
        [11017402] = {
          Content = "达芙涅对伤员们进行了治疗",
          ContentKR = "다프네가 부상자들을 치료했다.",
          DialogueId = 11017402,
          Duration = 2,
          GUID = "1B94B684",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B684"
        },
        [11017403] = {
          Content = "带着卡嘉一行人离开了此处……",
          ContentKR = "카지아 일행을 데리고 이곳을 떠났다...",
          DialogueId = 11017403,
          Duration = 2,
          GUID = "1B94B6AE",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B6AE"
        },
        [11017404] = {
          Content = "这是……继电器，总之先关闭一个",
          ContentKR = "이건... 계전기다. 먼저 하나 꺼보자.",
          DialogueId = 11017404,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B6D8",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B6D8"
        },
        [11017405] = {
          DialogueId = 11017405,
          Duration = 2,
          GUID = "1B94B702",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B702"
        },
        [11017406] = {
          Content = "不要动！",
          ContentKR = "움직이지 마세요!",
          DialogueId = 11017406,
          Duration = 2,
          GUID = "1B909E34",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 110005,
          VoiceName = "voice/$Locale$/story/1002/110110/1B909E34"
        },
        [11017407] = {
          Content = "水位降不下去！",
          ContentKR = "수위가 낮아지지 않아요!",
          DialogueId = 11017407,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B756",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
