          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B756"
        },
        [11017408] = {
          Content = "从边上绕过去吧。",
          ContentKR = "옆으로 돌아가보세요.",
          DialogueId = 11017408,
          Duration = 2,
          GUID = "1B94B780",
