          ContentKR = "(번거롭네...)",
          DialogueId = 11017512,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C890",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C890"
        },
        [11017513] = {
          Content = "你那边……什么动静？",
          ContentKR = "거기... 무슨 소리 나지 않았나?",
