          ExStoryInfo = "EXPlayer",
          GUID = "1B94F8CC",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F8CC"
        },
        [11017807] = {
          Content = "不要停，继续轰击！记得用高爆弹。",
          ContentKR = "멈추지 말고 계속 포격해! 고폭탄은 되는대로 계속 사용하고.",
          DialogueId = 11017807,
          GUID = "1B94F8F6",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F8F6"
        },
        [11017808] = {
          Content = "差不多了！过去看看吧。",
          ContentKR = "거의 끝났어! 가서 확인해 봐!",
          DialogueId = 11017808,
          GUID = "1B94F920",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110186/1B957C0C"
        },
        [11017809] = {
          Content = "别发愣啊，快轰！",
          ContentKR = "멍하니 서있지 말고, 서둘러!",
          DialogueId = 11017809,
          GUID = "1B94F94A",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F94A"
        },
        [11017810] = {
          Content = "你还好吧？别是哪儿受伤了？",
          ContentKR = "괜찮나? 어디 다친 건가?",
          DialogueId = 11017810,
          GUID = "1B94F974",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F974"
        },
        [11017811] = {
          Content = "等你把这门敲破，我小女儿都变成老奶奶了！回去开炮。",
          ContentKR = "그렇게 두드려서 어느 세월에 다 부순다는 건가! 어서 가서 포격이나 해.",
          DialogueId = 11017811,
          GUID = "1B94F99E",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F99E"
        },
        [11017812] = {
          DialogueId = 11017812,
          GUID = "1B94F9C8",
          IsBlack = 1,
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F9C8"
        },
        [11017901] = {
          Content = "去吧，保持联络，听我指示。",
          ContentKR = "어서 가라. 계속 통신할 테니 내 지시 잘 듣고.",
          DialogueId = 11017901,
          GUID = "1B950862",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110179/1B950862"
        },
        [11017902] = {
          Content = "维克……",
          ContentKR = "빅...",
          DialogueId = 11017902,
          GUID = "1B95088C",
          SpeakNpcId = 110020,
          VoiceName = "voice/$Locale$/story/1002/110179/1B95088C"
        },
        [11017903] = {
          Content = "准备好了，就激活髓动轮出发吧。",
          ContentKR = "준비다 됐으면, 회전체를 활성화하고 출발해.",
          DialogueId = 11017903,
          GUID = "1B9508B6",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110179/1B9508B6"
        },
        [11018001] = {
          Camera = "-1102.632935,-197.335449,128.499756,0.000169,-1.399683,12.991217,50.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "等一下。",
          ContentKR = "잠깐!",
          DialogueId = 11018001,
          GUID = "1B9518CA",
          LookAt = {
