        [11018002] = {
          Camera = "436.131592,1.919922,136.800903,0.000139,-1.999415,173.000534,35.0,100000.0,false,Manual,22.0,16:9 Digital Film",
          Content = "接下来的任务容不得出任何错，我们还是得排除风险——小姑娘和老人家不能跟着了。",
          ContentKR = "다음 임무는 절대 실수하면 안 되니 위험 요소부터 배제하는 게 좋겠군. 그러니 여자 아이와 노인은 함께 갈 수 없다.",
          DialogueId = 11018002,
          GUID = "1B9518F4",
          LookAt = {
            [1] = "110010:n(110034)"
          },
          NextDialogue = 11018003,
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110180/1B9518F4"
        },
        [11018003] = {
          Camera = "27.165649,69.382324,136.855469,0.000141,-0.199305,10.000502,35.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "……为什么？刚才您也看到了，到处都是秽兽，如果在这里和你们分开，我和爷爷一定会没命的！",
          ContentKR = "...왜요? 방금 보셨잖아요. 주변에 필토이드가 잔뜩이에요. 함께 갈 수 없다면 저와 할아버지는 죽은 목숨일 거예요!",
          DialogueId = 11018003,
          FacialId = {
            [1] = "110034:Sad01"
          },
          GUID = "1B95191E",
          LookAt = {
            [1] = "110034:n(110010)",
            [2] = "110022:n(110034)"
          },
          NextDialogue = 11018004,
          Scripts = "CameraMoveTo{_delay{8},TargetPosition{\"-263.419067,35.512207,120.94928,0.000142,0.800758,5.202505,30.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film\"},duration{0}}",
          SpeakNpcId = 110034,
          VoiceName = "voice/$Locale$/story/1002/110180/1B95191E"
        },
        [11018004] = {
          Camera = "-143.649597,-86.15332,142.109314,0.000144,-2.799244,26.800621,35.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "长官，我帮过您的！您想，我刚刚给您带路，帮您顺利会合……求求您……求求您不要抛下我们！",
          ContentKR = "나리, 제가 도울게요! 지금까지 길도 잘 안내했잖아요... 제발... 제발 저희를 버리지 말아 주세요!",
          DialogueId = 11018004,
          GUID = "1B951948",
          LookAt = {
            [1] = "110034:n(110022)",
            [2] = "110017:n(110010)"
          },
          NextOptions = {
            [1] = 11018005,
            [2] = 11018008
          },
          Scripts = "LookAt{_delay{1},LookAtDescription{\"110022:n(110034)\"}}",
          SpeakNpcId = 110034,
          VoiceName = "voice/$Locale$/story/1002/110180/1B951948"
        },
        [11018005] = {
          Content = "信任卡嘉",
          ContentKR = "카지아를 믿는다",
          DialogueId = 11018005,
          GUID = "1B951972",
          ImprPlusId = 1009,
          NextDialogue = 11018006
        },
        [11018006] = {
          Camera = "-372.804108,82.572754,153.340088,0.000149,-3.999233,-7.999348,50.000011,450.777496,false,DoNotOverride,7.0,16:9 Digital Film",
          Content = "老师也许多虑了。如果他们是敌人，那么在地下水道故意带错路会是更好的选择，但他们没有这么做。",
          ContentKR = "교관님 걱정하지 않으셔도 될 것 같습니다. 이 사람들이 우리 편이 아니었다면, 지하수도의 길도 제대로 알려주지 않았을 게 분명합니다.",
          DialogueId = 11018006,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95199C",
          LookAt = {
            [1] = "110022:n(110010)",
            [2] = "110010:n(110010)"
          },
          NextDialogue = 11018007,
          SpeakNpcId = 110022,
          TalkActionId = {
            [1] = "110022:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B95199C"
        },
        [11018007] = {
          Camera = "32.585205,14.534668,146.054871,0.00015,-1.399219,162.798279,50.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "如果他们另有打算呢。你不觉得，刚才这一路，他们“过于了解”这座要塞了吗？",
          ContentKR = "저들이 다른 속셈이 있는 거라면? 방금도 이 요새를 '너무 잘 알고' 있다는 생각 안 드나?",
          DialogueId = 11018007,
          GUID = "1B9519C6",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11018011,
          SpeakNpcId = 110010,
          TalkActionId = {
            [1] = "110022:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B9519C6"
        },
        [11018008] = {
          Content = "不信任卡嘉",
          ContentKR = "카지아를 믿지 않는다",
          DialogueId = 11018008,
          GUID = "1B9519F0",
          ImprPlusId = 1008,
          NextDialogue = 11018009
        },
        [11018009] = {
          Camera = "209.203857,228.964844,146.143616,0.000167,-4.599087,-120.406746,45.000011,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "……我赞同老师的判断。",
          ContentKR = "...교관님 판단에 동의합니다.",
          DialogueId = 11018009,
          ExStoryInfo = "EXPlayer",
          GUID = "1B951A1A",
          LookAt = {
            [1] = "110022:n(110034)"
          },
          NextDialogue = 11018010,
          Scripts = "SetRotation{SetRotationDescription{\"110022:n(110034)\"}}",
          SpeakNpcId = 110022,
          TalkActionId = {
            [1] = "110022:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B951A1A"
        },
        [11018010] = {
          Camera = "-127.301941,-114.787598,142.109314,0.000143,-1.599302,31.20196,35.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "如果是进中央控制室之前，我还可以勉强信任你；但是现在看来你似乎“过于了解”这座要塞了。",
          ContentKR = "중앙 관제실에 들어가기 전이라면 모를까 아무래도 넌 이 요새에 대해 '너무 잘 알고' 있는 것 같군.",
          DialogueId = 11018010,
          ExStoryInfo = "EXPlayer",
          GUID = "1B951A44",
          LookAt = {
            [1] = "110010:n(110022)",
            [2] = "110022:n(110034)"
          },
          NextDialogue = 11018011,
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110180/1B951A44"
        },
        [11018011] = {
          Camera = "414.556763,7.735352,138.894348,0.000155,-2.599324,169.392776,50.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "中央控制室是龙莎要塞的中枢，就算是同盟，也不会允许路边随便抓来的苦力来这种核心区域闲逛。",
          ContentKR = "중앙 관제실은 론샤 요새의 심장부다. 포세이큰 동맹이라고 해도 길에서 마구잡이로 데려온 사람들이 이런 핵심 지역을 돌아다니도록 놔두지 않았을 것이다.",
          DialogueId = 11018011,
          GUID = "1B951A6E",
          LookAt = {
            [1] = "110010:n(110010)"
          },
          NextDialogue = 11018012,
          SpeakNpcId = 110010,
          TurnTo = {
            [1] = "110022:n(110010)"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B951A6E"
        },
        [11018012] = {
          Content = "你不该对里面的路线也如此轻车熟路。",
          ContentKR = "이렇게 내부 동선을 제 집인 양 잘 알고 있다는 건 말이 안 돼.",
          DialogueId = 11018012,
          GUID = "1B951A98",
          LookAt = {
            [1] = "110010:n(110034)"
          },
          NextDialogue = 11018013,
          SpeakNpcId = 110010,
          TalkActionId = {
            [1] = "110010:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B951A98"
        },
        [11018013] = {
          Camera = "-38.761108,62.896484,133.47168,0.000157,0.600497,8.994007,50.000008,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "呃……那是因为——",
          ContentKR = "아... 그건...",
          DialogueId = 11018013,
          GUID = "1B951AC2",
          LookAt = {
            [1] = "110034:n(110010)"
          },
          NextDialogue = 11018014,
          SpeakNpcId = 110034,
          TalkActionId = {
            [1] = "110022:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B951AC2"
        },
        [11018014] = {
          Camera = "528.188843,-8.837402,130.242065,0.000159,-1.599541,172.787582,50.000008,824.380615,false,Manual,10.0,16:9 Digital Film",
          Content = "小姑娘，这么喜欢演戏，还是去皇都的大剧院演吧。",
          ContentKR = "꼬마 아가씨, 연기력이 대단한데. 황성의 극단에 들어가 보는 건 어떤가?",
          DialogueId = 11018014,
          GUID = "1B951AEC",
          LookAt = {
            [1] = "110010:n(110010)"
          },
          NextDialogue = 11018015,
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110180/1B951AEC"
        },
        [11018015] = {
          Camera = "-1102.632935,-197.335449,128.499756,0.000169,-1.399683,12.991217,50.0,100000.0,false,DoNotOverride,22.0,16:9 Digital Film",
          Content = "时间不多了，我们走。莱昂，留下来看好他们。",
          ContentKR = "시간이 없으니 이만 가지. 레온, 넌 여기 남아서 저들을 잘 지켜보도록.",
          DialogueId = 11018015,
          GUID = "1B951B16",
          SpeakNpcId = 110010,
          TalkActionId = {
            [1] = "110010:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B951B16"
        },
        [11018101] = {
          Content = "年轻的士兵半倚着冰冷的墙壁，已经没了气息。一道巨大的爪痕穿过他的胸口，将他贯穿。在刚刚的巨型秽兽面前，普通人类的力量太微弱了。",
          ContentKR = "젊은 병사는 차가운 벽에 몸을 기댄 채 이미 숨을 거두고 있었다. 거대한 발톱이 그의 가슴을 꿰뚫고 지나간 흔적이 선명했다. 방금 마주한 거대한 필토이드 앞에서, 평범한 인간의 힘은 너무나도 나약했다.",
          DialogueId = 11018101,
          GUID = "1B952932",
          VoiceName = "voice/$Locale$/story/1002/110181/1B952932"
        },
        [11018102] = {
          Content = "（……安息。）",
          ContentKR = "(...편히 쉬기를.)",
          DialogueId = 11018102,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95295C",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110181/1B95295C"
        },
        [11018201] = {
          Content = "先解决那个神弃者！这群秽兽受他操弄！",
          ContentKR = "저 포세이큰 놈부터 먼저 처리해! 이 필토이드들은 그놈이 조종하고 있어!",
          DialogueId = 11018201,
          GUID = "1B95399A",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110182/1B95399A"
        },
        [11018202] = {
          Content = "维克，莫妮卡，撑住……我们很快就到。",
          ContentKR = "빅, 모니카, 조금만 더 버텨... 곧 갈게.",
          DialogueId = 11018202,
          GUID = "1B9539C4",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110182/1B9539C4"
        },
        [11018203] = {
          Content = "（好，关停了。去找其他几台髓动轮吧。）",
          ContentKR = "(좋아, 종료시켰어. 이제 남은 회전체를 찾아보자.)",
          DialogueId = 11018203,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9539EE",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110182/1B9539EE"
        },
        [11018204] = {
          Content = "男人崭新的军装被撕碎，透过褴褛的布条，无数爪迹和齿痕清晰可辨；显然，他是被相当数量的秽兽撕咬致死的。他指节青白的手仍紧紧握着断刃，似是最后一刻仍在与群兽角力。",
          ContentKR = "남자의 새 군복은 갈기갈기 찢어져 있었고, 너덜너덜한 천 사이로 수많은 발톱 자국과 이빨 자국이 선명하게 드러났다. 그는 수많은 필토이드에게 물어뜯겨 처참하게 죽음을 맞이한 듯했다. 푸르게 질린 손가락은 여전히 부러진 칼날을 단단히 움켜쥐고 있었고, 마지막 순간까지도 필토이드들과 치열하게 싸웠음을 보여주고 있었다.",
          DialogueId = 11018204,
          GUID = "1B953A18",
          NextDialogue = 11018205,
          VoiceName = "voice/$Locale$/story/1002/110182/1B953A18"
        },
        [11018205] = {
          Content = "在他的身旁静静地躺着一枚铭牌，你认得出来，那是军团为每一位新兵颁发的铭牌。铭牌的正面是他的名字，维克·吉拉德。背面则用小刀刻着一行小字：“莫妮卡，下次射击比赛我一定会赢过你。”",
          ContentKR = "그의 곁에는 명패 하나가 조용히 놓여 있었다. 군단이 신병들에게 지급하는 명패라는 걸 알아볼 수 있다. 앞면에는 그의 이름, 빅 지라드가 새겨져 있었고, 뒷면에는 칼로 새긴 듯한 작은 글씨가 남아 있었다. \"모니카, 다음 사격 대회에선 내가 꼭 이길 거야.\"",
          DialogueId = 11018205,
          GUID = "1B953A42",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953A42"
        },
        [11018206] = {
          Content = "（月髓舱炸毁后，这些机关都瘫痪了。）",
          ContentKR = " (폭시코르가 폭발하고 나서, 이 장치들도 전부 멈춰 버렸군.)",
          DialogueId = 11018206,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953A6C",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110182/1B953A6C"
        },
        [11018207] = {
          Content = "就是这些畜生……把大家……",
          ContentKR = "이 짐승들이... 모두를... 이렇게...",
          DialogueId = 11018207,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953A96",
          NextDialogue = 11018208,
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110182/1B953A96"
        },
        [11018208] = {
          Content = "<W>不错，正是如此。仇恨刺痛着你的心脏，你从未如此渴求着鲜血。</>",
          ContentKR = "<W>그래, 바로 그거야. 증오가 심장을 후벼 파고, 이렇게까지 피를 원한 적은 한 번도 없었지.</>",
          DialogueId = 11018208,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953AC0",
          NextDialogue = 11018209,
          SnapShot = "MONSTER",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953AC0"
        },
        [11018209] = {
          Content = "<W>你只恨这些怪物无血无泪，它们无法感受你的愤怒与悲辛。</>",
          ContentKR = "<W>이 괴물들은 피도 눈물도 없어. 네 분노도, 슬픔도 전혀 느끼지 못해. 그걸 증오하고 있지?</>",
          DialogueId = 11018209,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953AEA",
          NextDialogue = 11018210,
          SnapShot = "MONSTER",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953AEA"
        },
        [11018210] = {
          Content = "<W>但是没有关系，你只需要挥剑、挥剑、挥剑——</>",
          ContentKR = "<W>하지만 괜찮아. 그냥 검을 휘둘러, 또 휘두르고, 계속 휘두르면 돼...</>",
          DialogueId = 11018210,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953B14",
          NextDialogue = 11018211,
          SnapShot = "MONSTER",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953B14"
        },
        [11018211] = {
          Content = "（……不行！）",
          ContentKR = "(...안 돼!)",
          DialogueId = 11018211,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953B3E",
          NextDialogue = 11018212,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110182/1B953B3E"
        },
        [11018212] = {
          Content = "（还有人等待我救援……不能被这些秽兽拖在这儿！）",
          ContentKR = "(아직도 내가 구해야 할 사람들이 있어... 여기서 필토이드들에게 발목 잡힐 순 없어!)",
          DialogueId = 11018212,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953B68",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110182/1B953B68"
        },
        [11018301] = {
          Content = "坚持住，队长就快来了！",
          ContentKR = "버티세요, 대장님이 곧 오십니다!",
          DialogueId = 11018301,
          GUID = "1B954A02",
          SpeakNpcId = 110016,
          VoiceName = "voice/$Locale$/story/1002/110183/1B954A02"
        },
        [11018302] = {
          Content = "神弃者同盟的人改造要塞要苦力，就派人到我们镇子，把我们强行绑过来。他们甚至不要索拉之民，而是专挑我们卡戎之民……",
          ContentKR = "저희는 포세이큰 동맹이 요새를 개조하는 데 일손이 필요해서 끌려왔을 뿐이에요. 심지어 솔라는 쏙 빼고 카론만 골라서 끌려왔죠...",
          DialogueId = 11018302,
          FacialId = {
            [1] = "110034:Sad01"
          },
          GUID = "1B954A2C",
          NextDialogue = 11011824,
          RelatedWikiId = {
            [1] = 201015
          },
          SpeakNpcId = 110034,
          VoiceName = "voice/$Locale$/story/1002/110183/1B954A2C"
        },
        [11018401] = {
          Camera = "-274.711914,194.082031,124.856079,0.00015,-1.800322,-91.197739,35.000008,229.080856,false,Manual,2.8,16:9 Digital Film",
          CameraBlendCurve = "easeInOutQuad",
          Content = "没错，仅仅因为我们比索拉之民力气更大，更不怕严寒暑热——也许在您的眼中我们是同类，但同盟从未把我们当过“同胞”。",
          ContentKR = "맞아요. 솔라보다 힘이 세고 추위나 더위를 덜 탄다는 이유만으로요. 사람들 눈에는 저희가 포세이큰 동맹과 같은 부류로 보이겠지만, 그 사람들은 단 한 번도 저희를 '동족'으로 대한 적이 없어요.",
          DialogueId = 11018401,
          FacialId = {
