          DialogueId = 11018603,
          GUID = "1B957B8E",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110186/1B957B8E"
        },
        [11018604] = {
          Content = "是这群秽兽的首领，干掉它！",
          ContentKR = "이놈이 우두머리야! 해치워!",
          DialogueId = 11018604,
          GUID = "1B957BB8",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110186/1B957BB8"
        },
        [11018605] = {
