        [11018812] = {
          Content = "（一份布防计划书，详细记录着神弃者同盟在撤离前夕，于龙莎要塞布设陷阱的安排。工程师的签名为：卡嘉·厄恩。）",
          ContentKR = "(포세이큰 동맹이 철수 직전에 론샤 요새에 함정을 배치한 계획서, 서명한 엔지니어는 카지아 어언이다.)",
          DialogueId = 11018812,
          GUID = "1B959DD8",
          NextDialogue = 11018813,
          VoiceName = "voice/$Locale$/story/1002/110188/1B959DD8"
        },
        [11018813] = {
          Content = "（原来是她。）",
          ContentKR = "(역시 그녀였군.)",
          DialogueId = 11018813,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B959E02",
