        [11018814] = {
          Content = "查阅第二份文件",
          ContentKR = "두 번째 문서 확인하기",
          DialogueId = 11018814,
          GUID = "1B959E2C",
          NextDialogue = 11018815
        },
        [11018815] = {
          Content = "龙莎要塞位于红溪河谷畔高地，一度扼守皇都与丹流城的水路交通要道。帝国根基尚未稳固之时，初代皇帝盖雷亚在此设伏，击败了敌对的联军，奠定了他一统帝国全境的基础。",
          ContentKR = "론샤 요새는 마노 계곡 고지에 자리 잡고 있으며, 한때 황성과 스칼렛을 잇는 수로 교통의 핵심 요충지였다. 제국의 기틀이 아직 불안정하던 시절, 초대 황제 갈레아는 이곳에서 적 연합군을 매복 공격하여 승리했고, 제국 통일의 초석을 다졌다.",
          DialogueId = 11018815,
          GUID = "1B959E56",
          NextDialogue = 11018816,
          VoiceName = "voice/$Locale$/story/1002/110188/1B959E56"
        },
        [11018816] = {
          Content = "但是随着迪斯玛尼亚与丹流城之间铁路的开通，距离铁路尚有一段距离的龙莎要塞地位有所下降，从重要的交通关口变成了单纯的军事要塞。",
          ContentKR = "그러나 디스마니아와 스칼렛을 잇는 철도가 개통되면서, 철도에서 멀리 떨어진 론샤 요새의 전략적 가치는 낮아졌고, 중요한 교통 요충지에서 단순한 군사 요새로 전락하고 말았다.",
          DialogueId = 11018816,
          GUID = "1B959E80",
          NextDialogue = 11018817,
          VoiceName = "voice/$Locale$/story/1002/110188/1B959E80"
        },
        [11018817] = {
          Content = "（没有什么值得在意的。）",
          ContentKR = "(굳이 신경 쓸 필요는 없겠군.)",
